/// Descriptor owner for the completed-abort source-byte witness. An ambiguous
/// close is kept here as an actual unresolved handle and bars every snapshot.
final class EraseAbortCheckedSnapshotIOV1 {
    struct CheckedTreeNode {
        let path: String
        let fact: stat
        let sha256: String?
    }

    private var selectedControlOwnerCellsV1 = SelectedControlOwnerCellsV1()
    private var uncertainDescriptors: [Int32] = []
    private var uncertainDirectories: [UnsafeMutablePointer<DIR>] = []
    // Distinct per-publication raw lifetime; ordinary Snapshot IO is intact.
    fileprivate var activeOriginalPointerPublication: OriginalErasePointerPublicationIOV1?
    fileprivate var retainedOriginalPointerPublications: [OriginalErasePointerPublicationIOV1] = []

    func requireSettled() throws {
        try selectedControlOwnerCellsV1.retained?.requireNoRawUncertainty()
        guard !retainedOriginalPointerPublications.contains(where: {
            $0.storage.phase == .uncertain || $0.storage.failure != nil
        }) else { throw StoreGenerationFailure.dataPointerInvalid }
        guard uncertainDescriptors.isEmpty, uncertainDirectories.isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    func retainUncertainDescriptor(_ descriptor: Int32) {
        uncertainDescriptors.append(descriptor)
    }

    func withOpen<Value>(parent: Int32, name: String, flags: Int32,
                         mode: mode_t = 0,
                         _ body: (Int32) throws -> Value) throws -> Value {
        try requireSettled()
        if let actual = activeOriginalPointerPublication {
            guard actual.storage.snapshotIO === self else { throw StoreGenerationFailure.dataPointerInvalid }
            return try actual.withOpen(parent: parent, name: name, flags: flags, mode: mode, body)
        }
        if selectedControlOwnerV1 != nil {
            return try selectedControlWithOpenV1(parent: parent, name: name, flags: flags | O_NOFOLLOW | O_CLOEXEC, mode: mode, body)
        }
        let descriptor = Darwin.openat(parent, name,
            flags | O_NOFOLLOW | O_CLOEXEC, mode)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        var closeAttempted = false
        do {
            let result = try body(descriptor)
            closeAttempted = true
            guard Darwin.close(descriptor) == 0 else {
                uncertainDescriptors.append(descriptor)
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return result
        } catch {
            if !closeAttempted, Darwin.close(descriptor) != 0 {
                uncertainDescriptors.append(descriptor)
            }
            throw error
        }
    }

    func names(in parent: Int32) throws -> [String] {
        try requireSettled()
        if let actual = activeOriginalPointerPublication {
            guard actual.storage.snapshotIO === self else { throw StoreGenerationFailure.dataPointerInvalid }
            return try actual.names(in: parent)
        }
        if selectedControlOwnerV1 != nil { return try selectedControlNamesV1(in: parent) }
        let descriptor = Darwin.openat(parent, ".", O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        guard let directory = Darwin.fdopendir(descriptor) else {
            if Darwin.close(descriptor) != 0 { uncertainDescriptors.append(descriptor) }
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var closeAttempted = false
        do {
            var result = [String]()
            errno = 0
            while let entry = Darwin.readdir(directory) {
                guard let name = OwnedStorageDirectoryEntryNameV1.decode(entry) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                if name != "." && name != ".." { result.append(name) }
                errno = 0
            }
            guard errno == 0 else { throw StoreGenerationFailure.dataPointerInvalid }
            closeAttempted = true
            guard Darwin.closedir(directory) == 0 else {
                uncertainDirectories.append(directory)
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return result.sorted()
        } catch {
            if !closeAttempted, Darwin.closedir(directory) != 0 {
                uncertainDirectories.append(directory)
            }
            throw error
        }
    }

    /// Fixed read-only census variant for closed control/owner namespaces.
    /// Ordinary tree and names readers remain byte-for-byte unchanged.
    func boundedNames(in parent: Int32, maximumCount: Int) throws -> [String] {
        try requireSettled()
        guard maximumCount >= 0, maximumCount <= 100_000 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let descriptor = Darwin.openat(parent, ".", O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        guard let directory = Darwin.fdopendir(descriptor) else {
            if Darwin.close(descriptor) != 0 { uncertainDescriptors.append(descriptor) }
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var closeAttempted = false
        do {
            var result: [String] = []
            errno = 0
            while let entry = Darwin.readdir(directory) {
                guard let name = OwnedStorageDirectoryEntryNameV1.decode(entry) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                if name != "." && name != ".." {
                    guard result.count < maximumCount else { throw StoreGenerationFailure.dataPointerInvalid }
                    result.append(name)
                }
                errno = 0
            }
            guard errno == 0, result.count == Set(result).count else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            closeAttempted = true
            guard Darwin.closedir(directory) == 0 else {
                uncertainDirectories.append(directory)
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return result.sorted()
        } catch {
            if !closeAttempted, Darwin.closedir(directory) != 0 { uncertainDirectories.append(directory) }
            throw error
        }
    }

    private func digestFile(_ descriptor: Int32, before: stat) throws -> String {
        try selectedControlOwnerV1?.backing.chargeBeforeBirth(UInt64(MemoryLayout<SHA256>.stride
            + MemoryLayout<[UInt8]>.stride + 65_536 + MemoryLayout<off_t>.stride
            + MemoryLayout<Int64>.stride + MemoryLayout<Int>.stride))
        var digest = SHA256()
        var count: off_t = 0
        var buffer = [UInt8](repeating: 0, count: 64 * 1024)
        while true {
            let rawRead = try selectedControlKernelV1(.readRaw, descriptor: descriptor) {
                Int64(buffer.withUnsafeMutableBytes { Darwin.read(descriptor, $0.baseAddress, $0.count) })
            }
            guard let readCount = Int(exactly: rawRead) else { throw StoreGenerationFailure.dataPointerInvalid }
            if readCount > 0 {
                count += off_t(readCount)
                guard count <= before.st_size else { throw StoreGenerationFailure.dataPointerInvalid }
                // CryptoKit consumes these bytes synchronously while buffer is pinned.
                // Avoid a fresh Data allocation for each checked 64 KiB read.
                buffer.withUnsafeBytes { rawBuffer in
                    digest.update(bufferPointer: UnsafeRawBufferPointer(
                        start: rawBuffer.baseAddress, count: readCount))
                }
            } else if readCount == 0 { break }
            else if errno != EINTR { throw StoreGenerationFailure.dataPointerInvalid }
        }
        guard count == before.st_size else { throw StoreGenerationFailure.dataPointerInvalid }
        return digest.finalize().map { String(format: "%02x", $0) }.joined()
    }

    func control(parent: Int32, name: String,
                 maximum: Int = 4 * 1024 * 1024) throws -> (Data, String) {
        guard maximum > 0, maximum <= 32 * 1024 * 1024 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireSettled()
        func requireNoPending() throws {
            let pendingNames = name == "current.json"
                ? [".current.json.restore-next", ".current.json.migration-next"]
                : [".\(name).restore-next"]
            for pendingName in pendingNames {
                var pending = stat()
                guard Darwin.fstatat(parent, pendingName, &pending,
                                     AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        try requireNoPending()
        return try withOpen(parent: parent, name: name,
                            flags: O_RDONLY | O_NONBLOCK) { descriptor in
            var before = stat(), after = stat(), named = stat()
            guard Darwin.fstat(descriptor, &before) == 0,
                  before.st_mode & S_IFMT == S_IFREG,
                  before.st_nlink == 1, before.st_size >= 0,
                  before.st_size <= off_t(maximum),
                  Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                  named.st_dev == before.st_dev, named.st_ino == before.st_ino else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var data = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    guard data.count <= maximum - count else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    data.append(contentsOf: buffer.prefix(count))
                } else if count == 0 { break }
                else if errno != EINTR { throw StoreGenerationFailure.dataPointerInvalid }
            }
            guard Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                  after.st_dev == before.st_dev, after.st_ino == before.st_ino,
                  after.st_size == before.st_size,
                  data.count == Int(before.st_size),
                  after.st_mtimespec.tv_sec == before.st_mtimespec.tv_sec,
                  after.st_mtimespec.tv_nsec == before.st_mtimespec.tv_nsec,
                  after.st_ctimespec.tv_sec == before.st_ctimespec.tv_sec,
                  after.st_ctimespec.tv_nsec == before.st_ctimespec.tv_nsec,
                  named.st_dev == before.st_dev, named.st_ino == before.st_ino else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try requireNoPending()
            let identity = "\(before.st_dev)|\(before.st_ino)|\(before.st_mode)|\(before.st_nlink)|\(before.st_size)|\(before.st_mtimespec.tv_sec)|\(before.st_mtimespec.tv_nsec)|\(before.st_ctimespec.tv_sec)|\(before.st_ctimespec.tv_nsec)"
            return (data, identity)
        }
    }

    /// Adds complete held/named ownership facts to the exact canonical
    /// pointer read. The first `control` also refuses its reserved temporary;
    /// the second held read must be the same bytes and physical inode.
    func originalRecoveryPointerFull(parent: Int32, name: String)
        throws -> (Data, OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact) {
        guard name == "current.json" || name == "retired.json" else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let first = try control(parent: parent, name: name)
        return try withOpen(parent: parent, name: name,
                            flags: O_RDONLY | O_NONBLOCK) { descriptor in
            var held = stat(), named = stat(), after = stat(), namedAfter = stat()
            guard Darwin.fstat(descriptor, &held) == 0,
                  Darwin.fstatat(parent, name, &named,
                      AT_SYMLINK_NOFOLLOW) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let fact = try OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact(held)
            guard fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                    .RegularFact(named)),
                  fact.checkedControlToken == first.1,
                  fact.size <= 4 * 1024 * 1024 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var bytes = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    guard bytes.count <= 4 * 1024 * 1024 - count else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    bytes.append(contentsOf: buffer.prefix(count))
                } else if count == 0 { break }
                else if errno != EINTR {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(parent, name, &namedAfter,
                      AT_SYMLINK_NOFOLLOW) == 0,
                  fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                      .RegularFact(after)),
                  fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                      .RegularFact(namedAfter)),
                  bytes.count == Int(fact.size),
                  bytes == first.0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return (bytes, fact)
        }
    }

    /// The original recovery owner holds EX/G across this read. The caller
    /// supplies the exact node from a checked full-tree walk, so a same-name
    /// replacement cannot be promoted merely by matching returned bytes.
    func sourceBytes(parent: Int32, name: String, node: CheckedTreeNode,
                     maximum: Int64) throws -> Data {
        guard maximum >= 0,
              maximum <= EvidenceCurationLimitsV1.maximumSourceBytes,
              node.fact.st_mode & S_IFMT == S_IFREG,
              node.fact.st_nlink == 1,
              node.fact.st_size >= 0, node.fact.st_size <= maximum,
              let expectedSHA256 = node.sha256 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return try withOpen(parent: parent, name: name,
                            flags: O_RDONLY | O_NONBLOCK) { descriptor in
            var held = stat(), named = stat()
            func requireExact() throws {
                guard Darwin.fstat(descriptor, &held) == 0,
                      Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                      held.st_dev == node.fact.st_dev,
                      held.st_ino == node.fact.st_ino,
                      held.st_mode == node.fact.st_mode,
                      held.st_nlink == node.fact.st_nlink,
                      held.st_size == node.fact.st_size,
                      held.st_mtimespec.tv_sec == node.fact.st_mtimespec.tv_sec,
                      held.st_mtimespec.tv_nsec == node.fact.st_mtimespec.tv_nsec,
                      held.st_ctimespec.tv_sec == node.fact.st_ctimespec.tv_sec,
                      held.st_ctimespec.tv_nsec == node.fact.st_ctimespec.tv_nsec,
                      named.st_dev == held.st_dev, named.st_ino == held.st_ino else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            try requireExact()
            var result = Data()
            var hasher = SHA256()
            var buffer = [UInt8](repeating: 0, count: 64 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    guard Int64(result.count) <= maximum - Int64(count) else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    buffer.withUnsafeBytes { raw in
                        hasher.update(bufferPointer: UnsafeRawBufferPointer(
                            start: raw.baseAddress, count: count))
                    }
                    result.append(contentsOf: buffer.prefix(count))
                } else if count == 0 { break }
                else if errno != EINTR {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            try requireExact()
            guard result.count == Int(node.fact.st_size),
                  hasher.finalize().map({ String(format: "%02x", $0) }).joined()
                    == expectedSHA256 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return result
        }
    }

    /// One classified node under its already checked parent. The file digest
    /// streams through this owner's descriptor; a directory proves its exact
    /// immediate names. All closes remain in withOpen/names quarantine.
    func requirePolicyNode(parent: Int32, name: String,
        expected: OriginalRecoveryProvisionalPolicyV1.Node) throws {
        let directory = expected.sha256 == nil
        let flags = O_RDONLY | O_NONBLOCK | (directory ? O_DIRECTORY : 0)
        try withOpen(parent: parent, name: name, flags: flags) { descriptor in
            var before = stat(), after = stat(), namedBefore = stat(), namedAfter = stat()
            guard Darwin.fstat(descriptor, &before) == 0,
                  Darwin.fstatat(parent, name, &namedBefore,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  expected.matches(before), expected.matches(namedBefore) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if let expectedSHA = expected.sha256 {
                guard try digestFile(descriptor, before: before) == expectedSHA else {
                    throw StoreGenerationFailure.dataPointerInvalid
