            guard Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(parent, name, &namedAfter,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  expected.matches(after), expected.matches(namedAfter) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
    }

    func treeWithNodes(parent: Int32, name: String) throws
        -> (digest: String, nodes: [CheckedTreeNode]) {
        var nodes = [CheckedTreeNode]()
        let digest = try tree(parent: parent, name: name,
            observeTypedNode: { nodes.append($0) })
        return (digest, nodes)
    }

    func tree(parent: Int32, name: String,
              observeNode: ((String, String, [String: String]) -> Void)? = nil,
              observeTypedNode: ((CheckedTreeNode) -> Void)? = nil) throws -> String {
        try requireSettled()
        var tokens = [String]()
        var nodeCount = 0
        var hasModel = false
        func walk(_ parent: Int32, _ name: String, _ path: String, _ depth: Int) throws {
            guard depth <= 64, nodeCount < 100_000 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            nodeCount += 1
            if !path.isEmpty {
                _ = try GenerationOwnedPathV1.classify(path, nodeType: .directory)
            }
            try withOpen(parent: parent, name: name, flags: O_RDONLY | O_DIRECTORY) { directory in
                var before = stat(), namedBefore = stat()
                guard Darwin.fstat(directory, &before) == 0,
                      before.st_mode & S_IFMT == S_IFDIR,
                      Darwin.fstatat(parent, name, &namedBefore, AT_SYMLINK_NOFOLLOW) == 0,
                      namedBefore.st_dev == before.st_dev,
                      namedBefore.st_ino == before.st_ino else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let initial = try names(in: directory)
                tokens.append("D|\(path)|\(before.st_dev)|\(before.st_ino)|\(before.st_mode)|\(before.st_mtimespec.tv_sec)|\(before.st_mtimespec.tv_nsec)|\(before.st_ctimespec.tv_sec)|\(before.st_ctimespec.tv_nsec)|\(initial.joined(separator: ","))")
                observeTypedNode?(CheckedTreeNode(path: path, fact: before, sha256: nil))
                if let observeNode {
                    observeNode(path, "directory", [
                        "device": String(before.st_dev), "inode": String(before.st_ino),
                        "mode": String(before.st_mode),
                        "mtime": "\(before.st_mtimespec.tv_sec).\(before.st_mtimespec.tv_nsec)",
                        "ctime": "\(before.st_ctimespec.tv_sec).\(before.st_ctimespec.tv_nsec)",
                        "membership": initial.joined(separator: "\u{0}")
                    ])
                }
                for child in initial {
                    guard !child.isEmpty, child != ".", child != "..",
                          !child.contains("/") else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    let childPath = path.isEmpty ? child : "\(path)/\(child)"
                    var named = stat()
                    guard Darwin.fstatat(directory, child, &named, AT_SYMLINK_NOFOLLOW) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    if named.st_mode & S_IFMT == S_IFDIR {
                        try walk(directory, child, childPath, depth + 1)
                    } else if named.st_mode & S_IFMT == S_IFREG {
                        nodeCount += 1
                        guard nodeCount < 100_000, named.st_nlink == 1 else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        _ = try GenerationOwnedPathV1.classify(childPath, nodeType: .regularFile)
                        if childPath == "model.sqlite" { hasModel = true }
                        try withOpen(parent: directory, name: child,
                                     flags: O_RDONLY | O_NONBLOCK) { file in
                            var start = stat(), end = stat(), renamed = stat()
                            guard Darwin.fstat(file, &start) == 0,
                                  start.st_mode & S_IFMT == S_IFREG,
                                  start.st_nlink == 1,
                                  start.st_dev == named.st_dev,
                                  start.st_ino == named.st_ino,
                                  start.st_size == named.st_size,
                                  start.st_size >= 0 else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            let hash = try digestFile(file, before: start)
                            guard Darwin.fstat(file, &end) == 0,
                                  Darwin.fstatat(directory, child, &renamed, AT_SYMLINK_NOFOLLOW) == 0,
                                  end.st_dev == start.st_dev, end.st_ino == start.st_ino,
                                  end.st_size == start.st_size, end.st_nlink == start.st_nlink,
                                  end.st_mtimespec.tv_sec == start.st_mtimespec.tv_sec,
                                  end.st_mtimespec.tv_nsec == start.st_mtimespec.tv_nsec,
                                  end.st_ctimespec.tv_sec == start.st_ctimespec.tv_sec,
                                  end.st_ctimespec.tv_nsec == start.st_ctimespec.tv_nsec,
                                  renamed.st_dev == start.st_dev, renamed.st_ino == start.st_ino else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            tokens.append("F|\(childPath)|\(start.st_dev)|\(start.st_ino)|\(start.st_mode)|\(start.st_nlink)|\(start.st_size)|\(start.st_mtimespec.tv_sec)|\(start.st_mtimespec.tv_nsec)|\(start.st_ctimespec.tv_sec)|\(start.st_ctimespec.tv_nsec)|\(hash)")
                            observeTypedNode?(CheckedTreeNode(
                                path: childPath, fact: start, sha256: hash))
                            if let observeNode {
                                observeNode(childPath, "file", [
                                    "device": String(start.st_dev), "inode": String(start.st_ino),
                                    "mode": String(start.st_mode), "nlink": String(start.st_nlink),
                                    "size": String(start.st_size),
                                    "mtime": "\(start.st_mtimespec.tv_sec).\(start.st_mtimespec.tv_nsec)",
                                    "ctime": "\(start.st_ctimespec.tv_sec).\(start.st_ctimespec.tv_nsec)",
                                    "sha256": hash
                                ])
                            }
                        }
                    } else { throw StoreGenerationFailure.dataPointerInvalid }
                }
                var after = stat(), namedAfter = stat()
                guard try names(in: directory) == initial,
                      Darwin.fstat(directory, &after) == 0,
                      Darwin.fstatat(parent, name, &namedAfter, AT_SYMLINK_NOFOLLOW) == 0,
                      after.st_dev == before.st_dev, after.st_ino == before.st_ino,
                      after.st_mtimespec.tv_sec == before.st_mtimespec.tv_sec,
                      after.st_mtimespec.tv_nsec == before.st_mtimespec.tv_nsec,
                      after.st_ctimespec.tv_sec == before.st_ctimespec.tv_sec,
                      after.st_ctimespec.tv_nsec == before.st_ctimespec.tv_nsec,
                      namedAfter.st_dev == before.st_dev, namedAfter.st_ino == before.st_ino else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        try walk(parent, name, "", 0)
        guard hasModel else { throw StoreGenerationFailure.dataGenerationMissing }
        try requireSettled()
        return StoreMigrationCanonicalJSONV1.sha256(Data(tokens.sorted().joined(separator: "\n").utf8))
    }

    /// Read a deletion cut against the immutable complete roster. Unlike the
    /// original generation walk this remains defined after model.sqlite has
    /// been unlinked. It observes all survivors, then admits only one exact
    /// postorder prefix of absent nodes; it never learns a replacement tree.
    func schema2ColdRosterCut(
        parent: Int32, generationName: String,
        generation: EraseSchema2ColdDeletionRosterV1.Generation,
        generationURL: URL,
        retainUncertainDescriptor: (Int32) -> Void,
        checkPolicy: Bool = true
    ) throws -> (deletedCount: Int, observedSHA256: String) {
        try requireSettled()
        guard generation.state == "present",
              generation.generationID == generationName,
              UUID(uuidString: generationName)?.uuidString.lowercased()
                == generationName,
              let nodes = generation.nodes,
              let deletionOrder = generation.deletionOrder,
              !nodes.isEmpty,
              nodes.first?.path == "",
              nodes.first?.kind == "directory",
              deletionOrder.count == nodes.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var expected: [String: EraseSchema2ColdDeletionRosterV1.Node] = [:]
        for node in nodes {
            guard expected.updateValue(node, forKey: node.path) == nil else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        guard expected.count == nodes.count,
              Set(deletionOrder) == Set(expected.keys) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        func fullFact(_ lhs: stat, _ rhs: stat) -> Bool {
            lhs.st_dev == rhs.st_dev && lhs.st_ino == rhs.st_ino &&
            lhs.st_mode == rhs.st_mode && lhs.st_nlink == rhs.st_nlink &&
            lhs.st_size == rhs.st_size &&
            lhs.st_mtimespec.tv_sec == rhs.st_mtimespec.tv_sec &&
            lhs.st_mtimespec.tv_nsec == rhs.st_mtimespec.tv_nsec &&
            lhs.st_ctimespec.tv_sec == rhs.st_ctimespec.tv_sec &&
            lhs.st_ctimespec.tv_nsec == rhs.st_ctimespec.tv_nsec
        }
        var observed: [String: (stat, String?)] = [:]
        func walk(_ parentFD: Int32, _ name: String,
            _ path: String, _ depth: Int) throws {
            guard depth <= 64,
                  let node = expected[path],
                  node.kind == "directory" else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try withOpen(parent: parentFD, name: name,
                flags: O_RDONLY | O_DIRECTORY) { directory in
                var before = stat(), namedBefore = stat()
                guard Darwin.fstat(directory, &before) == 0,
                      Darwin.fstatat(parentFD, name, &namedBefore,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      before.st_mode & S_IFMT == S_IFDIR,
                      fullFact(before, namedBefore),
                      observed[path] == nil else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                observed[path] = (before, nil)
                let children = try names(in: directory)
                for child in children {
                    guard !child.isEmpty, child != ".", child != "..",
                          !child.contains("/") else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    let childPath = path.isEmpty ? child
                        : "\(path)/\(child)"
                    guard let expectedChild = expected[childPath] else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    switch expectedChild.kind {
                    case "directory":
                        try walk(directory, child, childPath, depth + 1)
                    case "regular":
                        try withOpen(parent: directory, name: child,
                            flags: O_RDONLY | O_NONBLOCK) { file in
                            var first = stat(), named = stat(), last = stat()
                            guard Darwin.fstat(file, &first) == 0,
                                  Darwin.fstatat(directory, child, &named,
                                    AT_SYMLINK_NOFOLLOW) == 0,
                                  first.st_mode & S_IFMT == S_IFREG,
                                  first.st_nlink == 1,
                                  fullFact(first, named),
                                  observed[childPath] == nil else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            let sha = try digestFile(file, before: first)
                            guard Darwin.fstat(file, &last) == 0,
                                  Darwin.fstatat(directory, child, &named,
                                    AT_SYMLINK_NOFOLLOW) == 0,
                                  fullFact(first, last),
                                  fullFact(last, named) else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            observed[childPath] = (last, sha)
                        }
                    default:
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
                var after = stat(), namedAfter = stat()
                guard try names(in: directory) == children,
                      Darwin.fstat(directory, &after) == 0,
                      Darwin.fstatat(parentFD, name, &namedAfter,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      fullFact(before, after),
                      fullFact(after, namedAfter) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        var namedRoot = stat()
        if Darwin.fstatat(parent, generationName, &namedRoot,
                AT_SYMLINK_NOFOLLOW) != 0 {
            guard errno == ENOENT else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        } else {
            try walk(parent, generationName, "", 0)
        }
        let missing = Set(expected.keys).subtracting(observed.keys)
        let missingCount = missing.count
        guard missingCount <= deletionOrder.count,
              Set(deletionOrder.prefix(missingCount)) == missing else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        for (path, (fact, sha)) in observed {
            guard let node = expected[path],
                  node.device >= 0,
                  node.device <= Int64(dev_t.max),
                  node.inode <= UInt64(ino_t.max),
                  node.mode <= UInt32(mode_t.max),
                  node.links <= UInt64(nlink_t.max),
                  fact.st_dev == dev_t(node.device),
                  fact.st_ino == ino_t(node.inode),
                  fact.st_mode == mode_t(node.mode) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if node.kind == "regular" {
                guard fact.st_nlink == nlink_t(node.links),
                      fact.st_size == off_t(node.size),
                      fact.st_mtimespec.tv_sec == node.mtimeSeconds,
                      fact.st_mtimespec.tv_nsec == node.mtimeNanoseconds,
                      fact.st_ctimespec.tv_sec == node.ctimeSeconds,
                      fact.st_ctimespec.tv_nsec == node.ctimeNanoseconds,
                      sha == node.sha256 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            } else {
                let prefix = path.isEmpty ? "" : path + "/"
                let removedDirect = missing.compactMap { candidate -> String? in
                    guard candidate.hasPrefix(prefix),
                          candidate != path else { return nil }
                    let suffix = String(candidate.dropFirst(prefix.count))
                    return !suffix.isEmpty && !suffix.contains("/")
                        ? candidate : nil
                }
                let removedDirectories = removedDirect.filter {
                    expected[$0]?.kind == "directory"
                }.count
                guard node.links >= UInt64(removedDirectories),
                      fact.st_nlink == nlink_t(
                        node.links - UInt64(removedDirectories)),
                      fact.st_size >= 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                if removedDirect.isEmpty {
                    guard fact.st_size == off_t(node.size),
                          fact.st_mtimespec.tv_sec == node.mtimeSeconds,
                          fact.st_mtimespec.tv_nsec == node.mtimeNanoseconds,
                          fact.st_ctimespec.tv_sec == node.ctimeSeconds,
                          fact.st_ctimespec.tv_nsec == node.ctimeNanoseconds else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
            }
        }
        let observedTokens = observed.keys.sorted().compactMap { path
            -> String? in
            guard let (fact, sha) = observed[path] else { return nil }
            return "\(path)|\(fact.st_dev)|\(fact.st_ino)|\(fact.st_mode)|\(fact.st_nlink)|\(fact.st_size)|\(fact.st_mtimespec.tv_sec)|\(fact.st_mtimespec.tv_nsec)|\(fact.st_ctimespec.tv_sec)|\(fact.st_ctimespec.tv_nsec)|\(sha ?? "")"
        }
        guard observedTokens.count == observed.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let observedSHA256 = StoreMigrationCanonicalJSONV1.sha256(
            Data(observedTokens.joined(separator: "\n").utf8))
        guard generationURL.isFileURL,
              generationURL.lastPathComponent == generationName else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var policyCloseUncertain = false
        if checkPolicy { for path in observed.keys.sorted() {
            guard let (fact, _) = observed[path],
                  let node = expected[path] else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let kind: OwnedFileKindV1 = path.isEmpty
                ? .durableDirectory
                : try GenerationOwnedPathV1.classify(path,
                    nodeType: node.kind == "directory"
                        ? .directory : .regularFile).kind
            let url = path.isEmpty ? generationURL
                : generationURL.appendingPathComponent(path,
                    isDirectory: node.kind == "directory")
            let policy = try ProtectedFilePolicyV1
                .observeTemporalPolicyWithCheckedClose(kind, at: url,
                    retainUncertainDescriptor: { descriptor in
                        policyCloseUncertain = true
                        retainUncertainDescriptor(descriptor)
                    })
            guard !policyCloseUncertain,
                  policy.state == .strictComplete,
                  policy.device == UInt64(fact.st_dev),
                  policy.inode == UInt64(fact.st_ino),
                  policy.linkCount == UInt64(fact.st_nlink) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        } }
        try requireSettled()
        if checkPolicy {
            let after = try schema2ColdRosterCut(parent: parent,
                generationName: generationName,
                generation: generation,
                generationURL: generationURL,
                retainUncertainDescriptor: retainUncertainDescriptor,
                checkPolicy: false)
            guard after.deletedCount == missingCount,
                  after.observedSHA256 == observedSHA256 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        return (missingCount, observedSHA256)
    }

    /// Nonmutating, checked-close walk of an exact owner-held directory tree.
    /// Every transient descriptor remains here on an ambiguous close. This is
    /// intentionally independent of the generation-only path classifier.
    func postRetiredTree(parent: Int32, name: String,
        excluding excludedPaths: Set<String> = [],
        ignoringDirectoryMetadata ignoredDirectories: Set<String> = [],
        observedRootLinks: ((UInt64) -> Void)? = nil,
        normalizingSingleTargetManifestRootLinksFrom sourceRootLinks: UInt64? = nil,
        normalizingSingleRemovedFileDirectoryLinksFrom removedFile: (
            path: String, excludedChild: String, sourceLinks: UInt64)? = nil,
        observeNode: ((String, String, String, [String]?, String?) -> Void)? = nil,
        observeTypedNode: ((CheckedTreeNode, [String]?) -> Void)? = nil
    ) throws -> String {
        try requireSettled()
        if let removedFile {
            guard !removedFile.path.isEmpty,
                  !removedFile.excludedChild.isEmpty,
                  !removedFile.excludedChild.contains("/"),
                  removedFile.sourceLinks >= 2,
                  ignoredDirectories.contains(removedFile.path),
                  excludedPaths == Set([removedFile.path + "/"
                    + removedFile.excludedChild]) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        var tokens: [String] = []
        var nodeCount = 0
        var totalBytes: Int64 = 0
        var removedFileDirectorySeen = false
        // Directory names are adversarial UTF-8. Hex framing makes every
        // path and entry injective even when a name contains our token
        // separators, commas, newlines, or digits.
        func encoded(_ value: String) -> String {
            value.utf8.map { String(format: "%02x", $0) }.joined()
        }
        func nodeFact(_ value: stat) -> String {
            "\(value.st_dev)|\(value.st_ino)|\(value.st_mode)|\(value.st_nlink)|\(value.st_size)|\(value.st_mtimespec.tv_sec)|\(value.st_mtimespec.tv_nsec)|\(value.st_ctimespec.tv_sec)|\(value.st_ctimespec.tv_nsec)"
        }
        func stableDirectoryFact(_ value: stat, path: String) throws -> String {
            if ignoredDirectories.contains(path) {
                let links: UInt64
                if let removedFile, path == removedFile.path {
                    guard UInt64(value.st_nlink) == removedFile.sourceLinks - 1 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    links = removedFile.sourceLinks
                    removedFileDirectorySeen = true
                } else {
                    links = path.isEmpty
                        ? sourceRootLinks ?? UInt64(value.st_nlink)
                        : UInt64(value.st_nlink)
                }
                return "\(value.st_dev)|\(value.st_ino)|\(value.st_mode)|\(links)"
            }
            return nodeFact(value)
        }
        func walk(_ parent: Int32, _ name: String, _ path: String, _ depth: Int) throws {
            guard depth <= 64, nodeCount < 100_000 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            nodeCount += 1
            try withOpen(parent: parent, name: name,
                         flags: O_RDONLY | O_DIRECTORY) { directory in
                var before = stat(), named = stat()
                guard try selectedControlFStatV1(directory, &before) == 0,
                      before.st_mode & S_IFMT == S_IFDIR,
                      try selectedControlFStatAtV1(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                      named.st_dev == before.st_dev, named.st_ino == before.st_ino,
                      named.st_mode & S_IFMT == S_IFDIR,
                      selectedControlOwnerV1 == nil || Self.selectedControlFullStatEqualV1(before, named) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                if path.isEmpty {
                    observedRootLinks?(UInt64(before.st_nlink))
                    if let sourceRootLinks = sourceRootLinks {
                        guard ignoredDirectories.contains(""),
                              excludedPaths.count == 1,
                              sourceRootLinks < UInt64.max,
                              UInt64(before.st_nlink) == sourceRootLinks + 1 else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                }
                let entries = try names(in: directory)
                let visible = entries.filter { entry in
                    let child = path.isEmpty ? entry : "\(path)/\(entry)"
                    return !excludedPaths.contains(child)
                }
                let directoryFact = try stableDirectoryFact(before, path: path)
                tokens.append("D|\(encoded(path))|\(directoryFact)|\(visible.map(encoded).joined(separator: ","))")
                observeNode?(path, "directory", directoryFact, visible, nil)
                try selectedControlOwnerV1?.retainTreeNode(path: path, fact: before, members: visible, contentSHA256: nil)
                observeTypedNode?(CheckedTreeNode(path: path, fact: before,
                    sha256: nil), visible)
                for entry in visible {
                    guard !entry.isEmpty, entry != ".", entry != "..",
                          !entry.contains("/") else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    let childPath = path.isEmpty ? entry : "\(path)/\(entry)"
                    var child = stat()
                    guard try selectedControlFStatAtV1(directory, entry, &child,
                                         AT_SYMLINK_NOFOLLOW) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    switch child.st_mode & S_IFMT {
                    case S_IFDIR:
                        try walk(directory, entry, childPath, depth + 1)
                    case S_IFREG:
                        nodeCount += 1
                        guard nodeCount < 100_000, child.st_nlink == 1,
                              child.st_size >= 0, child.st_size <= 1_073_741_824,
                              totalBytes <= 1_073_741_824 - Int64(child.st_size) else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        totalBytes += Int64(child.st_size)
                        try withOpen(parent: directory, name: entry,
                                     flags: O_RDONLY | O_NONBLOCK) { file in
                            var start = stat(), end = stat(), namedAfter = stat()
                            guard try selectedControlFStatV1(file, &start) == 0,
                                  start.st_mode & S_IFMT == S_IFREG,
                                  start.st_nlink == 1,
                                  start.st_dev == child.st_dev,
                                  start.st_ino == child.st_ino,
                                  start.st_size == child.st_size else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            let digest = try digestFile(file, before: start)
                            guard try selectedControlFStatV1(file, &end) == 0,
                                  try selectedControlFStatAtV1(directory, entry, &namedAfter,
                                                AT_SYMLINK_NOFOLLOW) == 0,
                                  nodeFact(start) == nodeFact(end),
                                  nodeFact(start) == nodeFact(namedAfter),
                                  selectedControlOwnerV1 == nil || (Self.selectedControlFullStatEqualV1(start, end) && Self.selectedControlFullStatEqualV1(start, namedAfter)) else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            let fileFact = nodeFact(start)
                            tokens.append("F|\(encoded(childPath))|\(fileFact)|\(digest)")
                            observeNode?(childPath, "file", fileFact, nil, digest)
                            try selectedControlOwnerV1?.retainTreeNode(path: childPath, fact: start, members: nil, contentSHA256: digest)
                            observeTypedNode?(CheckedTreeNode(path: childPath,
                                fact: start, sha256: digest), nil)
                        }
                    default:
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
                var after = stat(), namedAfter = stat()
                guard try names(in: directory) == entries,
                      try selectedControlFStatV1(directory, &after) == 0,
                      try selectedControlFStatAtV1(parent, name, &namedAfter,
                                    AT_SYMLINK_NOFOLLOW) == 0,
                      nodeFact(before) == nodeFact(after),
                      nodeFact(before) == nodeFact(namedAfter),
                      selectedControlOwnerV1 == nil || (Self.selectedControlFullStatEqualV1(before, after) && Self.selectedControlFullStatEqualV1(before, namedAfter)) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        try walk(parent, name, "", 0)
        if removedFile != nil, !removedFileDirectorySeen {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireSettled()
        return StoreMigrationCanonicalJSONV1.sha256(
            Data(tokens.sorted().joined(separator: "\n").utf8))
    }

}

/// Closed typed storage roles for the cold Notification readonly kernel.
/// Counts are allocation DATA. Only the genuine Range reservation can issue
/// the retained lease before this owner's actual backing allocation.
enum ColdEraseScratchNotificationReadBackingKindV1: UInt8 {
    case nameEntries, nameUTF8Bytes, tokenEntries, tokenUTF8Bytes, readBytes, snapshotSlots
}

struct ColdEraseScratchNotificationReadNameEntryV1 {
    let offset: Int
    let length: Int
    var verified = false
}

struct ColdEraseScratchNotificationReadTokenEntryV1 {
    let offset: Int
    let length: Int
}

enum ColdEraseScratchNotificationReadSnapshotSlotV1 {
    case name(String)
    case tree(String, EraseSchema2ColdAuxiliaryFirstObserverV1.Tree)
    case child(String, EraseSchema2ColdAuxiliaryFirstObserverV1.OperationsChild)
    case control(EraseSchema2ColdAuxiliaryFirstObserverV1.ControlNode)
    case checkedNode(EraseAbortCheckedSnapshotIOV1.CheckedTreeNode)
    case policy(ColdEraseScratchNotificationControlPolicyObservationV1)
    case supportIdentity(EraseSchema2ColdAuxiliaryFirstObserverV1.ParentIdentity, String)
    case cacheIdentity(EraseSchema2ColdAuxiliaryFirstObserverV1.ParentIdentity)
    case temporaryIdentity(EraseSchema2ColdAuxiliaryFirstObserverV1.ParentIdentity)
    case supportTree(String, EraseSchema2ColdAuxiliaryFirstObserverV1.Tree)
    case operations(EraseSchema2ColdAuxiliaryFirstObserverV1.Tree)
    case ingressPresence(Bool), notificationPresence(Bool)
    case ingressControl(EraseSchema2ColdAuxiliaryFirstObserverV1.ControlNode)
    case notificationControl(EraseSchema2ColdAuxiliaryFirstObserverV1.ControlNode)
    case notificationStableDigest(String?)
    case cacheTree(EraseSchema2ColdAuxiliaryFirstObserverV1.Tree)
    case temporaryTree(EraseSchema2ColdAuxiliaryFirstObserverV1.Tree)
}

/// The pointers below are the REAL storage, not a mirror footprint. No
/// deinitializer silently releases an uncertain resource or reservation.
@MainActor final class ColdEraseScratchNotificationReadBackingV1 {
    private struct Storage {
        let reservation: ColdEraseScratchNotificationReadReservationV1
        let lease: ColdEraseScratchNotificationReadBackingLeaseV1
        weak var window: ColdEraseScratchNotificationReadWindowV1?
        weak var node: ColdEraseScratchNotificationReadNodeV1?
        let kind: ColdEraseScratchNotificationReadBackingKindV1
        let capacity: Int
        var allocated = false
        var released = false
        var names: UnsafeMutablePointer<ColdEraseScratchNotificationReadNameEntryV1>?
        var tokens: UnsafeMutablePointer<ColdEraseScratchNotificationReadTokenEntryV1>?
        var bytes: UnsafeMutablePointer<UInt8>?
        var snapshots: UnsafeMutablePointer<ColdEraseScratchNotificationReadSnapshotSlotV1?>?
    }
    private var storage: Storage
