        if storage.tokenCount > 1 {
            for i in stride(from: storage.tokenCount / 2 - 1, through: 0, by: -1) { sift(i, storage.tokenCount) }
            for end in stride(from: storage.tokenCount - 1, through: 1, by: -1) { swap(0, end); sift(0, end) }
