/// A checked, one-way close of the six directories held by the exact cleanup
/// authority. This grants no filesystem access after completion.
@MainActor
final class EraseGenerationAuthorityTerminalCloseReceiptV1 {
    private weak var authority: StoreRestoreGenerationAuthority?
    private weak var cleanup: EraseCleanupAfterRetirementV1?
    private weak var proof: ErasedRegistryRetirementProofV1?
    private let binding: EraseRetirementBindingV1

    fileprivate init(authority: StoreRestoreGenerationAuthority,
        cleanup: EraseCleanupAfterRetirementV1,
        proof: ErasedRegistryRetirementProofV1) {
        self.authority = authority
        self.cleanup = cleanup
        self.proof = proof
        binding = proof.binding
    }

    func matches(proof expected: ErasedRegistryRetirementProofV1) -> Bool {
        proof === expected
    }

    func matches(proof expectedProof: ErasedRegistryRetirementProofV1,
        cleanup expectedCleanup: EraseCleanupAfterRetirementV1,
        authority expectedAuthority: StoreRestoreGenerationAuthority) -> Bool {
        proof === expectedProof && cleanup === expectedCleanup
            && authority === expectedAuthority
    }

    /// Identity of the one completed close, never permission to read its FDs.
    func matchesSourceOwner(proof expectedProof: ErasedRegistryRetirementProofV1,
        authority expectedAuthority: StoreRestoreGenerationAuthority,
        binding expectedBinding: EraseRetirementBindingV1) -> Bool {
        proof === expectedProof && authority === expectedAuthority && cleanup != nil
            && binding == expectedBinding && expectedProof.binding == expectedBinding
            && expectedAuthority.eraseRetirementTerminalCloseAttempted
    }

    func matchesSourceDirectories(authority expectedAuthority: StoreRestoreGenerationAuthority,
        supportDevice: dev_t, supportInode: ino_t,
        dataDevice: dev_t, dataInode: ino_t) -> Bool {
        authority === expectedAuthority && proof != nil && cleanup != nil
            && expectedAuthority.matchesTerminalSourceDirectories(supportDevice: supportDevice,
                supportInode: supportInode, dataDevice: dataDevice, dataInode: dataInode)
    }

    func matchesSourcePointer(authority expectedAuthority: StoreRestoreGenerationAuthority,
        data: Data, fact: stat) -> Bool {
        authority === expectedAuthority && proof != nil && cleanup != nil
            && expectedAuthority.matchesTerminalSourcePointer(data: data, fact: fact)
    }

    func matchesSourceGenerationParent(authority expectedAuthority: StoreRestoreGenerationAuthority,
        fact: stat) -> Bool {
        authority === expectedAuthority && proof != nil && cleanup != nil
            && expectedAuthority.matchesTerminalSourceGenerationParent(fact)
    }
}

final class StoreRestoreGenerationAuthority {
    struct Identity: Equatable {
        let device: dev_t
        let inode: ino_t
    }

    fileprivate struct RegularFileIdentity: Equatable {
        let device: dev_t
        let inode: ino_t
        let linkCount: nlink_t
    }

    fileprivate struct RegularFileRead {
        let data: Data
        let identity: RegularFileIdentity
    }

    private struct EraseRetirementFileFact: Equatable {
        let device: dev_t, inode: ino_t, mode: mode_t, links: nlink_t
        let size: off_t
        let modifiedSeconds: Int64, modifiedNanoseconds: Int64
        let changedSeconds: Int64, changedNanoseconds: Int64

        init(_ value: stat) {
            device = value.st_dev; inode = value.st_ino
            mode = value.st_mode; links = value.st_nlink; size = value.st_size
            modifiedSeconds = Int64(value.st_mtimespec.tv_sec)
            modifiedNanoseconds = Int64(value.st_mtimespec.tv_nsec)
            changedSeconds = Int64(value.st_ctimespec.tv_sec)
            changedNanoseconds = Int64(value.st_ctimespec.tv_nsec)
        }
    }

    private struct EraseRetirementPointerRead: Equatable {
        let data: Data
        let identity: RegularFileIdentity
        let fact: EraseRetirementFileFact
    }

    private enum EraseRetirementPointerProvenance {
        case captured(data: Data, fact: String)
        case published(data: Data, fact: String)
    }

    private var eraseRetirementPointerProvenance: [String: EraseRetirementPointerProvenance] = [:]

    private static func eraseRetirementFactToken(_ fact: EraseRetirementFileFact) -> String {
        "\(fact.device)|\(fact.inode)|\(fact.mode)|\(fact.links)|\(fact.size)|\(fact.modifiedSeconds)|\(fact.modifiedNanoseconds)|\(fact.changedSeconds)|\(fact.changedNanoseconds)"
    }

    /// An authorized name swap may change inode ctime. It cannot change the
    /// source's device, inode, mode, link count, size or content mtime. The
    /// full post-swap fact is captured anew before a later policy request.
    private static func eraseRetirementFactBeforeRenameMatches(
        _ captured: String, _ observed: EraseRetirementFileFact
    ) -> Bool {
        let before = captured.split(separator: "|", omittingEmptySubsequences: false)
        let after = eraseRetirementFactToken(observed).split(
            separator: "|", omittingEmptySubsequences: false)
        return before.count == 9 && after.count == 9
            && before.prefix(7).elementsEqual(after.prefix(7))
    }

    @MainActor
    fileprivate func captureEraseRetirementPointerProvenance(currentData: Data) throws {
        try verify()
        try eraseRetirementCheckedSnapshotIO.requireSettled()
        let current = try eraseRetirementCheckedSnapshotIO.control(
            parent: dataDescriptor, name: "current.json")
        let retired = try eraseRetirementCheckedSnapshotIO.control(
            parent: dataDescriptor, name: "retired.json")
        guard current.0 == currentData,
              try CurrentPointerCodecV1.decode(current.0).data == currentData else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let retiredPointer: RetiredPointerV1 = try Self.decodeCanonicalPointer(retired.0)
        try StorePointerSchemaRegistry.requireRetired(retiredPointer.schemaVersion)
        try eraseRetirementCheckedSnapshotIO.requireSettled()
        try verify()
        if eraseRetirementPointerProvenance.isEmpty {
            eraseRetirementPointerProvenance = [
                "current.json": .captured(data: current.0, fact: current.1),
                "retired.json": .captured(data: retired.0, fact: retired.1)
            ]
        } else {
            guard case .captured(let currentBytes, let currentFact)? =
                    eraseRetirementPointerProvenance["current.json"],
                  currentBytes == current.0, currentFact == current.1,
                  case .captured(let retiredBytes, let retiredFact)? =
                    eraseRetirementPointerProvenance["retired.json"],
                  retiredBytes == retired.0, retiredFact == retired.1 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
    }

    private struct EraseRetirementTreeWitness: Equatable {
        let checkedTreeDigest: String
        let paths: [String]
        let directoryPaths: [String]
        let facts: [EraseRetirementFileFact]
        let files: [StoreGenerationFileDigestV1]
    }

    private var eraseRetirementUncertainDescriptors: [Int32] = []
    private let eraseRetirementCheckedSnapshotIO = EraseAbortCheckedSnapshotIOV1()
    private let originalErasePointerCheckedIO = EraseAbortCheckedSnapshotIOV1()
    private var originalErasePointerEffectUncertain = false

    fileprivate struct OriginalEraseCheckedPointerReadV1: Equatable {
        let data: Data
        let fact: OriginalErasePointerFullFactV1
    }

    fileprivate struct OriginalErasePointerSiblingNodeV1: Equatable {
        let path: String
        let fact: OriginalErasePointerFullFactV1
        let names: [String]?
        let sha256: String?
    }

    fileprivate struct OriginalErasePointerSiblingImageV1: Equatable {
        let nodes: [OriginalErasePointerSiblingNodeV1]
        let dataDirectoryChildren: Int
    }

    /// Minted only after the exact original-operation Data writer has closed
    /// every child descriptor and reached its terminal no-temp postimage.
    @MainActor
    final class OriginalErasePointerReceiptV1 {
        fileprivate weak var authority: StoreRestoreGenerationAuthority?
        fileprivate let operationID: ObjectIdentifier
        fileprivate let stage: OriginalEraseRetainedPointerStageV1
        fileprivate let source: OriginalEraseCheckedPointerReadV1
        fileprivate let published: OriginalEraseCheckedPointerReadV1
        fileprivate let other: OriginalEraseCheckedPointerReadV1
        fileprivate let names: [String]
        fileprivate let root: OriginalErasePointerFullFactV1
        fileprivate let siblings: OriginalErasePointerSiblingImageV1
        fileprivate let predecessor: OriginalErasePointerReceiptV1?
        fileprivate weak var successor: OriginalErasePointerReceiptV1?
        fileprivate var publicationSettlement: OriginalEraseRetainedPointerPublicationSettlementV1?
        // Immutable publication/origin remains above. Only a completed SAME
        // operation's checked physical transition can supply this successor.
        fileprivate var physicalSuccessor: OriginalErasePointerPhysicalSuccessorV1?
        /// Typed stored cells match this actual Receipt declaration. Heap
        /// headers, Foundation allocation and whole owner Scope remain DUE.
        fileprivate struct PublicationStoredCellProfile {
            weak var authority: StoreRestoreGenerationAuthority?
            let operationID: ObjectIdentifier
            let stage: OriginalEraseRetainedPointerStageV1
            let source: OriginalEraseCheckedPointerReadV1
            let published: OriginalEraseCheckedPointerReadV1
            let other: OriginalEraseCheckedPointerReadV1
            let names: [String]
            let root: OriginalErasePointerFullFactV1
            let siblings: OriginalErasePointerSiblingImageV1
            let predecessor: OriginalErasePointerReceiptV1?
            weak var successor: OriginalErasePointerReceiptV1?
            let publicationSettlement: OriginalEraseRetainedPointerPublicationSettlementV1?
            let physicalSuccessor: OriginalErasePointerPhysicalSuccessorV1?
        }

        fileprivate init(
            authority: StoreRestoreGenerationAuthority,
            operation: EraseRouterOperationV1,
            stage: OriginalEraseRetainedPointerStageV1,
            source: OriginalEraseCheckedPointerReadV1,
            published: OriginalEraseCheckedPointerReadV1,
            other: OriginalEraseCheckedPointerReadV1,
            names: [String],
            root: OriginalErasePointerFullFactV1,
            siblings: OriginalErasePointerSiblingImageV1,
            predecessor: OriginalErasePointerReceiptV1?
        ) {
            self.authority = authority
            operationID = ObjectIdentifier(operation)
            self.stage = stage
            self.source = source
            self.published = published
            self.other = other
            self.names = names
            self.root = root
            self.siblings = siblings
            self.predecessor = predecessor
        }

        func requireCompletedOriginalErasePointerPublication(
            authority: StoreRestoreGenerationAuthority,
            operation: EraseRouterOperationV1
        ) throws -> OriginalEraseRetainedPointerPublicationSettlementV1 {
            guard let actual = publicationSettlement else { throw StoreGenerationFailure.dataPointerInvalid }
            try actual.requirePermanentOriginalErasePointerData(authority: authority,
                operation: operation, receipt: self)
            return actual
        }

        func requireBound(
            authority: StoreRestoreGenerationAuthority,
            operation: EraseRouterOperationV1,
            stage: OriginalEraseRetainedPointerStageV1,
            predecessor: OriginalErasePointerReceiptV1?
        ) throws {
            guard self.authority === authority,
                  operationID == ObjectIdentifier(operation),
                  self.stage == stage,
                  self.predecessor === predecessor else {
                #if DEBUG
                print("ORIGINAL_POINTER_RECEIPT_BIND_V1 stage=identity")
                #endif
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if stage == .current, let successor {
                guard successor.predecessor === self else {
                    #if DEBUG
                    print("ORIGINAL_POINTER_RECEIPT_BIND_V1 stage=successor")
                    #endif
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try successor.requireBound(authority: authority,
                    operation: operation, stage: .retired, predecessor: self)
                return
            }
            try authority.requireOriginalErasePointerPostimage(self)
        }

        func currentGenerationID() throws -> UUID {
            let bytes = stage == .current ? published.data : other.data
            let value = try CurrentPointerCodecV1.decode(bytes)
            guard let id = UUID(uuidString: value.generationID),
                  StoreRestoreGenerationAuthority.canonical(id)
                    == value.generationID else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return id
        }

        func retiredGenerationIDs() throws -> [UUID] {
            do {
                let bytes = stage == .retired ? published.data : other.data
                let value = try JSONDecoder().decode(RetiredPointerV1.self,
                    from: bytes)
                try StorePointerSchemaRegistry.requireRetired(
                    value.schemaVersion)
                let ids = value.generationIDs.compactMap(UUID.init(uuidString:))
                let names = ids.map(StoreRestoreGenerationAuthority.canonical)
                guard ids.count == value.generationIDs.count,
                      names == value.generationIDs,
                      names == names.sorted(),
                      Set(ids).count == ids.count,
                      bytes == (try StoreRestoreGenerationAuthority
                        .canonicalOriginalEraseRetiredData(ids)) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                return ids
            } catch {
                #if DEBUG
                print("ORIGINAL_POINTER_RETIRED_READ_V1 stage=canonical-decode")
                #endif
                throw error
            }
        }
    }

    fileprivate struct OriginalErasePhysicalImageV1 {
        let siblings: OriginalErasePointerSiblingImageV1
        let sourceID: UUID
        let targetID: UUID
        let sourceSQLite: CompletedAbortSQLitePhysicalImageV1
        let targetSQLite: CompletedAbortSQLitePhysicalImageV1
    }

    /// A separate successor, bound to the genuine P publication and its
    /// operation. No pointer, origin or first cohort is recaptured or changed.
    @MainActor
    fileprivate final class OriginalErasePointerPhysicalSuccessorV1 {
        weak var authority: StoreRestoreGenerationAuthority?
        weak var operation: EraseRouterOperationV1?
        unowned let receipt: OriginalErasePointerReceiptV1
        let predecessor: OriginalErasePointerPhysicalSuccessorV1?
        let image: OriginalErasePhysicalImageV1
        init(authority: StoreRestoreGenerationAuthority,
             operation: EraseRouterOperationV1,
             receipt: OriginalErasePointerReceiptV1,
             predecessor: OriginalErasePointerPhysicalSuccessorV1?,
             image: OriginalErasePhysicalImageV1) {
            self.authority = authority; self.operation = operation
            self.receipt = receipt; self.predecessor = predecessor; self.image = image
        }
        func requireBound(authority expected: StoreRestoreGenerationAuthority,
                          receipt expectedReceipt: OriginalErasePointerReceiptV1) throws {
            guard authority === expected, receipt === expectedReceipt,
                  let operation, receipt.operationID == ObjectIdentifier(operation),
                  predecessor.map({ $0.receipt === receipt && $0.authority === expected }) ?? true else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try operation.requireSettledOriginalErasePhysicalTransition()
        }
    }

    /// Retained before the first real constructor or alias release. A failed
    /// constructor/observer/close permanently retains this uncertain owner.
    @MainActor
    final class OriginalErasePhysicalTransitionV1 {
        fileprivate weak var authority: StoreRestoreGenerationAuthority?
        fileprivate weak var operation: EraseRouterOperationV1?
        fileprivate let receipt: OriginalErasePointerReceiptV1
        fileprivate let origin: OriginalErasePhysicalImageV1
        fileprivate var checkedImage: OriginalErasePhysicalImageV1
        fileprivate var sourceAliasOrigin: OriginalErasePhysicalImageV1?
        fileprivate var shutdownAliasOrigin: OriginalErasePhysicalImageV1?
        fileprivate var pendingStage: OriginalErasePhysicalTransitionStageV1?
        fileprivate var pendingImage: OriginalErasePhysicalImageV1?
        fileprivate var uncertain = false
        fileprivate init(authority: StoreRestoreGenerationAuthority,
                         operation: EraseRouterOperationV1,
                         receipt: OriginalErasePointerReceiptV1,
                         image: OriginalErasePhysicalImageV1,
                         stage: OriginalErasePhysicalTransitionStageV1) {
            self.authority = authority; self.operation = operation; self.receipt = receipt
            origin = image; checkedImage = image; pendingStage = stage
        }
        func markUncertain() { uncertain = true }
        fileprivate func requireBound(authority expected: StoreRestoreGenerationAuthority,
                                      operation expectedOperation: EraseRouterOperationV1) throws {
            guard !uncertain, authority === expected, operation === expectedOperation,
                  receipt.authority === expected,
                  receipt.operationID == ObjectIdentifier(expectedOperation) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
    }

    @MainActor
    private func captureOriginalErasePhysicalImage(
        receipt: OriginalErasePointerReceiptV1,
        operation: EraseRouterOperationV1
    ) throws -> OriginalErasePhysicalImageV1 {
        guard receipt.authority === self, receipt.operationID == ObjectIdentifier(operation),
              receipt.stage == .retired, let predecessor = receipt.predecessor,
              predecessor.stage == .current,
              try originalEraseDataRootFact() == receipt.root,
              try originalErasePointerCheckedIO.names(in: dataDescriptor) == receipt.names,
              try originalEraseCheckedPointerRead("current.json") == receipt.other,
              try originalEraseCheckedPointerRead("retired.json") == receipt.published else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let oldPointer = try CurrentPointerCodecV1.decode(predecessor.source.data)
        guard let sourceID = UUID(uuidString: oldPointer.generationID),
              Self.canonical(sourceID) == oldPointer.generationID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let targetID = try receipt.currentGenerationID()
        guard sourceID != targetID else { throw StoreGenerationFailure.dataPointerInvalid }
        let siblings = try originalErasePointerSiblingImage(dataNames: receipt.names)
        func captureSQLite(id: UUID) throws -> CompletedAbortSQLitePhysicalImageV1 {
            let prefix = "generations/" + Self.canonical(id)
            func requireOpened(_ descriptor: Int32, parent: Int32, name: String,
                               path: String) throws {
                guard let node = siblings.nodes.first(where: { $0.path == path }),
                      siblings.nodes.filter({ $0.path == path }).count == 1 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                var held = stat(), named = stat()
                guard Darwin.fstat(descriptor, &held) == 0,
                      Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                      OriginalErasePointerFullFactV1(held) == node.fact,
                      OriginalErasePointerFullFactV1(named) == node.fact else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            return try originalErasePointerCheckedIO.withOpen(
                parent: installedGenerationsDescriptor, name: Self.canonical(id),
                flags: O_RDONLY | O_DIRECTORY | O_NONBLOCK) { generation in
                    try requireOpened(generation, parent: installedGenerationsDescriptor,
                        name: Self.canonical(id), path: prefix)
                    let image = try originalErasePointerCheckedIO.withOpen(
                        parent: generation, name: "model.sqlite", flags: O_RDONLY | O_NONBLOCK) { model in
                            try requireOpened(model, parent: generation, name: "model.sqlite",
                                path: prefix + "/model.sqlite")
                            let result: CompletedAbortSQLitePhysicalImageV1
                            if siblings.nodes.contains(where: { $0.path == prefix + "/model.sqlite-wal" }) {
                                result = try originalErasePointerCheckedIO.withOpen(
                                    parent: generation, name: "model.sqlite-wal", flags: O_RDONLY | O_NONBLOCK) { wal in
                                        try requireOpened(wal, parent: generation, name: "model.sqlite-wal",
                                            path: prefix + "/model.sqlite-wal")
                                        let captured = try CompletedAbortSQLitePhysicalImageV1.capture(model: model, wal: wal)
                                        try requireOpened(wal, parent: generation, name: "model.sqlite-wal",
                                            path: prefix + "/model.sqlite-wal")
                                        return captured
                                    }
                            } else { result = try CompletedAbortSQLitePhysicalImageV1.capture(model: model, wal: nil) }
                            try requireOpened(model, parent: generation, name: "model.sqlite",
                                path: prefix + "/model.sqlite")
                            return result
                        }
                    try requireOpened(generation, parent: installedGenerationsDescriptor,
                        name: Self.canonical(id), path: prefix)
                    return image
                }
        }
        let sourceSQLite = try captureSQLite(id: sourceID)
        let targetSQLite = try captureSQLite(id: targetID)
        guard try originalErasePointerSiblingImage(dataNames: receipt.names) == siblings,
              try originalEraseDataRootFact() == receipt.root,
              try originalErasePointerCheckedIO.names(in: dataDescriptor) == receipt.names,
              try originalEraseCheckedPointerRead("current.json") == receipt.other,
              try originalEraseCheckedPointerRead("retired.json") == receipt.published else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalErasePointerCheckedIO.requireSettled()
        return OriginalErasePhysicalImageV1(siblings: siblings, sourceID: sourceID,
            targetID: targetID, sourceSQLite: sourceSQLite, targetSQLite: targetSQLite)
    }

    /// Full tree conservation plus the existing page-complete SQLite/WAL
    /// frontier proof. Only the exact owned generation roots and SQLite leaves
    /// may change representation; every other byte, time, identity and member
    /// stays strict. Same-byte inode replacement is always refused.
    private func requireOriginalErasePhysicalTransition(
        from before: OriginalErasePhysicalImageV1,
        to after: OriginalErasePhysicalImageV1,
        allowing generationIDs: Set<UUID>
    ) throws {
        guard before.sourceID == after.sourceID, before.targetID == after.targetID,
              before.siblings.dataDirectoryChildren == after.siblings.dataDirectoryChildren,
              before.siblings.nodes.count == after.siblings.nodes.count,
              generationIDs.isSubset(of: [before.sourceID, before.targetID]) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let prefixes = generationIDs.map { "generations/" + Self.canonical($0) }
        for (old, new) in zip(before.siblings.nodes, after.siblings.nodes) {
            guard old.path == new.path, old.names == new.names else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if prefixes.contains(old.path) {
                guard old.fact.sameDirectoryIdentity(as: new.fact), old.fact.links == new.fact.links else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            } else if let prefix = prefixes.first(where: { old.path.hasPrefix($0 + "/") }),
                      ["model.sqlite", "model.sqlite-wal", "model.sqlite-shm"].contains(
                        String(old.path.dropFirst(prefix.count + 1))) {
                guard old.fact.device == new.fact.device, old.fact.inode == new.fact.inode,
                      old.fact.mode == new.fact.mode, old.fact.owner == new.fact.owner,
                      old.fact.group == new.fact.group, old.fact.links == new.fact.links,
                      old.fact.links == 1, old.fact.mode & S_IFMT == S_IFREG else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                if old.path == prefix + "/model.sqlite-shm", old.fact.size != new.fact.size {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            } else if old != new { throw StoreGenerationFailure.dataPointerInvalid }
        }
        try before.sourceSQLite.requireOwnedCloseTransition(to: after.sourceSQLite)
        try before.targetSQLite.requireOwnedCloseTransition(to: after.targetSQLite)
    }

    @MainActor
    func beginOriginalErasePhysicalTransition(
        receipt: OriginalErasePointerReceiptV1,
        operation: EraseRouterOperationV1,
        stage: OriginalErasePhysicalTransitionStageV1
    ) throws -> OriginalErasePhysicalTransitionV1 {
        try receipt.requireBound(authority: self, operation: operation,
            stage: .retired, predecessor: receipt.predecessor)
        let image = try captureOriginalErasePhysicalImage(receipt: receipt, operation: operation)
        guard image.siblings == (receipt.physicalSuccessor?.image.siblings ?? receipt.siblings) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return OriginalErasePhysicalTransitionV1(authority: self, operation: operation,
            receipt: receipt, image: image, stage: stage)
    }

    @MainActor
    func completeOriginalEraseTargetConstructor(
        _ transition: OriginalErasePhysicalTransitionV1,
        operation: EraseRouterOperationV1
    ) throws {
        try transition.requireBound(authority: self, operation: operation)
        guard transition.pendingStage == .targetConstructor, transition.pendingImage == nil else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let after = try captureOriginalErasePhysicalImage(receipt: transition.receipt, operation: operation)
        try requireOriginalErasePhysicalTransition(from: transition.origin, to: after,
            allowing: [transition.origin.targetID])
        transition.pendingImage = after
    }

    @MainActor
    func armOriginalEraseSourceAliasRelease(
        _ transition: OriginalErasePhysicalTransitionV1,
        operation: EraseRouterOperationV1
    ) throws {
        try transition.requireBound(authority: self, operation: operation)
        guard transition.pendingStage == nil, transition.sourceAliasOrigin == nil,
              transition.shutdownAliasOrigin == nil else { throw StoreGenerationFailure.dataPointerInvalid }
        // The existing real writer constructor/recovery used this SAME target
        // context. Conserve it, while the source remains the exact pre-release
        // tree; the Coordinator has not yet replaced its original aliases.
        let before = try captureOriginalErasePhysicalImage(receipt: transition.receipt, operation: operation)
        try requireOriginalErasePhysicalTransition(from: transition.checkedImage, to: before,
            allowing: [transition.origin.targetID])
        try requireOriginalErasePhysicalTransition(from: transition.origin, to: before,
            allowing: [transition.origin.targetID])
        transition.sourceAliasOrigin = before
        transition.pendingStage = .sourceOwnerHandoff
        transition.pendingImage = before
#if DEBUG
        try StoreGenerationFactory.fireOriginalErasePhysicalTransitionTestHook(
            operation: operation, applicationSupportURL: applicationSupportURL,
            stage: .sourceOwnerHandoff)
#endif
    }

#if DEBUG
    @MainActor
    func armOriginalEraseShutdownAliasRelease(
        _ transition: OriginalErasePhysicalTransitionV1,
        operation: EraseRouterOperationV1
    ) throws {
        try transition.requireBound(authority: self, operation: operation)
        guard transition.shutdownAliasOrigin == nil,
              transition.pendingStage == nil || transition.pendingStage == .shutdownAliasRelease,
              transition.pendingImage == nil else { throw StoreGenerationFailure.dataPointerInvalid }
        let before = try captureOriginalErasePhysicalImage(receipt: transition.receipt, operation: operation)
        let allowed: Set<UUID> = transition.sourceAliasOrigin == nil
            ? [transition.origin.targetID] : [transition.origin.sourceID, transition.origin.targetID]
        try requireOriginalErasePhysicalTransition(from: transition.checkedImage, to: before, allowing: allowed)
        try requireOriginalErasePhysicalTransition(from: transition.origin, to: before, allowing: allowed)
        transition.shutdownAliasOrigin = before
        transition.pendingStage = .shutdownAliasRelease
        transition.pendingImage = before
    }

    @MainActor
    func completeOriginalEraseDrainedShutdownTransition(
        _ transition: OriginalErasePhysicalTransitionV1,
        operation: EraseRouterOperationV1
    ) throws {
        try transition.requireBound(authority: self, operation: operation)
        guard transition.pendingStage == nil, let before = transition.shutdownAliasOrigin else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try StoreGenerationFactory.fireOriginalErasePhysicalTransitionTestHook(
            operation: operation, applicationSupportURL: applicationSupportURL,
            stage: .drainedShutdown)
        let after = try captureOriginalErasePhysicalImage(receipt: transition.receipt, operation: operation)
        let allowed: Set<UUID> = [transition.origin.sourceID, transition.origin.targetID]
        try requireOriginalErasePhysicalTransition(from: before, to: after, allowing: allowed)
        try requireOriginalErasePhysicalTransition(from: transition.origin, to: after, allowing: allowed)
        transition.pendingStage = .drainedShutdown
        transition.pendingImage = after
    }
#endif

    @MainActor
    func settleOriginalErasePhysicalTransition(
        _ transition: OriginalErasePhysicalTransitionV1,
        operation: EraseRouterOperationV1,
        stage: OriginalErasePhysicalTransitionStageV1
    ) throws {
        try transition.requireBound(authority: self, operation: operation)
        guard transition.pendingStage == stage, let after = transition.pendingImage else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let successor = OriginalErasePointerPhysicalSuccessorV1(authority: self, operation: operation,
            receipt: transition.receipt, predecessor: transition.receipt.physicalSuccessor, image: after)
        transition.receipt.physicalSuccessor = successor
        transition.checkedImage = after
        transition.pendingImage = nil
        transition.pendingStage = nil
    }

    private func originalEraseDataRootFact() throws -> OriginalErasePointerFullFactV1 {
        try requireCheckedEraseRetirementWriterAuthority()
        try originalErasePointerCheckedIO.requireSettled()
        var held = stat(), named = stat()
        guard Darwin.fstat(dataDescriptor, &held) == 0,
              Darwin.fstatat(applicationSupportDescriptor, Self.dataName,
                  &named, AT_SYMLINK_NOFOLLOW) == 0,
              held.st_mode & S_IFMT == S_IFDIR,
              OriginalErasePointerFullFactV1(held)
                  == OriginalErasePointerFullFactV1(named) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return OriginalErasePointerFullFactV1(held)
    }

    /// Freeze every non-pointer Data child before the first O_EXCL. Later
    /// checks walk exactly this image; a stable directory name alone cannot
    /// authorize a changed migration or generation subtree.
    private func originalErasePointerSiblingImage(
        dataNames: [String],
        diagnosticTargetID: String? = nil,
        diagnosticSourceID: String? = nil
    ) throws -> OriginalErasePointerSiblingImageV1 {
        var nodes = [OriginalErasePointerSiblingNodeV1]()
        var directoryChildren = 0
        #if DEBUG
        var reportedScanFailure = false
        #endif
        func walk(parent: Int32, name: String, path: String,
                  depth: Int) throws {
            do {
            guard depth <= 64, nodes.count < 100_000,
                  !name.isEmpty, name != ".", name != "..",
                  !name.contains("/") else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var firstNamed = stat()
            guard Darwin.fstatat(parent, name, &firstNamed,
                    AT_SYMLINK_NOFOLLOW) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let kind = firstNamed.st_mode & S_IFMT
            guard kind == S_IFDIR || (kind == S_IFREG && firstNamed.st_nlink == 1) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let flags: Int32 = kind == S_IFDIR
                ? O_RDONLY | O_DIRECTORY | O_NONBLOCK
                : O_RDONLY | O_NONBLOCK
            try originalErasePointerCheckedIO.withOpen(
                parent: parent, name: name, flags: flags
            ) { descriptor in
                var held = stat(), named = stat()
                guard Darwin.fstat(descriptor, &held) == 0,
                      Darwin.fstatat(parent, name, &named,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      OriginalErasePointerFullFactV1(held)
                        == OriginalErasePointerFullFactV1(firstNamed),
                      OriginalErasePointerFullFactV1(named)
                        == OriginalErasePointerFullFactV1(firstNamed) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                if kind == S_IFDIR {
                    let children = try originalErasePointerCheckedIO.names(
                        in: descriptor)
                    nodes.append(OriginalErasePointerSiblingNodeV1(
                        path: path,
                        fact: OriginalErasePointerFullFactV1(firstNamed),
                        names: children, sha256: nil))
                    for child in children {
                        try walk(parent: descriptor, name: child,
                            path: "\(path)/\(child)", depth: depth + 1)
                    }
                    guard try originalErasePointerCheckedIO.names(in: descriptor)
                            == children else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                } else {
                    var hash = SHA256()
                    var buffer = [UInt8](repeating: 0, count: 64 * 1024)
                    var total: Int64 = 0
                    while true {
                        let count = buffer.withUnsafeMutableBytes {
                            Darwin.read(descriptor, $0.baseAddress, $0.count)
                        }
                        if count > 0 {
                            total += Int64(count)
                            guard total <= Int64(firstNamed.st_size) else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            buffer.withUnsafeBytes { raw in
                                hash.update(bufferPointer: UnsafeRawBufferPointer(
                                    start: raw.baseAddress, count: count))
                            }
                        } else if count == 0 { break }
                        else if errno != EINTR {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                    guard total == Int64(firstNamed.st_size) else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    nodes.append(OriginalErasePointerSiblingNodeV1(
                        path: path,
                        fact: OriginalErasePointerFullFactV1(firstNamed),
                        names: nil,
                        sha256: hash.finalize().map {
                            String(format: "%02x", $0)
                        }.joined()))
                }
                guard Darwin.fstat(descriptor, &held) == 0,
                      Darwin.fstatat(parent, name, &named,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      OriginalErasePointerFullFactV1(held)
                        == OriginalErasePointerFullFactV1(firstNamed),
                      OriginalErasePointerFullFactV1(named)
                        == OriginalErasePointerFullFactV1(firstNamed) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            } catch {
                #if DEBUG
                if !reportedScanFailure {
                    let category = originalErasePointerSiblingClassify(
                        path, targetID: diagnosticTargetID,
                        sourceID: diagnosticSourceID)
                    print("ORIGINAL_POINTER_SIBLING_SCAN_V1 role=\(category.role) node=\(category.node)")
                    reportedScanFailure = true
                }
                #endif
                throw error
            }
        }
        for name in dataNames where name != "current.json"
            && name != "retired.json"
            && name != ".current.json.restore-next"
            && name != ".retired.json.restore-next" {
            var named = stat()
            guard Darwin.fstatat(dataDescriptor, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if named.st_mode & S_IFMT == S_IFDIR {
                directoryChildren += 1
            }
            try walk(parent: dataDescriptor, name: name,
                path: name, depth: 0)
        }
        guard try originalErasePointerCheckedIO.names(in: dataDescriptor)
                == dataNames else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return OriginalErasePointerSiblingImageV1(
            nodes: nodes, dataDirectoryChildren: directoryChildren)
    }

    private func originalErasePointerRootLinks(
        firstRoot: OriginalErasePointerFullFactV1,
        firstNames: [String],
        siblings: OriginalErasePointerSiblingImageV1,
        temporaryPresent: Bool
    ) throws -> nlink_t {
        // Both platform directory-link conventions are admitted only when
        // the complete first census proves which law this inode follows.
        guard firstNames.count <= Int.max - 3,
              siblings.dataDirectoryChildren <= Int.max - 2,
              let initial = Int(exactly: firstRoot.links) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let allEntry = 2 + firstNames.count
        let subdirectory = 2 + siblings.dataDirectoryChildren
        guard initial == allEntry || initial == subdirectory else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let projected = initial == allEntry && temporaryPresent
            ? allEntry + 1 : initial
        guard let exact = nlink_t(exactly: projected) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return exact
    }

    private func requireOriginalErasePointerSiblings(
        _ first: OriginalErasePointerSiblingImageV1,
        names: [String],
        diagnosticTargetID: String? = nil,
        diagnosticSourceID: String? = nil
    ) throws {
        let observed: OriginalErasePointerSiblingImageV1
        do {
            observed = try originalErasePointerSiblingImage(dataNames: names,
                diagnosticTargetID: diagnosticTargetID,
                diagnosticSourceID: diagnosticSourceID)
        } catch {
            #if DEBUG
            print("ORIGINAL_POINTER_SIBLING_DELTA_V1 result=scan-refused role=unknown node=unknown fact=unknown identityEqual=unobserved timeEqual=unobserved contentEqual=unobserved")
            #endif
            throw error
        }
        guard observed == first else {
            #if DEBUG
            let detail = originalErasePointerSiblingDifference(
                first: first, observed: observed,
                targetID: diagnosticTargetID, sourceID: diagnosticSourceID)
            let comparison = originalErasePointerSiblingComparison(
                first: first, observed: observed)
            print("ORIGINAL_POINTER_SIBLING_DELTA_V1 result=image-differed role=\(detail.role) node=\(detail.node) fact=\(detail.fact) identityEqual=\(comparison.identityEqual) timeEqual=\(comparison.timeEqual) contentEqual=\(comparison.contentEqual)")
            #endif
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    #if DEBUG
    /// Diagnostic lineage only. The retained current predecessor contains
    /// canonical current-pointer bytes; retired JSON is never decoded as one.
    /// An incoherent diagnostic association returns unknown, never authority.
    @MainActor
    private func originalErasePointerDiagnosticRoles(
        _ receipt: OriginalErasePointerReceiptV1
    ) -> (targetID: String?, sourceID: String?) {
        let current: OriginalErasePointerReceiptV1
        if receipt.stage == .retired {
            guard let predecessor = receipt.predecessor,
                  predecessor.stage == .current,
                  predecessor.authority === self,
                  receipt.authority === self,
                  predecessor.operationID == receipt.operationID,
                  predecessor.successor === receipt,
                  receipt.other == predecessor.published else {
                return (nil, nil)
            }
            current = predecessor
        } else {
            current = receipt
        }
        return (originalErasePointerDiagnosticID(current.published.data),
            originalErasePointerDiagnosticID(current.source.data))
    }

    private func originalErasePointerSiblingClassify(
        _ path: String, targetID: String?, sourceID: String?
    ) -> (role: String, node: String) {
        let parts = path.split(separator: "/", omittingEmptySubsequences: false)
        let role: String
        if parts.first == "generations", parts.count > 1 {
            if let targetID, String(parts[1]) == targetID { role = "target" }
            else if let sourceID, String(parts[1]) == sourceID { role = "source" }
            else if targetID == nil || sourceID == nil { role = "unknown" }
            else { role = "other-generation" }
        } else if parts.first == "generations" {
            role = "generation-parent"
        } else {
            role = "other-data"
        }
        let leaf = parts.last ?? ""
        let node: String
        if leaf == "model.sqlite-shm" { node = "sqlite-shm" }
        else if leaf == "model.sqlite-wal" { node = "sqlite-wal" }
        else if leaf == "model.sqlite" { node = "sqlite-main" }
        else if leaf == "generations" { node = "generations-root" }
        else if parts.count == 2, parts.first == "generations" {
            node = "generation-root"
        } else if leaf == "generation-leases" { node = "leases-root" }
        else { node = "other" }
        return (role, node)
    }

    /// Compare only the two genuine already-captured images. A membership
    /// mismatch prevents row association and is explicitly unobserved.
    /// These summaries never replace full image equality or release debt.
    private func originalErasePointerSiblingComparison(
        first: OriginalErasePointerSiblingImageV1,
        observed: OriginalErasePointerSiblingImageV1
    ) -> (identityEqual: String, timeEqual: String, contentEqual: String) {
        guard first.nodes.count == observed.nodes.count else {
            return ("unobserved", "unobserved", "unobserved")
        }
        for index in first.nodes.indices {
            guard first.nodes[index].path == observed.nodes[index].path else {
                return ("unobserved", "unobserved", "unobserved")
            }
        }
        var identityEqual = true
        var timeEqual = true
        var contentEqual = true
        var observedContent = false
        for index in first.nodes.indices {
            let a = first.nodes[index], b = observed.nodes[index]
            identityEqual = identityEqual && a.fact.device == b.fact.device
                && a.fact.inode == b.fact.inode
            timeEqual = timeEqual
                && a.fact.modifiedSeconds == b.fact.modifiedSeconds
                && a.fact.modifiedNanoseconds == b.fact.modifiedNanoseconds
                && a.fact.changedSeconds == b.fact.changedSeconds
                && a.fact.changedNanoseconds == b.fact.changedNanoseconds
            if a.sha256 != nil || b.sha256 != nil {
                observedContent = true
                contentEqual = contentEqual && a.sha256 == b.sha256
                    && a.fact.size == b.fact.size
            }
        }
        return (identityEqual ? "true" : "false",
            timeEqual ? "true" : "false",
            observedContent ? (contentEqual ? "true" : "false") : "unobserved")
    }

    private func originalErasePointerSiblingDifference(
        first: OriginalErasePointerSiblingImageV1,
        observed: OriginalErasePointerSiblingImageV1,
        targetID: String?, sourceID: String?
    ) -> (role: String, node: String, fact: String) {
        if first.dataDirectoryChildren != observed.dataDirectoryChildren {
            return ("other-data", "directory", "directory-count")
        }
        for index in 0..<min(first.nodes.count, observed.nodes.count) {
            let before = first.nodes[index], after = observed.nodes[index]
            if before.path != after.path {
                let category = originalErasePointerSiblingClassify(
                    before.path, targetID: targetID, sourceID: sourceID)
                return (category.role, category.node, "membership")
            }
            let category = originalErasePointerSiblingClassify(
                before.path, targetID: targetID, sourceID: sourceID)
            let a = before.fact, b = after.fact
            if a.device != b.device { return (category.role, category.node, "device") }
            if a.inode != b.inode { return (category.role, category.node, "inode") }
            if a.mode != b.mode { return (category.role, category.node, "mode") }
            if a.owner != b.owner { return (category.role, category.node, "owner") }
            if a.group != b.group { return (category.role, category.node, "group") }
            if a.links != b.links { return (category.role, category.node, "links") }
            if a.size != b.size { return (category.role, category.node, "size") }
            if a.modifiedSeconds != b.modifiedSeconds
                || a.modifiedNanoseconds != b.modifiedNanoseconds {
                return (category.role, category.node, "mtime")
            }
            if a.changedSeconds != b.changedSeconds
                || a.changedNanoseconds != b.changedNanoseconds {
                return (category.role, category.node, "ctime")
            }
            if before.names != after.names {
                return (category.role, category.node, "child-names")
            }
            if before.sha256 != after.sha256 {
                return (category.role, category.node, "content-sha")
            }
        }
        if first.nodes.count != observed.nodes.count {
            let path = first.nodes.count > observed.nodes.count
                ? first.nodes[observed.nodes.count].path
                : observed.nodes[first.nodes.count].path
            let category = originalErasePointerSiblingClassify(
                path, targetID: targetID, sourceID: sourceID)
            return (category.role, category.node, "membership")
        }
        return ("unknown", "unknown", "other")
    }

    private func originalErasePointerDiagnosticID(_ bytes: Data) -> String? {
        guard let decoded = try? CurrentPointerCodecV1.decode(bytes),
              case .v3(let pointer, _) = decoded else { return nil }
        return pointer.generationID
    }
    #endif

    private func originalEraseCheckedPointerRead(
        _ name: String
    ) throws -> OriginalEraseCheckedPointerReadV1 {
        try Self.requireSafeBasename(name)
        let root = try originalEraseDataRootFact()
        let result = try originalErasePointerCheckedIO.withOpen(
            parent: dataDescriptor, name: name,
            flags: O_RDONLY | O_NONBLOCK
        ) { descriptor -> OriginalEraseCheckedPointerReadV1 in
            var before = stat(), after = stat(), named = stat()
            guard Darwin.fstat(descriptor, &before) == 0,
                  Darwin.fstatat(dataDescriptor, name, &named,
                      AT_SYMLINK_NOFOLLOW) == 0,
                  before.st_mode & S_IFMT == S_IFREG,
                  before.st_nlink == 1,
                  before.st_uid == getuid(), before.st_gid == getgid(),
                  before.st_size >= 0,
                  before.st_size <= off_t(Self.maximumControlFileByteCount),
                  OriginalErasePointerFullFactV1(before)
                      == OriginalErasePointerFullFactV1(named) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var bytes = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    guard bytes.count <= Self.maximumControlFileByteCount - count else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    bytes.append(contentsOf: buffer.prefix(count))
                } else if count == 0 {
                    break
                } else if errno != EINTR {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(dataDescriptor, name, &named,
                      AT_SYMLINK_NOFOLLOW) == 0,
                  OriginalErasePointerFullFactV1(after)
                      == OriginalErasePointerFullFactV1(before),
                  OriginalErasePointerFullFactV1(named)
                      == OriginalErasePointerFullFactV1(before),
                  bytes.count == Int(before.st_size) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return OriginalEraseCheckedPointerReadV1(
                data: bytes, fact: OriginalErasePointerFullFactV1(before))
        }
        guard try originalEraseDataRootFact() == root else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return result
    }

    @MainActor
    fileprivate func requireOriginalErasePointerPostimage(
        _ receipt: OriginalErasePointerReceiptV1
    ) throws {
        #if DEBUG
        var fixedStage = "owner-and-first-root"
        let diagnosticRoles = originalErasePointerDiagnosticRoles(receipt)
        #endif
        do {
            let expectedSiblings: OriginalErasePointerSiblingImageV1
            if let successor = receipt.physicalSuccessor {
                try successor.requireBound(authority: self, receipt: receipt)
                expectedSiblings = successor.image.siblings
            } else { expectedSiblings = receipt.siblings }
            guard receipt.authority === self,
                  !originalErasePointerEffectUncertain,
                  try originalErasePointerCheckedIO.names(in: dataDescriptor)
                      == receipt.names,
                  try originalEraseDataRootFact() == receipt.root else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            #if DEBUG
            fixedStage = "first-sibling-image"
            #endif
            #if DEBUG
            try requireOriginalErasePointerSiblings(expectedSiblings,
                names: receipt.names,
                diagnosticTargetID: diagnosticRoles.targetID,
                diagnosticSourceID: diagnosticRoles.sourceID)
            #else
            try requireOriginalErasePointerSiblings(expectedSiblings,
                names: receipt.names)
            #endif
            let name = receipt.stage == .current
                ? "current.json" : "retired.json"
            let other = receipt.stage == .current
                ? "retired.json" : "current.json"
            #if DEBUG
            fixedStage = "published-pointer"
            #endif
            guard try originalEraseCheckedPointerRead(name)
                    == receipt.published else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            #if DEBUG
            fixedStage = "other-pointer"
            #endif
            guard try originalEraseCheckedPointerRead(other)
                    == receipt.other else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            #if DEBUG
            fixedStage = "final-root-and-names"
            #endif
            guard try originalErasePointerCheckedIO.names(in: dataDescriptor)
                    == receipt.names,
                  try originalEraseDataRootFact() == receipt.root else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            #if DEBUG
            fixedStage = "final-sibling-image"
            #endif
            #if DEBUG
            try requireOriginalErasePointerSiblings(expectedSiblings,
                names: receipt.names,
                diagnosticTargetID: diagnosticRoles.targetID,
                diagnosticSourceID: diagnosticRoles.sourceID)
            #else
            try requireOriginalErasePointerSiblings(expectedSiblings,
                names: receipt.names)
            #endif
        } catch {
            #if DEBUG
            print("ORIGINAL_POINTER_POSTIMAGE_V1 stage=\(fixedStage)")
            #endif
            throw error
        }
    }

    /// This is the original operation's P writer. Ordinary Restore's
    /// replacePointer may reconcile a matching-name temp or roll back after
    /// uncertainty, so it cannot publish either Erase pointer under retained
    /// EX. The original operation owns the single effect latch in Router.
    @MainActor
    fileprivate func publishOriginalErasePointer(
        stage: OriginalEraseRetainedPointerStageV1,
        expected: Data,
        replacement: Data,
        otherExpected: Data,
        operation: EraseRouterOperationV1,
        predecessor: OriginalErasePointerReceiptV1?
    ) throws -> OriginalErasePointerReceiptV1 {
        let name = stage == .current ? "current.json" : "retired.json"
        let otherName = stage == .current ? "retired.json" : "current.json"
        let temporary = ".\(name).restore-next"
        guard !originalErasePointerEffectUncertain,
              (stage == .current) == (predecessor == nil),
              expected != replacement else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        if let predecessor {
            try predecessor.requireBound(
                authority: self, operation: operation,
                stage: .current, predecessor: nil)
        }
        Self.pointerMutationLock.lock()
        defer { Self.pointerMutationLock.unlock() }
        try requireCheckedEraseRetirementWriterAuthority()
        try originalErasePointerCheckedIO.requireSettled()
        let publication = try makeOriginalPointerPublicationIO(operation: operation,
            stage: stage, predecessor: predecessor)
        publication.storage.phase = .observing
        do {
        let firstRoot = try publication.rootFact()
        let firstNames = try publication.names(in: dataDescriptor)
        guard firstNames.contains(name), firstNames.contains(otherName),
              !firstNames.contains(temporary),
              !firstNames.contains(".current.json.restore-next"),
              !firstNames.contains(".retired.json.restore-next"),
              !firstNames.contains(".current.json.restore-rollback"),
              !firstNames.contains(".retired.json.restore-rollback"),
              !firstNames.contains(".current.json.migration-next"),
              !firstNames.contains(".retired.json.migration-next") else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let firstSiblings = try publication.siblingImage(
            dataNames: firstNames)
        guard firstRoot.links == (try originalErasePointerRootLinks(
                firstRoot: firstRoot, firstNames: firstNames,
                siblings: firstSiblings, temporaryPresent: false)),
              predecessor == nil || predecessor?.siblings == firstSiblings else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let source = try publication.pointerRead(name)
        let other = try publication.pointerRead(otherName)
        guard source.data == expected, other.data == otherExpected,
              try publication.rootFact() == firstRoot,
              try publication.names(in: dataDescriptor)
                  == firstNames,
              predecessor == nil
                  || (predecessor?.published == other
                      && predecessor?.other == source) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        #if DEBUG
        try StoreGenerationFactory.fireOriginalErasePointerTestHook(
            operation: operation,
            applicationSupportURL: applicationSupportURL,
            stage: .beforeFirstPointerEffect)
        #endif
        try publication.requireSiblings(firstSiblings,
            names: firstNames)
        let stagedNames = (firstNames + [temporary]).sorted()
        func requireStage(
            sourceExpected: OriginalEraseCheckedPointerReadV1,
            otherExpected: OriginalEraseCheckedPointerReadV1,
            staged: OriginalEraseCheckedPointerReadV1?,
            renamed: Bool
        ) throws -> OriginalEraseCheckedPointerReadV1? {
            let root = try publication.rootFact()
            guard root.sameDirectoryIdentity(as: firstRoot),
                  root.links == (try originalErasePointerRootLinks(
                    firstRoot: firstRoot, firstNames: firstNames,
                    siblings: firstSiblings, temporaryPresent: true)),
                  try publication.names(in: dataDescriptor)
                    == stagedNames else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try publication.requireSiblings(firstSiblings,
                names: stagedNames)
            let current = try publication.pointerRead(name)
            let otherCurrent = try publication.pointerRead(otherName)
            let temp = try publication.pointerRead(temporary)
            guard otherCurrent == otherExpected else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if renamed {
                guard current.data == replacement,
                      staged.map({ current.fact.sameRenamedInode(as: $0.fact) })
                        ?? false,
                      temp.data == expected,
                      temp.fact.sameRenamedInode(as: sourceExpected.fact) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            } else {
                guard current == sourceExpected,
                      staged.map({ temp.fact.sameRenamedInode(as: $0.fact)
                        && temp.data == $0.data }) ?? true else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            let trailingRoot = try publication.rootFact()
            guard try publication.names(in: dataDescriptor)
                    == stagedNames,
                  trailingRoot.sameDirectoryIdentity(as: firstRoot),
                  trailingRoot.links
                    == (try originalErasePointerRootLinks(
                        firstRoot: firstRoot, firstNames: firstNames,
                        siblings: firstSiblings, temporaryPresent: true)) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try publication.requireSiblings(firstSiblings,
                names: stagedNames)
            return temp
        }
        var firstEffectStarted = false
        do {
            // The first O_EXCL FD is owned by checked IO before any byte or
            // policy request. A failed close remains held and blocks retry.
            firstEffectStarted = true
            publication.storage.effectEntered = true
            publication.storage.phase = .publishing
            var writerFDPostimage: OriginalErasePointerFullFactV1?
            _ = try publication.withOpen(
                parent: dataDescriptor, name: temporary,
                flags: O_RDWR | O_CREAT | O_EXCL,
                mode: mode_t(0o600)
            ) { descriptor in
                var opened = stat(), named = stat()
                guard try publication.fstat(descriptor, &opened) == 0,
                      try publication.fstatat(dataDescriptor, temporary, &named,
                          AT_SYMLINK_NOFOLLOW) == 0,
                      OriginalErasePointerFullFactV1(opened)
                        == OriginalErasePointerFullFactV1(named),
                      opened.st_mode & S_IFMT == S_IFREG,
                      opened.st_nlink == 1,
                      opened.st_uid == getuid(), opened.st_gid == getgid(),
                      opened.st_size == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let justCreatedRoot = try publication.rootFact()
                guard justCreatedRoot.sameDirectoryIdentity(as: firstRoot),
                      justCreatedRoot.links
                        == (try originalErasePointerRootLinks(
                            firstRoot: firstRoot, firstNames: firstNames,
                            siblings: firstSiblings,
                            temporaryPresent: true)),
                      try publication.names(
                        in: dataDescriptor) == stagedNames else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try publication.requireSiblings(firstSiblings,
                    names: stagedNames)
                try replacement.withUnsafeBytes { raw in
                    guard let base = raw.baseAddress else { return }
                    var written = 0
                    while written < raw.count {
                        let result = try publication.write(
                            descriptor, base.advanced(by: written),
                            raw.count - written)
                        if result > 0 { written += result }
                        else if result < 0 && errno == EINTR { continue }
                        else { throw StoreGenerationFailure.dataPointerInvalid }
                    }
                }
                guard try publication.fsync(descriptor) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                var afterWrite = stat()
                guard try publication.fstat(descriptor, &afterWrite) == 0,
                      try publication.fstatat(dataDescriptor, temporary, &named,
                          AT_SYMLINK_NOFOLLOW) == 0,
                      OriginalErasePointerFullFactV1(afterWrite)
                        == OriginalErasePointerFullFactV1(named),
                      OriginalErasePointerFullFactV1(afterWrite)
                        .sameDirectoryIdentity(
                            as: OriginalErasePointerFullFactV1(opened)),
                      afterWrite.st_nlink == 1,
                      afterWrite.st_size == off_t(replacement.count) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                writerFDPostimage = OriginalErasePointerFullFactV1(afterWrite)
            }
            guard try publication.fsync(dataDescriptor) == 0,
                  let writerFDPostimage,
                  let justWritten = try requireStage(
                    sourceExpected: source, otherExpected: other,
                    staged: nil, renamed: false),
                  justWritten.data == replacement,
                  justWritten.fact == writerFDPostimage else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let written = try publication.pointerRead(temporary)
            try publication.applyPolicy(.generationPointerTemporary, name: temporary, authorityCheck: {
                    let now = try requireStage(sourceExpected: source,
                        otherExpected: other, staged: written, renamed: false)
                    guard now?.data == replacement,
                          now.map({ $0.fact.sameRenamedInode(as: written.fact) })
                            == true else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }, beforeFirstEffect: {
                    guard try requireStage(sourceExpected: source,
                        otherExpected: other, staged: written, renamed: false)
                            == written else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                })
            guard eraseRetirementUncertainDescriptors.isEmpty,
                  let protected = try requireStage(
                    sourceExpected: source, otherExpected: other,
                    staged: written, renamed: false),
                  protected.data == replacement,
                  protected.fact.sameRenamedInode(as: written.fact) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            _ = try publication.withOpen(
                parent: dataDescriptor, name: temporary,
                flags: O_RDONLY | O_NONBLOCK
            ) { descriptor in
                var held = stat(), named = stat()
                guard try publication.fstat(descriptor, &held) == 0,
                      try publication.fstatat(dataDescriptor, temporary, &named,
                          AT_SYMLINK_NOFOLLOW) == 0,
                      OriginalErasePointerFullFactV1(held) == protected.fact,
                      OriginalErasePointerFullFactV1(named) == protected.fact,
                      try requireStage(sourceExpected: source,
                        otherExpected: other, staged: protected,
                        renamed: false) == protected,
                      try publication.fsync(descriptor) == 0,
                      try publication.renameatx_np(dataDescriptor, temporary,
                        dataDescriptor, name, UInt32(RENAME_SWAP)) == 0,
                      try publication.fsync(dataDescriptor) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let displaced = try requireStage(sourceExpected: source,
                    otherExpected: other, staged: protected, renamed: true)
                guard displaced?.data == expected,
                      try publication.fstat(descriptor, &held) == 0,
                      OriginalErasePointerFullFactV1(held)
                        == (try publication.pointerRead(name)).fact else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            let renamed = try publication.pointerRead(name)
            try publication.applyPolicy(.generationPointer, name: name, authorityCheck: {
                    guard try requireStage(sourceExpected: source,
                        otherExpected: other, staged: protected,
                        renamed: true)?.data == expected,
                          (try publication.pointerRead(name)).fact
                            .sameRenamedInode(as: renamed.fact) else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }, beforeFirstEffect: {
                    guard try publication.pointerRead(name) == renamed,
                          try requireStage(sourceExpected: source,
                            otherExpected: other, staged: protected,
                            renamed: true)?.data == expected else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                })
            guard eraseRetirementUncertainDescriptors.isEmpty,
                  try requireStage(sourceExpected: source,
                    otherExpected: other, staged: protected,
                    renamed: true)?.data == expected else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            _ = try publication.withOpen(
                parent: dataDescriptor, name: temporary,
                flags: O_RDONLY | O_NONBLOCK
            ) { descriptor in
                let displaced = try publication.pointerRead(temporary)
                var held = stat(), named = stat()
                guard displaced.data == expected,
                      displaced.fact.sameRenamedInode(as: source.fact),
                      try publication.fstat(descriptor, &held) == 0,
                      try publication.fstatat(dataDescriptor, temporary, &named,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      OriginalErasePointerFullFactV1(held) == displaced.fact,
                      OriginalErasePointerFullFactV1(named) == displaced.fact,
                      try requireStage(sourceExpected: source,
                        otherExpected: other, staged: protected,
                        renamed: true) == displaced,
                      try publication.unlinkat(dataDescriptor, temporary, 0) == 0,
                      try publication.fsync(dataDescriptor) == 0,
                      try publication.fstat(descriptor, &held) == 0,
                      held.st_dev == displaced.fact.device,
                      held.st_ino == displaced.fact.inode,
                      held.st_nlink == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                guard try publication.fstatat(dataDescriptor, temporary, &named,
                    AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            let resultRoot = try publication.rootFact()
            let result = try publication.pointerRead(name)
            let unchangedOther = try publication.pointerRead(otherName)
            guard result.data == replacement,
                  result.fact.sameRenamedInode(as: protected.fact),
                  unchangedOther == other,
                  resultRoot.sameDirectoryIdentity(as: firstRoot),
                  resultRoot.links == firstRoot.links,
                  try publication.names(in: dataDescriptor)
                    == firstNames,
                  eraseRetirementUncertainDescriptors.isEmpty else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try publication.requireSiblings(firstSiblings,
                names: firstNames)
            let receipt = OriginalErasePointerReceiptV1(
                authority: self, operation: operation, stage: stage,
                source: source, published: result, other: other,
                names: firstNames, root: resultRoot,
                siblings: firstSiblings,
                predecessor: predecessor)
            publication.storage.receipt = receipt
            let data = try publication.makeDataProjection(receipt: receipt)
            let priorSettlement = predecessor?.publicationSettlement
            guard (stage == .current) == (priorSettlement == nil) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let settlement = OriginalEraseRetainedPointerPublicationSettlementV1(
                authority: self, operation: operation, receipt: receipt,
                publication: publication, predecessor: priorSettlement, data: data)
            receipt.publicationSettlement = settlement // SAME before any final fallible proof
            publication.storage.settlement = settlement
            publication.storage.phase = .completing
            try receipt.requireBound(authority: self, operation: operation,
                stage: stage, predecessor: predecessor)
            try publication.requireFinalDataProjection(data, receipt: receipt)
            publication.storage.originalPostproofReturned = true
            predecessor?.successor = receipt
            priorSettlement?.storage.successor = settlement
            publication.storage.phase = .completed
            settlement.storage.originalIntervalReturned = true
            try settlement.requirePermanentOriginalErasePointerData(authority: self,
                operation: operation, receipt: receipt)
            try originalErasePointerCheckedIO.finishOriginalPointerPublication(publication)
            return receipt
        } catch {
            if firstEffectStarted { originalErasePointerEffectUncertain = true }
            throw error
        }
        } catch {
            publication.storage.settlement?.storage.failure = error
            publication.fail(error) // actual primary retained; no close/retry/rollback
            throw error
        }
    }

    @MainActor
    func publishOriginalEraseCurrentPointer(
        expectedOldID: UUID,
        targetID: UUID,
        expectedCurrent: CurrentGenerationPointerV3,
        replacementCurrent: CurrentGenerationPointerV3,
        priorRetiredIDs: [UUID],
        operation: EraseRouterOperationV1
    ) throws -> OriginalErasePointerReceiptV1 {
        try expectedCurrent.validate()
        try replacementCurrent.validate()
        guard expectedOldID != targetID,
              expectedCurrent.generationID == Self.canonical(expectedOldID),
              replacementCurrent.generationID == Self.canonical(targetID),
              !priorRetiredIDs.contains(targetID),
              priorRetiredIDs == priorRetiredIDs.sorted(by: Self.idOrder),
              Set(priorRetiredIDs).count == priorRetiredIDs.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(expectedOldID))
        _ = try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(targetID))
        return try publishOriginalErasePointer(
            stage: .current,
            expected: expectedCurrent.canonicalData(),
            replacement: replacementCurrent.canonicalData(),
            otherExpected: Self.canonicalData(RetiredPointerV1(
                generationIDs: priorRetiredIDs.map(Self.canonical),
                schemaVersion: StorePointerSchemaRegistry.retiredVersion)),
            operation: operation, predecessor: nil)
    }

    @MainActor
    func publishOriginalEraseRetiredPointer(
        expected: [UUID],
        replacement: [UUID],
        targetID: UUID,
        currentReceipt: OriginalErasePointerReceiptV1,
        operation: EraseRouterOperationV1
    ) throws -> OriginalErasePointerReceiptV1 {
        guard !expected.contains(targetID),
              !replacement.contains(targetID),
              expected == expected.sorted(by: Self.idOrder),
              replacement == replacement.sorted(by: Self.idOrder),
              Set(expected).count == expected.count,
              Set(replacement).count == replacement.count,
              currentReceipt.published.data
                == (try originalEraseCheckedPointerRead("current.json")).data,
              try CurrentPointerCodecV1.decode(
                currentReceipt.published.data).generationID
                  == Self.canonical(targetID) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try currentReceipt.requireBound(
            authority: self, operation: operation,
            stage: .current, predecessor: nil)
        return try publishOriginalErasePointer(
            stage: .retired,
            expected: Self.canonicalData(RetiredPointerV1(
                generationIDs: expected.map(Self.canonical),
                schemaVersion: StorePointerSchemaRegistry.retiredVersion)),
            replacement: Self.canonicalData(RetiredPointerV1(
                generationIDs: replacement.map(Self.canonical),
                schemaVersion: StorePointerSchemaRegistry.retiredVersion)),
            otherExpected: currentReceipt.published.data,
            operation: operation, predecessor: currentReceipt)
    }

    fileprivate static func canonicalOriginalEraseRetiredData(
        _ ids: [UUID]
    ) throws -> Data {
        try canonicalData(RetiredPointerV1(
            generationIDs: ids.map(Self.canonical),
            schemaVersion: StorePointerSchemaRegistry.retiredVersion))
    }

    fileprivate struct RegularFileSnapshot: Equatable {
        let device: dev_t
        let inode: ino_t
        let linkCount: nlink_t
        let type: mode_t
        let byteCount: off_t
        let modificationSeconds: Int64
        let modificationNanoseconds: Int64
        let statusChangeSeconds: Int64
        let statusChangeNanoseconds: Int64

        static func == (lhs: Self, rhs: Self) -> Bool {
            // Preserve the settled migration path's historical identity
            // predicate. Restore capabilities compare the timestamp fields in
            // their separately minted immutable NodeFact values.
            lhs.device == rhs.device
                && lhs.inode == rhs.inode
                && lhs.linkCount == rhs.linkCount
                && lhs.type == rhs.type
                && lhs.byteCount == rhs.byteCount
        }
    }

    fileprivate struct StreamedFileDigest {
        let byteCount: Int
        let sha256: String
        let snapshot: RegularFileSnapshot
    }

    private static let migrationStreamBufferByteCount = 64 * 1024
    private static let maximumControlFileByteCount = 4 * 1024 * 1024
#if DEBUG
    private let completedAbortIO = EraseAbortCheckedSnapshotIOV1()

    private func requireCompletedAbortHeldRoots() throws {
        func requireNamed(_ parent: Int32, _ name: String, _ expected: Identity) throws {
            var named = stat()
            guard Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                  named.st_mode & S_IFMT == S_IFDIR,
                  named.st_dev == expected.device, named.st_ino == expected.inode else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        try Self.require(applicationSupportDescriptor, applicationSupportIdentity)
        try Self.require(dataDescriptor, dataIdentity)
        try Self.require(installedGenerationsDescriptor, installedGenerationsIdentity)
        var namedSupport = stat()
        guard Darwin.lstat(applicationSupportURL.path, &namedSupport) == 0,
              namedSupport.st_mode & S_IFMT == S_IFDIR,
              namedSupport.st_dev == applicationSupportIdentity.device,
              namedSupport.st_ino == applicationSupportIdentity.inode else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireNamed(applicationSupportDescriptor, Self.dataName, dataIdentity)
        try requireNamed(dataDescriptor, Self.generationsName, installedGenerationsIdentity)
        try completedAbortIO.requireSettled()
    }

    func requireCompletedAbortTargetAbsent(_ targetID: UUID) throws {
        try requireCompletedAbortHeldRoots()
        var target = stat()
        let name = Self.canonical(targetID)
        let result = Darwin.fstatat(installedGenerationsDescriptor, name,
                                    &target, AT_SYMLINK_NOFOLLOW)
        let lookupError = errno
        guard result != 0, lookupError == ENOENT else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireCompletedAbortHeldRoots()
    }

    func requireCompletedAbortModelURL(id: UUID, rootURL: URL,
                                       modelURL: URL) throws {
        try requireCompletedAbortHeldRoots()
        guard rootURL.standardizedFileURL
                  == applicationSupportURL.appendingPathComponent(Self.dataName)
                      .appendingPathComponent(Self.generationsName)
                      .appendingPathComponent(Self.canonical(id)).standardizedFileURL,
              modelURL.standardizedFileURL
                  == rootURL.appendingPathComponent("model.sqlite").standardizedFileURL else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var heldRoot = stat(), namedRoot = stat(), pathRoot = stat()
        guard Darwin.fstatat(installedGenerationsDescriptor, Self.canonical(id),
                             &namedRoot, AT_SYMLINK_NOFOLLOW) == 0,
              namedRoot.st_mode & S_IFMT == S_IFDIR,
              Darwin.lstat(rootURL.path, &pathRoot) == 0,
              pathRoot.st_mode & S_IFMT == S_IFDIR,
              pathRoot.st_dev == namedRoot.st_dev,
              pathRoot.st_ino == namedRoot.st_ino else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try completedAbortIO.withOpen(parent: installedGenerationsDescriptor,
                                      name: Self.canonical(id),
                                      flags: O_RDONLY | O_DIRECTORY) { root in
            guard Darwin.fstat(root, &heldRoot) == 0,
                  heldRoot.st_dev == namedRoot.st_dev,
                  heldRoot.st_ino == namedRoot.st_ino else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var namedModel = stat(), pathModel = stat()
            guard Darwin.fstatat(root, "model.sqlite", &namedModel,
                                 AT_SYMLINK_NOFOLLOW) == 0,
                  namedModel.st_mode & S_IFMT == S_IFREG,
                  namedModel.st_nlink == 1,
                  Darwin.lstat(modelURL.path, &pathModel) == 0,
                  pathModel.st_mode & S_IFMT == S_IFREG,
                  pathModel.st_dev == namedModel.st_dev,
                  pathModel.st_ino == namedModel.st_ino else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        try requireCompletedAbortHeldRoots()
    }

    func snapshotCompletedAbortSource(
        id: UUID, oldPointer: RestorePointerIdentityV1,
        priorRetired: [UUID]
    ) throws -> EraseCompletedAbortSourceBytesV1 {
        try requireCompletedAbortHeldRoots()
        let (current, currentIdentity) = try completedAbortIO.control(
            parent: dataDescriptor, name: "current.json")
        let (retired, retiredIdentity) = try completedAbortIO.control(
            parent: dataDescriptor, name: "retired.json")
        guard case .v3(let pointer, _) = try CurrentPointerCodecV1.decode(current) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let parsedReplicaIDs = pointer.knownReplicaIDs.compactMap(UUID.init(uuidString:))
        guard oldPointer.generationID == id,
              try pointer.canonicalData() == current,
              pointer.generationID == Self.canonical(oldPointer.generationID),
              pointer.generationManifestSHA256 == oldPointer.generationManifestSHA256,
              UUID(uuidString: pointer.workspaceID) == oldPointer.workspaceID,
              UUID(uuidString: pointer.replicaID) == oldPointer.replicaID,
              parsedReplicaIDs.count == pointer.knownReplicaIDs.count,
              Set(parsedReplicaIDs).count == parsedReplicaIDs.count,
              parsedReplicaIDs == oldPointer.knownReplicaIDs,
              zip(pointer.knownReplicaIDs, parsedReplicaIDs).allSatisfy({
                  $0.0 == $0.1.uuidString.lowercased()
              }) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let retiredValue = try JSONDecoder().decode(RetiredPointerV1.self, from: retired)
        try StorePointerSchemaRegistry.requireRetired(retiredValue.schemaVersion)
        guard try Self.canonicalData(retiredValue) == retired,
              retiredValue.generationIDs == priorRetired.map(Self.canonical) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var sourceNodes: [String: EraseCompletedAbortNodeFactV1] = [:]
        let sourceTreeDigest = try completedAbortIO.tree(
            parent: installedGenerationsDescriptor, name: Self.canonical(id),
            observeNode: { path, nodeType, fields in
                sourceNodes[path] = EraseCompletedAbortNodeFactV1(
                    nodeType: nodeType, fields: fields)
            })
        let (currentAfter, currentIdentityAfter) = try completedAbortIO.control(
            parent: dataDescriptor, name: "current.json")
        let (retiredAfter, retiredIdentityAfter) = try completedAbortIO.control(
            parent: dataDescriptor, name: "retired.json")
        guard currentAfter == current, currentIdentityAfter == currentIdentity,
              retiredAfter == retired, retiredIdentityAfter == retiredIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireCompletedAbortHeldRoots()
        return EraseCompletedAbortSourceBytesV1(
            current: current, currentIdentity: currentIdentity,
            retired: retired, retiredIdentity: retiredIdentity,
            sourceTreeDigest: sourceTreeDigest,
            sourceNodes: sourceNodes)
    }

    private func completedAbortSQLiteIdentity(_ value: stat) -> String {
        "\(value.st_dev)|\(value.st_ino)|\(value.st_mode)|\(value.st_nlink)|\(value.st_size)|\(value.st_mtimespec.tv_sec)|\(value.st_mtimespec.tv_nsec)|\(value.st_ctimespec.tv_sec)|\(value.st_ctimespec.tv_nsec)"
    }

    /// One complete checked source-tree walk fixes both the SQLite filenames
    /// and their byte identities before any private scratch allocation.
    func completedAbortSQLiteFiles(id: UUID, treeDigest: String)
        throws -> [EraseCompletedAbortSQLiteFileV1] {
        try requireCompletedAbortHeldRoots()
        let walk = try completedAbortIO.treeWithNodes(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        guard walk.digest == treeDigest else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let allowed: Set<String> = ["model.sqlite", "model.sqlite-wal", "model.sqlite-shm"]
        let files = try walk.nodes.filter { allowed.contains($0.path) }.map { node in
            guard let hash = node.sha256,
                  node.fact.st_mode & S_IFMT == S_IFREG,
                  node.fact.st_nlink == 1,
                  node.fact.st_size >= 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return EraseCompletedAbortSQLiteFileV1(
                name: node.path, byteCount: UInt64(node.fact.st_size),
                sha256: hash,
                physicalIdentity: completedAbortSQLiteIdentity(node.fact))
        }.sorted { $0.name < $1.name }
        guard files.contains(where: { $0.name == "model.sqlite" }),
              Set(files.map(\.name)).count == files.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireCompletedAbortHeldRoots()
        return files
    }

    /// Capture every committed SQLite page through the same no-follow source
    /// descriptors. No second Registry reader or SQLite connection touches the
    /// live generation. The complete tree is rechecked on both sides.
    func completedAbortSQLitePhysicalImage(id: UUID, treeDigest: String)
        throws -> CompletedAbortSQLitePhysicalImageV1 {
        var diagnosticStage = "files-before"
        do {
        let files = try completedAbortSQLiteFiles(id: id, treeDigest: treeDigest)
        diagnosticStage = "physical-read"
        let image = try completedAbortIO.withOpen(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(id),
            flags: O_RDONLY | O_DIRECTORY
        ) { root in
            try completedAbortIO.withOpen(parent: root, name: "model.sqlite",
                flags: O_RDONLY | O_NONBLOCK) { model in
                if files.contains(where: { $0.name == "model.sqlite-wal" }) {
                    return try completedAbortIO.withOpen(
                        parent: root, name: "model.sqlite-wal",
                        flags: O_RDONLY | O_NONBLOCK
                    ) { wal in
                        try CompletedAbortSQLitePhysicalImageV1.capture(
                            model: model, wal: wal)
                    }
                }
                return try CompletedAbortSQLitePhysicalImageV1.capture(
                    model: model, wal: nil)
            }
        }
        diagnosticStage = "files-after"
        guard try completedAbortSQLiteFiles(id: id, treeDigest: treeDigest) == files
        else { throw StoreGenerationFailure.dataPointerInvalid }
        return image
        } catch {
            FileHandle.standardError.write(Data((
                "ERASE_COMPLETED_ABORT_PHYSICAL_V1 stage=" + diagnosticStage + "\n"
            ).utf8))
            throw error
        }
    }

    /// Streams only the three fixed SQLite names through the same retained
    /// generation parent and checked-close I/O owner. Source bytes and named
    /// identity are rechecked after every copy and after the complete set.
    @MainActor
    func copyCompletedAbortSQLiteFiles(
        id: UUID, files: [EraseCompletedAbortSQLiteFileV1],
        treeDigest: String,
        into copy: ScratchDataLeaseStoreV1.SourceReadDirectory
    ) throws {
        guard try completedAbortSQLiteFiles(id: id, treeDigest: treeDigest) == files else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try completedAbortIO.withOpen(parent: installedGenerationsDescriptor,
            name: Self.canonical(id), flags: O_RDONLY | O_DIRECTORY) { root in
            for file in files {
                try completedAbortIO.withOpen(parent: root, name: file.name,
                    flags: O_RDONLY | O_NONBLOCK) { source in
                    func requireExactSource() throws {
                        var held = stat(), named = stat()
                        guard Darwin.fstat(source, &held) == 0,
                              Darwin.fstatat(root, file.name, &named,
                                  AT_SYMLINK_NOFOLLOW) == 0,
                              held.st_mode & S_IFMT == S_IFREG,
                              held.st_nlink == 1,
                              completedAbortSQLiteIdentity(held) == file.physicalIdentity,
                              completedAbortSQLiteIdentity(named) == file.physicalIdentity else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                    try requireExactSource()
                    try copy.copySQLiteFile(named: file.name,
                        byteCount: file.byteCount) { target in
                        guard Darwin.lseek(source, 0, SEEK_SET) == 0 else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        var digest = SHA256()
                        var count: UInt64 = 0
                        var buffer = [UInt8](repeating: 0, count: 65_536)
                        while true {
                            let amount = buffer.withUnsafeMutableBytes {
                                Darwin.read(source, $0.baseAddress, $0.count)
                            }
                            if amount == 0 { break }
                            if amount < 0 && errno == EINTR { continue }
                            guard amount > 0,
                                  count <= file.byteCount,
                                  UInt64(amount) <= file.byteCount - count else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            count += UInt64(amount)
                            let bytes = Data(buffer.prefix(amount))
                            digest.update(data: bytes)
                            try bytes.withUnsafeBytes { raw in
                                guard let base = raw.baseAddress else {
                                    throw StoreGenerationFailure.dataPointerInvalid
                                }
                                var offset = 0
                                while offset < raw.count {
                                    let written = Darwin.write(target,
                                        base.advanced(by: offset), raw.count - offset)
                                    if written > 0 { offset += written }
                                    else if written < 0 && errno == EINTR { continue }
                                    else { throw StoreGenerationFailure.dataPointerInvalid }
                                }
                            }
                        }
                        guard count == file.byteCount,
                              digest.finalize().map({ String(format: "%02x", $0) }).joined()
                                == file.sha256 else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                    try requireExactSource()
                }
            }
        }
        guard try completedAbortSQLiteFiles(id: id, treeDigest: treeDigest) == files else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireCompletedAbortHeldRoots()
    }
    /// DEBUG original-Erase cold-exit observation after the current pointer
    /// has legitimately moved. It observes the *same held old generation*,
    /// never a fresh path owner or the new target, and does not repair control
    /// state. The caller compares this result to its pre-admission digest.
    func originalEraseSourceTreeForColdExitForTesting(id: UUID) throws -> String {
        try requireCompletedAbortHeldRoots()
        let digest = try completedAbortIO.tree(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        try requireCompletedAbortHeldRoots()
        return digest
    }
    /// DEBUG-only checked observation for diagnosing the exact physical
    /// source-tree field that changes during the original owner handoff.
    /// It uses the same retained descriptors and checked tree walker.
    func originalEraseSourceTreeObservationForColdExitForTesting(id: UUID) throws
        -> (digest: String, nodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode]) {
        try requireCompletedAbortHeldRoots()
        let observation = try completedAbortIO.treeWithNodes(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        try requireCompletedAbortHeldRoots()
        return observation
    }

    /// The original operation retains this authority and its checked I/O
    /// owner. Capture uses only held no-follow descriptors; it never opens a
    /// new SwiftData reader or mints a replacement Registry token.
    func originalEraseSQLitePhysicalImageForColdExitForTesting(id: UUID) throws
        -> (tree: String, nodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode],
            image: CompletedAbortSQLitePhysicalImageV1) {
        try requireCompletedAbortHeldRoots()
        let before = try completedAbortIO.treeWithNodes(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        func samePhysicalFact(_ lhs: stat, _ rhs: stat) -> Bool {
            lhs.st_dev == rhs.st_dev && lhs.st_ino == rhs.st_ino &&
            lhs.st_mode == rhs.st_mode && lhs.st_nlink == rhs.st_nlink &&
            lhs.st_size == rhs.st_size &&
            lhs.st_mtimespec.tv_sec == rhs.st_mtimespec.tv_sec &&
            lhs.st_mtimespec.tv_nsec == rhs.st_mtimespec.tv_nsec &&
            lhs.st_ctimespec.tv_sec == rhs.st_ctimespec.tv_sec &&
            lhs.st_ctimespec.tv_nsec == rhs.st_ctimespec.tv_nsec
        }
        func requireBoundDescriptor(_ descriptor: Int32, parent: Int32,
                                    name: String, path: String) throws {
            guard let expected = before.nodes.first(where: { $0.path == path }),
                  before.nodes.filter({ $0.path == path }).count == 1 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var held = stat(), named = stat()
            guard Darwin.fstat(descriptor, &held) == 0,
                  Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                  samePhysicalFact(held, expected.fact),
                  samePhysicalFact(named, expected.fact) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        let image: CompletedAbortSQLitePhysicalImageV1 = try completedAbortIO.withOpen(
            parent: installedGenerationsDescriptor, name: Self.canonical(id),
            flags: O_RDONLY | O_DIRECTORY) { generation in
            try requireBoundDescriptor(generation,
                parent: installedGenerationsDescriptor,
                name: Self.canonical(id), path: "")
            return try completedAbortIO.withOpen(parent: generation,
                name: "model.sqlite", flags: O_RDONLY | O_NONBLOCK) { model in
                try requireBoundDescriptor(model, parent: generation,
                    name: "model.sqlite", path: "model.sqlite")
                var wal = stat()
                if Darwin.fstatat(generation, "model.sqlite-wal", &wal,
                    AT_SYMLINK_NOFOLLOW) == 0 {
                    guard wal.st_mode & S_IFMT == S_IFREG, wal.st_nlink == 1 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    let captured = try completedAbortIO.withOpen(parent: generation,
                        name: "model.sqlite-wal", flags: O_RDONLY | O_NONBLOCK) {
                        descriptor in
                        try requireBoundDescriptor(descriptor,
                            parent: generation, name: "model.sqlite-wal",
                            path: "model.sqlite-wal")
                        let value = try CompletedAbortSQLitePhysicalImageV1.capture(
                            model: model, wal: descriptor)
                        try requireBoundDescriptor(descriptor,
                            parent: generation, name: "model.sqlite-wal",
                            path: "model.sqlite-wal")
                        return value
                    }
                    try requireBoundDescriptor(model, parent: generation,
                        name: "model.sqlite", path: "model.sqlite")
                    try requireBoundDescriptor(generation,
                        parent: installedGenerationsDescriptor,
                        name: Self.canonical(id), path: "")
                    return captured
                }
                guard errno == ENOENT else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                guard !before.nodes.contains(where: { $0.path == "model.sqlite-wal" }) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let captured = try CompletedAbortSQLitePhysicalImageV1.capture(
                    model: model, wal: nil)
                var missing = stat()
                guard Darwin.fstatat(generation, "model.sqlite-wal", &missing,
                    AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try requireBoundDescriptor(model, parent: generation,
                    name: "model.sqlite", path: "model.sqlite")
                try requireBoundDescriptor(generation,
                    parent: installedGenerationsDescriptor,
                    name: Self.canonical(id), path: "")
                return captured
            }
        }
        let after = try completedAbortIO.treeWithNodes(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        try requireCompletedAbortHeldRoots()
        guard before.digest == after.digest else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return (before.digest, after.nodes, image)
    }

    func originalEraseControlsForColdExitForTesting()
        throws -> EraseOriginalColdExitControlsV1 {
        try requireCompletedAbortHeldRoots()
        let (current, currentIdentity) = try completedAbortIO.control(
            parent: dataDescriptor, name: "current.json")
        let (retired, retiredIdentity) = try completedAbortIO.control(
            parent: dataDescriptor, name: "retired.json")
        try requireCompletedAbortHeldRoots()
        return EraseOriginalColdExitControlsV1(
            current: current, currentIdentity: currentIdentity,
            retired: retired, retiredIdentity: retiredIdentity)
    }

    func requireOriginalErasePublishedControlsForColdExitForTesting(
        target: RestorePointerIdentityV1,
        retiredIDs: [UUID]
    ) throws -> EraseOriginalColdExitControlsV1 {
        guard Set(retiredIDs).count == retiredIDs.count,
              retiredIDs == retiredIDs.sorted(by: Self.idOrder),
              !retiredIDs.contains(target.generationID) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let actual = try originalEraseControlsForColdExitForTesting()
        let expectedRetired = try Self.canonicalData(RetiredPointerV1(
            generationIDs: retiredIDs.map(Self.canonical),
            schemaVersion: StorePointerSchemaRegistry.retiredVersion))
        let expectedCurrent = try CurrentGenerationPointerV3(
            generationID: target.generationID,
            generationManifestSHA256: target.generationManifestSHA256,
            workspaceID: WorkspaceID(rawValue: target.workspaceID),
            replicaID: ReplicaID(rawValue: target.replicaID),
            knownReplicaIDs: Set(target.knownReplicaIDs.map { ReplicaID(rawValue: $0) }),
            storeSchemaVersion: PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major)
        guard actual.current == (try expectedCurrent.canonicalData()),
              actual.retired == expectedRetired else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return actual
    }
    /// Exact nonrepairing post-retirement physical observation under the
    /// transferred original EX. It never accepts a newly constructed owner.
    func snapshotPostRetiredEraseGenerations(
        newID: UUID, deleting oldIDs: [UUID]
    ) throws -> ErasePostRetiredGenerationSnapshotV1 {
        guard !eraseRetirementTerminalCloseAttempted else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireCompletedAbortHeldRoots()
        let allowed = Set(([newID] + oldIDs).map(Self.canonical))
        guard allowed.count == oldIDs.count + 1 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let names = try completedAbortIO.names(in: installedGenerationsDescriptor)
        guard Set(names) == allowed, names.count == allowed.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let (current, currentIdentity) = try completedAbortIO.control(
            parent: dataDescriptor, name: "current.json")
        let (retired, retiredIdentity) = try completedAbortIO.control(
            parent: dataDescriptor, name: "retired.json")
        guard case .v3(let pointer, _) = try CurrentPointerCodecV1.decode(current),
              try pointer.canonicalData() == current,
              pointer.generationID == Self.canonical(newID) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let dataRootDigest = try completedAbortIO.postRetiredTree(
            parent: applicationSupportDescriptor, name: Self.dataName)
        var digests: [String: String] = [:]
        for name in names {
            digests[name] = try completedAbortIO.tree(
                parent: installedGenerationsDescriptor, name: name)
        }
        let (currentAfter, currentIdentityAfter) = try completedAbortIO.control(
            parent: dataDescriptor, name: "current.json")
        let (retiredAfter, retiredIdentityAfter) = try completedAbortIO.control(
            parent: dataDescriptor, name: "retired.json")
        guard currentAfter == current, currentIdentityAfter == currentIdentity,
              retiredAfter == retired, retiredIdentityAfter == retiredIdentity,
              try completedAbortIO.names(in: installedGenerationsDescriptor) == names,
              try completedAbortIO.postRetiredTree(
                  parent: applicationSupportDescriptor,
                  name: Self.dataName) == dataRootDigest else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireCompletedAbortHeldRoots()
        return ErasePostRetiredGenerationSnapshotV1(
            current: current, currentIdentity: currentIdentity,
            retired: retired, retiredIdentity: retiredIdentity,
            installedNames: names, treeDigests: digests,
            dataRootDigest: dataRootDigest)
    }

#endif

    /// Holds every parent in one operation's root-to-leaf chain, while the
    /// complete inventory stores identities rather than an unbounded FD set.
    fileprivate final class GenerationDirectoryChain {
        private struct Entry {
            let name: String
            let descriptor: Int32
            let identity: Identity
        }
        private var entries: [Entry] = []

        init(rootDescriptor: Int32, rootIdentity: Identity,
             directories: [String: Identity], path: String) throws {
            do {
                let root = Darwin.openat(rootDescriptor, ".", O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
                guard root >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
                entries.append(Entry(name: "", descriptor: root, identity: rootIdentity))
                guard try StoreRestoreGenerationAuthority.identity(root) == rootIdentity else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                var prefix = ""
                for component in path.split(separator: "/") {
                    let name = String(component)
                    try StoreRestoreGenerationAuthority.requireSafeBasename(name)
                    prefix = prefix.isEmpty ? name : "\(prefix)/\(name)"
                    guard let expected = directories[prefix], let parent = entries.last else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    let child = Darwin.openat(parent.descriptor, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
                    guard child >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
                    entries.append(Entry(name: name, descriptor: child, identity: expected))
                    guard try StoreRestoreGenerationAuthority.identity(child) == expected else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
                try verify()
            } catch {
                closeDescriptors()
                throw error
            }
        }

        deinit { closeDescriptors() }
        private func closeDescriptors() {
            for entry in entries.reversed() { _ = Darwin.close(entry.descriptor) }
            entries.removeAll()
        }
        var descriptor: Int32 { entries.last!.descriptor }
        func verify() throws {
            guard !entries.isEmpty else { throw StoreGenerationFailure.dataPointerInvalid }
            for (index, entry) in entries.enumerated() {
                guard try StoreRestoreGenerationAuthority.identity(entry.descriptor) == entry.identity else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                if index > 0 {
                    guard try StoreRestoreGenerationAuthority.requiredDirectoryIdentity(
                        parent: entries[index - 1].descriptor, name: entry.name
                    ) == entry.identity else { throw StoreGenerationFailure.dataPointerInvalid }
                }
            }
        }
    }

    /// Complete preflight with bounded descriptor use: retain the root, scan
    /// depth-first, then reacquire verified parent chains for each operation.
    /// URL spellings never discover descendants or grant deletion authority.
    fileprivate final class GenerationInventory {
        struct Directory {
            let descriptor: Int32
            let identity: Identity
        }
        struct File {
            let snapshot: RegularFileSnapshot
            let ownership: GenerationOwnedPathV1.Classification
        }
        let root: Directory
        private(set) var directories: [String: Identity] = [:]
        private(set) var files: [String: File] = [:]
        private var children: [String: Set<String>] = [:]
        private let cancellationCheck: () throws -> Void
        private let defersLivePrivatePreparation: Bool
        private let c05SourceJobs: [UUID: ResumableLocalJobV1]?
        private let c05SourceEpoch: GenerationEpochV1?
        private var c05CloseUncertain = false
        private var closed = false

        /// `defersLivePrivatePreparation` is set only for protection of an
        /// installed generation (open and after-save reproof). Reserved private
        /// preparation leaves then stay outside this inventory: they exist while
        /// a live photo or finalization prepares, and after a crash they belong
        /// to startup retirement, which alone validates and disposes of them.
        init(
            parent: Int32,
            requireModel: Bool,
            partialCleanup: Bool = false,
            defersLivePrivatePreparation: Bool = false,
            c05SourceJobs: [ResumableLocalJobV1]? = nil,
            c05SourceEpoch: GenerationEpochV1? = nil,
            cancellationCheck: @escaping () throws -> Void = {}
        ) throws {
            self.cancellationCheck = cancellationCheck
            self.defersLivePrivatePreparation = defersLivePrivatePreparation
            guard (c05SourceJobs == nil) == (c05SourceEpoch == nil),
                  c05SourceJobs.map({ Set($0.map(\.id)).count == $0.count }) ?? true else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if let c05SourceJobs, let c05SourceEpoch {
                try c05SourceEpoch.validate()
                guard try c05SourceJobs.allSatisfy({ job in
                    try job.validate()
                    return job.generationEpoch == c05SourceEpoch
                }) else { throw StoreGenerationFailure.dataPointerInvalid }
                self.c05SourceJobs = Dictionary(uniqueKeysWithValues:
                    c05SourceJobs.map { ($0.id.rawValue, $0) })
            } else {
                self.c05SourceJobs = nil
            }
            self.c05SourceEpoch = c05SourceEpoch
            try cancellationCheck()
            let descriptor = Darwin.openat(parent, ".", O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
            guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
            do {
                root = Directory(descriptor: descriptor, identity: try StoreRestoreGenerationAuthority.identity(descriptor))
            } catch {
                _ = Darwin.close(descriptor)
                throw error
            }
            do {
                try scan(directory: root, prefix: "")
                try validateC05TransientIfPresent()
                let hasModel = files["model.sqlite"] != nil
                guard !requireModel || hasModel,
                      partialCleanup || hasModel
                        || (files["model.sqlite-wal"] == nil && files["model.sqlite-shm"] == nil) else {
                    throw StoreGenerationFailure.dataGenerationMissing
                }
                try revalidate()
            } catch {
                closed = true
                _ = Darwin.close(root.descriptor)
                throw error
            }
        }

        deinit { if !closed { _ = Darwin.close(root.descriptor) } }
        func close() {
            guard !closed else { return }
            closed = true
            _ = Darwin.close(root.descriptor)
        }
        var tree: Tree { Tree(directories: Set(directories.keys), files: Set(files.keys)) }
        static func parentPath(_ path: String) -> String {
            path.split(separator: "/").dropLast().joined(separator: "/")
        }
        static func basename(_ path: String) -> String {
            String(path.split(separator: "/").last!)
        }

        private func withDirectory<T>(_ path: String,
                                      _ body: (GenerationDirectoryChain) throws -> T) throws -> T {
            let chain = try GenerationDirectoryChain(rootDescriptor: root.descriptor,
                rootIdentity: root.identity, directories: directories, path: path)
            let value = try body(chain)
            try chain.verify()
            return value
        }

        /// The two reserved locations of the live finalizer and media publisher.
        /// Any node type is deferred; startup retirement fails closed on anything
        /// but an exact reserved name for a regular single-link leaf.
        static func isLivePrivatePreparation(_ name: String, directory: String) -> Bool {
            let prefix: String
            switch directory {
            case "": prefix = ".immutable-"
            case ".staging/snapshots": prefix = ".live-finalization-"
            default: return false
            }
            return name.hasPrefix(prefix) && name.hasSuffix(".tmp")
        }

        private func retainedNames(_ names: [String], in directory: String) -> [String] {
            guard defersLivePrivatePreparation else { return names }
            return names.filter { !Self.isLivePrivatePreparation($0, directory: directory) }
        }

        /// This is an Erase-source-only alternate classifier supplied by the
        /// fenced original C05 actor. It does not expand the ordinary closed
        /// generation grammar or make operational bytes backup input.
        private func classifyOwnedPath(
            _ path: String,
            nodeType: GenerationOwnedPathV1.NodeType
        ) throws -> GenerationOwnedPathV1.Classification {
            if let ordinary = try? GenerationOwnedPathV1.classify(
                path, nodeType: nodeType) {
                return ordinary
            }
            guard let c05SourceJobs,
                  c05SourceEpoch != nil,
                  !path.isEmpty, !path.hasPrefix("/"),
                  !path.hasSuffix("/"), !path.contains("\\"),
                  path.split(separator: "/", omittingEmptySubsequences: false)
                    .allSatisfy({ !$0.isEmpty && $0 != "." && $0 != ".." }) else {
                throw StoreMigrationFailure.invalidPath
            }
            let parts = path.split(separator: "/").map(String.init)
            let parents = [
                ["operational"],
                ["operational", "local-job-staging-v1"],
                ["operational", "local-job-staging-v1", "asset-label-render"],
            ]
            if nodeType == .directory, parents.contains(parts) {
                return .init(kind: .stagingDirectory, recoveryOwned: true)
            }
            guard parts.count == (nodeType == .directory ? 4 : 5),
                  Array(parts.prefix(3)) == parents[2],
                  let identifier = UUID(uuidString: parts[3]),
                  identifier.uuidString.lowercased() == parts[3],
                  let job = c05SourceJobs[identifier],
                  job.kind == .render,
                  job.stagingRelativePath == "asset-label-render/\(parts[3])" else {
                throw StoreMigrationFailure.invalidPath
            }
            return .init(
                kind: nodeType == .directory ? .stagingDirectory : .stagingFile,
                recoveryOwned: true)
        }

        private func readC05TransientFile(
            _ path: String,
            maximumBytes: Int
        ) throws -> Data {
            guard let file = files[path],
                  file.snapshot.byteCount > 0,
                  file.snapshot.byteCount <= off_t(maximumBytes) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            func readOnce() throws -> Data {
                try withFile(path) { descriptor, snapshot in
                    guard Darwin.lseek(descriptor, 0, SEEK_SET) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    var data = Data()
                    var buffer = [UInt8](repeating: 0, count: 16 * 1024)
                    while data.count < Int(snapshot.byteCount) {
                        let request = min(buffer.count,
                            Int(snapshot.byteCount) - data.count)
                        let count = buffer.withUnsafeMutableBytes { raw in
                            Darwin.read(descriptor, raw.baseAddress, request)
                        }
                        if count > 0 {
                            data.append(contentsOf: buffer.prefix(count))
                        } else if count == -1 && errno == EINTR {
                            continue
                        } else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                    guard data.count == Int(snapshot.byteCount) else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    return data
                }
            }
            let first = try readOnce()
            guard try readOnce() == first else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return first
        }

        /// Each final C45 attempt is bound to the exact canonical C05 row and
        /// complete plan/result manifest. A pre-enqueue `.stage-*` directory,
        /// unknown child or partial result never becomes deletion authority.
        private func validateC05TransientIfPresent() throws {
            guard let c05SourceJobs else { return }
            let parent = "operational/local-job-staging-v1/asset-label-render"
            let hasOperational = directories["operational"] != nil
            let hasStaging = directories["operational/local-job-staging-v1"] != nil
            let hasRender = directories[parent] != nil
            guard !hasOperational || (hasStaging && hasRender),
                  !hasStaging || (hasOperational && hasRender),
                  !hasRender || (hasOperational && hasStaging) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let attempts = directories.keys.filter { $0.hasPrefix(parent + "/") }
            guard attempts.count <= LocalJobStoreSchemaV1.maximumJobCount else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            for attempt in attempts.sorted() {
                let name = Self.basename(attempt)
                guard let identifier = UUID(uuidString: name),
                      let job = c05SourceJobs[identifier],
                      job.kind == .render else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let planPath = attempt + "/plan.json"
                let manifestPath = attempt + "/manifest.json"
                let environmentPath = attempt + "/native-text-environment.json"
                let plan = try AssetLabelCanonicalCodecV1.decode(
                    AssetLabelGenerationPlanV1.self,
                    from: readC05TransientFile(planPath,
                        maximumBytes: AssetLabelCanonicalCodecV1.maximumCanonicalByteCount))
                let manifest = try AssetLabelCanonicalCodecV1.decode(
                    LabelArtifactManifestV1.self,
                    from: readC05TransientFile(manifestPath,
                        maximumBytes: AssetLabelCanonicalCodecV1.maximumCanonicalByteCount))
                let environment = try AssetLabelCanonicalCodecV1.decode(
                    AssetLabelNativeTextEnvironmentV1.self,
                    from: readC05TransientFile(environmentPath,
                        maximumBytes: AssetLabelCanonicalCodecV1.maximumCanonicalByteCount))
                guard plan.workspaceID.rawValue == job.workspaceID,
                      plan.planSHA256 == job.immutableInputSHA256,
                      manifest.planSHA256 == plan.planSHA256 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let expectedFiles = Set([planPath, manifestPath, environmentPath]
                    + manifest.entries.map { attempt + "/" + $0.safeFilename })
                let observedFiles = Set(files.keys.filter {
                    Self.parentPath($0) == attempt
                })
                guard expectedFiles.count == 6,
                      observedFiles == expectedFiles else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let artifacts = try manifest.entries.map { entry in
                    try LabelProjectedArtifactV1(
                        kind: entry.kind,
                        safeFilename: entry.safeFilename,
                        mediaType: entry.mediaType,
                        bytes: readC05TransientFile(
                            attempt + "/" + entry.safeFilename,
                            maximumBytes: Int(AssetLabelLimitsV1.maximumBytes(for: entry.kind))),
                        itemCount: entry.itemCount)
                }
                let result = try LabelProjectionResultV1(
                    plan: plan, artifacts: artifacts,
                    nativeTextEnvironment: environment)
                guard result.manifest == manifest else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }

        private func scan(directory: Directory, prefix: String) throws {
            try cancellationCheck()
            let names = try retainedNames(StoreRestoreGenerationAuthority.names(in: directory.descriptor), in: prefix)
            children[prefix] = Set(names)
            for name in names {
                try cancellationCheck()
                try StoreRestoreGenerationAuthority.requireSafeBasename(name)
                let path = prefix.isEmpty ? name : "\(prefix)/\(name)"
                var info = stat()
                guard Darwin.fstatat(directory.descriptor, name, &info, AT_SYMLINK_NOFOLLOW) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                switch info.st_mode & S_IFMT {
                case S_IFDIR:
                    _ = try GenerationOwnedPathV1.classify(path, nodeType: .directory)
                    let child = Darwin.openat(directory.descriptor, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
                    guard child >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
                    do {
                        let identity = try StoreRestoreGenerationAuthority.identity(child)
                        guard identity == Identity(device: info.st_dev, inode: info.st_ino) else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        directories[path] = identity
                        try scan(directory: Directory(descriptor: child, identity: identity), prefix: path)
                        guard try StoreRestoreGenerationAuthority.requiredDirectoryIdentity(
                            parent: directory.descriptor, name: name
                        ) == identity else { throw StoreGenerationFailure.dataPointerInvalid }
                    } catch {
                        _ = Darwin.close(child)
                        throw error
                    }
                    _ = Darwin.close(child)
                case S_IFREG:
                    let ownership = try GenerationOwnedPathV1.classify(path, nodeType: .regularFile)
                    guard info.st_nlink == 1 else { throw StoreGenerationFailure.dataPointerInvalid }
                    let child = Darwin.openat(directory.descriptor, name, O_RDONLY | O_NONBLOCK | O_NOFOLLOW)
                    guard child >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
                    do {
                        let snapshot = try StoreRestoreGenerationAuthority.regularFileSnapshot(
                            descriptor: child, mismatchReason: .sourceMismatch)
                        guard snapshot.device == info.st_dev, snapshot.inode == info.st_ino,
                              snapshot.byteCount == info.st_size else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        files[path] = File(snapshot: snapshot, ownership: ownership)
                    } catch {
                        _ = Darwin.close(child)
                        throw error
                    }
                    _ = Darwin.close(child)
                default:
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard try retainedNames(StoreRestoreGenerationAuthority.names(in: directory.descriptor), in: prefix) == names,
                  try StoreRestoreGenerationAuthority.identity(directory.descriptor) == directory.identity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }

        func revalidate() throws {
            for path in [""] + directories.keys.sorted() {
                try cancellationCheck()
                guard let expected = children[path] else { throw StoreGenerationFailure.dataPointerInvalid }
                try withDirectory(path) { chain in
                    guard Set(try retainedNames(StoreRestoreGenerationAuthority.names(in: chain.descriptor),
                                                in: path)) == expected else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
            }
            for path in files.keys.sorted() {
                try cancellationCheck()
                try withFile(path) { _, _ in }
            }
        }

        func c05TransientWitness() throws -> C05GenerationTransientWitnessV1 {
            guard c05SourceJobs != nil, c05SourceEpoch != nil else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try validateC05TransientIfPresent()
            try revalidate()
            let transientDirectories = Set(directories.keys.filter {
                $0 == "operational" || $0.hasPrefix("operational/")
            })
            let transientFiles = Set(files.keys.filter {
                $0.hasPrefix("operational/")
            })
            var tokens = [
                "c05-transient-source-v1",
                "root|\(root.identity.device)|\(root.identity.inode)",
            ]
            for path in transientDirectories.sorted() {
                guard let identity = directories[path] else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                tokens.append("directory|\(path)|\(identity.device)|\(identity.inode)")
            }
            for path in transientFiles.sorted() {
                guard let snapshot = files[path]?.snapshot else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let bytes = try readC05TransientFile(path,
                    maximumBytes: max(
                        AssetLabelCanonicalCodecV1.maximumCanonicalByteCount,
                        Int(AssetLabelLimitsV1.maximumBytes(for: .pdf))))
                tokens.append("file|\(path)|\(snapshot.device)|\(snapshot.inode)|"
                    + "\(snapshot.byteCount)|\(snapshot.modificationSeconds)|"
                    + "\(snapshot.modificationNanoseconds)|"
                    + "\(snapshot.statusChangeSeconds)|"
                    + "\(snapshot.statusChangeNanoseconds)|"
                    + KernelCanonicalHashV1.sha256(bytes))
            }
            try revalidate()
            return C05GenerationTransientWitnessV1(
                rootDevice: UInt64(root.identity.device),
                rootInode: UInt64(root.identity.inode),
                directories: transientDirectories,
                files: transientFiles,
                sha256: KernelCanonicalHashV1.sha256(
                    Data(tokens.joined(separator: "\n").utf8)))
        }

        /// After the real C05 runner has removed each attempt, remove only
        /// the now-empty operational parents observed in the same held tree.
        /// No artifact or job directory can be swept by this method.
        func removeEmptyOriginalC05Parents(
            expectedAfterJobDrain: C05GenerationTransientWitnessV1
        ) throws {
            guard !c05CloseUncertain else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let observed = try c05TransientWitness()
            let parents = [
                "operational",
                "operational/local-job-staging-v1",
                "operational/local-job-staging-v1/asset-label-render",
            ]
            guard observed == expectedAfterJobDrain,
                  observed.files.isEmpty,
                  observed.directories.isSubset(of: Set(parents)) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var remainingChildren = children
            for path in parents.reversed() where observed.directories.contains(path) {
                guard let expectedIdentity = directories[path] else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try withDirectory(Self.parentPath(path)) { chain in
                    let name = Self.basename(path)
                    let child = Darwin.openat(chain.descriptor, name,
                        O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
                    guard child >= 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    var childNeedsClose = true
                    do {
                        try chain.verify()
                        guard Set(try StoreRestoreGenerationAuthority.names(
                            in: chain.descriptor))
                                == remainingChildren[Self.parentPath(path)],
                              try StoreRestoreGenerationAuthority.identity(child)
                                == expectedIdentity,
                              try StoreRestoreGenerationAuthority.names(in: child)
                                .isEmpty,
                              try StoreRestoreGenerationAuthority
                                .requiredDirectoryIdentity(
                                    parent: chain.descriptor, name: name)
                                == expectedIdentity,
                              Darwin.unlinkat(chain.descriptor, name,
                                AT_REMOVEDIR) == 0,
                              Darwin.fsync(chain.descriptor) == 0 else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        let closeResult = Darwin.close(child)
                        childNeedsClose = false
                        guard closeResult == 0 else {
                            c05CloseUncertain = true
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    } catch {
                        if childNeedsClose, Darwin.close(child) != 0 {
                            c05CloseUncertain = true
                        }
                        throw error
                    }
                    remainingChildren[Self.parentPath(path)]?.remove(name)
                }
            }
            guard try StoreRestoreGenerationAuthority.identity(
                root.descriptor) == root.identity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }

        /// O_NONBLOCK prevents a regular-file -> FIFO replacement from
        /// blocking before fstat. Parent descriptors live through the body.
        func withFile<T>(_ path: String, _ body: (Int32, RegularFileSnapshot) throws -> T) throws -> T {
            guard let file = files[path] else { throw StoreGenerationFailure.dataPointerInvalid }
            return try withDirectory(Self.parentPath(path)) { chain in
                let name = Self.basename(path)
                let descriptor = Darwin.openat(chain.descriptor, name, O_RDONLY | O_NONBLOCK | O_NOFOLLOW)
                guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
                defer { _ = Darwin.close(descriptor) }
                guard try StoreRestoreGenerationAuthority.regularFileSnapshot(
                    descriptor: descriptor, mismatchReason: .sourceMismatch
                ) == file.snapshot,
                      try StoreRestoreGenerationAuthority.namedRegularFileSnapshot(
                        parent: chain.descriptor, name: name, mismatchReason: .sourceMismatch
                      ) == file.snapshot else { throw StoreGenerationFailure.dataPointerInvalid }
                let value = try body(descriptor, file.snapshot)
                guard try StoreRestoreGenerationAuthority.regularFileSnapshot(
                    descriptor: descriptor, mismatchReason: .sourceMismatch
                ) == file.snapshot,
                      try StoreRestoreGenerationAuthority.namedRegularFileSnapshot(
                        parent: chain.descriptor, name: name, mismatchReason: .sourceMismatch
                      ) == file.snapshot else { throw StoreGenerationFailure.dataPointerInvalid }
                return value
            }
        }

        func requireSettledMigrationInput() throws {
            guard !files.values.contains(where: { $0.ownership.recoveryOwned }) else {
                throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
            }
        }

        func requireRestoreManifestInput(
            _ proof: StoreRestoreGenerationManifestProofV1
        ) throws {
            try proof.validate()
            let recoveryFilePaths = Set(files.compactMap { path, value in
                value.ownership.recoveryOwned ? path : nil
            })
            let recoveryDirectoryPaths = Set(try directories.keys.filter { path in
                try GenerationOwnedPathV1.classify(
                    path,
                    nodeType: .directory
                ).recoveryOwned
            })
            guard recoveryFilePaths == Set(proof.recoveryFiles.map(\.relativePath)),
                  recoveryDirectoryPaths == Set(proof.recoveryDirectories) else {
                throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
            }
            for expected in proof.recoveryFiles {
                guard let file = files[expected.relativePath],
                      file.ownership.recoveryOwned,
                      file.ownership.kind == expected.kind,
                      file.snapshot.byteCount == off_t(expected.byteCount) else {
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
            }
        }

        func fileDigests(
            durable: Bool,
            restoreProof: StoreRestoreGenerationManifestProofV1? = nil,
            includeRecoveryOwnedForEraseDiscard: Bool = false
        ) throws -> [StoreGenerationFileDigestV1] {
            if let restoreProof {
                try requireRestoreManifestInput(restoreProof)
            } else if !includeRecoveryOwnedForEraseDiscard {
                try requireSettledMigrationInput()
            }
            try revalidate()
            var values = [StoreGenerationFileDigestV1]()
            for path in files.keys.sorted() {
                try cancellationCheck()
                guard let file = files[path] else { throw StoreGenerationFailure.dataPointerInvalid }
                let digest = try withFile(path) { descriptor, snapshot in
                    let digest = try StoreRestoreGenerationAuthority.streamedDigest(
                        descriptor: descriptor,
                        expectedSnapshot: snapshot,
                        mismatchReason: .sourceMismatch,
                        cancellationCheck: cancellationCheck)
                    if durable, Darwin.fsync(descriptor) != 0 {
                        throw StoreMigrationFailure.maintenanceRequired(.targetUnavailable)
                    }
                    return digest
                }
                values.append(try StoreGenerationFileDigestV1(
                    relativePath: path, byteCount: digest.byteCount, sha256: digest.sha256, kind: file.ownership.kind))
            }
            for value in values {
                try cancellationCheck()
                let reproof = try withFile(value.relativePath) { descriptor, snapshot in
                    try StoreRestoreGenerationAuthority.streamedDigest(
                        descriptor: descriptor,
                        expectedSnapshot: snapshot,
                        mismatchReason: .sourceMismatch,
                        cancellationCheck: cancellationCheck)
                }
                guard reproof.sha256 == value.sha256 else {
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
            }
            try revalidate()
            if durable {
                for path in [""] + directories.keys.sorted() {
                    try withDirectory(path) { chain in
                        guard Darwin.fsync(chain.descriptor) == 0 else {
                            throw StoreMigrationFailure.maintenanceRequired(.targetUnavailable)
                        }
                    }
                }
            }
            if let restoreProof {
                let recovery = try values.filter {
                    try GenerationOwnedPathV1.classify(
                        $0.relativePath,
                        nodeType: .regularFile
                    ).recoveryOwned
                }
                guard recovery == restoreProof.recoveryFiles else {
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
                let observed = Dictionary(
                    uniqueKeysWithValues: values.map {
                        ($0.relativePath, $0)
                    }
                )
                guard restoreProof.generationFiles.allSatisfy({
                    observed[$0.relativePath] == $0
                }) else {
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
            }
            return values
        }

        /// Directory tokens leave both historical flat SQLite encodings intact.
        var directoryIdentityTokens: [String] {
            directories.keys.sorted().map { path in
                let identity = directories[path]!
                return "subdirectory|\(path)|\(identity.device)|\(identity.inode)"
            }
        }

        func frozenIdentityDigest(
            restoreProof: StoreRestoreGenerationManifestProofV1
        ) throws -> String {
            try requireRestoreManifestInput(restoreProof)
            let directory = root.identity
            var tokens = ["directory|\(directory.device)|\(directory.inode)"]
            for name in files.keys.sorted() {
                guard let file = files[name] else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let identity = file.snapshot
                tokens.append(
                    "\(name)|\(identity.device)|\(identity.inode)|\(identity.linkCount)"
                )
            }
            tokens.append(contentsOf: directoryIdentityTokens)
            return StoreMigrationCanonicalJSONV1.sha256(
                Data(tokens.joined(separator: "\n").utf8)
            )
        }

        func snapshotFacts(rootName: String) throws
            -> [StoreRestoreGenerationFileSnapshotV1.NodeFact] {
            try StoreRestoreGenerationAuthority.requireSafeBasename(rootName)
            var result = [StoreRestoreGenerationFileSnapshotV1.NodeFact(
                relativePath: "",
                parentRelativePath: "",
                name: rootName,
                type: .directory,
                device: UInt64(root.identity.device),
                inode: UInt64(root.identity.inode),
                linkCount: nil,
                byteCount: nil,
                modificationSeconds: nil,
                modificationNanoseconds: nil,
                statusChangeSeconds: nil,
                statusChangeNanoseconds: nil
            )]
            for path in directories.keys.sorted() {
                guard let identity = directories[path] else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                result.append(.init(
                    relativePath: path,
                    parentRelativePath: Self.parentPath(path),
                    name: Self.basename(path),
                    type: .directory,
                    device: UInt64(identity.device),
                    inode: UInt64(identity.inode),
                    linkCount: nil,
                    byteCount: nil,
                    modificationSeconds: nil,
                    modificationNanoseconds: nil,
                    statusChangeSeconds: nil,
                    statusChangeNanoseconds: nil
                ))
            }
            for path in files.keys.sorted() {
                guard let file = files[path] else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let value = file.snapshot
                result.append(.init(
                    relativePath: path,
                    parentRelativePath: Self.parentPath(path),
                    name: Self.basename(path),
                    type: .regularFile,
                    device: UInt64(value.device),
                    inode: UInt64(value.inode),
                    linkCount: UInt64(value.linkCount),
                    byteCount: Int(value.byteCount),
                    modificationSeconds: value.modificationSeconds,
                    modificationNanoseconds: value.modificationNanoseconds,
                    statusChangeSeconds: value.statusChangeSeconds,
                    statusChangeNanoseconds: value.statusChangeNanoseconds
                ))
            }
            return result.sorted {
                if $0.relativePath != $1.relativePath {
                    return $0.relativePath < $1.relativePath
                }
                return $0.type.rawValue < $1.type.rawValue
            }
        }

        func verifyProtection(rootURL: URL, staging: Bool) throws {
            try revalidate()
            let rootKind: OwnedFileKindV1 = staging ? .restoreStaging : .durableDirectory
            try ProtectedFilePolicyV1.verify(rootKind, at: rootURL)
            for path in directories.keys.sorted() + files.keys.sorted() {
                try cancellationCheck()
                let isDirectory = directories[path] != nil
                let owned = try GenerationOwnedPathV1.classify(
                    path,
                    nodeType: isDirectory ? .directory : .regularFile
                )
                let kind: OwnedFileKindV1 = staging
                    ? (isDirectory ? .stagingDirectory : .stagingFile)
                    : owned.kind
                try ProtectedFilePolicyV1.verify(
                    kind,
                    at: rootURL.appendingPathComponent(
                        path,
                        isDirectory: isDirectory
                    )
                )
            }
            try revalidate()
        }

        func protect(rootURL: URL, staging: Bool,
                     apply: (OwnedFileKindV1, URL, @escaping () throws -> Void) throws -> Void) throws {
            try revalidate()
            for path in directories.keys.sorted() + files.keys.sorted() {
                let isDirectory = directories[path] != nil
                let owned = try GenerationOwnedPathV1.classify(path, nodeType: isDirectory ? .directory : .regularFile)
                let kind: OwnedFileKindV1 = staging
                    ? (isDirectory ? .stagingDirectory : .stagingFile) : owned.kind
                let parentPath = isDirectory ? path : Self.parentPath(path)
                try withDirectory(parentPath) { chain in
                    let check = {
                        try chain.verify()
                        guard try StoreRestoreGenerationAuthority.directoryIdentity(at: rootURL) == self.root.identity else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        if !isDirectory {
                            guard let file = self.files[path],
                                  try StoreRestoreGenerationAuthority.namedRegularFileSnapshot(
                                    parent: chain.descriptor, name: Self.basename(path), mismatchReason: .sourceMismatch
                                  ) == file.snapshot else { throw StoreGenerationFailure.dataPointerInvalid }
                        }
                    }
                    try apply(kind, rootURL.appendingPathComponent(path, isDirectory: isDirectory), check)
                }
            }
            try revalidate()
        }

        func removeAll(authorityCheck: () throws -> Void = {}) throws {
            // The full classified tree is checked before the first unlink.
            try authorityCheck()
            try revalidate()
            var remainingChildren = children
            for path in files.keys.sorted() {
                guard let file = files[path] else { throw StoreGenerationFailure.dataPointerInvalid }
                try withDirectory(Self.parentPath(path)) { chain in
                    let name = Self.basename(path)
                    try authorityCheck()
                    try chain.verify()
                    guard Set(try StoreRestoreGenerationAuthority.names(in: chain.descriptor))
                            == remainingChildren[Self.parentPath(path)],
                          try StoreRestoreGenerationAuthority.namedRegularFileSnapshot(
                        parent: chain.descriptor, name: name, mismatchReason: .sourceMismatch
                    ) == file.snapshot,
                          Darwin.unlinkat(chain.descriptor, name, 0) == 0,
                          Darwin.fsync(chain.descriptor) == 0 else { throw StoreGenerationFailure.dataPointerInvalid }
                    remainingChildren[Self.parentPath(path)]?.remove(name)
                }
            }
            let bottomUp = directories.keys.sorted {
                let left = $0.split(separator: "/").count, right = $1.split(separator: "/").count
                return left == right ? $0 > $1 : left > right
            }
            for path in bottomUp {
                guard let expected = directories[path] else { throw StoreGenerationFailure.dataPointerInvalid }
                try withDirectory(Self.parentPath(path)) { chain in
                    let name = Self.basename(path)
                    let child = Darwin.openat(chain.descriptor, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
                    guard child >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
                    defer { _ = Darwin.close(child) }
                    try authorityCheck()
                    try chain.verify()
                    guard Set(try StoreRestoreGenerationAuthority.names(in: chain.descriptor))
                            == remainingChildren[Self.parentPath(path)],
                          try StoreRestoreGenerationAuthority.identity(child) == expected,
                          try StoreRestoreGenerationAuthority.names(in: child).isEmpty,
                          try StoreRestoreGenerationAuthority.requiredDirectoryIdentity(
                            parent: chain.descriptor, name: name
                          ) == expected,
                          Darwin.unlinkat(chain.descriptor, name, AT_REMOVEDIR) == 0,
                          Darwin.fsync(chain.descriptor) == 0 else { throw StoreGenerationFailure.dataPointerInvalid }
                    remainingChildren[Self.parentPath(path)]?.remove(name)
                }
            }
            try authorityCheck()
            guard try StoreRestoreGenerationAuthority.identity(root.descriptor) == root.identity,
                  try StoreRestoreGenerationAuthority.names(in: root.descriptor).isEmpty,
                  Darwin.fsync(root.descriptor) == 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        }
    }

    struct Presence {
        let staging: Bool
        let installed: Bool
    }

    struct Tree: Equatable {
        let directories: Set<String>
        let files: Set<String>
    }

    struct C05GenerationTransientWitnessV1: Equatable, Sendable {
        let rootDevice: UInt64
        let rootInode: UInt64
        let directories: Set<String>
        let files: Set<String>
        let sha256: String
    }

    /// Descriptor-relative, byte-stable snapshot returned by the V1 -> V2
    /// copy-on-write clone.  The source identities are deliberately reduced to
    /// digests before this value leaves the authority; callers never receive a
    /// path-derived authority that could be rebound after a rename.
    struct MigrationCloneResult {
        let files: [StoreGenerationFileDigestV1]
        let sourceTreeDigest: String
        let frozenIdentityDigest: String
    }

    final class InstalledGenerationHandle {
        fileprivate let id: UUID
        fileprivate let descriptor: Int32
        fileprivate let identity: Identity

        fileprivate init(id: UUID, descriptor: Int32, identity: Identity) {
            self.id = id
            self.descriptor = descriptor
            self.identity = identity
        }

        deinit {
            _ = Darwin.close(descriptor)
        }
    }

    private static let dataName = "FieldEvidenceData"
    private static let restoreName = "FieldEvidenceRestore"
    private static let generationsName = "generations"
    private static let importStagingName = "staging"
    private static let pointerMutationLock = NSLock()

    private let applicationSupportURL: URL
    private let applicationSupportDescriptor: Int32
    private let applicationSupportIdentity: Identity
    private let dataDescriptor: Int32
    private let dataIdentity: Identity
    private let installedGenerationsDescriptor: Int32
    private let installedGenerationsIdentity: Identity
    private let restoreDescriptor: Int32
    private let restoreIdentity: Identity
    private let stagingGenerationsDescriptor: Int32
    private let stagingGenerationsIdentity: Identity
    private let importStagingDescriptor: Int32
    private let importStagingIdentity: Identity
    fileprivate let mutationRegistry: GenerationLeaseRegistryV1

    /// Identity comparison only; this does not expose or mint Registry authority.
    func matchesMutationRegistryForOriginalErase(
        _ registry: GenerationLeaseRegistryV1
    ) -> Bool {
        mutationRegistry === registry
    }
    fileprivate let c05SourceGenerationID: UUID?
    fileprivate let c05SourceEpoch: GenerationEpochV1?
    fileprivate let c05SourceJobs: [ResumableLocalJobV1]?
    private var originalC05ParentRemovalUncertain = false
    private let originalRecoveryNoCreate: Bool
    private let originalRecoveryIO = EraseAbortCheckedSnapshotIOV1()
    private var originalRecoveryCloseAttempted = false
    private(set) var eraseRetirementTerminalCloseAttempted = false

    /// Immutable origin identity only; no access to the closed descriptors.
    fileprivate func matchesTerminalSourceDirectories(supportDevice: dev_t,
        supportInode: ino_t, dataDevice: dev_t, dataInode: ino_t) -> Bool {
        eraseRetirementTerminalCloseAttempted
            && applicationSupportIdentity.device == supportDevice
            && applicationSupportIdentity.inode == supportInode
            && dataIdentity.device == dataDevice && dataIdentity.inode == dataInode
    }

    fileprivate func matchesTerminalSourcePointer(data: Data, fact: stat) -> Bool {
        guard eraseRetirementTerminalCloseAttempted,
              let provenance = eraseRetirementPointerProvenance["current.json"] else { return false }
        let expectedData: Data
        let expectedFact: String
        switch provenance {
        case .captured(let bytes, let token), .published(let bytes, let token):
            expectedData = bytes; expectedFact = token
        }
        return data == expectedData
            && Self.eraseRetirementFactToken(EraseRetirementFileFact(fact)) == expectedFact
    }

    fileprivate func matchesTerminalSourceGenerationParent(_ fact: stat) -> Bool {
        eraseRetirementTerminalCloseAttempted && fact.st_mode & S_IFMT == S_IFDIR
            && fact.st_dev == installedGenerationsIdentity.device
            && fact.st_ino == installedGenerationsIdentity.inode
    }
    private var originalRecoveryRetiredStageAttempted = false
    private var originalRecoveryRetiredRenameAttempted = false
    private static let originalRecoveryUncertainCloseLock = NSLock()
    nonisolated(unsafe) private static var originalRecoveryUncertainDescriptors: [Int32] = []

    init(
        applicationSupportURL: URL,
        expectedApplicationSupportIdentity: StoreApplicationSupportIdentity? = nil,
        mutationRegistry: GenerationLeaseRegistryV1? = nil,
        c05SourceGenerationID: UUID? = nil,
        c05SourceEpoch: GenerationEpochV1? = nil,
        c05SourceJobs: [ResumableLocalJobV1]? = nil,
        originalRecoveryNoCreate: Bool = false
    ) throws {
        guard (c05SourceGenerationID == nil) == (c05SourceEpoch == nil),
              (c05SourceEpoch == nil) == (c05SourceJobs == nil),
              c05SourceEpoch == nil
                || c05SourceEpoch?.generationID == c05SourceGenerationID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let root = applicationSupportURL.standardizedFileURL
        guard root.isFileURL else { throw StoreGenerationFailure.dataPointerInvalid }
        let app = Darwin.open(root.path, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard app >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        var retained = [app]
        var succeeded = false
        defer {
            if !succeeded {
                for descriptor in retained.reversed() {
                    if Darwin.close(descriptor) != 0 && originalRecoveryNoCreate {
                        Self.originalRecoveryUncertainCloseLock.withLock {
                            Self.originalRecoveryUncertainDescriptors.append(descriptor)
                        }
                    }
                }
            }
        }

        let appIdentity = try Self.identity(app)
        if let expectedApplicationSupportIdentity {
            guard appIdentity.device == expectedApplicationSupportIdentity.device,
                  appIdentity.inode == expectedApplicationSupportIdentity.inode else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        let data = try Self.openDirectory(parent: app, name: Self.dataName)
        retained.append(data)
        let dataIdentity = try Self.identity(data)
        let installed = try Self.openDirectory(
            parent: data,
            name: Self.generationsName
        )
        retained.append(installed)
        let installedIdentity = try Self.identity(installed)
        let restore = try (originalRecoveryNoCreate
            ? Self.openDirectory(parent: app, name: Self.restoreName)
            : Self.openOrCreateDirectory(parent: app, name: Self.restoreName))
        retained.append(restore)
        let restoreIdentity = try Self.identity(restore)
        let stagingGenerations = try (originalRecoveryNoCreate
            ? Self.openDirectory(parent: restore, name: Self.generationsName)
            : Self.openOrCreateDirectory(parent: restore, name: Self.generationsName))
        retained.append(stagingGenerations)
        let stagingGenerationsIdentity = try Self.identity(stagingGenerations)
        let importStaging = try (originalRecoveryNoCreate
            ? Self.openDirectory(parent: restore, name: Self.importStagingName)
            : Self.openOrCreateDirectory(parent: restore, name: Self.importStagingName))
        retained.append(importStaging)
        let importStagingIdentity = try Self.identity(importStaging)

        self.applicationSupportURL = root
        self.applicationSupportDescriptor = app
        self.applicationSupportIdentity = appIdentity
        self.dataDescriptor = data
        self.dataIdentity = dataIdentity
        self.installedGenerationsDescriptor = installed
        self.installedGenerationsIdentity = installedIdentity
        self.restoreDescriptor = restore
        self.restoreIdentity = restoreIdentity
        self.stagingGenerationsDescriptor = stagingGenerations
        self.stagingGenerationsIdentity = stagingGenerationsIdentity
        self.importStagingDescriptor = importStaging
        self.importStagingIdentity = importStagingIdentity
        self.c05SourceGenerationID = c05SourceGenerationID
        self.c05SourceEpoch = c05SourceEpoch
        self.c05SourceJobs = c05SourceJobs
        self.originalRecoveryNoCreate = originalRecoveryNoCreate
        guard !originalRecoveryNoCreate || mutationRegistry != nil else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        self.mutationRegistry = try mutationRegistry ?? GenerationLeaseRegistryV1(applicationSupportURL: root)
        if !originalRecoveryNoCreate {
            try protectAuthorityRoots()
        }
        succeeded = true
    }

    deinit {
        if !originalRecoveryCloseAttempted && !eraseRetirementTerminalCloseAttempted {
            _ = Darwin.close(importStagingDescriptor)
            _ = Darwin.close(stagingGenerationsDescriptor)
            _ = Darwin.close(restoreDescriptor)
            _ = Darwin.close(installedGenerationsDescriptor)
            _ = Darwin.close(dataDescriptor)
            _ = Darwin.close(applicationSupportDescriptor)
        }
    }

    /// All six descriptors must settle before the recovery owner may reopen
    /// producer admission. An uncertain close remains quarantined for process
    /// life, never retried by deinit.
    func closeCheckedForOriginalRecovery() throws {
        guard originalRecoveryNoCreate, !originalRecoveryCloseAttempted else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        originalRecoveryCloseAttempted = true
        do { try verify() }
        catch {
            Self.originalRecoveryUncertainCloseLock.withLock {
                Self.originalRecoveryUncertainDescriptors.append(contentsOf: [
                    importStagingDescriptor, stagingGenerationsDescriptor,
                    restoreDescriptor, installedGenerationsDescriptor,
                    dataDescriptor, applicationSupportDescriptor])
            }
            throw error
        }
        var uncertain = false
        for fd in [importStagingDescriptor, stagingGenerationsDescriptor,
                   restoreDescriptor, installedGenerationsDescriptor,
                   dataDescriptor, applicationSupportDescriptor] {
            if Darwin.close(fd) != 0 {
                Self.originalRecoveryUncertainCloseLock.withLock {
                    Self.originalRecoveryUncertainDescriptors.append(fd)
                }
                uncertain = true
            }
        }
        guard !uncertain else { throw StoreGenerationFailure.dataPointerInvalid }
    }

    private struct EraseTerminalDirectoryFact: Equatable {
        let device: dev_t
        let inode: ino_t
        let mode: mode_t
        let links: nlink_t
        let uid: uid_t
        let gid: gid_t
        let size: off_t
        let modificationSeconds: Int
        let modificationNanoseconds: Int
        let changeSeconds: Int
        let changeNanoseconds: Int

        init(_ value: stat) {
            device = value.st_dev; inode = value.st_ino
            mode = value.st_mode; links = value.st_nlink
            uid = value.st_uid; gid = value.st_gid; size = value.st_size
            modificationSeconds = value.st_mtimespec.tv_sec
            modificationNanoseconds = value.st_mtimespec.tv_nsec
            changeSeconds = value.st_ctimespec.tv_sec
            changeNanoseconds = value.st_ctimespec.tv_nsec
        }
    }

    /// Never opens a replacement path or silently closes a transient FD.
    /// The named and held facts must match twice before the first close.
    private func requireEraseTerminalHeldAndNamedDirectories() throws {
        let directories: [(Int32, Identity, Int32?, String?)] = [
            (applicationSupportDescriptor, applicationSupportIdentity, nil, nil),
            (dataDescriptor, dataIdentity, applicationSupportDescriptor, Self.dataName),
            (installedGenerationsDescriptor, installedGenerationsIdentity,
                dataDescriptor, Self.generationsName),
            (restoreDescriptor, restoreIdentity, applicationSupportDescriptor, Self.restoreName),
            (stagingGenerationsDescriptor, stagingGenerationsIdentity,
                restoreDescriptor, Self.generationsName),
            (importStagingDescriptor, importStagingIdentity,
                restoreDescriptor, Self.importStagingName)
        ]
        func readFacts() throws -> [EraseTerminalDirectoryFact] {
            try directories.map { fd, identity, parent, name in
                var heldBefore = stat(), named = stat(), heldAfter = stat()
                guard Darwin.fstat(fd, &heldBefore) == 0,
                      (parent == nil
                        ? Darwin.lstat(applicationSupportURL.path, &named) == 0
                        : Darwin.fstatat(parent!, name!, &named, AT_SYMLINK_NOFOLLOW) == 0),
                      Darwin.fstat(fd, &heldAfter) == 0,
                      heldBefore.st_mode & S_IFMT == S_IFDIR,
                      EraseTerminalDirectoryFact(heldBefore) == EraseTerminalDirectoryFact(named),
                      EraseTerminalDirectoryFact(heldAfter) == EraseTerminalDirectoryFact(named),
                      heldAfter.st_dev == identity.device,
                      heldAfter.st_ino == identity.inode else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                return EraseTerminalDirectoryFact(named)
            }
        }
        let first = try readFacts()
        guard try readFacts() == first else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    /// Terminal transfer for the ordinary original/cold/legacy erase owner.
    /// Once a close starts, even a failed close never retries its numeric FD.
    @MainActor
    func closeCheckedForEraseRetirement(cleanup: EraseCleanupAfterRetirementV1,
        proof: ErasedRegistryRetirementProofV1) throws
        -> EraseGenerationAuthorityTerminalCloseReceiptV1 {
        guard !originalRecoveryNoCreate, !originalRecoveryCloseAttempted,
              !eraseRetirementTerminalCloseAttempted,
              !originalC05ParentRemovalUncertain,
              eraseRetirementUncertainDescriptors.isEmpty,
              !originalErasePointerEffectUncertain,
              applicationSupportURL.standardizedFileURL
                == proof.binding.subject.applicationSupportURL.standardizedFileURL,
              Int64(applicationSupportIdentity.device)
                == proof.binding.subject.applicationSupportDevice,
              UInt64(applicationSupportIdentity.inode)
                == proof.binding.subject.applicationSupportInode else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try cleanup.requireTerminalAuthorityCloseAdmission(authority: self, proof: proof)
        try eraseRetirementCheckedSnapshotIO.requireSettled()
        try originalRecoveryIO.requireSettled()
        try originalErasePointerCheckedIO.requireSettled()
#if DEBUG
        try completedAbortIO.requireSettled()
#endif
        try requireEraseTerminalHeldAndNamedDirectories()
        try cleanup.requireTerminalAuthorityCloseAdmission(authority: self, proof: proof)
        eraseRetirementTerminalCloseAttempted = true
        var uncertain = false
        for fd in [importStagingDescriptor, stagingGenerationsDescriptor,
                   restoreDescriptor, installedGenerationsDescriptor,
                   dataDescriptor, applicationSupportDescriptor] {
            if Darwin.close(fd) != 0 {
                Self.originalRecoveryUncertainCloseLock.withLock {
                    Self.originalRecoveryUncertainDescriptors.append(fd)
                }
                uncertain = true
            }
        }
        guard !uncertain else { throw StoreGenerationFailure.dataPointerInvalid }
        return EraseGenerationAuthorityTerminalCloseReceiptV1(
            authority: self, cleanup: cleanup, proof: proof)
    }

    private var dataURL: URL {
        applicationSupportURL.appendingPathComponent(Self.dataName, isDirectory: true)
    }

    private var installedGenerationsURL: URL {
        dataURL.appendingPathComponent(Self.generationsName, isDirectory: true)
    }

    private var restoreURL: URL {
        applicationSupportURL.appendingPathComponent(Self.restoreName, isDirectory: true)
    }

    private var stagingGenerationsURL: URL {
        restoreURL.appendingPathComponent(Self.generationsName, isDirectory: true)
    }

    private var importStagingURL: URL {
        restoreURL.appendingPathComponent(Self.importStagingName, isDirectory: true)
    }

    private func enforce(
        _ kind: OwnedFileKindV1,
        at url: URL,
        authorityCheck: @escaping () throws -> Void = {}
    ) throws {
        do {
            let root = applicationSupportURL.standardizedFileURL
            let target = url.standardizedFileURL
            let insideRoot = root.path == "/"
                ? target.path.hasPrefix("/")
                : target.path.hasPrefix(root.path + "/")
            guard insideRoot else {
                throw ProtectedFilePolicyError.invalidRelativePath
            }
            let relativePath = String(target.path.dropFirst(root.path.count))
                .trimmingCharacters(in: CharacterSet(charactersIn: "/"))
            try ProtectedFilePolicyV1.applyAndVerify(
                kind,
                relativePath: relativePath,
                within: root,
                authorityCheck: {
                    try self.verify()
                    try authorityCheck()
                }
            )
        } catch let failure as StoreGenerationFailure {
            throw failure
        } catch let error as ProtectedFilePolicyError
            where error == .protectedDataUnavailable {
            throw error
        } catch {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private func enforceGenerationFile(
        descriptor: Int32,
        root: URL,
        name: String,
        kind: OwnedFileKindV1,
        authorityCheck: @escaping () throws -> Void = {}
    ) throws {
        try Self.requireSafeBasename(name)
        let generationIdentity = try StoreRestoreGenerationAuthority.directoryIdentity(
            descriptor: descriptor
        )
        let fileDescriptor = Darwin.openat(
            descriptor,
            name,
            O_RDONLY | O_NONBLOCK | O_NOFOLLOW
        )
        guard fileDescriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.close(fileDescriptor) }
        let fileIdentity = try Self.regularFileIdentity(descriptor: fileDescriptor)
        let url = root.appendingPathComponent(name, isDirectory: false)
        try enforce(
            kind,
            at: url,
            authorityCheck: {
                try authorityCheck()
                guard try StoreRestoreGenerationAuthority.directoryIdentity(
                          descriptor: descriptor
                      ) == generationIdentity,
                      try Self.directoryIdentity(at: root) == generationIdentity,
                      try Self.regularFileIdentity(descriptor: fileDescriptor)
                          == fileIdentity,
                      try Self.regularFileIdentity(at: url) == fileIdentity else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        )
    }

    private func protectAuthorityRoots() throws {
        try enforce(.durableDirectory, at: dataURL)
        try enforce(.durableDirectory, at: installedGenerationsURL)
        try enforce(.stagingDirectory, at: restoreURL)
        try enforce(.stagingDirectory, at: stagingGenerationsURL)
        try enforce(.stagingDirectory, at: importStagingURL)
    }

    private func protectKnownStoreFiles(
        parent: Int32,
        id: UUID,
        root: URL,
        rootKind: OwnedFileKindV1,
        requireModel: Bool = false
    ) throws {
        let descriptor = Darwin.openat(parent, Self.canonical(id), O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        let inventory = try GenerationInventory(parent: descriptor, requireModel: requireModel)
        let generationIdentity = inventory.root.identity
        try enforce(rootKind, at: root, authorityCheck: {
            try inventory.revalidate()
            guard try Self.requiredDirectoryIdentity(parent: parent, name: Self.canonical(id)) == generationIdentity,
                  try Self.directoryIdentity(at: root) == generationIdentity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        })
        try inventory.protect(rootURL: root, staging: rootKind == .restoreStaging) { kind, url, check in
            try self.enforce(kind, at: url, authorityCheck: check)
        }
        guard try Self.requiredDirectoryIdentity(parent: parent, name: Self.canonical(id)) == generationIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    func protectStagingGeneration(
        id: UUID,
        requireModel: Bool = false
    ) throws {
        try requireStagingGeneration(id: id)
        let root = stagingGenerationsURL.appendingPathComponent(
            Self.canonical(id),
            isDirectory: true
        )
        try protectKnownStoreFiles(
            parent: stagingGenerationsDescriptor,
            id: id,
            root: root,
            rootKind: .restoreStaging,
            requireModel: requireModel
        )
        try requireStagingGeneration(id: id)
    }

    func protectInstalledGeneration(
        id: UUID,
        requireModel: Bool = false
    ) throws {
        try requireInstalledGeneration(id: id)
        let root = installedGenerationsURL.appendingPathComponent(
            Self.canonical(id),
            isDirectory: true
        )
        try protectKnownStoreFiles(
            parent: installedGenerationsDescriptor,
            id: id,
            root: root,
            rootKind: .durableDirectory,
            requireModel: requireModel
        )
        try requireInstalledGeneration(id: id)
    }

    func protectStagingFile(
        id: UUID,
        name: String,
        kind: OwnedFileKindV1,
        ifPresent: Bool = false
    ) throws {
        try Self.requireSafeBasename(name)
        try requireStagingGeneration(id: id)
        let root = stagingGenerationsURL.appendingPathComponent(
            Self.canonical(id),
            isDirectory: true
        )
        let descriptor = Darwin.openat(
            stagingGenerationsDescriptor,
            Self.canonical(id),
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.close(descriptor) }
        if ifPresent, try !Self.itemExists(parent: descriptor, name: name) { return }
        try enforceGenerationFile(
            descriptor: descriptor,
            root: root,
            name: name,
            kind: kind
        )
        try requireStagingGeneration(id: id)
    }

    func protectInstalledFile(
        id: UUID,
        name: String,
        kind: OwnedFileKindV1,
        ifPresent: Bool = false
    ) throws {
        try Self.requireSafeBasename(name)
        try requireInstalledGeneration(id: id)
        let root = installedGenerationsURL.appendingPathComponent(
            Self.canonical(id),
            isDirectory: true
        )
        let descriptor = Darwin.openat(
            installedGenerationsDescriptor,
            Self.canonical(id),
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.close(descriptor) }
        if ifPresent, try !Self.itemExists(parent: descriptor, name: name) { return }
        try enforceGenerationFile(
            descriptor: descriptor,
            root: root,
            name: name,
            kind: kind
        )
        try requireInstalledGeneration(id: id)
    }

    fileprivate static func requireSafeBasename(_ name: String) throws {
        guard !name.isEmpty,
              name != ".",
              name != "..",
              !name.contains("/"),
              !name.contains("\\") else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    fileprivate static func requireExactGenerationContents(
        parent: Int32,
        requireModel: Bool
    ) throws {
        _ = try exactGenerationEntries(parent: parent, requireModel: requireModel)
    }

    fileprivate static func exactGenerationEntries(
        parent: Int32,
        requireModel: Bool
    ) throws -> Set<String> {
        let inventory = try GenerationInventory(parent: parent, requireModel: requireModel)
        try inventory.revalidate()
        return inventory.tree.files
    }

    func verify() throws {
        guard !eraseRetirementTerminalCloseAttempted else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try Self.require(applicationSupportDescriptor, applicationSupportIdentity)
        try Self.require(dataDescriptor, dataIdentity)
        try Self.require(installedGenerationsDescriptor, installedGenerationsIdentity)
        try Self.require(restoreDescriptor, restoreIdentity)
        try Self.require(stagingGenerationsDescriptor, stagingGenerationsIdentity)
        try Self.require(importStagingDescriptor, importStagingIdentity)

        if originalRecoveryNoCreate {
            try originalRecoveryIO.requireSettled()
            var named = stat()
            for (parent, name, expected) in [
                (applicationSupportDescriptor, Self.dataName, dataIdentity),
                (dataDescriptor, Self.generationsName, installedGenerationsIdentity),
                (applicationSupportDescriptor, Self.restoreName, restoreIdentity),
                (restoreDescriptor, Self.generationsName, stagingGenerationsIdentity),
                (restoreDescriptor, Self.importStagingName, importStagingIdentity),
            ] {
                guard Darwin.fstatat(parent, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                    named.st_mode & S_IFMT == S_IFDIR,
                    named.st_dev == expected.device,
                    named.st_ino == expected.inode else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            return
        }

        let app = Darwin.open(
            applicationSupportURL.path,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard app >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(app) }
        guard try Self.identity(app) == applicationSupportIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let data = try Self.openDirectory(parent: app, name: Self.dataName)
        defer { _ = Darwin.close(data) }
        guard try Self.identity(data) == dataIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let installed = try Self.openDirectory(
            parent: data,
            name: Self.generationsName
        )
        defer { _ = Darwin.close(installed) }
        guard try Self.identity(installed) == installedGenerationsIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let restore = try Self.openDirectory(parent: app, name: Self.restoreName)
        defer { _ = Darwin.close(restore) }
        guard try Self.identity(restore) == restoreIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let stagingGenerations = try Self.openDirectory(
            parent: restore,
            name: Self.generationsName
        )
        defer { _ = Darwin.close(stagingGenerations) }
        guard try Self.identity(stagingGenerations) == stagingGenerationsIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let importStaging = try Self.openDirectory(
            parent: restore,
            name: Self.importStagingName
        )
        defer { _ = Darwin.close(importStaging) }
        guard try Self.identity(importStaging) == importStagingIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private func originalRecoverySQLiteIdentity(_ value: stat) -> String {
        "\(value.st_dev)|\(value.st_ino)|\(value.st_mode)|\(value.st_nlink)|\(value.st_size)|\(value.st_mtimespec.tv_sec)|\(value.st_mtimespec.tv_nsec)|\(value.st_ctimespec.tv_sec)|\(value.st_ctimespec.tv_nsec)"
    }

    /// Data only: the full first root fact brackets the entire checked walk.
    /// The caller retains the real original owner and must compare this image
    /// to its immutable first capture rather than treating it as authority.
    func originalRecoverySourceTreeImage(id: UUID) throws
        -> OriginalEraseRecoverySourceTreeImageV1 {
        guard originalRecoveryNoCreate else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        let name = Self.canonical(id)
        let image = try originalRecoveryIO.withOpen(
            parent: installedGenerationsDescriptor, name: name,
            flags: O_RDONLY | O_DIRECTORY) { root in
            func fact(_ value: stat) -> String {
                "\(value.st_dev)|\(value.st_ino)|\(value.st_mode)|\(value.st_uid)|\(value.st_gid)|\(value.st_nlink)|\(value.st_size)|\(value.st_mtimespec.tv_sec)|\(value.st_mtimespec.tv_nsec)|\(value.st_ctimespec.tv_sec)|\(value.st_ctimespec.tv_nsec)"
            }
            func heldAndNamed() throws -> String {
                var held = stat(), named = stat()
                guard Darwin.fstat(root, &held) == 0,
                      Darwin.fstatat(installedGenerationsDescriptor, name,
                          &named, AT_SYMLINK_NOFOLLOW) == 0,
                      held.st_mode & S_IFMT == S_IFDIR,
                      fact(held) == fact(named) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                return fact(held)
            }
            let before = try heldAndNamed()
            var walkedRoot: String?
            var walkedRootCount = 0
            let digest = try originalRecoveryIO.tree(
                parent: installedGenerationsDescriptor, name: name,
                observeTypedNode: { node in
                    if node.path.isEmpty {
                        walkedRootCount += 1
                        walkedRoot = fact(node.fact)
                    }
                })
            guard walkedRootCount == 1, walkedRoot == before,
                  try heldAndNamed() == before else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return OriginalEraseRecoverySourceTreeImageV1(
                rootFact: before, digest: digest)
        }
        try originalRecoveryIO.requireSettled()
        try verify()
        return image
    }

    func originalRecoverySourceTreeDigest(id: UUID) throws -> String {
        guard originalRecoveryNoCreate else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        let digest = try originalRecoveryIO.tree(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        try verify()
        return digest
    }

    /// Reprove the original P→Q Data postimage through this recovery authority's
    /// retained descriptors. The caller has just bound `receipt` to its original
    /// issuing operation under the same EX/G. Every read here is checked and
    /// nonrepairing; the original writer's complete sibling image remains the
    /// immutable baseline rather than a surviving recovery-side snapshot.
    @MainActor
    func requireOriginalRecoveryPublishedControls(
        receipt: OriginalErasePointerReceiptV1,
        intent: EraseIntentV1
    ) throws {
        guard !originalRecoveryNoCreate,
              intent.schemaVersion == 2,
              intent.phase == .pointerSwitched,
              receipt.stage == .retired,
              receipt.predecessor?.stage == .current,
              try receipt.currentGenerationID() == intent.newGenerationID,
              try receipt.retiredGenerationIDs() == intent.generationIDsToDelete else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        func requireHeldPostimage() throws {
            var support = stat(), held = stat(), named = stat()
            guard Darwin.lstat(applicationSupportURL.path, &support) == 0,
                  support.st_mode & S_IFMT == S_IFDIR,
                  support.st_dev == applicationSupportIdentity.device,
                  support.st_ino == applicationSupportIdentity.inode,
                  Darwin.fstat(dataDescriptor, &held) == 0,
                  Darwin.fstatat(applicationSupportDescriptor, Self.dataName,
                      &named, AT_SYMLINK_NOFOLLOW) == 0,
                  OriginalErasePointerFullFactV1(held) == receipt.root,
                  OriginalErasePointerFullFactV1(named) == receipt.root,
                  try originalErasePointerCheckedIO.names(in: dataDescriptor)
                      == receipt.names else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let current = try originalRecoveryIO.originalRecoveryPointerFull(
                parent: dataDescriptor, name: "current.json")
            let retired = try originalRecoveryIO.originalRecoveryPointerFull(
                parent: dataDescriptor, name: "retired.json")
            guard current.0 == receipt.other.data,
                  OriginalErasePointerFullFactV1(current.1)
                      == receipt.other.fact,
                  retired.0 == receipt.published.data,
                  OriginalErasePointerFullFactV1(retired.1)
                      == receipt.published.fact else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try requireOriginalErasePointerSiblings(
                receipt.siblings, names: receipt.names)
        }
        try originalErasePointerCheckedIO.requireSettled()
        try originalRecoveryIO.requireSettled()
        try requireHeldPostimage()
        try requireHeldPostimage()
        try originalRecoveryIO.requireSettled()
        try originalErasePointerCheckedIO.requireSettled()
    }

    /// After the original owner's first-effect EX becomes a typed Coordinator
    /// maintenance transfer, reprove the exact old source without constructing
    /// an old ModelContainer or using verify()'s ordinary transient opens.
    func requireOriginalRecoveryTransferredSourceTree(
        id: UUID, expectedDigest: String
    ) throws {
        guard !originalRecoveryNoCreate,
              StoreMigrationCanonicalJSONV1.isLowercaseSHA256(expectedDigest) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        func requireHeldNames() throws {
            try Self.require(applicationSupportDescriptor,
                applicationSupportIdentity)
            try Self.require(dataDescriptor, dataIdentity)
            try Self.require(installedGenerationsDescriptor,
                installedGenerationsIdentity)
            var support = stat(), named = stat()
            guard Darwin.lstat(applicationSupportURL.path, &support) == 0,
                  support.st_mode & S_IFMT == S_IFDIR,
                  support.st_dev == applicationSupportIdentity.device,
                  support.st_ino == applicationSupportIdentity.inode else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            for (parent, name, expected) in [
                (applicationSupportDescriptor, Self.dataName, dataIdentity),
                (dataDescriptor, Self.generationsName,
                    installedGenerationsIdentity),
            ] {
                guard Darwin.fstatat(parent, name, &named,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      named.st_mode & S_IFMT == S_IFDIR,
                      named.st_dev == expected.device,
                      named.st_ino == expected.inode else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        try originalRecoveryIO.requireSettled()
        try requireHeldNames()
        guard try originalRecoveryIO.tree(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(id)) == expectedDigest else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.requireSettled()
        try requireHeldNames()
    }

    @MainActor
    func requireOriginalRecoveryTransferredCompletedSource(
        _ receipt: OriginalRecoveryCompletedSourcePolicyV1,
        originalAuthority: StoreRestoreGenerationAuthority,
        expectedOriginalDigest: String,
        namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
        supportFact: OriginalEraseRecoveryNamespaceSnapshotV1.DirectoryFact,
        priorImage: OriginalEraseRecoveryPriorRetiredImageV1?
    ) throws {
        guard !originalRecoveryNoCreate, originalAuthority.originalRecoveryNoCreate,
              receipt.issuer == ObjectIdentifier(originalAuthority),
              receipt.originalTreeDigest == expectedOriginalDigest,
              receipt.nodes.count == receipt.policies.count,
              receipt.nodes.count == receipt.dispositions.count,
              !receipt.nodes.isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        func parents() throws {
            for (fd, expected) in [(applicationSupportDescriptor, supportFact),
                (dataDescriptor, namespace.data),
                (installedGenerationsDescriptor, namespace.installedParent),
                (restoreDescriptor, namespace.restore),
                (stagingGenerationsDescriptor, namespace.restoreGenerations),
                (importStagingDescriptor, namespace.importStaging)] {
                var value = stat()
                guard Darwin.fstat(fd, &value) == 0,
                      try OriginalEraseRecoveryNamespaceSnapshotV1.DirectoryFact(value) == expected else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            var namedSupport = stat()
            guard Darwin.lstat(applicationSupportURL.path, &namedSupport) == 0,
                  try OriginalEraseRecoveryNamespaceSnapshotV1.DirectoryFact(namedSupport)
                    == supportFact else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            for (parent, name, expected) in [
                (applicationSupportDescriptor, Self.dataName, namespace.data),
                (dataDescriptor, Self.generationsName, namespace.installedParent),
                (applicationSupportDescriptor, Self.restoreName, namespace.restore),
                (restoreDescriptor, Self.generationsName, namespace.restoreGenerations),
                (restoreDescriptor, Self.importStagingName, namespace.importStaging)
            ] {
                var named = stat()
                guard Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                      try OriginalEraseRecoveryNamespaceSnapshotV1.DirectoryFact(named) == expected else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard try originalRecoveryIO.names(in: installedGenerationsDescriptor)
                    == namespace.installedNames,
                  try originalRecoveryIO.names(in: restoreDescriptor) == namespace.restoreNames,
                  try originalRecoveryIO.names(in: stagingGenerationsDescriptor)
                    == namespace.restoreGenerationNames,
                  try originalRecoveryIO.names(in: importStagingDescriptor) == namespace.importNames else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let retired = try originalRecoveryIO.originalRecoveryPointerFull(
                parent: dataDescriptor, name: "retired.json")
            guard retired.0 == namespace.retiredBytes, retired.1 == namespace.retiredFact else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try requireOriginalRecoveryTransferredSourceTree(
                id: receipt.generationID, expectedDigest: receipt.projectedTreeDigest)
        }
        try parents()
        var byPath = [String: OriginalRecoveryProvisionalPolicyV1.Node]()
        for node in receipt.nodes {
            guard byPath.updateValue(node, forKey: node.path) == nil else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        for (node, policy) in zip(receipt.nodes, receipt.policies) {
            _ = try requireOriginalRecoveryPolicyNode(
                id: receipt.generationID, target: node, byPath: byPath)
            guard try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
                node.kind, at: originalRecoveryPolicyURL(
                    id: receipt.generationID, path: node.path),
                retainUncertainDescriptor: { [originalRecoveryIO] in
                    originalRecoveryIO.retainUncertainDescriptor($0)
                }) == policy else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            _ = try requireOriginalRecoveryPolicyNode(
                id: receipt.generationID, target: node, byPath: byPath)
        }
        if let image = priorImage {
            guard image.generationID == receipt.generationID,
                  image.sourceTreeDigest == receipt.originalTreeDigest,
                  image.namespace == namespace else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            func fullFact(_ v: stat) -> String {
                "\(v.st_dev)|\(v.st_ino)|\(v.st_mode)|\(v.st_uid)|\(v.st_gid)|\(v.st_nlink)|\(v.st_size)|\(v.st_mtimespec.tv_sec)|\(v.st_mtimespec.tv_nsec)|\(v.st_ctimespec.tv_sec)|\(v.st_ctimespec.tv_nsec)"
            }
            func check(_ fd: Int32, parent: Int32, name: String,
                kind: mode_t, expected: String) throws {
                var held = stat(), named = stat()
                guard Darwin.fstat(fd, &held) == 0,
                      Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                      held.st_mode & S_IFMT == kind,
                      kind != S_IFREG || held.st_nlink == 1,
                      fullFact(held) == expected, fullFact(named) == expected else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            try originalRecoveryIO.withOpen(parent: applicationSupportDescriptor,
                name: "FieldEvidenceOperations", flags: O_RDONLY | O_DIRECTORY) { operations in
                var heldOperations = stat()
                guard Darwin.fstat(operations, &heldOperations) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                guard fullFact(heldOperations) == image.operationsFact,
                      try originalRecoveryIO.names(in: operations)
                        == image.operationsNames else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try check(operations, parent: applicationSupportDescriptor,
                    name: "FieldEvidenceOperations", kind: S_IFDIR,
                    expected: image.operationsFact)
                try originalRecoveryIO.withOpen(parent: operations,
                    name: "schema-migration", flags: O_RDONLY | O_DIRECTORY) { migration in
                    try check(migration, parent: operations, name: "schema-migration",
                        kind: S_IFDIR, expected: image.migrationFact)
                    let name = "manifest-" + receipt.generationID.uuidString.lowercased() + ".json"
                    try originalRecoveryIO.withOpen(parent: migration, name: name,
                        flags: O_RDONLY | O_NONBLOCK) { leaf in
                        try check(leaf, parent: migration, name: name,
                            kind: S_IFREG, expected: image.manifestFact)
                        let (bytes, fact) = try originalRecoveryIO.control(parent: migration, name: name)
                        var held = stat()
                        guard Darwin.fstat(leaf, &held) == 0,
                              fact == "\(held.st_dev)|\(held.st_ino)|\(held.st_mode)|\(held.st_nlink)|\(held.st_size)|\(held.st_mtimespec.tv_sec)|\(held.st_mtimespec.tv_nsec)|\(held.st_ctimespec.tv_sec)|\(held.st_ctimespec.tv_nsec)",
                              bytes == image.manifestBytes else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        try check(leaf, parent: migration, name: name,
                            kind: S_IFREG, expected: image.manifestFact)
                    }
                    try check(migration, parent: operations, name: "schema-migration",
                        kind: S_IFDIR, expected: image.migrationFact)
                }
                guard try originalRecoveryIO.names(in: operations)
                    == image.operationsNames else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try check(operations, parent: applicationSupportDescriptor,
                    name: "FieldEvidenceOperations", kind: S_IFDIR,
                    expected: image.operationsFact)
            }
        }
        try originalRecoveryIO.requireSettled()
        try parents()
    }

    private func originalRecoveryPolicyTree(
        id: UUID, treeDigest: String?
    ) throws -> OriginalRecoveryProvisionalPolicyV1.Tree {
        try verify()
        let walk = try originalRecoveryIO.treeWithNodes(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        guard treeDigest == nil || walk.digest == treeDigest else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var children = [String: [String]]()
        var seenPaths = Set<String>()
        seenPaths.reserveCapacity(walk.nodes.count)
        for node in walk.nodes {
            guard seenPaths.insert(node.path).inserted else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        for node in walk.nodes where !node.path.isEmpty {
            let pieces = node.path.split(separator: "/").map(String.init)
            let parent = pieces.dropLast().joined(separator: "/")
            guard let name = pieces.last else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            children[parent, default: []].append(name)
        }
        let nodes = try walk.nodes.map { node in
            let kind: OwnedFileKindV1
            if node.path.isEmpty {
                guard node.fact.st_mode & S_IFMT == S_IFDIR else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                kind = .durableDirectory
            } else {
                let nodeType: GenerationOwnedPathV1.NodeType =
                    node.sha256 == nil ? .directory : .regularFile
                kind = try GenerationOwnedPathV1.classify(
                    node.path, nodeType: nodeType).kind
                if node.sha256 != nil {
                    // ReportPDFAnchoredFile infers .reportPDF for every
                    // non-staging read and .stagingFile under .staging.
                    // Its actual-read observation uses that exact kind;
                    // the generation-wide request retains the path grammar's
                    // kind and must have the identical physical disposition.
                    let reportReadKind: OwnedFileKindV1 =
                        node.path.split(separator: "/").contains(".staging")
                        ? .stagingFile : .reportPDF
                    guard ProtectedFilePolicyV1.disposition(for: kind)
                        == ProtectedFilePolicyV1.disposition(
                            for: reportReadKind) else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
            }
            return OriginalRecoveryProvisionalPolicyV1.Node(node, kind: kind,
                children: (children[node.path] ?? []).sorted())
        }
        try verify()
        return .init(digest: walk.digest, nodes: nodes)
    }

    private func originalRecoveryPolicyURL(
        id: UUID, path: String
    ) -> URL {
        let root = installedGenerationsURL
            .appendingPathComponent(Self.canonical(id), isDirectory: true)
        return path.isEmpty ? root : root.appendingPathComponent(path)
    }

    private func requireOriginalRecoveryPolicyNode(
        id: UUID, target: OriginalRecoveryProvisionalPolicyV1.Node,
        byPath: [String: OriginalRecoveryProvisionalPolicyV1.Node]
    ) throws -> OriginalRecoveryProvisionalPolicyV1.Node {
        let components = target.path.isEmpty ? []
            : target.path.split(separator: "/").map(String.init)
        guard components.joined(separator: "/") == target.path else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        func descend(_ parent: Int32, _ name: String,
            _ path: String, _ index: Int) throws {
            guard let expected = byPath[path] else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if index == components.count {
                try originalRecoveryIO.requirePolicyNode(
                    parent: parent, name: name, expected: target)
                return
            }
            guard expected.sha256 == nil else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try originalRecoveryIO.withOpen(parent: parent, name: name,
                flags: O_RDONLY | O_DIRECTORY) { directory in
                var held = stat(), named = stat()
                guard Darwin.fstat(directory, &held) == 0,
                      Darwin.fstatat(parent, name, &named,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      expected.matches(held), expected.matches(named) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let nextPath = path.isEmpty ? components[index]
                    : path + "/" + components[index]
                try descend(directory, components[index], nextPath, index + 1)
                guard Darwin.fstat(directory, &held) == 0,
                      Darwin.fstatat(parent, name, &named,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      expected.matches(held), expected.matches(named) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        try descend(installedGenerationsDescriptor, Self.canonical(id), "", 0)
        try originalRecoveryIO.requireSettled()
        return target
    }

    /// This value is only a read-only obligation. A pending DEBUG observation
    /// cannot validate source policy or authorize the first Erase effect.
    func originalRecoveryProvisionalPolicy(
        id: UUID, treeDigest: String
    ) throws -> OriginalRecoveryProvisionalPolicyV1 {
        guard originalRecoveryNoCreate else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let tree = try originalRecoveryPolicyTree(id: id,
            treeDigest: treeDigest)
        var policies = [TemporalPolicyObservationV1]()
        policies.reserveCapacity(tree.nodes.count)
        var byPath = [String: OriginalRecoveryProvisionalPolicyV1.Node]()
        byPath.reserveCapacity(tree.nodes.count)
        for node in tree.nodes {
            guard byPath.updateValue(node, forKey: node.path) == nil else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        for node in tree.nodes {
            let observed = try ProtectedFilePolicyV1
                .observeTemporalPolicyWithCheckedClose(node.kind,
                    at: originalRecoveryPolicyURL(id: id, path: node.path),
                    retainUncertainDescriptor: { [originalRecoveryIO] in
                        originalRecoveryIO.retainUncertainDescriptor($0)
                    })
            guard observed.device == UInt64(node.device),
                  observed.inode == UInt64(node.inode),
                  observed.linkCount == UInt64(node.links),
                  observed.mode == UInt16(node.mode) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            _ = try requireOriginalRecoveryPolicyNode(
                id: id, target: node, byPath: byPath)
            policies.append(observed)
        }
        guard try originalRecoveryPolicyTree(id: id,
            treeDigest: treeDigest) == tree else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.requireSettled()
        return OriginalRecoveryProvisionalPolicyV1(
            generationID: id, treeDigest: treeDigest,
            issuer: ObjectIdentifier(self), nodes: tree.nodes,
            policies: policies)
    }

    /// Read-only preflight for the complete cohort before the first setter.
    func requireOriginalRecoveryProvisionalPolicyUnchanged(
        _ provisional: OriginalRecoveryProvisionalPolicyV1
    ) throws {
        guard provisional.issuer == ObjectIdentifier(self),
              try originalRecoveryProvisionalPolicy(
                id: provisional.generationID,
                treeDigest: provisional.treeDigest)
                .sameObservedSource(as: provisional) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    func requireOriginalRecoveryExternalReadsUnchanged(
        _ reads: [OriginalEraseRecoveryExternalReadV1],
        snapshot: OriginalEraseRecoveryExternalSnapshotV1
    ) throws {
        try requireOriginalRecoveryExternalSnapshot(snapshot)
        var seen = Set<String>()
        for read in reads {
            let kind: OwnedFileKindV1 = read.family == .portable
                ? .portableExchangeSessionFile : .stagingFile
            guard read.kind == kind, read.maximum >= 0,
                  seen.insert(read.family.rawValue + ":" + read.path).inserted,
                  let observed = try originalRecoveryExternalBytes(
                    family: read.family, path: read.path,
                    snapshot: snapshot, maximum: read.maximum,
                    policyKind: read.kind)?.1,
                  observed == read.policy else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        try requireOriginalRecoveryExternalSnapshot(snapshot)
    }

    /// Called only inside the original owner's one-effect Registry G scope.
    /// The fixed pre-request physical tree is rechecked after every request;
    /// no pending observation is silently promoted or used as a new baseline.
    @MainActor func originalRecoveryCompletePolicyRequests(
        _ provisional: OriginalRecoveryProvisionalPolicyV1,
        permit: OriginalEraseRecoveryFirstEffectPermitV1,
        owner: StoreOriginalEraseRecoveryPreOpenOwnerV1
    ) throws -> OriginalRecoveryCompletedSourcePolicyV1 {
        guard originalRecoveryNoCreate,
              provisional.issuer == ObjectIdentifier(self),
              provisional.nodes.count == provisional.policies.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try permit.requireHeld()
        try owner.requireObservationUnchangedInsideOriginalRecoveryG()
        var projected = OriginalRecoveryProvisionalPolicyV1.Tree(
            digest: provisional.treeDigest, nodes: provisional.nodes)
        var policies = provisional.policies
        var dispositions = [ProtectedFileVerificationDispositionV1]()
        func observePolicies(_ tree: OriginalRecoveryProvisionalPolicyV1.Tree) throws
            -> [TemporalPolicyObservationV1] {
            try tree.nodes.map { node in
                let value = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
                    node.kind, at: originalRecoveryPolicyURL(
                        id: provisional.generationID, path: node.path),
                    retainUncertainDescriptor: { [originalRecoveryIO] in
                        originalRecoveryIO.retainUncertainDescriptor($0)
                    })
                guard value.device == UInt64(node.device),
                      value.inode == UInt64(node.inode),
                      value.linkCount == UInt64(node.links),
                      value.mode == UInt16(node.mode) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                return value
            }
        }
        for index in projected.nodes.indices {
            let target = projected.nodes[index]
            var requestInFlight = false
            func readPhysical() throws -> OriginalRecoveryProvisionalPolicyV1.Tree {
                try permit.requireHeld()
                try owner.requireObservationUnchangedInsideOriginalRecoveryG()
                let current = try originalRecoveryPolicyTree(
                    id: provisional.generationID, treeDigest: nil)
                guard current.nodes.count == projected.nodes.count else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                if requestInFlight {
                    for i in current.nodes.indices {
                        guard i == index
                            ? current.nodes[i].sameExceptPolicyChangeTime(as: projected.nodes[i])
                            : current.nodes[i] == projected.nodes[i] else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                } else {
                    guard current == projected else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
                return current
            }
            _ = try readPhysical()
            guard try observePolicies(projected) == policies else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let disposition = try ProtectedFilePolicyV1
                .verifyEraseColdTemporalPolicyWithCheckedRequest(
                    target.kind, at: originalRecoveryPolicyURL(
                        id: provisional.generationID, path: target.path),
                    retainUncertainDescriptor: { [originalRecoveryIO] in
                        originalRecoveryIO.retainUncertainDescriptor($0)
                    }, willRequestCompleteProtection: {
                        _ = try readPhysical()
                        guard try observePolicies(projected) == policies else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        requestInFlight = true
                    }, unchangedWitness: {
                        _ = try readPhysical()
                        return true
                    })
            // Only successful checked request/readback reaches this point.
            let after = try readPhysical()
            let afterPolicies = try observePolicies(after)
            for i in policies.indices where i != index {
                guard afterPolicies[i] == policies[i] else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard afterPolicies[index].state ==
                    (disposition == .verifiedComplete
                        ? .strictComplete : .pendingSimulatorRequest),
                  requestInFlight || afterPolicies[index] == policies[index],
                  try originalRecoveryPolicyTree(
                    id: provisional.generationID, treeDigest: after.digest) == after else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            projected = after
            policies = afterPolicies
            dispositions.append(disposition)
        }
        guard try originalRecoveryPolicyTree(
                id: provisional.generationID, treeDigest: projected.digest) == projected,
              try observePolicies(projected) == policies else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.requireSettled()
        try owner.requireObservationUnchangedInsideOriginalRecoveryG()
        try permit.requireHeld()
        return .init(generationID: provisional.generationID,
            originalTreeDigest: provisional.treeDigest, projectedTree: projected,
            issuer: ObjectIdentifier(self), policies: policies, dispositions: dispositions)
    }

    func requireOriginalRecoveryCompletedSourcePolicy(
        _ receipt: OriginalRecoveryCompletedSourcePolicyV1
    ) throws {
        guard originalRecoveryNoCreate, receipt.issuer == ObjectIdentifier(self),
              receipt.nodes.count == receipt.policies.count,
              receipt.nodes.count == receipt.dispositions.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let tree = OriginalRecoveryProvisionalPolicyV1.Tree(
            digest: receipt.projectedTreeDigest, nodes: receipt.nodes)
        guard try originalRecoveryPolicyTree(id: receipt.generationID,
            treeDigest: receipt.projectedTreeDigest) == tree else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        for (node, policy) in zip(receipt.nodes, receipt.policies) {
            guard try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
                node.kind, at: originalRecoveryPolicyURL(
                    id: receipt.generationID, path: node.path),
                retainUncertainDescriptor: { [originalRecoveryIO] in
                    originalRecoveryIO.retainUncertainDescriptor($0)
                }) == policy else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        guard try originalRecoveryPolicyTree(id: receipt.generationID,
            treeDigest: receipt.projectedTreeDigest) == tree else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.requireSettled()
    }

    func requireOriginalRecoveryCompletedExternalPolicy(
        _ receipt: OriginalRecoveryCompletedExternalPolicyV1
    ) throws {
        guard originalRecoveryNoCreate, receipt.issuer == ObjectIdentifier(self) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireOriginalRecoveryExternalSnapshot(receipt.projected)
        for read in receipt.reads {
            guard let expected = receipt.policies[read.family.rawValue + ":leaf:" + read.path],
                  let observed = try originalRecoveryExternalBytes(
                    family: read.family, path: read.path, snapshot: receipt.projected,
                    maximum: read.maximum, policyKind: read.kind)?.1,
                  observed == expected else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        try requireOriginalRecoveryExternalSnapshot(receipt.projected)
        try originalRecoveryIO.requireSettled()
    }

    func originalRecoveryCheckedSourceRootIdentity(
        id: UUID, treeDigest: String
    ) throws -> ReportPDFAnchoredFile.RootIdentity {
        guard originalRecoveryNoCreate else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        let walk = try originalRecoveryIO.treeWithNodes(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        guard walk.digest == treeDigest,
              let root = walk.nodes.first(where: { $0.path.isEmpty }),
              root.fact.st_mode & S_IFMT == S_IFDIR else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        return ReportPDFAnchoredFile.RootIdentity(
            device: root.fact.st_dev, inode: root.fact.st_ino)
    }

    func originalRecoveryCheckedSourceFilePresent(
        id: UUID, path: String, treeDigest: String
    ) throws -> Bool {
        guard originalRecoveryNoCreate else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try GenerationOwnedPathV1.classify(path, nodeType: .regularFile)
        try verify()
        let walk = try originalRecoveryIO.treeWithNodes(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        guard walk.digest == treeDigest else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let present = walk.nodes.contains {
            $0.path == path && $0.fact.st_mode & S_IFMT == S_IFREG
        }
        try verify()
        return present
    }

    /// The original-operation reader remains under the retained EX/G. This
    /// visitor never opens a live ModelContainer or acquires a second Registry.
    /// It rechecks the complete original tree on both sides of every byte read.
    func originalRecoveryCheckedSourceBytes(
        id: UUID, path: String, treeDigest: String,
        maximum: Int64, verifyReportReadPolicy: Bool = false
    ) throws -> Data {
        guard originalRecoveryNoCreate, !path.isEmpty,
              maximum >= 0,
              maximum <= EvidenceCurationLimitsV1.maximumSourceBytes else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try GenerationOwnedPathV1.classify(path, nodeType: .regularFile)
        let components = path.split(separator: "/").map(String.init)
        guard components.joined(separator: "/") == path else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        let first = try originalRecoveryIO.treeWithNodes(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        guard first.digest == treeDigest,
              let node = first.nodes.first(where: { $0.path == path }),
              node.fact.st_mode & S_IFMT == S_IFREG,
              node.fact.st_nlink == 1 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let policyKind: OwnedFileKindV1 = components.contains(".staging")
            ? .stagingFile : .reportPDF
        let policyURL = installedGenerationsURL
            .appendingPathComponent(Self.canonical(id), isDirectory: true)
            .appendingPathComponent(path)
        let policyBefore: TemporalPolicyObservationV1?
        if verifyReportReadPolicy {
            let observed = try ProtectedFilePolicyV1
                .observeTemporalPolicyWithCheckedClose(policyKind,
                    at: policyURL, retainUncertainDescriptor: {
                        [originalRecoveryIO] in
                        originalRecoveryIO.retainUncertainDescriptor($0)
                    })
            guard observed.state == .strictComplete
                    || observed.state == .pendingSimulatorRequest,
                  observed.device == UInt64(node.fact.st_dev),
                  observed.inode == UInt64(node.fact.st_ino),
                  observed.linkCount == UInt64(node.fact.st_nlink),
                  try originalRecoveryIO.tree(
                    parent: installedGenerationsDescriptor,
                    name: Self.canonical(id)) == treeDigest else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            policyBefore = observed
        } else {
            policyBefore = nil
        }
        let bytes = try originalRecoveryIO.withOpen(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(id), flags: O_RDONLY | O_DIRECTORY) { root in
            func read(_ parent: Int32, _ index: Int) throws -> Data {
                if index == components.count - 1 {
                    return try originalRecoveryIO.sourceBytes(
                        parent: parent, name: components[index], node: node,
                        maximum: maximum)
                }
                return try originalRecoveryIO.withOpen(parent: parent,
                    name: components[index], flags: O_RDONLY | O_DIRECTORY) {
                    try read($0, index + 1)
                }
            }
            return try read(root, 0)
        }
        guard try originalRecoveryIO.tree(parent: installedGenerationsDescriptor,
                name: Self.canonical(id)) == treeDigest else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        if let policyBefore {
            let policyAfter = try ProtectedFilePolicyV1
                .observeTemporalPolicyWithCheckedClose(policyKind,
                    at: policyURL, retainUncertainDescriptor: {
                        [originalRecoveryIO] in
                        originalRecoveryIO.retainUncertainDescriptor($0)
                    })
            guard policyAfter == policyBefore,
                  try originalRecoveryIO.tree(
                    parent: installedGenerationsDescriptor,
                    name: Self.canonical(id)) == treeDigest else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try originalRecoveryIO.requireSettled()
        }
        try verify()
        return bytes
    }

    /// The tree walker has already streamed every content byte through its
    /// checked FD owner. Reference checks need its exact size/hash, not a
    /// second potentially gigabyte-sized Data materialization.
    func originalRecoveryCheckedContentReference(
        id: UUID, reference: ContentReferenceV1, treeDigest: String
    ) throws -> ContentReferenceV1 {
        guard originalRecoveryNoCreate,
              reference.byteLength >= 0,
              reference.byteLength <= EvidenceCurationLimitsV1.maximumSourceBytes,
              let expected = reference.digests.digest(for: .sha256) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let path = "content/\(reference.workspaceID)/\(reference.contentID)/original.bin"
        _ = try GenerationOwnedPathV1.classify(path, nodeType: .regularFile)
        try verify()
        let walk = try originalRecoveryIO.treeWithNodes(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        guard walk.digest == treeDigest,
              let node = walk.nodes.first(where: { $0.path == path }),
              node.fact.st_mode & S_IFMT == S_IFREG,
              node.fact.st_nlink == 1,
              node.fact.st_size == reference.byteLength,
              node.sha256 == expected.hexadecimalValue else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let url = installedGenerationsURL
            .appendingPathComponent(Self.canonical(id), isDirectory: true)
            .appendingPathComponent(path)
        let firstPolicy = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
            .mediaOriginal, at: url,
            retainUncertainDescriptor: { [originalRecoveryIO] in
                originalRecoveryIO.retainUncertainDescriptor($0)
            })
        guard firstPolicy.state == .strictComplete
                || firstPolicy.state == .pendingSimulatorRequest,
              try originalRecoveryIO.tree(parent: installedGenerationsDescriptor,
                  name: Self.canonical(id)) == treeDigest else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let secondPolicy = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
            .mediaOriginal, at: url,
            retainUncertainDescriptor: { [originalRecoveryIO] in
                originalRecoveryIO.retainUncertainDescriptor($0)
            })
        guard secondPolicy == firstPolicy else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        guard try originalRecoveryIO.tree(parent: installedGenerationsDescriptor,
                name: Self.canonical(id)) == treeDigest else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.requireSettled()
        try verify()
        return reference
    }

    /// A fresh target has no file-backed user payload before its one writer is
    /// installed. This checked walk captures every target node and rejects an
    /// extra directory, link or file before the first canonical phase effect.
    func originalRecoveryEmptyTargetTreeDigest(id: UUID) throws -> String {
        guard originalRecoveryNoCreate else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        let walk = try originalRecoveryIO.treeWithNodes(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        let allowed: Set<String> = ["model.sqlite", "model.sqlite-wal", "model.sqlite-shm"]
        guard walk.nodes.contains(where: { $0.path == "" && $0.fact.st_mode & S_IFMT == S_IFDIR }),
              walk.nodes.contains(where: { $0.path == "model.sqlite" }),
              walk.nodes.allSatisfy({ node in
                  node.path.isEmpty || (allowed.contains(node.path)
                      && node.fact.st_mode & S_IFMT == S_IFREG
                      && node.fact.st_nlink == 1
                      && node.sha256 != nil)
              }) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        return walk.digest
    }

    /// Checked held/named directory and complete child census while the
    /// original recovery owner holds the same Support EX and Registry G.
    /// The target-current pointer/manifest and source trees are separately
    /// authenticated; this snapshot closes their surrounding namespace.
    func originalRecoveryNamespaceSnapshot(intent: EraseIntentV1) throws
        -> OriginalEraseRecoveryNamespaceSnapshotV1 {
        guard originalRecoveryNoCreate, intent.schemaVersion == 2,
              intent.targetPointer?.generationID == intent.newGenerationID,
              intent.oldPointer != nil else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        func fact(parent: Int32, name: String, opened: Int32) throws
            -> OriginalEraseRecoveryNamespaceSnapshotV1.DirectoryFact {
            var held = stat(), named = stat()
            guard Darwin.fstat(opened, &held) == 0,
                  Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let actual = try OriginalEraseRecoveryNamespaceSnapshotV1.DirectoryFact(held)
            guard actual == (try OriginalEraseRecoveryNamespaceSnapshotV1.DirectoryFact(named)) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return actual
        }
        func captureFacts() throws -> [OriginalEraseRecoveryNamespaceSnapshotV1.DirectoryFact] {
            try [
                fact(parent: applicationSupportDescriptor, name: Self.dataName,
                     opened: dataDescriptor),
                fact(parent: dataDescriptor, name: Self.generationsName,
                     opened: installedGenerationsDescriptor),
                fact(parent: applicationSupportDescriptor, name: Self.restoreName,
                     opened: restoreDescriptor),
                fact(parent: restoreDescriptor, name: Self.generationsName,
                     opened: stagingGenerationsDescriptor),
                fact(parent: restoreDescriptor, name: Self.importStagingName,
                     opened: importStagingDescriptor),
            ]
        }
        let before = try captureFacts()
        let dataNames = try originalRecoveryIO.names(in: dataDescriptor)
        func captureDataChildren() throws
            -> [String: OriginalEraseRecoveryNamespaceSnapshotV1.DataChildFact] {
            var children = [String: OriginalEraseRecoveryNamespaceSnapshotV1.DataChildFact]()
            for name in dataNames {
                var named = stat()
                guard Darwin.fstatat(dataDescriptor, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let kind = named.st_mode & S_IFMT
                guard kind == S_IFDIR || kind == S_IFREG else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let child = try originalRecoveryIO.withOpen(
                    parent: dataDescriptor, name: name,
                    flags: kind == S_IFDIR
                        ? O_RDONLY | O_DIRECTORY : O_RDONLY | O_NONBLOCK) {
                    descriptor -> OriginalEraseRecoveryNamespaceSnapshotV1.DataChildFact in
                    var held = stat(), namedAfter = stat()
                    guard Darwin.fstat(descriptor, &held) == 0,
                          Darwin.fstatat(dataDescriptor, name, &namedAfter,
                              AT_SYMLINK_NOFOLLOW) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    if kind == S_IFDIR {
                        let fact = try OriginalEraseRecoveryNamespaceSnapshotV1
                            .DirectoryFact(held)
                        guard fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                                .DirectoryFact(named)),
                              fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                                .DirectoryFact(namedAfter)) else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        return .directory(fact)
                    }
                    let fact = try OriginalEraseRecoveryNamespaceSnapshotV1
                        .RegularFact(held)
                    guard fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                            .RegularFact(named)),
                          fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                            .RegularFact(namedAfter)) else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    return .regular(fact)
                }
                guard children.updateValue(child, forKey: name) == nil else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            return children
        }
        let firstDataChildren = try captureDataChildren()
        let installed = try originalRecoveryIO.names(in: installedGenerationsDescriptor)
        let restore = try originalRecoveryIO.names(in: restoreDescriptor)
        let restoreGenerations = try originalRecoveryIO.names(in: stagingGenerationsDescriptor)
        let imports = try originalRecoveryIO.names(in: importStagingDescriptor)
        let current = try originalRecoveryIO.originalRecoveryPointerFull(
            parent: dataDescriptor, name: "current.json")
        guard try CurrentPointerCodecV1.decode(current.0).generationID
                == Self.canonical(intent.newGenerationID) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let retired = try originalRecoveryIO.originalRecoveryPointerFull(
            parent: dataDescriptor, name: "retired.json")
        let pointer: RetiredPointerV1 = try Self.decodeCanonicalPointer(retired.0)
        try StorePointerSchemaRegistry.requireRetired(pointer.schemaVersion)
        let expectedInstalled = (intent.generationIDsToDelete + [intent.newGenerationID])
            .map(Self.canonical).sorted()
        let complete = intent.generationIDsToDelete.map(Self.canonical)
        let prior = intent.generationIDsToDelete
            .filter { $0 != intent.oldGenerationID }.map(Self.canonical)
        let retiredState: OriginalEraseRecoveryNamespaceSnapshotV1.RetiredState
        if pointer.generationIDs == complete {
            retiredState = .complete
        } else if intent.phase == .emptyGenerationPrepared,
                  pointer.generationIDs == prior {
            retiredState = .prior
        } else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let currentAfter = try originalRecoveryIO.originalRecoveryPointerFull(
            parent: dataDescriptor, name: "current.json")
        let retiredAfter = try originalRecoveryIO.originalRecoveryPointerFull(
            parent: dataDescriptor, name: "retired.json")
        guard installed == expectedInstalled,
              restore == [Self.generationsName, Self.importStagingName].sorted(),
              restoreGenerations.isEmpty, imports.isEmpty,
              try captureFacts() == before,
              try originalRecoveryIO.names(in: dataDescriptor) == dataNames,
              try captureDataChildren() == firstDataChildren,
              firstDataChildren["current.json"] == .regular(current.1),
              firstDataChildren["retired.json"] == .regular(retired.1),
              firstDataChildren[Self.generationsName]
                == .directory(before[1]),
              try originalRecoveryIO.names(in: installedGenerationsDescriptor) == installed,
              try originalRecoveryIO.names(in: restoreDescriptor) == restore,
              try originalRecoveryIO.names(in: stagingGenerationsDescriptor) == restoreGenerations,
              try originalRecoveryIO.names(in: importStagingDescriptor) == imports,
              currentAfter.0 == current.0,
              currentAfter.1 == current.1,
              retiredAfter.0 == retired.0,
              retiredAfter.1 == retired.1 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.requireSettled()
        try verify()
        return OriginalEraseRecoveryNamespaceSnapshotV1(
            data: before[0], dataChildren: firstDataChildren,
            installedParent: before[1], restore: before[2],
            restoreGenerations: before[3], importStaging: before[4],
            dataNames: dataNames,
            installedNames: installed, restoreNames: restore,
            restoreGenerationNames: restoreGenerations, importNames: imports,
            currentBytes: current.0, currentFact: current.1,
            retiredBytes: retired.0, retiredFact: retired.1,
            retiredState: retiredState)
    }

    /// Computes the exact proposed post-retirement bytes from the immutable
    /// first P cut. This is data only: the separate original-operation Store
    /// commitment must bind these bytes before any pointer temporary exists.
    func originalRecoveryRetiredReplacementBytes(
        intent: EraseIntentV1,
        namespace: OriginalEraseRecoveryNamespaceSnapshotV1
    ) throws -> Data {
        guard originalRecoveryNoCreate,
              intent.schemaVersion == 2,
              intent.phase == .emptyGenerationPrepared,
              namespace.retiredState == .prior,
              namespace.dataNames == ["current.json", "generations", "retired.json"],
              namespace.dataChildren.count == 3,
              namespace.dataChildren["current.json"]
                == .regular(namespace.currentFact),
              namespace.dataChildren["retired.json"]
                == .regular(namespace.retiredFact),
              namespace.dataChildren[Self.generationsName]
                == .directory(namespace.installedParent),
              try CurrentPointerCodecV1.decode(namespace.currentBytes).generationID
                  == Self.canonical(intent.newGenerationID) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let prior: RetiredPointerV1 = try Self.decodeCanonicalPointer(
            namespace.retiredBytes)
        try StorePointerSchemaRegistry.requireRetired(prior.schemaVersion)
        let expectedPrior = intent.generationIDsToDelete
            .filter { $0 != intent.oldGenerationID }.map(Self.canonical)
        let complete = intent.generationIDsToDelete.map(Self.canonical)
        guard prior.generationIDs == expectedPrior,
              complete == complete.sorted(),
              Set(complete).count == complete.count,
              !complete.contains(Self.canonical(intent.newGenerationID)) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return try Self.canonicalData(RetiredPointerV1(
            generationIDs: complete,
            schemaVersion: StorePointerSchemaRegistry.retiredVersion))
    }

    private func originalRecoveryRetiredStageRead(_ name: String,
        expectedBytes: Data) throws
        -> OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact {
        guard expectedBytes.count <= 4 * 1024 * 1024 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return try originalRecoveryIO.withOpen(parent: dataDescriptor,
            name: name, flags: O_RDONLY | O_NONBLOCK) { descriptor in
            var held = stat(), named = stat(), after = stat(), namedAfter = stat()
            guard Darwin.fstat(descriptor, &held) == 0,
                  Darwin.fstatat(dataDescriptor, name, &named,
                      AT_SYMLINK_NOFOLLOW) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let fact = try OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact(held)
            guard fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                    .RegularFact(named)),
                  fact.mode & 0o7777 == 0o600,
                  fact.size == off_t(expectedBytes.count) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var bytes = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    guard count <= expectedBytes.count,
                          bytes.count <= expectedBytes.count - count else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    bytes.append(contentsOf: buffer.prefix(count))
                } else if count == 0 { break }
                else if errno != EINTR {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard bytes == expectedBytes,
                  Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(dataDescriptor, name, &namedAfter,
                      AT_SYMLINK_NOFOLLOW) == 0,
                  fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                    .RegularFact(after)),
                  fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                    .RegularFact(namedAfter)) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return fact
        }
    }

    private func requireOriginalRecoveryRetiredStageProjection(
        first: OriginalEraseRecoveryNamespaceSnapshotV1,
        after: OriginalEraseRecoveryNamespaceSnapshotV1,
        stageName: String,
        stageFact: OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact
    ) throws {
        guard !first.dataNames.contains(stageName),
              !first.dataChildren.keys.contains(stageName),
              first.data.device == after.data.device,
              first.data.inode == after.data.inode,
              first.data.mode == after.data.mode,
              first.data.user == after.data.user,
              first.data.group == after.data.group,
              after.dataNames == (first.dataNames + [stageName]).sorted(),
              after.dataChildren.count == first.dataChildren.count + 1,
              after.dataChildren[stageName] == .regular(stageFact),
              first.dataChildren.allSatisfy({ after.dataChildren[$0.key] == $0.value }),
              after.installedParent == first.installedParent,
              after.restore == first.restore,
              after.restoreGenerations == first.restoreGenerations,
              after.importStaging == first.importStaging,
              after.installedNames == first.installedNames,
              after.restoreNames == first.restoreNames,
              after.restoreGenerationNames == first.restoreGenerationNames,
              after.importNames == first.importNames,
              after.currentBytes == first.currentBytes,
              after.currentFact == first.currentFact,
              after.retiredBytes == first.retiredBytes,
              after.retiredFact == first.retiredFact,
              after.retiredState == first.retiredState else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let directoryCount = first.dataChildren.values.reduce(0) { count, child in
            if case .directory = child { return count + 1 }
            return count
        }
        let firstLinks = Int64(first.data.links)
        let afterLinks = Int64(after.data.links)
        var allowed = Set<Int64>()
        if firstLinks == 2 { allowed.insert(2) }
        if firstLinks == 2 + Int64(directoryCount) {
            allowed.insert(2 + Int64(directoryCount))
        }
        if firstLinks == 2 + Int64(first.dataChildren.count) {
            allowed.insert(2 + Int64(first.dataChildren.count) + 1)
        }
        guard allowed.count == 1, allowed.contains(afterLinks) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    @MainActor
    func requireOriginalRecoveryRetiredPrivateStage(
        _ receipt: OriginalEraseRecoveryRetiredStageReceiptV1,
        namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
        replacementBytes: Data
    ) throws {
        try verify()
        let stageFact = try originalRecoveryRetiredStageRead(
            receipt.privateStageName, expectedBytes: replacementBytes)
        guard stageFact == receipt.stageFact else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let current = try originalRecoveryNamespaceSnapshot(
            intent: receipt.intent)
        try requireOriginalRecoveryRetiredStageProjection(
            first: namespace, after: current,
            stageName: receipt.privateStageName, stageFact: stageFact)
        guard current.data == receipt.afterDataFact else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.requireSettled()
        try verify()
    }

    /// Creates only this operation's absent private stage under the second
    /// original-recovery G interval. Success is a same-process receipt; the
    /// separate Store inode record is required before any rename or replay.
    @MainActor
    func prepareOriginalRecoveryRetiredPrivateStage(
        intent: EraseIntentV1,
        namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
        replacementBytes: Data,
        commitment: EraseIntentStore.OriginalRecoveryRetiredCommitmentReceiptV1,
        operation: EraseRouterOperationV1,
        owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
        permit: OriginalEraseRecoveryRetiredStagePermitV1
    ) throws -> OriginalEraseRecoveryRetiredStageReceiptV1 {
        guard originalRecoveryNoCreate,
              !originalRecoveryRetiredStageAttempted,
              intent.schemaVersion == 2,
              intent.phase == .emptyGenerationPrepared,
              namespace.retiredState == .prior,
              namespace.dataNames == ["current.json", "generations", "retired.json"],
              replacementBytes.count <= 4 * 1024 * 1024 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try permit.requireHeld()
        try commitment.requireBound(operation: operation, owner: owner,
            namespace: namespace, replacementBytes: replacementBytes)
        let names = try commitment.requireReservedDataStageNames(
            operation: operation, owner: owner,
            namespace: namespace, replacementBytes: replacementBytes)
        let stageName = names.privateStageName
        guard !namespace.dataNames.contains(stageName),
              !namespace.dataNames.contains(names.canonicalTempName) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try owner.requireObservationUnchangedInsideOriginalRecoveryG()
        guard try originalRecoveryNamespaceSnapshot(intent: intent) == namespace,
              try originalRecoveryRetiredReplacementBytes(intent: intent,
                  namespace: namespace) == replacementBytes else {
            throw StoreGenerationFailure.dataPointerInvalid
        }

        // This sticky latch is set before O_EXCL. A failed or ambiguous
        // checked close never permits a second same-process creation attempt.
        originalRecoveryRetiredStageAttempted = true
        do {
            var createdFact: OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact?
            _ = try originalRecoveryIO.withOpen(parent: dataDescriptor,
                name: stageName, flags: O_WRONLY | O_CREAT | O_EXCL,
                mode: mode_t(0o600)) { descriptor in
                var created = stat(), named = stat()
                guard Darwin.fstat(descriptor, &created) == 0,
                      Darwin.fstatat(dataDescriptor, stageName, &named,
                          AT_SYMLINK_NOFOLLOW) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let fact = try OriginalEraseRecoveryNamespaceSnapshotV1
                    .RegularFact(created)
                guard fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                        .RegularFact(named)),
                      fact.mode & 0o7777 == 0o600,
                      fact.user == Darwin.getuid(),
                      fact.group == namespace.data.group,
                      fact.size == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try replacementBytes.withUnsafeBytes { raw in
                    guard let base = raw.baseAddress else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    var offset = 0
                    while offset < raw.count {
                        let count = Darwin.write(descriptor,
                            base.advanced(by: offset), raw.count - offset)
                        if count > 0 { offset += count }
                        else if count < 0 && errno == EINTR { continue }
                        else { throw StoreGenerationFailure.dataPointerInvalid }
                    }
                }
                var finished = stat(), namedFinished = stat()
                guard Darwin.fsync(descriptor) == 0,
                      Darwin.fstat(descriptor, &finished) == 0,
                      Darwin.fstatat(dataDescriptor, stageName, &namedFinished,
                          AT_SYMLINK_NOFOLLOW) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let finalFact = try OriginalEraseRecoveryNamespaceSnapshotV1
                    .RegularFact(finished)
                guard finalFact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                        .RegularFact(namedFinished)),
                      finalFact.device == fact.device,
                      finalFact.inode == fact.inode,
                      finalFact.mode == fact.mode,
                      finalFact.links == fact.links,
                      finalFact.user == fact.user,
                      finalFact.group == fact.group,
                      finalFact.size == off_t(replacementBytes.count) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                createdFact = finalFact
            }
            guard Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let beforePolicyFact = try originalRecoveryRetiredStageRead(
                stageName, expectedBytes: replacementBytes)
            guard let createdFact, beforePolicyFact == createdFact else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let afterCreate = try originalRecoveryNamespaceSnapshot(intent: intent)
            try requireOriginalRecoveryRetiredStageProjection(
                first: namespace, after: afterCreate,
                stageName: stageName, stageFact: beforePolicyFact)

            let stageURL = applicationSupportURL
                .appendingPathComponent(Self.dataName, isDirectory: true)
                .appendingPathComponent(stageName, isDirectory: false)
            var setterStarted = false
            func requireSameStageBeforeAndAfterPolicy(
                allowOwnedCTimeDrift: Bool
            ) throws {
                try permit.requireHeld()
                try owner.requireObservationUnchangedInsideOriginalRecoveryG()
                let fact = try originalRecoveryRetiredStageRead(stageName,
                    expectedBytes: replacementBytes)
                guard fact.device == beforePolicyFact.device,
                      fact.inode == beforePolicyFact.inode,
                      fact.mode == beforePolicyFact.mode,
                      fact.links == beforePolicyFact.links,
                      fact.user == beforePolicyFact.user,
                      fact.group == beforePolicyFact.group,
                      fact.size == beforePolicyFact.size,
                      fact.modifiedSeconds == beforePolicyFact.modifiedSeconds,
                      fact.modifiedNanoseconds == beforePolicyFact.modifiedNanoseconds,
                      allowOwnedCTimeDrift || (
                        fact.changedSeconds == beforePolicyFact.changedSeconds
                        && fact.changedNanoseconds == beforePolicyFact.changedNanoseconds
                      ) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let current = try originalRecoveryNamespaceSnapshot(intent: intent)
                try requireOriginalRecoveryRetiredStageProjection(
                    first: namespace, after: current,
                    stageName: stageName, stageFact: fact)
                guard current.data == afterCreate.data else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            let disposition = try ProtectedFilePolicyV1
                .applyAndVerifyEraseColdPrivateWithCheckedClose(
                    .generationPointerTemporary, at: stageURL,
                    retainUncertainDescriptor: { [self] in
                        originalRecoveryIO.retainUncertainDescriptor($0)
                    }, authorityCheck: {
                        try requireSameStageBeforeAndAfterPolicy(
                            allowOwnedCTimeDrift: setterStarted)
                    }, beforeFirstEffect: {
                        try requireSameStageBeforeAndAfterPolicy(
                            allowOwnedCTimeDrift: false)
                        setterStarted = true
                    })
            try requireSameStageBeforeAndAfterPolicy(
                allowOwnedCTimeDrift: true)
            _ = try originalRecoveryIO.withOpen(parent: dataDescriptor,
                name: stageName, flags: O_RDONLY | O_NONBLOCK) { descriptor in
                guard Darwin.fsync(descriptor) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let finalFact = try originalRecoveryRetiredStageRead(
                stageName, expectedBytes: replacementBytes)
            let final = try originalRecoveryNamespaceSnapshot(intent: intent)
            try requireOriginalRecoveryRetiredStageProjection(
                first: namespace, after: final,
                stageName: stageName, stageFact: finalFact)
            guard final.data == afterCreate.data else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try originalRecoveryIO.requireSettled()
            let receipt = OriginalEraseRecoveryRetiredStageReceiptV1(
                authority: self, operation: operation, owner: owner,
                commitment: commitment, permit: permit, intent: intent,
                namespace: namespace, replacementBytes: replacementBytes,
                privateStageName: stageName, afterDataFact: final.data,
                stageFact: finalFact, policyDisposition: disposition)
            try receipt.requireBound(authority: self, operation: operation,
                owner: owner, commitment: commitment, namespace: namespace,
                replacementBytes: replacementBytes)
            return receipt
        } catch {
            owner.poisonOnUncertainScratch()
            throw error
        }
    }

    private func originalRecoveryExactRetiredControlRead(
        _ name: String, bytes expectedBytes: Data
    ) throws -> OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact {
        guard expectedBytes.count <= 4 * 1024 * 1024 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return try originalRecoveryIO.withOpen(parent: dataDescriptor,
            name: name, flags: O_RDONLY | O_NONBLOCK) { descriptor in
            var held = stat(), named = stat(), after = stat(), namedAfter = stat()
            guard Darwin.fstat(descriptor, &held) == 0,
                  Darwin.fstatat(dataDescriptor, name, &named,
                      AT_SYMLINK_NOFOLLOW) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let fact = try OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact(held)
            guard fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                    .RegularFact(named)),
                  fact.size == off_t(expectedBytes.count) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var data = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    guard count <= expectedBytes.count,
                          data.count <= expectedBytes.count - count else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    data.append(contentsOf: buffer.prefix(count))
                } else if count == 0 { break }
                else if errno != EINTR {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard data == expectedBytes,
                  Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(dataDescriptor, name, &namedAfter,
                      AT_SYMLINK_NOFOLLOW) == 0,
                  fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                    .RegularFact(after)),
                  fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                    .RegularFact(namedAfter)) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return fact
        }
    }

    private func originalRecoveryDataDirectoryFact()
        throws -> OriginalEraseRecoveryNamespaceSnapshotV1.DirectoryFact {
        var held = stat(), named = stat()
        guard Darwin.fstat(dataDescriptor, &held) == 0,
              Darwin.fstatat(applicationSupportDescriptor, Self.dataName,
                  &named, AT_SYMLINK_NOFOLLOW) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let fact = try OriginalEraseRecoveryNamespaceSnapshotV1.DirectoryFact(held)
        guard fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                .DirectoryFact(named)) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return fact
    }

    @MainActor
    func requireOriginalRecoveryRetiredNamedTemporary(
        _ receipt: OriginalEraseRecoveryRetiredNamedTemporaryReceiptV1,
        namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
        replacementBytes: Data
    ) throws {
        try verify()
        let names = try originalRecoveryIO.names(in: dataDescriptor)
        guard names == (["current.json", "generations", "retired.json",
            receipt.temporaryName]).sorted(),
              let current = try? originalRecoveryIO.originalRecoveryPointerFull(
                  parent: dataDescriptor, name: "current.json"),
              current.0 == namespace.currentBytes,
              current.1 == namespace.currentFact,
              try originalRecoveryExactRetiredControlRead(
                  "retired.json", bytes: namespace.retiredBytes)
                    == namespace.retiredFact,
              try originalRecoveryRetiredStageRead(receipt.temporaryName,
                  expectedBytes: replacementBytes) == receipt.temporaryFact else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var generationHeld = stat(), generationNamed = stat()
        guard Darwin.fstat(installedGenerationsDescriptor,
                  &generationHeld) == 0,
              Darwin.fstatat(dataDescriptor, Self.generationsName,
                  &generationNamed, AT_SYMLINK_NOFOLLOW) == 0,
              try OriginalEraseRecoveryNamespaceSnapshotV1
                .DirectoryFact(generationHeld) == namespace.installedParent,
              try OriginalEraseRecoveryNamespaceSnapshotV1
                .DirectoryFact(generationNamed) == namespace.installedParent,
              try originalRecoveryDataDirectoryFact() == receipt.afterDataFact,
              try originalRecoveryIO.names(in: dataDescriptor) == names else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.requireSettled()
        try verify()
    }

    /// Moves only the operation-owned, inode-recorded private stage to the
    /// reserved temporary name. It does not swap or publish retired.json.
    @MainActor
    func publishOriginalRecoveryRetiredNamedTemporary(
        intent: EraseIntentV1,
        namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
        replacementBytes: Data,
        commitment: EraseIntentStore.OriginalRecoveryRetiredCommitmentReceiptV1,
        stage: OriginalEraseRecoveryRetiredStageReceiptV1,
        stageIdentity: EraseIntentStore.OriginalRecoveryRetiredStageIdentityReceiptV1,
        operation: EraseRouterOperationV1,
        owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
        permit: OriginalEraseRecoveryRetiredStagePermitV1
    ) throws -> OriginalEraseRecoveryRetiredNamedTemporaryReceiptV1 {
        guard originalRecoveryNoCreate,
              !originalRecoveryRetiredRenameAttempted,
              intent.schemaVersion == 2,
              intent.phase == .emptyGenerationPrepared,
              namespace.retiredState == .prior,
              stage.intent == intent else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try permit.requireHeld()
        try stageIdentity.requireBound(operation: operation, owner: owner,
            commitment: commitment, stage: stage,
            namespace: namespace, replacementBytes: replacementBytes)
        try owner.requireObservationUnchangedInsideOriginalRecoveryG()
        try stage.requireBound(authority: self, operation: operation,
            owner: owner, commitment: commitment,
            namespace: namespace, replacementBytes: replacementBytes)
        let tempName = try commitment.requireReservedDataStageNames(
            operation: operation, owner: owner,
            namespace: namespace,
            replacementBytes: replacementBytes).canonicalTempName
        let beforeDataFact = try originalRecoveryDataDirectoryFact()
        guard beforeDataFact == stage.afterDataFact,
              try originalRecoveryIO.names(in: dataDescriptor)
                == (["current.json", "generations", "retired.json",
                    stage.privateStageName]).sorted() else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireOriginalRecoveryRetiredPrivateStage(stage,
            namespace: namespace, replacementBytes: replacementBytes)
        originalRecoveryRetiredRenameAttempted = true
        do {
            guard Darwin.renameatx_np(dataDescriptor, stage.privateStageName,
                    dataDescriptor, tempName, UInt32(RENAME_EXCL)) == 0,
                  Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let temporaryFact = try originalRecoveryRetiredStageRead(
                tempName, expectedBytes: replacementBytes)
            guard temporaryFact.device == stage.stageFact.device,
                  temporaryFact.inode == stage.stageFact.inode,
                  temporaryFact.mode == stage.stageFact.mode,
                  temporaryFact.links == stage.stageFact.links,
                  temporaryFact.user == stage.stageFact.user,
                  temporaryFact.group == stage.stageFact.group,
                  temporaryFact.size == stage.stageFact.size,
                  temporaryFact.modifiedSeconds
                    == stage.stageFact.modifiedSeconds,
                  temporaryFact.modifiedNanoseconds
                    == stage.stageFact.modifiedNanoseconds else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let afterDataFact = try originalRecoveryDataDirectoryFact()
            guard afterDataFact.device == beforeDataFact.device,
                  afterDataFact.inode == beforeDataFact.inode,
                  afterDataFact.mode == beforeDataFact.mode,
                  afterDataFact.links == beforeDataFact.links,
                  afterDataFact.user == beforeDataFact.user,
                  afterDataFact.group == beforeDataFact.group else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let receipt = OriginalEraseRecoveryRetiredNamedTemporaryReceiptV1(
                authority: self, operation: operation, owner: owner,
                stage: stage, commitment: commitment,
                stageIdentity: stageIdentity, permit: permit,
                namespace: namespace, replacementBytes: replacementBytes,
                temporaryName: tempName, afterDataFact: afterDataFact,
                temporaryFact: temporaryFact)
            try receipt.requireBound(authority: self, operation: operation,
                owner: owner, stage: stage, commitment: commitment,
                stageIdentity: stageIdentity, namespace: namespace,
                replacementBytes: replacementBytes)
            let tempURL = applicationSupportURL
                .appendingPathComponent(Self.dataName, isDirectory: true)
                .appendingPathComponent(tempName, isDirectory: false)
            let policy = try ProtectedFilePolicyV1
                .observeTemporalPolicyWithCheckedClose(
                    .generationPointerTemporary, at: tempURL,
                    retainUncertainDescriptor: { [self] in
                        originalRecoveryIO.retainUncertainDescriptor($0)
                    })
            guard policy.device == UInt64(temporaryFact.device),
                  policy.inode == UInt64(temporaryFact.inode),
                  policy.linkCount == UInt64(temporaryFact.links),
                  policy.mode == UInt16(temporaryFact.mode),
                  policy.backupExcluded == true,
                  policy.isDirectory == false,
                  (policy.state == .strictComplete
                    || (policy.state == .pendingSimulatorRequest
                        && stage.policyDisposition
                          == .simulatorFileProtectionUnsupported)) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try receipt.requireBound(authority: self, operation: operation,
                owner: owner, stage: stage, commitment: commitment,
                stageIdentity: stageIdentity, namespace: namespace,
                replacementBytes: replacementBytes)
            return receipt
        } catch {
            owner.poisonOnUncertainScratch()
            throw error
        }
    }

    private func originalRecoverySameRenamedInode(
        _ before: OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact,
        _ after: OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact
    ) -> Bool {
        before.device == after.device && before.inode == after.inode
            && before.mode == after.mode && before.links == after.links
            && before.user == after.user && before.group == after.group
            && before.size == after.size
            && before.modifiedSeconds == after.modifiedSeconds
            && before.modifiedNanoseconds == after.modifiedNanoseconds
    }

    @MainActor
    func requireOriginalRecoveryRetiredCanonical(
        _ receipt: OriginalEraseRecoveryRetiredCanonicalReceiptV1,
        namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
        replacementBytes: Data
    ) throws {
        try verify()
        let after = try originalRecoveryNamespaceSnapshot(intent: receipt.intent)
        guard after.retiredState == .complete,
              after.dataNames == namespace.dataNames,
              after.dataChildren.count == namespace.dataChildren.count,
              after.dataChildren["current.json"] == namespace.dataChildren["current.json"],
              after.dataChildren["generations"] == namespace.dataChildren["generations"],
              after.dataChildren["retired.json"] == .regular(receipt.retiredFact),
              after.currentBytes == namespace.currentBytes,
              after.currentFact == namespace.currentFact,
              after.retiredBytes == replacementBytes,
              after.retiredFact == receipt.retiredFact,
              after.installedParent == namespace.installedParent,
              after.restore == namespace.restore,
              after.restoreGenerations == namespace.restoreGenerations,
              after.importStaging == namespace.importStaging,
              after.installedNames == namespace.installedNames,
              after.restoreNames == namespace.restoreNames,
              after.restoreGenerationNames == namespace.restoreGenerationNames,
              after.importNames == namespace.importNames,
              after.data.device == namespace.data.device,
              after.data.inode == namespace.data.inode,
              after.data.mode == namespace.data.mode,
              after.data.links == namespace.data.links,
              after.data.user == namespace.data.user,
              after.data.group == namespace.data.group,
              after.data == receipt.finalDataFact else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.requireSettled()
        try verify()
    }

    /// Performs the checked swap of the inode-bound temp with retired.json,
    /// then unlinks only the displaced, first-captured retired inode. The
    /// caller must keep the second original-recovery G permit alive through
    /// this entire method; every uncertain post-swap cut poisons the owner.
    @MainActor
    func publishOriginalRecoveryRetiredCanonical(
        intent: EraseIntentV1,
        namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
        replacementBytes: Data,
        commitment: EraseIntentStore.OriginalRecoveryRetiredCommitmentReceiptV1,
        stage: OriginalEraseRecoveryRetiredStageReceiptV1,
        stageIdentity: EraseIntentStore.OriginalRecoveryRetiredStageIdentityReceiptV1,
        temporary: OriginalEraseRecoveryRetiredNamedTemporaryReceiptV1,
        operation: EraseRouterOperationV1,
        owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
        permit: OriginalEraseRecoveryRetiredStagePermitV1
    ) throws -> OriginalEraseRecoveryRetiredCanonicalReceiptV1 {
        guard originalRecoveryNoCreate,
              originalRecoveryRetiredRenameAttempted,
              intent.schemaVersion == 2,
              intent.phase == .emptyGenerationPrepared,
              namespace.retiredState == .prior,
              stage.intent == intent else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try permit.requireHeld()
        try temporary.requireBound(authority: self, operation: operation,
            owner: owner, stage: stage, commitment: commitment,
            stageIdentity: stageIdentity, namespace: namespace,
            replacementBytes: replacementBytes)
        let tempName = temporary.temporaryName
        let expectedBefore = temporary.afterDataFact
        do {
            let final = try originalRecoveryIO.withOpen(parent: dataDescriptor,
                name: tempName, flags: O_RDONLY | O_NONBLOCK) { heldNew in
                try originalRecoveryIO.withOpen(parent: dataDescriptor,
                    name: "retired.json", flags: O_RDONLY | O_NONBLOCK) { heldOld
                    -> (OriginalEraseRecoveryNamespaceSnapshotV1.DirectoryFact,
                        OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact) in
                    var newStat = stat(), oldStat = stat(), namedNew = stat()
                    var namedOld = stat()
                    guard Darwin.fstat(heldNew, &newStat) == 0,
                          Darwin.fstat(heldOld, &oldStat) == 0,
                          Darwin.fstatat(dataDescriptor, tempName, &namedNew,
                              AT_SYMLINK_NOFOLLOW) == 0,
                          Darwin.fstatat(dataDescriptor, "retired.json", &namedOld,
                              AT_SYMLINK_NOFOLLOW) == 0,
                          try OriginalEraseRecoveryNamespaceSnapshotV1
                            .RegularFact(newStat) == temporary.temporaryFact,
                          try OriginalEraseRecoveryNamespaceSnapshotV1
                            .RegularFact(namedNew) == temporary.temporaryFact,
                          try OriginalEraseRecoveryNamespaceSnapshotV1
                            .RegularFact(oldStat) == namespace.retiredFact,
                          try OriginalEraseRecoveryNamespaceSnapshotV1
                            .RegularFact(namedOld) == namespace.retiredFact,
                          try originalRecoveryDataDirectoryFact() == expectedBefore,
                          try originalRecoveryIO.names(in: dataDescriptor)
                            == (["current.json", "generations", "retired.json",
                                tempName]).sorted() else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    try temporary.requireBound(authority: self,
                        operation: operation, owner: owner, stage: stage,
                        commitment: commitment, stageIdentity: stageIdentity,
                        namespace: namespace, replacementBytes: replacementBytes)
                    guard Darwin.fsync(heldNew) == 0,
                          Darwin.renameatx_np(dataDescriptor, tempName,
                              dataDescriptor, "retired.json",
                              UInt32(RENAME_SWAP)) == 0,
                          Darwin.fsync(dataDescriptor) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    guard Darwin.fstat(heldNew, &newStat) == 0,
                          Darwin.fstat(heldOld, &oldStat) == 0,
                          Darwin.fstatat(dataDescriptor, "retired.json", &namedNew,
                              AT_SYMLINK_NOFOLLOW) == 0,
                          Darwin.fstatat(dataDescriptor, tempName, &namedOld,
                              AT_SYMLINK_NOFOLLOW) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    let canonical = try OriginalEraseRecoveryNamespaceSnapshotV1
                        .RegularFact(newStat)
                    let displaced = try OriginalEraseRecoveryNamespaceSnapshotV1
                        .RegularFact(oldStat)
                    let afterSwapData = try originalRecoveryDataDirectoryFact()
                    guard canonical == (try OriginalEraseRecoveryNamespaceSnapshotV1
                            .RegularFact(namedNew)),
                          displaced == (try OriginalEraseRecoveryNamespaceSnapshotV1
                            .RegularFact(namedOld)),
                          originalRecoverySameRenamedInode(
                            temporary.temporaryFact, canonical),
                          originalRecoverySameRenamedInode(
                            namespace.retiredFact, displaced),
                          try originalRecoveryExactRetiredControlRead(
                            "retired.json", bytes: replacementBytes) == canonical,
                          try originalRecoveryExactRetiredControlRead(
                            tempName, bytes: namespace.retiredBytes) == displaced,
                          afterSwapData.device == expectedBefore.device,
                          afterSwapData.inode == expectedBefore.inode,
                          afterSwapData.mode == expectedBefore.mode,
                          afterSwapData.links == expectedBefore.links,
                          afterSwapData.user == expectedBefore.user,
                          afterSwapData.group == expectedBefore.group else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    let canonicalURL = applicationSupportURL
                        .appendingPathComponent(Self.dataName, isDirectory: true)
                        .appendingPathComponent("retired.json", isDirectory: false)
                    let policy = try ProtectedFilePolicyV1
                        .observeTemporalPolicyWithCheckedClose(
                            .generationPointer, at: canonicalURL,
                            retainUncertainDescriptor: { [self] in
                                originalRecoveryIO.retainUncertainDescriptor($0)
                            })
                    guard policy.device == UInt64(canonical.device),
                          policy.inode == UInt64(canonical.inode),
                          policy.linkCount == UInt64(canonical.links),
                          policy.mode == UInt16(canonical.mode),
                          policy.backupExcluded == true, policy.isDirectory == false,
                          (policy.state == .strictComplete
                            || (policy.state == .pendingSimulatorRequest
                                && stage.policyDisposition
                                  == .simulatorFileProtectionUnsupported)),
                          try originalRecoveryExactRetiredControlRead(
                            "retired.json", bytes: replacementBytes) == canonical,
                          try originalRecoveryExactRetiredControlRead(
                            tempName, bytes: namespace.retiredBytes) == displaced,
                          try originalRecoveryDataDirectoryFact()
                            == afterSwapData,
                          try originalRecoveryIO.names(in: dataDescriptor)
                            == (["current.json", "generations", "retired.json",
                                tempName]).sorted(),
                          Darwin.unlinkat(dataDescriptor, tempName, 0) == 0,
                          Darwin.fsync(dataDescriptor) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    guard Darwin.fstat(heldOld, &oldStat) == 0,
                          oldStat.st_dev == displaced.device,
                          oldStat.st_ino == displaced.inode,
                          oldStat.st_nlink == 0,
                          Darwin.fstatat(dataDescriptor, tempName, &namedOld,
                              AT_SYMLINK_NOFOLLOW) != 0,
                          errno == ENOENT else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    let after = try originalRecoveryNamespaceSnapshot(intent: intent)
                    guard after.retiredState == .complete,
                          after.retiredBytes == replacementBytes,
                          after.currentBytes == namespace.currentBytes,
                          after.retiredFact == canonical,
                          after.dataNames == namespace.dataNames,
                          after.dataChildren["current.json"]
                            == namespace.dataChildren["current.json"],
                          after.dataChildren["generations"]
                            == namespace.dataChildren["generations"],
                          after.installedParent == namespace.installedParent,
                          after.restore == namespace.restore,
                          after.restoreGenerations == namespace.restoreGenerations,
                          after.importStaging == namespace.importStaging else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    return (after.data, after.retiredFact)
                }
            }
            try originalRecoveryIO.requireSettled()
            let receipt = OriginalEraseRecoveryRetiredCanonicalReceiptV1(
                authority: self, operation: operation, owner: owner,
                temporary: temporary, intent: intent,
                namespace: namespace,
                replacementBytes: replacementBytes,
                finalDataFact: final.0, retiredFact: final.1)
            try receipt.requireBound(authority: self, operation: operation,
                owner: owner, temporary: temporary, namespace: namespace,
                replacementBytes: replacementBytes)
            return receipt
        } catch {
            owner.poisonOnUncertainScratch()
            throw error
        }
    }

    func originalRecoveryExternalSnapshot() throws
        -> OriginalEraseRecoveryExternalSnapshotV1 {
        guard originalRecoveryNoCreate else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        typealias Snapshot = OriginalEraseRecoveryExternalSnapshotV1
        func directoryFact(_ descriptor: Int32) throws
            -> OriginalEraseRecoveryNamespaceSnapshotV1.DirectoryFact {
            var held = stat()
            guard Darwin.fstat(descriptor, &held) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return try .init(held)
        }
        func root(parent: Int32, name: String, url: URL,
            kind: OwnedFileKindV1) throws -> Snapshot.Root? {
            var named = stat()
            if Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) != 0 {
                guard errno == ENOENT else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                return nil
            }
            guard named.st_mode & S_IFMT == S_IFDIR else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var nodes = [Snapshot.Node]()
            let digest = try originalRecoveryIO.postRetiredTree(
                parent: parent, name: name,
                observeTypedNode: { observed, children in
                    nodes.append(.init(observed, children: children ?? []))
                })
            guard !nodes.isEmpty,
                  nodes[0].path.isEmpty,
                  Set(nodes.map(\.path)).count == nodes.count,
                  nodes[0].matches(named) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let policy = try ProtectedFilePolicyV1
                .observeTemporalPolicyWithCheckedClose(kind, at: url,
                    retainUncertainDescriptor: { [originalRecoveryIO] in
                        originalRecoveryIO.retainUncertainDescriptor($0)
                    })
            guard policy.device == UInt64(named.st_dev),
                  policy.inode == UInt64(named.st_ino),
                  policy.linkCount == UInt64(named.st_nlink),
                  policy.mode == UInt16(named.st_mode),
                  try originalRecoveryIO.postRetiredTree(
                    parent: parent, name: name) == digest else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return .init(digest: digest, nodes: nodes, policy: policy)
        }
        let support = try directoryFact(applicationSupportDescriptor)
        let data = try directoryFact(dataDescriptor)
        let supportNames = try originalRecoveryIO.names(in: applicationSupportDescriptor)
        let dataNames = try originalRecoveryIO.names(in: dataDescriptor)
        guard Set(supportNames).count == supportNames.count,
              Set(dataNames).count == dataNames.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let portable = try root(parent: applicationSupportDescriptor,
            name: PortableExchangeSessionStoreLayoutV2.directoryName,
            url: applicationSupportURL.appendingPathComponent(
                PortableExchangeSessionStoreLayoutV2.directoryName,
                isDirectory: true), kind: .portableExchangeDirectory)
        let draft = try root(parent: dataDescriptor,
            name: DraftAttachmentStagingAdapterV1.directoryName,
            url: applicationSupportURL
                .appendingPathComponent(Self.dataName, isDirectory: true)
                .appendingPathComponent(
                    DraftAttachmentStagingAdapterV1.directoryName,
                    isDirectory: true), kind: .stagingDirectory)
        guard supportNames.contains(
                PortableExchangeSessionStoreLayoutV2.directoryName)
                == (portable != nil),
              dataNames.contains(DraftAttachmentStagingAdapterV1.directoryName)
                == (draft != nil),
              try directoryFact(applicationSupportDescriptor) == support,
              try directoryFact(dataDescriptor) == data,
              try originalRecoveryIO.names(in: applicationSupportDescriptor)
                == supportNames,
              try originalRecoveryIO.names(in: dataDescriptor) == dataNames else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.requireSettled()
        try verify()
        return .init(support: support, data: data,
            supportNames: supportNames, dataNames: dataNames,
            portable: portable, draft: draft)
    }

    func requireOriginalRecoveryExternalSnapshot(
        _ expected: OriginalEraseRecoveryExternalSnapshotV1
    ) throws {
        guard try originalRecoveryExternalSnapshot() == expected else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    /// A policy request may change only its policy state. The complete
    /// no-follow namespace, metadata and byte image remains exact.
    func requireOriginalRecoveryExternalPhysicalSnapshot(
        _ expected: OriginalEraseRecoveryExternalSnapshotV1
    ) throws {
        guard try originalRecoveryExternalSnapshot()
                .physicallyMatches(expected) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    /// One exact external leaf under a previously captured whole-tree image.
    /// Missing envelope is represented by nil only when its checked parent
    /// census proves absence. No producer, policy setter or reparative store
    /// is entered by this reader.
    func originalRecoveryExternalBytes(
        family: OriginalEraseRecoveryExternalSnapshotV1.Family,
        path: String, snapshot: OriginalEraseRecoveryExternalSnapshotV1,
        maximum: Int64, policyKind: OwnedFileKindV1?
    ) throws -> (Data, TemporalPolicyObservationV1?)? {
        guard originalRecoveryNoCreate, maximum >= 0,
              maximum <= EvidenceCurationLimitsV1.maximumSourceBytes,
              C48PortableReviewPersistenceValidationV1.validRelativePath(path),
              !path.isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        let parent = family == .portable
            ? applicationSupportDescriptor : dataDescriptor
        let rootName = family == .portable
            ? PortableExchangeSessionStoreLayoutV2.directoryName
            : DraftAttachmentStagingAdapterV1.directoryName
        let parentNames = family == .portable
            ? snapshot.supportNames : snapshot.dataNames
        guard try originalRecoveryIO.names(in: parent) == parentNames else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        guard let root = snapshot.root(family) else {
            var named = stat()
            guard !parentNames.contains(rootName),
                  Darwin.fstatat(parent, rootName, &named,
                    AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return nil
        }
        var byPath = [String: OriginalEraseRecoveryExternalSnapshotV1.Node]()
        byPath.reserveCapacity(root.nodes.count)
        for node in root.nodes {
            guard byPath.updateValue(node, forKey: node.path) == nil else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        let parts = path.split(separator: "/").map(String.init)
        guard parts.joined(separator: "/") == path,
              let rootNode = byPath[""], rootNode.sha256 == nil else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let rootURL: URL
        switch family {
        case .portable:
            rootURL = applicationSupportURL.appendingPathComponent(
                rootName, isDirectory: true)
        case .draft:
            rootURL = applicationSupportURL
                .appendingPathComponent(Self.dataName, isDirectory: true)
                .appendingPathComponent(rootName, isDirectory: true)
        }
        func requireDirectory(_ descriptor: Int32, parent: Int32,
            name: String, node: OriginalEraseRecoveryExternalSnapshotV1.Node
        ) throws {
            var held = stat(), named = stat()
            guard node.sha256 == nil,
                  Darwin.fstat(descriptor, &held) == 0,
                  Darwin.fstatat(parent, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  node.matches(held), node.matches(named),
                  try originalRecoveryIO.names(in: descriptor)
                    == node.children else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        func descend(_ directory: Int32, parent: Int32,
            name: String, node: OriginalEraseRecoveryExternalSnapshotV1.Node,
            index: Int, prefix: String
        ) throws -> (Data, TemporalPolicyObservationV1?)? {
            try requireDirectory(directory, parent: parent,
                name: name, node: node)
            let childName = parts[index]
            let childPath = prefix.isEmpty ? childName
                : prefix + "/" + childName
            guard let child = byPath[childPath] else {
                var absent = stat()
                guard index == parts.count - 1,
                      !node.children.contains(childName),
                      Darwin.fstatat(directory, childName, &absent,
                        AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try requireDirectory(directory, parent: parent,
                    name: name, node: node)
                return nil
            }
            guard node.children.contains(childName) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let value: (Data, TemporalPolicyObservationV1?)?
            if index + 1 == parts.count {
                guard child.sha256 != nil, child.size <= maximum else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                var named = stat()
                guard Darwin.fstatat(directory, childName, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                      child.matches(named) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let url = rootURL.appendingPathComponent(path)
                let policy: TemporalPolicyObservationV1?
                if let policyKind {
                    let observed = try ProtectedFilePolicyV1
                        .observeTemporalPolicyWithCheckedClose(
                            policyKind, at: url,
                            retainUncertainDescriptor: { [originalRecoveryIO] in
                                originalRecoveryIO.retainUncertainDescriptor($0)
                            })
                    guard observed.device == UInt64(child.device),
                          observed.inode == UInt64(child.inode),
                          observed.linkCount == UInt64(child.links),
                          observed.mode == UInt16(child.mode) else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    policy = observed
                } else { policy = nil }
                let bytes = try originalRecoveryIO.sourceBytes(
                    parent: directory, name: childName,
                    node: .init(path: child.path, fact: named,
                        sha256: child.sha256), maximum: maximum)
                if let policyKind, let policy {
                    guard try ProtectedFilePolicyV1
                        .observeTemporalPolicyWithCheckedClose(
                            policyKind, at: url,
                            retainUncertainDescriptor: { [originalRecoveryIO] in
                                originalRecoveryIO.retainUncertainDescriptor($0)
                            }) == policy else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
                value = (bytes, policy)
            } else {
                guard child.sha256 == nil else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                value = try originalRecoveryIO.withOpen(
                    parent: directory, name: childName,
                    flags: O_RDONLY | O_DIRECTORY) { opened in
                        try descend(opened, parent: directory,
                            name: childName, node: child,
                            index: index + 1, prefix: childPath)
                    }
            }
            try requireDirectory(directory, parent: parent,
                name: name, node: node)
            return value
        }
        let result = try originalRecoveryIO.withOpen(
            parent: parent, name: rootName,
            flags: O_RDONLY | O_DIRECTORY) { rootDescriptor in
                try descend(rootDescriptor, parent: parent, name: rootName,
                    node: rootNode, index: 0, prefix: "")
            }
        guard try originalRecoveryIO.names(in: parent) == parentNames else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.requireSettled()
        try verify()
        return result
    }

    /// Requests only the external leaves that the canonical source parser
    /// actually read. The original tree, leaf and policy observation were
    /// independently compared across admission; no extra file is promoted.
    @MainActor func originalRecoveryCompleteExternalPolicyRequests(
        _ reads: [OriginalEraseRecoveryExternalReadV1],
        snapshot: OriginalEraseRecoveryExternalSnapshotV1,
        permit: OriginalEraseRecoveryFirstEffectPermitV1,
        owner: StoreOriginalEraseRecoveryPreOpenOwnerV1
    ) throws -> OriginalRecoveryCompletedExternalPolicyV1 {
        typealias Snapshot = OriginalEraseRecoveryExternalSnapshotV1
        struct Target {
            let family: Snapshot.Family
            let path: String
            let kind: OwnedFileKindV1
            let url: URL
            let firstPolicy: TemporalPolicyObservationV1
            var key: String { family.rawValue + (path.isEmpty ? ":root" : ":leaf:" + path) }
        }
        func rootURL(_ family: Snapshot.Family) -> URL {
            switch family {
            case .portable:
                applicationSupportURL.appendingPathComponent(
                    PortableExchangeSessionStoreLayoutV2.directoryName, isDirectory: true)
            case .draft:
                applicationSupportURL.appendingPathComponent(Self.dataName, isDirectory: true)
                    .appendingPathComponent(DraftAttachmentStagingAdapterV1.directoryName,
                                           isDirectory: true)
            }
        }
        guard originalRecoveryNoCreate else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try permit.requireHeld()
        try owner.requireObservationUnchangedInsideOriginalRecoveryG()
        try requireOriginalRecoveryExternalReadsUnchanged(reads, snapshot: snapshot)
        var targets = [Target]()
        for read in reads {
            guard !read.path.isEmpty else { throw StoreGenerationFailure.dataPointerInvalid }
            targets.append(Target(family: read.family, path: read.path, kind: read.kind,
                url: rootURL(read.family).appendingPathComponent(read.path),
                firstPolicy: read.policy))
        }
        for family in [Snapshot.Family.portable, .draft] {
            guard let root = snapshot.root(family) else { continue }
            targets.append(Target(family: family, path: "",
                kind: family == .portable ? .portableExchangeDirectory : .stagingDirectory,
                url: rootURL(family), firstPolicy: root.policy))
        }
        guard Set(targets.map(\.key)).count == targets.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var projected = snapshot
        var policies = Dictionary(uniqueKeysWithValues: targets.map { ($0.key, $0.firstPolicy) })
        var dispositions = [ProtectedFileVerificationDispositionV1]()
        func observePolicies() throws -> [String: TemporalPolicyObservationV1] {
            var result = [String: TemporalPolicyObservationV1]()
            for target in targets {
                result[target.key] = try ProtectedFilePolicyV1
                    .observeTemporalPolicyWithCheckedClose(target.kind, at: target.url,
                        retainUncertainDescriptor: { [originalRecoveryIO] in
                            originalRecoveryIO.retainUncertainDescriptor($0)
                        })
            }
            return result
        }
        for target in targets {
            var requestInFlight = false
            func readPhysical() throws -> Snapshot {
                try permit.requireHeld()
                try owner.requireObservationUnchangedInsideOriginalRecoveryG()
                let current = try originalRecoveryExternalSnapshot()
                guard requestInFlight else {
                    guard current == projected else { throw StoreGenerationFailure.dataPointerInvalid }
                    return current
                }
                guard current.support == projected.support, current.data == projected.data,
                      current.supportNames == projected.supportNames,
                      current.dataNames == projected.dataNames else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                for family in [Snapshot.Family.portable, .draft] {
                    let before = projected.root(family), after = current.root(family)
                    if family != target.family {
                        guard before == after else { throw StoreGenerationFailure.dataPointerInvalid }
                        continue
                    }
                    guard let before, let after, before.nodes.count == after.nodes.count,
                          before.nodes.contains(where: { $0.path == target.path }) else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    for (old, new) in zip(before.nodes, after.nodes) {
                        guard old.path == target.path
                            ? old.sameExceptPolicyChangeTime(as: new) : old == new else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                    if !target.path.isEmpty {
                        guard before.policy == after.policy else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                }
                return current
            }
            _ = try readPhysical()
            guard try observePolicies() == policies else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let disposition = try ProtectedFilePolicyV1
                .verifyEraseColdTemporalPolicyWithCheckedRequest(
                    target.kind, at: target.url,
                    retainUncertainDescriptor: { [originalRecoveryIO] in
                        originalRecoveryIO.retainUncertainDescriptor($0)
                    }, willRequestCompleteProtection: {
                        _ = try readPhysical()
                        guard try observePolicies() == policies else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        requestInFlight = true
                    }, unchangedWitness: {
                        _ = try readPhysical()
                        return true
                    })
            let after = try readPhysical()
            let afterPolicies = try observePolicies()
            for (key, value) in policies where key != target.key {
                guard afterPolicies[key] == value else { throw StoreGenerationFailure.dataPointerInvalid }
            }
            guard let policy = afterPolicies[target.key],
                  policy.state == (disposition == .verifiedComplete
                    ? .strictComplete : .pendingSimulatorRequest),
                  requestInFlight || policy == policies[target.key],
                  try originalRecoveryExternalSnapshot() == after else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            projected = after; policies = afterPolicies
            dispositions.append(disposition)
        }
        guard try originalRecoveryExternalSnapshot() == projected,
              try observePolicies() == policies else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.requireSettled()
        try owner.requireObservationUnchangedInsideOriginalRecoveryG()
        try permit.requireHeld()
        return .init(original: snapshot, projected: projected, reads: reads, issuer: ObjectIdentifier(self),
                     policies: policies, dispositions: dispositions)
    }

    /// Under the original recovery EX/G, one checked source-tree walk fixes the SQLite filenames
    /// and their byte identities before any private scratch allocation.
    func originalRecoverySQLiteFiles(id: UUID, treeDigest: String)
        throws -> [OriginalRecoverySQLiteFileV1] {
        guard originalRecoveryNoCreate else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        let walk = try originalRecoveryIO.treeWithNodes(
            parent: installedGenerationsDescriptor, name: Self.canonical(id))
        guard walk.digest == treeDigest else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let allowed: Set<String> = ["model.sqlite", "model.sqlite-wal", "model.sqlite-shm"]
        let files = try walk.nodes.filter { allowed.contains($0.path) }.map { node in
            guard let hash = node.sha256,
                  node.fact.st_mode & S_IFMT == S_IFREG,
                  node.fact.st_nlink == 1,
                  node.fact.st_size >= 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return OriginalRecoverySQLiteFileV1(
                name: node.path, byteCount: UInt64(node.fact.st_size),
                sha256: hash,
                physicalIdentity: originalRecoverySQLiteIdentity(node.fact))
        }.sorted { $0.name < $1.name }
        guard files.contains(where: { $0.name == "model.sqlite" }),
              Set(files.map(\.name)).count == files.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        return files
    }

    @MainActor
    func copyOriginalRecoverySQLiteFiles(
        id: UUID, files: [OriginalRecoverySQLiteFileV1],
        treeDigest: String,
        into copy: ScratchDataLeaseStoreV1.SourceReadDirectory
    ) throws {
        guard try originalRecoverySQLiteFiles(id: id, treeDigest: treeDigest) == files else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try originalRecoveryIO.withOpen(parent: installedGenerationsDescriptor,
            name: Self.canonical(id), flags: O_RDONLY | O_DIRECTORY) { root in
            for file in files {
                try originalRecoveryIO.withOpen(parent: root, name: file.name,
                    flags: O_RDONLY | O_NONBLOCK) { source in
                    func requireExactSource() throws {
                        var held = stat(), named = stat()
                        guard Darwin.fstat(source, &held) == 0,
                              Darwin.fstatat(root, file.name, &named,
                                  AT_SYMLINK_NOFOLLOW) == 0,
                              held.st_mode & S_IFMT == S_IFREG,
                              held.st_nlink == 1,
                              originalRecoverySQLiteIdentity(held) == file.physicalIdentity,
                              originalRecoverySQLiteIdentity(named) == file.physicalIdentity else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                    try requireExactSource()
                    try copy.copySQLiteFile(named: file.name,
                        byteCount: file.byteCount) { target in
                        guard Darwin.lseek(source, 0, SEEK_SET) == 0 else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        var digest = SHA256()
                        var count: UInt64 = 0
                        var buffer = [UInt8](repeating: 0, count: 65_536)
                        while true {
                            let amount = buffer.withUnsafeMutableBytes {
                                Darwin.read(source, $0.baseAddress, $0.count)
                            }
                            if amount == 0 { break }
                            if amount < 0 && errno == EINTR { continue }
                            guard amount > 0,
                                  count <= file.byteCount,
                                  UInt64(amount) <= file.byteCount - count else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            count += UInt64(amount)
                            let bytes = Data(buffer.prefix(amount))
                            digest.update(data: bytes)
                            try bytes.withUnsafeBytes { raw in
                                guard let base = raw.baseAddress else {
                                    throw StoreGenerationFailure.dataPointerInvalid
                                }
                                var offset = 0
                                while offset < raw.count {
                                    let written = Darwin.write(target,
                                        base.advanced(by: offset), raw.count - offset)
                                    if written > 0 { offset += written }
                                    else if written < 0 && errno == EINTR { continue }
                                    else { throw StoreGenerationFailure.dataPointerInvalid }
                                }
                            }
                        }
                        guard count == file.byteCount,
                              digest.finalize().map({ String(format: "%02x", $0) }).joined()
                                == file.sha256 else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                    try requireExactSource()
                }
            }
        }
        guard try originalRecoverySQLiteFiles(id: id, treeDigest: treeDigest) == files else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
    }

    func requireNoEraseAuthority() throws {
        try verify()
        let descriptor = Darwin.openat(
            applicationSupportDescriptor,
            "FieldEvidenceErase",
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        if descriptor < 0, errno == ENOENT { return }
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        let expected = try Self.identity(descriptor)
        guard try Self.names(in: descriptor).isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let reopened = Darwin.openat(
            applicationSupportDescriptor,
            "FieldEvidenceErase",
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard reopened >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(reopened) }
        guard try Self.identity(reopened) == expected else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
    }

    fileprivate func requireRestoreReviewRoot(_ root: URL) throws {
        guard root.standardizedFileURL == applicationSupportURL else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
    }

    func requireNoRestoreJournal() throws {
        try verify()
        guard try !Self.itemExists(
            parent: restoreDescriptor,
            name: "restore.json"
        ),
              try !Self.itemExists(
                parent: restoreDescriptor,
                name: ".restore.json.next"
              ) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
    }

    func presence(id: UUID) throws -> Presence {
        try verify()
        let name = Self.canonical(id)
        return Presence(
            staging: try Self.directoryPresence(
                parent: stagingGenerationsDescriptor,
                name: name
            ),
            installed: try Self.directoryPresence(
                parent: installedGenerationsDescriptor,
                name: name
            )
        )
    }

    /// Fixed retirement observation. This never reconciles pointer temporaries
    /// or invokes policy repair, and remains usable after Operations retirement.
    @MainActor
    func readPointerForEraseRetirement(name: String, expectedData: Data? = nil,
        binding: EraseRetirementBindingV1,
        exclusion: EraseRetirementExclusionV1) throws -> Data {
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=pointer-name-enter")
        let nameCategory = name == "current.json" ? 1 : name == "retired.json" ? 2 : 0
        print("C46_ERASE_POINTER_ENTRY_V1 terminalCloseAttempted=\(eraseRetirementTerminalCloseAttempted ? 1 : 0) nameCategory=\(nameCategory)")
#endif
        guard !eraseRetirementTerminalCloseAttempted,
              name == "current.json" || name == "retired.json" else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        func requireAuthority() throws {
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-descriptors-enter")
#endif
            guard eraseRetirementUncertainDescriptors.isEmpty else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-support-enter")
#endif
            try exclusion.requireSupport(binding: binding)
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-subject-enter")
#endif
            guard applicationSupportURL.standardizedFileURL == binding.subject.applicationSupportURL,
                  Int64(applicationSupportIdentity.device) == binding.subject.applicationSupportDevice,
                  UInt64(applicationSupportIdentity.inode) == binding.subject.applicationSupportInode else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-held-root-enter")
#endif
            try Self.require(applicationSupportDescriptor, applicationSupportIdentity)
            try Self.require(dataDescriptor, dataIdentity)
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-named-root-enter")
#endif
            guard try Self.directoryIdentity(at: applicationSupportURL) == applicationSupportIdentity,
                  try Self.requiredDirectoryIdentity(parent: applicationSupportDescriptor,
                    name: Self.dataName) == dataIdentity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-pending-enter")
#endif
            var pending = stat()
            guard Darwin.fstatat(dataDescriptor, ".\(name).restore-next", &pending,
                AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        func read() throws -> EraseRetirementPointerRead {
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-read-authority-enter")
#endif
            try requireAuthority()
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-file-open-enter")
#endif
            let descriptor = Darwin.openat(dataDescriptor, name,
                O_RDONLY | O_NOFOLLOW | O_NONBLOCK | O_CLOEXEC)
            guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
            var closeAttempted = false
            do {
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-file-open-complete")
#endif
            var before = stat()
            guard Darwin.fstat(descriptor, &before) == 0,
                  before.st_mode & S_IFMT == S_IFREG, before.st_nlink == 1,
                  before.st_size >= 0,
                  before.st_size <= off_t(Self.maximumControlFileByteCount) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let identity = RegularFileIdentity(device: before.st_dev, inode: before.st_ino,
                linkCount: before.st_nlink)
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-before-stat-complete")
#endif
            guard try Self.regularFileIdentity(parent: dataDescriptor, name: name) == identity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let fact = EraseRetirementFileFact(before)
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-before-name-complete")
#endif
            var data = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    guard data.count <= Self.maximumControlFileByteCount - count else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    data.append(contentsOf: buffer.prefix(count))
                } else if count == 0 { break }
                else if errno != EINTR { throw StoreGenerationFailure.dataPointerInvalid }
            }
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-read-bytes-complete")
#endif
            var after = stat()
            guard Darwin.fstat(descriptor, &after) == 0,
                  after.st_mode & S_IFMT == S_IFREG, after.st_nlink == 1,
                  fact == EraseRetirementFileFact(after),
                  data.count == Int(after.st_size),
                  try Self.regularFileIdentity(parent: dataDescriptor, name: name) == identity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-after-facts-complete")
#endif
            try requireAuthority()
            closeAttempted = true
            guard Darwin.close(descriptor) == 0 else {
                eraseRetirementUncertainDescriptors.append(descriptor)
                throw StoreGenerationFailure.dataPointerInvalid
            }
#if DEBUG
            print("C46_ERASE_ADVANCE_V1 stage=pointer-close-complete")
#endif
            return EraseRetirementPointerRead(data: data,
                identity: identity, fact: fact)
            } catch {
                if !closeAttempted {
                    closeAttempted = true
                    if Darwin.close(descriptor) != 0 {
                        eraseRetirementUncertainDescriptors.append(descriptor)
                    }
                }
                throw error
            }
        }
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=pointer-first-read-enter")
#endif
        let first = try read()
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=pointer-first-read-complete")
#endif
        let second = try read()
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=pointer-second-read-complete")
#endif
        guard first == second,
              expectedData.map({ first.data == $0 }) ?? true,
              let provenance = eraseRetirementPointerProvenance[name] else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=pointer-provenance-enter")
#endif
        switch provenance {
        case .captured(let data, let fact):
            guard first.data == data,
                  Self.eraseRetirementFactToken(first.fact) == fact else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        case .published(let data, let fact):
            guard first.data == data,
                  Self.eraseRetirementFactToken(first.fact) == fact else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=pointer-provenance-complete")
#endif
        if name == "current.json" {
            guard try CurrentPointerCodecV1.decode(first.data).generationID
                    == Self.canonical(binding.subject.newGenerationID) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=pointer-canonical-complete")
#endif
        let url = dataURL.appendingPathComponent(name)
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=pointer-policy-enter")
#endif
        _ = try ProtectedFilePolicyV1
            .verifyEraseColdTemporalPolicyWithCheckedRequest(
                .generationPointer, at: url,
                retainUncertainDescriptor: { value in
                    self.eraseRetirementUncertainDescriptors.append(value)
                }, unchangedWitness: {
                    let current = try read()
                    guard current == first else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    return current
                })
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=pointer-policy-complete")
#endif
        guard eraseRetirementUncertainDescriptors.isEmpty,
              try read() == first else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=pointer-final-read-complete")
#endif
        return first.data
    }

    func currentGenerationID() throws -> UUID {
        try verify()
        try reconcileRestorePointerTemporary(name: "current.json")
        try enforce(
            .generationPointer,
            at: dataURL.appendingPathComponent("current.json", isDirectory: false)
        )
        let captured = try Self.readRegularFileWithIdentity(
            parent: dataDescriptor,
            name: "current.json"
        )
        let envelope = try CurrentPointerCodecV1.decode(captured.data)
        guard try Self.regularFileIdentity(
                  parent: dataDescriptor,
                  name: "current.json"
              ) == captured.identity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        switch envelope {
        case .legacy(let value, _):
            guard let id = UUID(uuidString: value.generationID),
                  Self.canonical(id) == value.generationID else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return id
        case .v2(let value, _):
            guard let id = UUID(uuidString: value.generationID) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return id
        case .v3(let value, _):
            guard let id = UUID(uuidString: value.generationID) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return id
        }
    }

    func retiredGenerationIDs() throws -> [UUID] {
        #if DEBUG
        var fixedStage = "verify"
        #endif
        do {
            try verify()
            #if DEBUG
            fixedStage = "temporary"
            #endif
            try reconcileRestorePointerTemporary(name: "retired.json")
            #if DEBUG
            fixedStage = "policy"
            #endif
            try enforce(
                .generationPointer,
                at: dataURL.appendingPathComponent("retired.json", isDirectory: false)
            )
            #if DEBUG
            fixedStage = "canonical-decode"
            #endif
            let value: RetiredPointerV1 = try Self.decodeCanonicalPointer(
                parent: dataDescriptor,
                name: "retired.json"
            )
            try StorePointerSchemaRegistry.requireRetired(value.schemaVersion)
            guard value.generationIDs == value.generationIDs.sorted(),
                  Set(value.generationIDs).count == value.generationIDs.count else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let ids = value.generationIDs.compactMap(UUID.init(uuidString:))
            guard ids.count == value.generationIDs.count,
                  zip(ids, value.generationIDs).allSatisfy({
                      Self.canonical($0.0) == $0.1
                  }) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return ids
        } catch {
            #if DEBUG
            print("ORIGINAL_AUTHORITY_RETIRED_READ_V1 stage=\(fixedStage)")
            #endif
            throw error
        }
    }

    func switchCurrentGeneration(expected oldID: UUID, to newID: UUID) throws {
        try verify()
        guard oldID != newID,
              try currentGenerationID() == oldID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(oldID)
        )
        _ = try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(newID)
        )
        let captured = try Self.readRegularFileWithIdentity(
            parent: dataDescriptor,
            name: "current.json"
        )
        guard case .legacy = try CurrentPointerCodecV1.decode(captured.data) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try replacePointer(
            name: "current.json",
            value: CurrentPointerV1(
                generationID: Self.canonical(newID),
                schemaVersion: StorePointerSchemaRegistry.legacyCurrentVersion
            )
        )
        guard try currentGenerationID() == newID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    func switchCurrentGeneration(
        expected oldID: UUID,
        to newID: UUID,
        pointer: CurrentGenerationPointerV2
    ) throws {
        try pointer.validate()
        guard pointer.generationID == Self.canonical(newID),
              oldID != newID,
              try currentGenerationID() == oldID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(oldID)
        )
        _ = try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(newID)
        )
        let captured = try Self.readRegularFileWithIdentity(
            parent: dataDescriptor,
            name: "current.json"
        )
        _ = try CurrentPointerCodecV1.decode(captured.data)
        try replacePointer(name: "current.json", value: pointer)
        guard try currentGenerationID() == newID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    func switchCurrentGeneration(
        expected oldID: UUID,
        to newID: UUID,
        pointer: CurrentGenerationPointerV3,
        expectedCurrentPointer: CurrentGenerationPointerV3
    ) throws {
        try pointer.validate()
        guard pointer.generationID == Self.canonical(newID),
              oldID != newID,
              try currentGenerationID() == oldID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(oldID)
        )
        _ = try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(newID)
        )
        let captured = try Self.readRegularFileWithIdentity(
            parent: dataDescriptor,
            name: "current.json"
        )
        _ = try CurrentPointerCodecV1.decode(captured.data)
        if captured.data != (try expectedCurrentPointer.canonicalData()) {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try replacePointer(
            name: "current.json",
            value: pointer,
            expectedData: try expectedCurrentPointer.canonicalData()
        )
        guard try currentGenerationID() == newID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    func switchCurrentGeneration(
        expected oldID: UUID,
        to newID: UUID,
        pointer: CurrentGenerationPointerV3,
        expectedCurrentPointer: CurrentGenerationPointerV3,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1
    ) throws {
        guard !restoreFileSnapshot.staging,
              restoreFileSnapshot.generationID == newID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try Self.validateRestoreGenerationFileSnapshot(
            restoreFileSnapshot,
            generationID: newID,
            staging: false,
            rootURL: installedGenerationsURL
                .appendingPathComponent(Self.canonical(newID), isDirectory: true)
                .standardizedFileURL,
            restoreProof: restoreFileSnapshot.restoreProof
        )
        try switchCurrentGeneration(
            expected: oldID,
            to: newID,
            pointer: pointer,
            expectedCurrentPointer: expectedCurrentPointer
        )
    }

    func switchCurrentGeneration(
        expected oldID: UUID,
        to newID: UUID,
        pointer: CurrentGenerationPointerV3,
        expectedCurrentPointerData: Data
    ) throws {
        let expected = try CurrentPointerCodecV1.decode(expectedCurrentPointerData)
        switch expected {
        case .legacy, .v2: break
        case .v3: throw StoreGenerationFailure.dataPointerInvalid
        }
        try pointer.validate()
        guard expected.generationID == Self.canonical(oldID),
              pointer.generationID == Self.canonical(newID), oldID != newID,
              try currentGenerationID() == oldID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try Self.requiredDirectoryIdentity(parent: installedGenerationsDescriptor, name: Self.canonical(oldID))
        _ = try Self.requiredDirectoryIdentity(parent: installedGenerationsDescriptor, name: Self.canonical(newID))
        let captured = try Self.readRegularFileWithIdentity(parent: dataDescriptor, name: "current.json")
        guard captured.data == expectedCurrentPointerData else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try replacePointer(name: "current.json", value: pointer, expectedData: expectedCurrentPointerData)
        guard try currentGenerationID() == newID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }
    func retireGeneration(oldID: UUID, currentID: UUID) throws {
        try verify()
        guard oldID != currentID,
              try currentGenerationID() == currentID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(oldID)
        )
        _ = try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(currentID)
        )
        let retired = try retiredGenerationIDs()
        guard !retired.contains(currentID) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let values = Array(Set(retired + [oldID])).sorted {
            Self.canonical($0) < Self.canonical($1)
        }
        try replacePointer(
            name: "retired.json",
            value: RetiredPointerV1(
                generationIDs: values.map(Self.canonical),
                schemaVersion: StorePointerSchemaRegistry.retiredVersion
            )
        )
        guard try retiredGenerationIDs() == values else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    func createStagingGeneration(id: UUID) throws {
        try mutationRegistry.withNoMigrationReservation { try createStagingGenerationLocked(id: id) }
    }

    fileprivate func publishAggregateAllocation(reservation: StoreAggregateMigrationJournalV1,
                                                control: StoreAggregateMigrationControlV1,
                                                afterRenameBeforeSync: () throws -> Void) throws {
        try mutationRegistry.withMigrationReservation(expected: reservation) {
            try verify()
            try control.publishBoundAllocation(reservation, afterRenameBeforeSync: afterRenameBeforeSync)
            try verify()
        }
    }

    fileprivate func aggregateRootIdentity(id: UUID, staging: Bool) throws -> (device: UInt64, inode: UInt64) {
        try verify()
        let value = try Self.requiredDirectoryIdentity(parent: staging ? stagingGenerationsDescriptor : installedGenerationsDescriptor,
                                                       name: Self.canonical(id))
        return (UInt64(value.device), UInt64(value.inode))
    }

    /// Restore review writes are confined to this authority's unpublished tree.
    /// Installed report-file authority must not be broadened to admit staging.
    func restoreReviewRootIdentity(id: UUID) throws -> ReportPDFAnchoredFile.RootIdentity {
        try verify()
        let value = try Self.requiredDirectoryIdentity(
            parent: stagingGenerationsDescriptor, name: Self.canonical(id))
        try verify()
        return ReportPDFAnchoredFile.RootIdentity(device: value.device, inode: value.inode)
    }

    func restoreGenerationRootIdentity(
        id: UUID,
        staging: Bool
    ) throws -> StreamingArchiveRootIdentityV1 {
        try verify()
        let identity = try Self.requiredDirectoryIdentity(
            parent: staging
                ? stagingGenerationsDescriptor : installedGenerationsDescriptor,
            name: Self.canonical(id)
        )
        return StreamingArchiveRootIdentityV1(
            device: UInt64(identity.device),
            inode: UInt64(identity.inode)
        )
    }

    fileprivate static func prepareRestoreGenerationFileSnapshot(
        generationID: UUID,
        staging: Bool,
        rootURL: URL,
        expectedRootIdentity: StreamingArchiveRootIdentityV1,
        restoreProof: StoreRestoreGenerationManifestProofV1,
        cancellationCheck: @escaping () throws -> Void
    ) throws -> StoreRestoreGenerationFileSnapshotV1 {
        try cancellationCheck()
        try restoreProof.validate()
        guard restoreProof.generationID == generationID,
              rootURL.isFileURL,
              rootURL.standardizedFileURL == rootURL else {
            throw StoreMigrationFailure.invalidContract
        }
        let descriptor = Darwin.open(
            rootURL.path,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.close(descriptor) }
        let observedRoot = try identity(descriptor)
        guard UInt64(observedRoot.device) == expectedRootIdentity.device,
              UInt64(observedRoot.inode) == expectedRootIdentity.inode,
              try directoryIdentity(at: rootURL) == observedRoot else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let inventory = try GenerationInventory(
            parent: descriptor,
            requireModel: true,
            cancellationCheck: cancellationCheck
        )
        defer { inventory.close() }
        guard inventory.root.identity == observedRoot else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let before = try inventory.snapshotFacts(
            rootName: rootURL.lastPathComponent
        )
        let files = try inventory.fileDigests(
            durable: true,
            restoreProof: restoreProof
        )
        let frozenIdentityDigest = try inventory.frozenIdentityDigest(
            restoreProof: restoreProof
        )
        try inventory.verifyProtection(rootURL: rootURL, staging: staging)
        try cancellationCheck()
        guard try inventory.snapshotFacts(rootName: rootURL.lastPathComponent)
                == before,
              try identity(descriptor) == observedRoot,
              try directoryIdentity(at: rootURL) == observedRoot else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        return StoreRestoreGenerationFileSnapshotV1(
            generationID: generationID,
            staging: staging,
            rootURL: rootURL,
            expectedRootIdentity: expectedRootIdentity,
            restoreProof: restoreProof,
            facts: before,
            files: files,
            frozenIdentityDigest: frozenIdentityDigest
        )
    }

    fileprivate static func validateRestoreGenerationFileSnapshot(
        _ snapshot: StoreRestoreGenerationFileSnapshotV1,
        generationID: UUID,
        staging: Bool,
        rootURL: URL,
        restoreProof: StoreRestoreGenerationManifestProofV1
    ) throws {
        try restoreProof.validate()
        guard snapshot.generationID == generationID,
              snapshot.staging == staging,
              snapshot.rootURL == rootURL,
              snapshot.restoreProof == restoreProof,
              restoreProof.generationID == generationID,
              rootURL.isFileURL,
              rootURL.standardizedFileURL == rootURL else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        func freshInventory(
            verifyProtection: Bool
        ) throws -> [StoreRestoreGenerationFileSnapshotV1.NodeFact] {
            let descriptor = Darwin.open(
                rootURL.path,
                O_RDONLY | O_DIRECTORY | O_NOFOLLOW
            )
            guard descriptor >= 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            defer { _ = Darwin.close(descriptor) }
            let root = try identity(descriptor)
            guard UInt64(root.device) == snapshot.expectedRootIdentity.device,
                  UInt64(root.inode) == snapshot.expectedRootIdentity.inode,
                  try directoryIdentity(at: rootURL) == root else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let inventory = try GenerationInventory(
                parent: descriptor,
                requireModel: true
            )
            defer { inventory.close() }
            try inventory.requireRestoreManifestInput(restoreProof)
            let before = try inventory.snapshotFacts(
                rootName: rootURL.lastPathComponent
            )
            guard before == snapshot.facts else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            if verifyProtection {
                try inventory.verifyProtection(rootURL: rootURL, staging: staging)
            }
            try inventory.revalidate()
            guard try inventory.snapshotFacts(rootName: rootURL.lastPathComponent)
                    == before,
                  try identity(descriptor) == root,
                  try directoryIdentity(at: rootURL) == root else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            return before
        }
        _ = try freshInventory(verifyProtection: true)
        guard try freshInventory(verifyProtection: false) == snapshot.facts else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
    }

    fileprivate func clearAggregateStagingGeneration(reservation: StoreAggregateMigrationJournalV1) throws {
        guard reservation.phase == .sourceFrozen else { throw StoreMigrationFailure.invalidPhaseTransition }
        try mutationRegistry.withMigrationReservation(expected: reservation) {
            let name = Self.canonical(reservation.targetGenerationID)
            let expected = try aggregateRootIdentity(id: reservation.targetGenerationID, staging: true)
            guard expected.device == reservation.candidateRootDevice, expected.inode == reservation.candidateRootInode else {
                throw StoreMigrationFailure.invalidIdentity
            }
            let fd = Darwin.openat(stagingGenerationsDescriptor, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
            guard fd >= 0 else { throw StoreMigrationFailure.invalidIdentity }
            defer { _ = Darwin.close(fd) }
            let inventory = try GenerationInventory(parent: fd, requireModel: false, partialCleanup: true)
            guard UInt64(inventory.root.identity.device) == expected.device,
                  UInt64(inventory.root.identity.inode) == expected.inode else { throw StoreMigrationFailure.invalidIdentity }
            try inventory.removeAll {
                try self.verify()
                let current = try self.aggregateRootIdentity(id: reservation.targetGenerationID, staging: true)
                guard current.device == expected.device, current.inode == expected.inode else { throw StoreMigrationFailure.invalidIdentity }
            }
        }
    }

    private func createStagingGenerationLocked(id: UUID) throws {
        try verify()
        let name = Self.canonical(id)
        guard try !Self.itemExists(parent: stagingGenerationsDescriptor, name: name),
              try !Self.itemExists(parent: installedGenerationsDescriptor, name: name) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        guard Darwin.mkdirat(
            stagingGenerationsDescriptor,
            name,
            mode_t(0o700)
        ) == 0 else {
            throw NSError(domain: NSPOSIXErrorDomain, code: Int(errno))
        }
        guard Darwin.fsync(stagingGenerationsDescriptor) == 0 else {
            throw NSError(domain: NSPOSIXErrorDomain, code: Int(errno))
        }
        try verify()
        guard try Self.directoryPresence(
            parent: stagingGenerationsDescriptor,
            name: name
        ) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try enforce(
            .restoreStaging,
            at: stagingGenerationsURL.appendingPathComponent(name, isDirectory: true)
        )
    }

    func createInstalledGeneration(id: UUID) throws -> InstalledGenerationHandle {
        try verify()
        let name = Self.canonical(id)
        guard try !Self.itemExists(parent: stagingGenerationsDescriptor, name: name),
              try !Self.itemExists(parent: installedGenerationsDescriptor, name: name),
              Darwin.mkdirat(
                  installedGenerationsDescriptor,
                  name,
                  mode_t(0o700)
              ) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let descriptor = Darwin.openat(
            installedGenerationsDescriptor,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else {
            _ = Darwin.unlinkat(
                installedGenerationsDescriptor,
                name,
                AT_REMOVEDIR
            )
            _ = Darwin.fsync(installedGenerationsDescriptor)
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var createdIdentity: Identity?
        do {
            let identity = try Self.identity(descriptor)
            createdIdentity = identity
            guard Darwin.fsync(installedGenerationsDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try verify()
            try Self.require(descriptor, identity)
            guard try Self.requiredDirectoryIdentity(
                parent: installedGenerationsDescriptor,
                name: name
            ) == identity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try protectInstalledGeneration(id: id)
            return InstalledGenerationHandle(
                id: id,
                descriptor: descriptor,
                identity: identity
            )
        } catch {
            if let createdIdentity,
               let currentIdentity = try? Self.requiredDirectoryIdentity(
                   parent: installedGenerationsDescriptor,
                   name: name
               ), currentIdentity == createdIdentity {
                _ = Darwin.unlinkat(
                    installedGenerationsDescriptor,
                    name,
                    AT_REMOVEDIR
                )
                _ = Darwin.fsync(installedGenerationsDescriptor)
            }
            _ = Darwin.close(descriptor)
            throw error
        }
    }

    func modelStoreURL(
        for handle: InstalledGenerationHandle,
        name: String
    ) throws -> URL {
        try Self.requireSafeBasename(name)
        try requireInstalledGeneration(handle)
        let root = try Self.currentURL(for: handle.descriptor)
        guard root.isFileURL,
              root.lastPathComponent == Self.canonical(handle.id) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let reopened = Darwin.open(
            root.path,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard reopened >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.close(reopened) }
        guard try Self.identity(reopened) == handle.identity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireInstalledGeneration(handle)
        return root.appendingPathComponent(name, isDirectory: false)
    }

    func requireRegularFile(
        named name: String,
        in handle: InstalledGenerationHandle
    ) throws {
        try Self.requireSafeBasename(name)
        try requireInstalledGeneration(handle)
        let inventory = try GenerationInventory(parent: handle.descriptor, requireModel: true)
        guard inventory.files[name] != nil else { throw StoreGenerationFailure.dataGenerationMissing }
        try inventory.withFile(name) { descriptor, _ in
            guard Darwin.fsync(descriptor) == 0, Darwin.fsync(handle.descriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        if name == "model.sqlite" {
            let root = try Self.currentURL(for: handle.descriptor)
            try inventory.protect(rootURL: root, staging: false) { kind, url, check in
                try self.enforce(kind, at: url, authorityCheck: {
                    try self.requireInstalledGeneration(handle)
                    try check()
                })
            }
        }
        try inventory.revalidate()
        try requireInstalledGeneration(handle)
    }

    func requireInstalledGeneration(
        _ handle: InstalledGenerationHandle
    ) throws {
        try verify()
        try Self.require(handle.descriptor, handle.identity)
        guard try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(handle.id)
        ) == handle.identity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    func removeCreatedInstalledGeneration(
        _ handle: InstalledGenerationHandle
    ) throws {
        try Self.require(handle.descriptor, handle.identity)
        let currentURL = try Self.currentURL(for: handle.descriptor)
        let parentURL = currentURL.deletingLastPathComponent()
        let parent = Darwin.open(
            parentURL.path,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard parent >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.close(parent) }
        guard try Self.identity(parent) == installedGenerationsIdentity,
              try Self.requiredDirectoryIdentity(
                  parent: parent,
                  name: currentURL.lastPathComponent
              ) == handle.identity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try Self.removeContents(of: handle.descriptor, authorityCheck: {
            guard try Self.identity(parent) == self.installedGenerationsIdentity,
                  try Self.requiredDirectoryIdentity(parent: parent, name: currentURL.lastPathComponent) == handle.identity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        })
        guard try Self.requiredDirectoryIdentity(
            parent: parent,
            name: currentURL.lastPathComponent
        ) == handle.identity,
              Darwin.unlinkat(
                  parent,
                  currentURL.lastPathComponent,
                  AT_REMOVEDIR
              ) == 0,
              Darwin.fsync(parent) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    func installStagingGeneration(id: UUID) throws {
        try mutationRegistry.withNoMigrationReservation { try installStagingGenerationLocked(id: id) }
    }

    func installStagingGeneration(
        id: UUID,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1
    ) throws {
        try mutationRegistry.withNoMigrationReservation {
            try installRestoreStagingGenerationLocked(
                id: id,
                restoreFileSnapshot: restoreFileSnapshot
            )
        }
    }

    fileprivate func installAggregateGeneration(reservation: StoreAggregateMigrationJournalV1) throws {
        guard reservation.phase == .targetValidated else { throw StoreMigrationFailure.invalidPhaseTransition }
        try mutationRegistry.withMigrationReservation(expected: reservation) {
            let identity = try aggregateRootIdentity(id: reservation.targetGenerationID, staging: true)
            guard identity.device == reservation.candidateRootDevice, identity.inode == reservation.candidateRootInode else {
                throw StoreMigrationFailure.invalidIdentity
            }
            try installStagingGenerationLocked(id: reservation.targetGenerationID)
        }
    }

    private func installStagingGenerationLocked(id: UUID) throws {
        try verify()
        let name = Self.canonical(id)
        try protectStagingGeneration(id: id, requireModel: true)
        let sourceIdentity = try Self.requiredDirectoryIdentity(
            parent: stagingGenerationsDescriptor,
            name: name
        )
        guard try !Self.itemExists(parent: installedGenerationsDescriptor, name: name),
              Darwin.renameatx_np(
                  stagingGenerationsDescriptor,
                  name,
                  installedGenerationsDescriptor,
                  name,
                  UInt32(RENAME_EXCL)
              ) == 0,
              Darwin.fsync(stagingGenerationsDescriptor) == 0,
              Darwin.fsync(installedGenerationsDescriptor) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        guard try !Self.itemExists(parent: stagingGenerationsDescriptor, name: name),
              try Self.requiredDirectoryIdentity(
                  parent: installedGenerationsDescriptor,
                  name: name
              ) == sourceIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try protectInstalledGeneration(id: id, requireModel: true)
    }

    private func installRestoreStagingGenerationLocked(
        id: UUID,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1
    ) throws {
        try verify()
        let name = Self.canonical(id)
        let rootURL = stagingGenerationsURL
            .appendingPathComponent(name, isDirectory: true)
            .standardizedFileURL
        guard restoreFileSnapshot.staging,
              restoreFileSnapshot.generationID == id else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try Self.validateRestoreGenerationFileSnapshot(
            restoreFileSnapshot,
            generationID: id,
            staging: true,
            rootURL: rootURL,
            restoreProof: restoreFileSnapshot.restoreProof
        )
        let sourceIdentity = try Self.requiredDirectoryIdentity(
            parent: stagingGenerationsDescriptor,
            name: name
        )
        guard UInt64(sourceIdentity.device)
                == restoreFileSnapshot.expectedRootIdentity.device,
              UInt64(sourceIdentity.inode)
                == restoreFileSnapshot.expectedRootIdentity.inode,
              try !Self.itemExists(
                parent: installedGenerationsDescriptor,
                name: name
              ),
              Darwin.renameatx_np(
                stagingGenerationsDescriptor,
                name,
                installedGenerationsDescriptor,
                name,
                UInt32(RENAME_EXCL)
              ) == 0,
              Darwin.fsync(stagingGenerationsDescriptor) == 0,
              Darwin.fsync(installedGenerationsDescriptor) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        guard try !Self.itemExists(
                parent: stagingGenerationsDescriptor,
                name: name
              ),
              try Self.requiredDirectoryIdentity(
                parent: installedGenerationsDescriptor,
                name: name
              ) == sourceIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    /// Pure target closure observation for the actual Erase EX owner. It
    /// deliberately does not require the Restore or Operations namespaces,
    /// which the same operation later retires. No creating getter or policy
    /// repair is used; pending protection facts remain unavailable here.
    @MainActor
    func snapshotTargetForEraseValidation(binding: EraseRetirementBindingV1,
        exclusion: EraseRetirementExclusionV1) throws -> MigrationCloneResult {
        try snapshotTargetForEraseValidation(binding: binding, exclusion: exclusion,
            postClose: nil)
    }

    private struct ErasePostCloseTargetSource {
        let manifest: EraseManifestRetirementAttemptV1
        let receipt: EraseGenerationAuthorityTerminalCloseReceiptV1
        let retirement: ErasedRegistryRetirementProofV1
        let pointerData: Data
    }

    @MainActor
    fileprivate func snapshotTargetForPostCloseEraseValidation(binding: EraseRetirementBindingV1,
        exclusion: EraseRetirementExclusionV1, manifest: EraseManifestRetirementAttemptV1,
        receipt: EraseGenerationAuthorityTerminalCloseReceiptV1,
        retirement: ErasedRegistryRetirementProofV1, pointerData: Data) throws -> MigrationCloneResult {
        guard receipt.matchesSourceOwner(proof: retirement, authority: self, binding: binding) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return try snapshotTargetForEraseValidation(binding: binding, exclusion: exclusion,
            postClose: ErasePostCloseTargetSource(manifest: manifest, receipt: receipt,
                retirement: retirement, pointerData: pointerData))
    }

    /// The fixed tree/policy/digest algorithm is shared. Only the exact live
    /// descriptor owner changes after the genuine terminal-close transfer.
    @MainActor
    private func snapshotTargetForEraseValidation(binding: EraseRetirementBindingV1,
        exclusion: EraseRetirementExclusionV1,
        postClose: ErasePostCloseTargetSource?) throws -> MigrationCloneResult {
        func requireInstalledAuthority() throws {
            if let postClose {
                _ = try postClose.manifest.requirePostCloseSourceControls(binding: binding,
                    exclusion: exclusion, retirement: postClose.retirement,
                    receipt: postClose.receipt, authority: self,
                    expectedPointerData: postClose.pointerData)
                return
            }
            try exclusion.requireSupport(binding: binding)
            guard applicationSupportURL.standardizedFileURL == binding.subject.applicationSupportURL,
                  Int64(applicationSupportIdentity.device) == binding.subject.applicationSupportDevice,
                  UInt64(applicationSupportIdentity.inode) == binding.subject.applicationSupportInode else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try Self.require(applicationSupportDescriptor, applicationSupportIdentity)
            try Self.require(dataDescriptor, dataIdentity)
            try Self.require(installedGenerationsDescriptor, installedGenerationsIdentity)
            guard try Self.directoryIdentity(at: applicationSupportURL) == applicationSupportIdentity,
                  try Self.requiredDirectoryIdentity(parent: applicationSupportDescriptor,
                    name: Self.dataName) == dataIdentity,
                  try Self.requiredDirectoryIdentity(parent: dataDescriptor,
                    name: Self.generationsName) == installedGenerationsIdentity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        try requireInstalledAuthority()
        let name = Self.canonical(binding.subject.newGenerationID)
        let rootURL = installedGenerationsURL.appendingPathComponent(name, isDirectory: true)
        func snapshotTree() throws -> EraseRetirementTreeWitness {
            guard eraseRetirementUncertainDescriptors.isEmpty else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try eraseRetirementCheckedSnapshotIO.requireSettled()
            try requireInstalledAuthority()
            let checked: (digest: String, nodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode])
            if let postClose {
                checked = try postClose.manifest.readPostCloseTargetTree(binding: binding,
                    exclusion: exclusion, retirement: postClose.retirement,
                    receipt: postClose.receipt, authority: self,
                    expectedPointerData: postClose.pointerData,
                    checkedIO: eraseRetirementCheckedSnapshotIO)
            } else {
                checked = try eraseRetirementCheckedSnapshotIO.treeWithNodes(
                    parent: installedGenerationsDescriptor, name: name)
            }
            var byPath = [String: EraseAbortCheckedSnapshotIOV1.CheckedTreeNode]()
            for node in checked.nodes {
                guard byPath.updateValue(node, forKey: node.path) == nil else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard let root = byPath[""], root.sha256 == nil,
                  root.fact.st_mode & S_IFMT == S_IFDIR else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let directories = byPath.values.filter { $0.sha256 == nil && !$0.path.isEmpty }
                .map(\.path).sorted()
            let filePaths = byPath.values.filter { $0.sha256 != nil }
                .map(\.path).sorted()
            let paths = [""] + directories + filePaths
            let facts = try paths.map { path -> EraseRetirementFileFact in
                guard let node = byPath[path] else { throw StoreGenerationFailure.dataPointerInvalid }
                return EraseRetirementFileFact(node.fact)
            }
            let files = try filePaths.map { path -> StoreGenerationFileDigestV1 in
                guard let node = byPath[path], let digest = node.sha256,
                      node.fact.st_size >= 0, node.fact.st_size <= off_t(Int.max),
                      node.fact.st_nlink == 1 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let kind = try GenerationOwnedPathV1.classify(path,
                    nodeType: .regularFile).kind
                return try StoreGenerationFileDigestV1(
                    relativePath: path, byteCount: Int(node.fact.st_size),
                    sha256: digest, kind: kind)
            }
            try eraseRetirementCheckedSnapshotIO.requireSettled()
            try requireInstalledAuthority()
            return EraseRetirementTreeWitness(
                checkedTreeDigest: checked.digest, paths: paths,
                directoryPaths: directories, facts: facts, files: files)
        }
        // Read-only shape and complete canonical digest come before any
        // Simulator policy request. Each request is separately bound to the
        // same physical tree and may not rebaseline its bytes or metadata.
        let baseline = try snapshotTree()
        let paths = baseline.paths
        let files = baseline.files
        let directoryPaths = Set(baseline.directoryPaths)
        func nodeURL(_ path: String) -> URL {
            path.isEmpty ? rootURL : rootURL.appendingPathComponent(path,
                isDirectory: directoryPaths.contains(path))
        }
        func nodeKind(_ path: String) throws -> OwnedFileKindV1 {
            if path.isEmpty { return .durableDirectory }
            return try GenerationOwnedPathV1.classify(path,
                nodeType: directoryPaths.contains(path) ? .directory : .regularFile).kind
        }
        for (index, path) in paths.enumerated() {
            let observed = try ProtectedFilePolicyV1
                .observeTemporalPolicyWithCheckedClose(
                    nodeKind(path), at: nodeURL(path),
                    retainUncertainDescriptor: { value in
                        self.eraseRetirementUncertainDescriptors.append(value)
                    })
            let expected = baseline.facts[index]
            guard eraseRetirementUncertainDescriptors.isEmpty,
                  observed.device == UInt64(expected.device),
                  observed.inode == UInt64(expected.inode),
                  observed.linkCount == UInt64(expected.links),
                  observed.state == .strictComplete
                    || observed.state == .pendingSimulatorRequest else {
                throw EraseIntentStoreError.retirementPolicyEffectUnavailable
            }
        }
        guard try snapshotTree() == baseline else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let identity = Identity(device: baseline.facts[0].device,
            inode: baseline.facts[0].inode)
        var tokens = ["source-directory|\(identity.device)|\(identity.inode)"]
        let fileFacts = Dictionary(uniqueKeysWithValues:
            zip(paths, baseline.facts).map { ($0, $1) })
        for file in files {
            guard let fact = fileFacts[file.relativePath] else {
                throw StoreMigrationFailure.invalidPath
            }
            tokens.append("\(file.relativePath)|\(fact.device)|\(fact.inode)|\(fact.links)|\(file.sha256)")
        }
        for path in baseline.directoryPaths {
            guard let fact = fileFacts[path] else { throw StoreMigrationFailure.invalidPath }
            tokens.append("subdirectory|\(path)|\(fact.device)|\(fact.inode)")
        }
        for path in paths {
            _ = try ProtectedFilePolicyV1
                .verifyEraseColdTemporalPolicyWithCheckedRequest(
                    nodeKind(path), at: nodeURL(path),
                    retainUncertainDescriptor: { value in
                        self.eraseRetirementUncertainDescriptors.append(value)
                    }, unchangedWitness: {
                        let current = try snapshotTree()
                        guard current == baseline else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        return current
                    })
            guard eraseRetirementUncertainDescriptors.isEmpty,
                  try snapshotTree() == baseline else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        try requireInstalledAuthority()
        if postClose != nil {
            guard try snapshotTree() == baseline else { throw StoreGenerationFailure.dataPointerInvalid }
        } else {
            guard try Self.requiredDirectoryIdentity(parent: installedGenerationsDescriptor,
                name: name) == identity else { throw StoreGenerationFailure.dataPointerInvalid }
        }
        return MigrationCloneResult(files: files,
            sourceTreeDigest: StoreMigrationCanonicalJSONV1.sha256(try StoreMigrationCanonicalJSONV1.encode(files)),
            frozenIdentityDigest: StoreMigrationCanonicalJSONV1.sha256(Data(tokens.sorted().joined(separator: "\n").utf8)))
    }

    /// Snapshots the classified durable file closure and binds each owned
    /// directory identity, including empty directories. File reads use bounded
    /// descriptor chains and revalidate bytes and identity before returning.
    func snapshotInstalledGeneration(id: UUID) throws -> MigrationCloneResult {
        try verify()
        try requireInstalledGeneration(id: id)
        let descriptor = Darwin.openat(installedGenerationsDescriptor, Self.canonical(id), O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw StoreMigrationFailure.maintenanceRequired(.sourceUnavailable) }
        defer { _ = Darwin.close(descriptor) }
        let inventory = try GenerationInventory(parent: descriptor, requireModel: true)
        let files = try inventory.fileDigests(durable: false)
        let directory = inventory.root.identity
        var tokens = ["source-directory|\(directory.device)|\(directory.inode)"]
        for file in files {
            guard let source = inventory.files[file.relativePath] else { throw StoreMigrationFailure.invalidPath }
            let identity = source.snapshot
            tokens.append("\(file.relativePath)|\(identity.device)|\(identity.inode)|\(identity.linkCount)|\(file.sha256)")
        }
        tokens.append(contentsOf: inventory.directoryIdentityTokens)
        try inventory.revalidate()
        try verify()
        guard try Self.requiredDirectoryIdentity(parent: installedGenerationsDescriptor, name: Self.canonical(id)) == directory else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        return MigrationCloneResult(
            files: files,
            sourceTreeDigest: StoreMigrationCanonicalJSONV1.sha256(try StoreMigrationCanonicalJSONV1.encode(files)),
            frozenIdentityDigest: StoreMigrationCanonicalJSONV1.sha256(Data(tokens.sorted().joined(separator: "\n").utf8))
        )
    }

    /// Clones the complete classified durable tree into empty restore staging,
    /// preserving directory paths and reproving source and target bytes. This
    /// does not acquire the legacy restore pointer-swap rollback semantics.
    func cloneInstalledGeneration(
        sourceID: UUID,
        toStagingGeneration targetID: UUID
    ) throws -> MigrationCloneResult {
        try mutationRegistry.withNoMigrationReservation {
            try cloneInstalledGenerationLocked(sourceID: sourceID, toStagingGeneration: targetID)
        }
    }

    fileprivate func cloneAggregateSource(reservation: StoreAggregateMigrationJournalV1) throws -> MigrationCloneResult {
        guard reservation.phase == .sourceFrozen else { throw StoreMigrationFailure.invalidPhaseTransition }
        return try mutationRegistry.withMigrationReservation(expected: reservation) {
            let identity = try aggregateRootIdentity(id: reservation.targetGenerationID, staging: true)
            guard identity.device == reservation.candidateRootDevice, identity.inode == reservation.candidateRootInode else {
                throw StoreMigrationFailure.invalidIdentity
            }
            return try cloneInstalledGenerationLocked(sourceID: reservation.sourceGenerationID, toStagingGeneration: reservation.targetGenerationID)
        }
    }

    private func cloneInstalledGenerationLocked(sourceID: UUID, toStagingGeneration targetID: UUID) throws -> MigrationCloneResult {
        try verify()
        try requireInstalledGeneration(id: sourceID)
        try requireStagingGeneration(id: targetID)
        let sourceName = Self.canonical(sourceID), targetName = Self.canonical(targetID)
        let source = Darwin.openat(installedGenerationsDescriptor, sourceName, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard source >= 0 else { throw StoreMigrationFailure.maintenanceRequired(.sourceUnavailable) }
        defer { _ = Darwin.close(source) }
        let target = Darwin.openat(stagingGenerationsDescriptor, targetName, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard target >= 0 else { throw StoreMigrationFailure.maintenanceRequired(.targetUnavailable) }
        defer { _ = Darwin.close(target) }
        let sourceInventory = try GenerationInventory(parent: source, requireModel: true)
        try sourceInventory.requireSettledMigrationInput()
        let targetIdentity = try Self.identity(target)
        do {
            let emptyTarget = try GenerationInventory(parent: target, requireModel: false)
            guard emptyTarget.tree.files.isEmpty, emptyTarget.tree.directories.isEmpty else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        }
        let targetRoot = stagingGenerationsURL.appendingPathComponent(targetName, isDirectory: true)
        var createdDirectories: [String: Identity] = [:]
        func targetChain(_ path: String) throws -> GenerationDirectoryChain {
            try GenerationDirectoryChain(rootDescriptor: target, rootIdentity: targetIdentity,
                directories: createdDirectories, path: path)
        }
        func verifyCloneRoots() throws {
            try self.verify()
            guard try Self.identity(source) == sourceInventory.root.identity,
                  try Self.requiredDirectoryIdentity(parent: self.installedGenerationsDescriptor, name: sourceName) == sourceInventory.root.identity,
                  try Self.identity(target) == targetIdentity,
                  try Self.requiredDirectoryIdentity(parent: self.stagingGenerationsDescriptor, name: targetName) == targetIdentity else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        }
        try verifyCloneRoots()
        // Parents precede children, and known empty directories are retained.
        let directoryPaths = sourceInventory.directories.keys.sorted {
            let left = $0.split(separator: "/").count, right = $1.split(separator: "/").count
            return left == right ? $0 < $1 : left < right
        }
        for path in directoryPaths {
            let parent = try targetChain(GenerationInventory.parentPath(path))
            let name = GenerationInventory.basename(path)
            try verifyCloneRoots()
            try parent.verify()
            guard Darwin.mkdirat(parent.descriptor, name, mode_t(0o700)) == 0 else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            let child = Darwin.openat(parent.descriptor, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
            guard child >= 0 else { throw StoreMigrationFailure.maintenanceRequired(.targetMismatch) }
            defer { _ = Darwin.close(child) }
            let identity = try Self.identity(child)
            createdDirectories[path] = identity
            try enforce(.stagingDirectory, at: targetRoot.appendingPathComponent(path, isDirectory: true), authorityCheck: {
                try verifyCloneRoots()
                try parent.verify()
                guard try Self.identity(child) == identity,
                      try Self.requiredDirectoryIdentity(parent: parent.descriptor, name: name) == identity else {
                    throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                }
            })
            guard Darwin.fsync(child) == 0, Darwin.fsync(parent.descriptor) == 0 else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        }
        var fileDigests = [StoreGenerationFileDigestV1]()
        var identityTokens = ["source-directory|\(sourceInventory.root.identity.device)|\(sourceInventory.root.identity.inode)"]
        for path in sourceInventory.files.keys.sorted() {
            let parent = try targetChain(GenerationInventory.parentPath(path))
            try verifyCloneRoots()
            try parent.verify()
            guard let file = sourceInventory.files[path] else { throw StoreMigrationFailure.invalidPath }
            let copied = try sourceInventory.withFile(path) { sourceDescriptor, sourceSnapshot in
                try createProtectedStagingFile(
                    targetID: targetID, parent: parent.descriptor, name: GenerationInventory.basename(path),
                    parentRelativePath: GenerationInventory.parentPath(path),
                    sourceDescriptor: sourceDescriptor, sourceSnapshot: sourceSnapshot,
                    authorityCheck: { try verifyCloneRoots(); try parent.verify() }
                )
            }
            fileDigests.append(try StoreGenerationFileDigestV1(
                relativePath: path, byteCount: copied.byteCount, sha256: copied.sha256, kind: file.ownership.kind
            ))
            identityTokens.append("\(path)|\(file.snapshot.device)|\(file.snapshot.inode)|\(file.snapshot.linkCount)|\(copied.sha256)")
        }
        identityTokens.append(contentsOf: sourceInventory.directoryIdentityTokens)
        let targetInventory = try GenerationInventory(parent: target, requireModel: true)
        guard targetInventory.tree == sourceInventory.tree,
              targetInventory.directories == createdDirectories,
              try targetInventory.fileDigests(durable: true) == fileDigests,
              try sourceInventory.fileDigests(durable: false) == fileDigests else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        try targetInventory.protect(rootURL: targetRoot, staging: true) { kind, url, check in
            try self.enforce(kind, at: url, authorityCheck: {
                try verifyCloneRoots()
                try check()
            })
        }
        try targetInventory.revalidate()
        try sourceInventory.revalidate()
        try verifyCloneRoots()
        guard Darwin.fsync(target) == 0, Darwin.fsync(stagingGenerationsDescriptor) == 0 else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        return MigrationCloneResult(
            files: fileDigests,
            sourceTreeDigest: StoreMigrationCanonicalJSONV1.sha256(try StoreMigrationCanonicalJSONV1.encode(fileDigests)),
            frozenIdentityDigest: StoreMigrationCanonicalJSONV1.sha256(Data(identityTokens.sorted().joined(separator: "\n").utf8))
        )
    }

    private func createProtectedStagingFile(
        targetID: UUID,
        parent: Int32,
        name: String,
        parentRelativePath: String,
        sourceDescriptor: Int32,
        sourceSnapshot: RegularFileSnapshot,
        authorityCheck: @escaping () throws -> Void
    ) throws -> StreamedFileDigest {
        try Self.requireSafeBasename(name)
        try authorityCheck()
        let descriptor = Darwin.openat(
            parent,
            name,
            O_RDWR | O_CREAT | O_EXCL | O_NOFOLLOW,
            mode_t(0o600)
        )
        guard descriptor >= 0 else {
            throw NSError(domain: NSPOSIXErrorDomain, code: Int(errno))
        }
        defer { _ = Darwin.close(descriptor) }
        let createdSnapshot = try Self.regularFileSnapshot(
            descriptor: descriptor,
            mismatchReason: .targetMismatch
        )
        guard createdSnapshot.byteCount == 0 else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        var removeCreated = true
        defer {
            if removeCreated {
                do {
                    try authorityCheck()
                    let namedSnapshot = try Self.namedRegularFileSnapshot(
                        parent: parent, name: name, mismatchReason: .targetMismatch
                    )
                    if namedSnapshot.device == createdSnapshot.device,
                       namedSnapshot.inode == createdSnapshot.inode {
                        _ = Darwin.unlinkat(parent, name, 0)
                        _ = Darwin.fsync(parent)
                    }
                } catch {
                    // Uncertain placement retains the partial file for its
                    // original recovery owner; never unlink via a stale root.
                }
            }
        }
        let root = stagingGenerationsURL.appendingPathComponent(
            Self.canonical(targetID),
            isDirectory: true
        ).appendingPathComponent(parentRelativePath, isDirectory: true)
        try enforceGenerationFile(
            descriptor: parent,
            root: root,
            name: name,
            kind: .stagingFile,
            authorityCheck: authorityCheck
        )
        guard Darwin.lseek(sourceDescriptor, 0, SEEK_SET) == 0 else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceUnavailable)
        }
        var sourceHasher = SHA256()
        var copiedByteCount = 0
        var buffer = [UInt8](
            repeating: 0,
            count: Self.migrationStreamBufferByteCount
        )
        while true {
            let count = buffer.withUnsafeMutableBytes {
                Darwin.read(sourceDescriptor, $0.baseAddress, $0.count)
            }
            if count == 0 { break }
            guard count > 0 else {
                if errno == EINTR { continue }
                throw StoreMigrationFailure.maintenanceRequired(.sourceUnavailable)
            }
            let (nextCount, overflow) = copiedByteCount.addingReportingOverflow(count)
            guard !overflow, off_t(nextCount) <= sourceSnapshot.byteCount else {
                throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
            }
            copiedByteCount = nextCount
            let chunk = Data(buffer.prefix(count))
            sourceHasher.update(data: chunk)
            try chunk.withUnsafeBytes { raw in
                var offset = 0
                while offset < raw.count {
                    try authorityCheck()
                    let written = Darwin.write(
                        descriptor,
                        raw.baseAddress?.advanced(by: offset),
                        raw.count - offset
                    )
                    if written > 0 {
                        offset += written
                    } else if written < 0, errno == EINTR {
                        continue
                    } else {
                        throw NSError(
                            domain: NSPOSIXErrorDomain,
                            code: Int(errno)
                        )
                    }
                }
            }
        }
        guard copiedByteCount == Int(sourceSnapshot.byteCount),
              try Self.regularFileSnapshot(
                  descriptor: sourceDescriptor,
                  mismatchReason: .sourceMismatch
              ) == sourceSnapshot else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        guard Darwin.fsync(descriptor) == 0 else {
            throw NSError(domain: NSPOSIXErrorDomain, code: Int(errno))
        }
        guard Darwin.fsync(parent) == 0 else {
            throw NSError(domain: NSPOSIXErrorDomain, code: Int(errno))
        }
        let targetSnapshot = try Self.regularFileSnapshot(
            descriptor: descriptor,
            mismatchReason: .targetMismatch
        )
        guard targetSnapshot.device == createdSnapshot.device,
              targetSnapshot.inode == createdSnapshot.inode,
              targetSnapshot.linkCount == 1,
              targetSnapshot.type == S_IFREG,
              targetSnapshot.byteCount == off_t(copiedByteCount),
              try Self.namedRegularFileSnapshot(
                  parent: parent,
                  name: name,
                  mismatchReason: .targetMismatch
              ) == targetSnapshot else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        let targetDigest = try Self.streamedDigest(
            descriptor: descriptor,
            expectedSnapshot: targetSnapshot,
            mismatchReason: .targetMismatch
        )
        let sourceDigest = Self.hexDigest(sourceHasher.finalize())
        guard targetDigest.byteCount == copiedByteCount,
              targetDigest.sha256 == sourceDigest,
              targetDigest.snapshot == targetSnapshot else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        try enforceGenerationFile(
            descriptor: parent,
            root: root,
            name: name,
            kind: .stagingFile,
            authorityCheck: authorityCheck
        )
        guard try Self.regularFileSnapshot(
                  descriptor: descriptor,
                  mismatchReason: .targetMismatch
              ) == targetSnapshot,
              try Self.namedRegularFileSnapshot(
                  parent: parent,
                  name: name,
                  mismatchReason: .targetMismatch
              ) == targetSnapshot else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        removeCreated = false
        return StreamedFileDigest(
            byteCount: copiedByteCount,
            sha256: sourceDigest,
            snapshot: sourceSnapshot
        )
    }

    func requireStagingGeneration(id: UUID) throws {
        try verify()
        _ = try Self.requiredDirectoryIdentity(
            parent: stagingGenerationsDescriptor,
            name: Self.canonical(id)
        )
    }

    func requireInstalledGeneration(id: UUID) throws {
        try verify()
        _ = try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(id)
        )
    }

    /// Descriptor-pinned physical binding for a semantically validated Erase
    /// preparation target. The full owned tree is inventoried and hashed,
    /// including recovery-owned leaves of a genuinely interrupted target.
    fileprivate func snapshotErasePreparedTarget(id: UUID, partialCleanup: Bool = false) throws
        -> ErasePreparedTargetSnapshotV1 {
        try requireInstalledGeneration(id: id)
        let descriptor = Darwin.openat(installedGenerationsDescriptor,
            Self.canonical(id), O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        let inventory = try GenerationInventory(parent: descriptor,
            requireModel: !partialCleanup, partialCleanup: partialCleanup)
        defer { inventory.close() }
        let facts = try inventory.snapshotFacts(rootName: Self.canonical(id))
        let files = try inventory.fileDigests(durable: false,
            includeRecoveryOwnedForEraseDiscard: true)
        guard try inventory.snapshotFacts(rootName: Self.canonical(id)) == facts,
              try Self.requiredDirectoryIdentity(parent: installedGenerationsDescriptor,
                  name: Self.canonical(id)) == inventory.root.identity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return ErasePreparedTargetSnapshotV1(facts: facts, files: files)
    }

    func stagingTree(id: UUID) throws -> Tree {
        try tree(parent: stagingGenerationsDescriptor, id: id)
    }

    func installedTree(id: UUID) throws -> Tree {
        if originalRecoveryNoCreate {
            try verify()
            let walked = try originalRecoveryIO.treeWithNodes(
                parent: installedGenerationsDescriptor,
                name: Self.canonical(id))
            let directories = Set(walked.nodes.filter {
                $0.fact.st_mode & S_IFMT == S_IFDIR && !$0.path.isEmpty
            }.map(\.path))
            let files = Set(walked.nodes.filter {
                $0.fact.st_mode & S_IFMT == S_IFREG
            }.map(\.path))
            guard try originalRecoveryIO.tree(parent: installedGenerationsDescriptor,
                name: Self.canonical(id)) == walked.digest else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try verify()
            return Tree(directories: directories, files: files)
        }
        return try tree(parent: installedGenerationsDescriptor, id: id)
    }

    /// The canonical tree remains separate. This original-Erase-only digest
    /// binds the complete C45 operational subtree to the fenced C05 rows.
    func c05SourceTransientWitness(id: UUID) throws
        -> C05GenerationTransientWitnessV1 {
        guard id == c05SourceGenerationID,
              let c05SourceJobs, let c05SourceEpoch else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        let descriptor = Darwin.openat(installedGenerationsDescriptor,
            Self.canonical(id), O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        let inventory = try GenerationInventory(parent: descriptor,
            requireModel: true, c05SourceJobs: c05SourceJobs,
            c05SourceEpoch: c05SourceEpoch)
        defer { inventory.close() }
        let witness = try inventory.c05TransientWitness()
        guard try Self.requiredDirectoryIdentity(
            parent: installedGenerationsDescriptor,
            name: Self.canonical(id)) == inventory.root.identity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        return witness
    }

    func removeEmptyOriginalC05Parents(
        id: UUID,
        expectedAfterJobDrain: C05GenerationTransientWitnessV1
    ) throws {
        guard !originalC05ParentRemovalUncertain,
              id == c05SourceGenerationID,
              let c05SourceJobs, let c05SourceEpoch else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        let descriptor = Darwin.openat(installedGenerationsDescriptor,
            Self.canonical(id), O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
        guard descriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var closeAttempted = false
        do {
            let inventory = try GenerationInventory(parent: descriptor,
                requireModel: true, c05SourceJobs: c05SourceJobs,
                c05SourceEpoch: c05SourceEpoch)
            try inventory.removeEmptyOriginalC05Parents(
                expectedAfterJobDrain: expectedAfterJobDrain)
            guard try Self.requiredDirectoryIdentity(
                parent: installedGenerationsDescriptor,
                name: Self.canonical(id)) == inventory.root.identity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let ordinary = try GenerationInventory(parent: descriptor,
                requireModel: true)
            try ordinary.revalidate()
            closeAttempted = true
            guard Darwin.close(descriptor) == 0 else {
                originalC05ParentRemovalUncertain = true
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try verify()
        } catch {
            originalC05ParentRemovalUncertain = true
            if !closeAttempted {
                // One checked attempt only. A failed close is ambiguous and
                // the numeric descriptor is never retried or reassigned.
                _ = Darwin.close(descriptor)
            }
            throw error
        }
    }

    func removeStagingGeneration(id: UUID) throws {
        try mutationRegistry.withNoMigrationReservation {
            try removeDirectory(parent: stagingGenerationsDescriptor, name: Self.canonical(id), ownership: .generation)
        }
    }

    func removeInstalledGeneration(id: UUID) throws {
        try mutationRegistry.withNoMigrationReservation {
            try removeDirectory(parent: installedGenerationsDescriptor, name: Self.canonical(id), ownership: .generation)
        }
    }

    /// Fixed Erase-only mutation under the actual retained EX. Ordinary
    /// generation removal continues through its original reservation guard.
    @MainActor
    func removeInstalledGenerationForEraseRetirement(
        id: UUID, keeping currentID: UUID, retirement: ErasedRegistryRetirementProofV1
    ) throws {
        try retirement.requireGenerationDeletion(id: id, keeping: currentID)
        guard applicationSupportURL.standardizedFileURL
                == retirement.binding.subject.applicationSupportURL.standardizedFileURL,
              Int64(applicationSupportIdentity.device) == retirement.binding.subject.applicationSupportDevice,
              UInt64(applicationSupportIdentity.inode) == retirement.binding.subject.applicationSupportInode,
              try CurrentPointerCodecV1.decode(retirement.readPointer(using: self,
                name: "current.json")).generationID == Self.canonical(currentID) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try removeDirectory(parent: installedGenerationsDescriptor,
            name: Self.canonical(id), ownership: .generation)
        try retirement.requireGenerationDeletion(id: id, keeping: currentID)
    }

    @MainActor
    func clearRetiredGenerationsForEraseRetirement(
        expected: [UUID], currentID: UUID, retirement: ErasedRegistryRetirementProofV1
    ) throws {
        try retirement.requireRetiredPointerClear(expected: expected, currentID: currentID)
        guard applicationSupportURL.standardizedFileURL
                == retirement.binding.subject.applicationSupportURL.standardizedFileURL,
              Int64(applicationSupportIdentity.device) == retirement.binding.subject.applicationSupportDevice,
              UInt64(applicationSupportIdentity.inode) == retirement.binding.subject.applicationSupportInode else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let currentBytes = try retirement.readPointer(using: self, name: "current.json")
        guard try CurrentPointerCodecV1.decode(currentBytes).generationID == Self.canonical(currentID) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        guard !expected.contains(currentID),
              expected.map(Self.canonical) == expected.map(Self.canonical).sorted(),
              Set(expected).count == expected.count,
              try eraseRetirementCheckedSnapshotIO.names(
                  in: installedGenerationsDescriptor)
                    == [Self.canonical(currentID)] else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let oldData = try Self.canonicalData(RetiredPointerV1(
            generationIDs: expected.map(Self.canonical),
            schemaVersion: StorePointerSchemaRegistry.retiredVersion))
        let replacementData = try Self.canonicalData(RetiredPointerV1(
            generationIDs: [], schemaVersion: StorePointerSchemaRegistry.retiredVersion))
        _ = try retiredIDsForEraseRetirementWithReservedTemporary(
            expected: expected, currentID: currentID, retirement: retirement)
        Self.pointerMutationLock.lock()
        defer { Self.pointerMutationLock.unlock() }
        func observe() throws -> EraseRetirementPointerState {
            try observeEraseRetirementPointerState(expected: expected,
                currentID: currentID, currentData: currentBytes,
                oldData: oldData, replacementData: replacementData,
                retirement: retirement)
        }
        var state = try observe()
        if state.cut == .before || state.cut == .preparingTemporary {
            state = try completeEraseRetirementTemporary(state: state,
                expected: expected, currentID: currentID,
                currentData: currentBytes, oldData: oldData,
                replacementData: replacementData, retirement: retirement)
            state = try publishEraseRetirementTemporary(state: state,
                expected: expected, currentID: currentID,
                currentData: currentBytes, oldData: oldData,
                replacementData: replacementData, retirement: retirement)
        }
        if state.cut == .swapped {
            state = try removeEraseRetirementOldTemporary(state: state,
                expected: expected, currentID: currentID,
                currentData: currentBytes, oldData: oldData,
                replacementData: replacementData, retirement: retirement)
        }
        guard state.cut == .complete,
              try observe() == state,
              eraseRetirementUncertainDescriptors.isEmpty,
              try eraseRetirementCheckedSnapshotIO.names(
                  in: installedGenerationsDescriptor)
                    == [Self.canonical(currentID)] else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        eraseRetirementPointerProvenance["retired.json"] = .published(
            data: replacementData,
            fact: Self.eraseRetirementFactToken(state.retired.fact))
        guard try retirement.readPointer(using: self, name: "retired.json") == replacementData,
              try retirement.readPointer(using: self, name: "current.json") == currentBytes else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try retirement.requireRetiredPointerClear(expected: expected, currentID: currentID)
    }

    func replaceRetiredGenerationIDs(
        expected: [UUID],
        with replacement: [UUID],
        currentID: UUID
    ) throws {
        try verify()
        guard try currentGenerationID() == currentID,
              try retiredGenerationIDs() == expected,
              !replacement.contains(currentID),
              Set(replacement).count == replacement.count,
              replacement == replacement.sorted(by: Self.idOrder) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try replacePointer(
            name: "retired.json",
            value: RetiredPointerV1(
                generationIDs: replacement.map(Self.canonical),
                schemaVersion: StorePointerSchemaRegistry.retiredVersion
            )
        )
        guard try retiredGenerationIDs() == replacement else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

