    func removeImportStagingPackage(name: String) throws {
        try Self.requireSafeBasename(name)
        try removeDirectory(parent: importStagingDescriptor, name: name, ownership: .importStaging)
    }

    private func reconcileRestorePointerTemporary(name: String) throws {
        let temporary = ".\(name).restore-next"
        guard try Self.itemExists(
            parent: dataDescriptor,
            name: temporary
        ) else {
            return
        }

        Self.pointerMutationLock.lock()
        defer { Self.pointerMutationLock.unlock() }
        guard try Self.itemExists(
            parent: dataDescriptor,
            name: temporary
        ) else {
            return
        }
        try verify()
        try enforce(
            .generationPointer,
            at: dataURL.appendingPathComponent(name, isDirectory: false)
        )
        try enforce(
            .generationPointerTemporary,
            at: dataURL.appendingPathComponent(temporary, isDirectory: false)
        )
        let current = try Self.readRegularFileWithIdentity(
            parent: dataDescriptor,
            name: name
        )
        let candidate = try Self.readRegularFileWithIdentity(
            parent: dataDescriptor,
            name: temporary
        )
        switch name {
        case "current.json":
            _ = try CurrentPointerCodecV1.decode(current.data)
            _ = try CurrentPointerCodecV1.decode(candidate.data)
        case "retired.json":
            let currentValue = try JSONDecoder().decode(
                RetiredPointerV1.self,
                from: current.data
            )
            let candidateValue = try JSONDecoder().decode(
                RetiredPointerV1.self,
                from: candidate.data
            )
            guard try Self.canonicalData(currentValue) == current.data,
                  try Self.canonicalData(candidateValue) == candidate.data else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try StorePointerSchemaRegistry.requireRetired(
                currentValue.schemaVersion
            )
            try StorePointerSchemaRegistry.requireRetired(
                candidateValue.schemaVersion
            )
        default:
            throw StoreGenerationFailure.dataPointerInvalid
        }
        guard current.identity.linkCount == 1,
              candidate.identity.linkCount == 1,
              try Self.regularFileIdentity(
                  parent: dataDescriptor,
                  name: name
              ) == current.identity,
              try Self.regularFileIdentity(
                  parent: dataDescriptor,
                  name: temporary
              ) == candidate.identity,
              Darwin.unlinkat(dataDescriptor, temporary, 0) == 0,
              Darwin.fsync(dataDescriptor) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        try enforce(
            .generationPointer,
            at: dataURL.appendingPathComponent(name, isDirectory: false)
        )
    }

    private func requireCheckedEraseRetirementWriterAuthority() throws {
        guard eraseRetirementUncertainDescriptors.isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try eraseRetirementCheckedSnapshotIO.requireSettled()
        try Self.require(applicationSupportDescriptor, applicationSupportIdentity)
        try Self.require(dataDescriptor, dataIdentity)
        try Self.require(installedGenerationsDescriptor, installedGenerationsIdentity)
        try Self.require(restoreDescriptor, restoreIdentity)
        try Self.require(stagingGenerationsDescriptor, stagingGenerationsIdentity)
        try Self.require(importStagingDescriptor, importStagingIdentity)
        func requireNamed(_ parent: Int32, _ name: String, _ expected: Identity) throws {
            guard try Self.requiredDirectoryIdentity(parent: parent, name: name)
                    == expected else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        var root = stat()
        guard Darwin.lstat(applicationSupportURL.path, &root) == 0,
              root.st_mode & S_IFMT == S_IFDIR,
              root.st_dev == applicationSupportIdentity.device,
              root.st_ino == applicationSupportIdentity.inode else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireNamed(applicationSupportDescriptor, Self.dataName, dataIdentity)
        try requireNamed(dataDescriptor, Self.generationsName, installedGenerationsIdentity)
        try requireNamed(applicationSupportDescriptor, Self.restoreName, restoreIdentity)
        try requireNamed(restoreDescriptor, Self.generationsName, stagingGenerationsIdentity)
        try requireNamed(restoreDescriptor, Self.importStagingName, importStagingIdentity)
    }

    private func checkedEraseRetirementRead(_ name: String) throws -> EraseRetirementPointerRead {
        try Self.requireSafeBasename(name)
        try requireCheckedEraseRetirementWriterAuthority()
        let value = try eraseRetirementCheckedSnapshotIO.withOpen(
            parent: dataDescriptor, name: name,
            flags: O_RDONLY | O_NONBLOCK) { descriptor in
            var before = stat(), after = stat(), named = stat()
            guard Darwin.fstat(descriptor, &before) == 0,
                  before.st_mode & S_IFMT == S_IFREG, before.st_nlink == 1,
                  before.st_size >= 0,
                  before.st_size <= off_t(Self.maximumControlFileByteCount),
                  Darwin.fstatat(dataDescriptor, name, &named,
                      AT_SYMLINK_NOFOLLOW) == 0,
                  EraseRetirementFileFact(named) == EraseRetirementFileFact(before) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var data = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    guard data.count <= Self.maximumControlFileByteCount - count else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    data.append(contentsOf: buffer.prefix(count))
                } else if count == 0 { break }
                else if errno != EINTR { throw StoreGenerationFailure.dataPointerInvalid }
            }
            guard Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(dataDescriptor, name, &named,
                      AT_SYMLINK_NOFOLLOW) == 0,
                  EraseRetirementFileFact(after) == EraseRetirementFileFact(before),
                  EraseRetirementFileFact(named) == EraseRetirementFileFact(before),
                  data.count == Int(before.st_size) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return EraseRetirementPointerRead(data: data,
                identity: RegularFileIdentity(device: before.st_dev,
                    inode: before.st_ino, linkCount: before.st_nlink),
                fact: EraseRetirementFileFact(before))
        }
        try requireCheckedEraseRetirementWriterAuthority()
        return value
    }

    private func checkedEraseRetirementCreateEmpty(_ name: String) throws {
        try Self.requireSafeBasename(name)
        try requireCheckedEraseRetirementWriterAuthority()
        _ = try eraseRetirementCheckedSnapshotIO.withOpen(parent: dataDescriptor,
            name: name, flags: O_WRONLY | O_CREAT | O_EXCL,
            mode: mode_t(0o600)) { descriptor in
            guard Darwin.fsync(descriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        guard Darwin.fsync(dataDescriptor) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireCheckedEraseRetirementWriterAuthority()
    }

    private struct EraseRetirementPointerState: Equatable {
        enum Cut: Equatable {
            case before
            case preparingTemporary
            case swapped
            case complete
        }
        let current: EraseRetirementPointerRead
        let retired: EraseRetirementPointerRead
        let temporary: EraseRetirementPointerRead?
        let dataDirectoryFact: EraseRetirementFileFact
        let cut: Cut
    }

    /// Pure, checked observation of the four canonical Erase pointer cuts.
    /// In particular, a prefix temp is not made into an authority by its name:
    /// the genuine proof and frozen P/current/target are rechecked before any
    /// later policy request or write.  No ordinary Restore reconciliation runs.
    @MainActor
    private func observeEraseRetirementPointerState(
        expected: [UUID], currentID: UUID,
        currentData: Data, oldData: Data, replacementData: Data,
        retirement: ErasedRegistryRetirementProofV1
    ) throws -> EraseRetirementPointerState {
        try retirement.requireRetiredPointerClear(expected: expected, currentID: currentID)
        try requireCheckedEraseRetirementWriterAuthority()
        let allowed = ["current.json", "generations", "retired.json"]
        let temporaryName = ".retired.json.restore-next"
        func directoryFact() throws -> EraseRetirementFileFact {
            var held = stat(), named = stat()
            guard Darwin.fstat(dataDescriptor, &held) == 0,
                  Darwin.fstatat(applicationSupportDescriptor, Self.dataName,
                      &named, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseRetirementFileFact(held) == EraseRetirementFileFact(named),
                  held.st_mode & S_IFMT == S_IFDIR else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return EraseRetirementFileFact(held)
        }
        func once() throws -> EraseRetirementPointerState {
            let before = try directoryFact()
            let names = try eraseRetirementCheckedSnapshotIO.names(in: dataDescriptor)
            guard names == allowed || names == (allowed + [temporaryName]).sorted() else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let current = try checkedEraseRetirementRead("current.json")
            let retired = try checkedEraseRetirementRead("retired.json")
            let temporary = names.contains(temporaryName)
                ? try checkedEraseRetirementRead(temporaryName) : nil
            guard try directoryFact() == before,
                  try eraseRetirementCheckedSnapshotIO.names(in: dataDescriptor) == names,
                  current.data == currentData,
                  try CurrentPointerCodecV1.decode(current.data).generationID
                    == Self.canonical(currentID),
                  retired.data == oldData || retired.data == replacementData else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if case .captured(let bytes, let fact)? =
                eraseRetirementPointerProvenance["current.json"] {
                guard bytes == current.data,
                      fact == Self.eraseRetirementFactToken(current.fact) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            let cut: EraseRetirementPointerState.Cut
            if retired.data == oldData {
                guard temporary.map({ replacementData.starts(with: $0.data) }) ?? true else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                cut = temporary == nil ? .before : .preparingTemporary
                if case .captured(let bytes, let fact)? =
                    eraseRetirementPointerProvenance["retired.json"] {
                    guard bytes == retired.data,
                          fact == Self.eraseRetirementFactToken(retired.fact) else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
            } else {
                guard temporary.map({ $0.data == oldData }) ?? true else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                cut = temporary == nil ? .complete : .swapped
                if case .captured(let bytes, let fact)? =
                    eraseRetirementPointerProvenance["retired.json"],
                   let temporary {
                    guard bytes == temporary.data,
                          Self.eraseRetirementFactBeforeRenameMatches(
                              fact, temporary.fact) else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
                if case .published(let bytes, let fact)? =
                    eraseRetirementPointerProvenance["retired.json"] {
                    guard bytes == retired.data,
                          fact == Self.eraseRetirementFactToken(retired.fact) else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
            }
            return EraseRetirementPointerState(current: current, retired: retired,
                temporary: temporary, dataDirectoryFact: before, cut: cut)
        }
        let first = try once()
        guard try once() == first else { throw StoreGenerationFailure.dataPointerInvalid }
        try retirement.requireRetiredPointerClear(expected: expected, currentID: currentID)
        return first
    }

    /// The newly named pointer inherits the temporary inode's backup policy
    /// across RENAME_SWAP. Settle only that exact, operation-bound inode before
    /// a strict pointer read. The displaced old pointer keeps pointer policy
    /// until its checked unlink. A crash at either cut resumes from the same
    /// canonical bytes and closed Data namespace, without an ordinary writer.
    @MainActor
    private func settlePublishedEraseRetirementPointerPolicy(
        state original: EraseRetirementPointerState,
        expected: [UUID], currentID: UUID,
        currentData: Data, oldData: Data, replacementData: Data,
        retirement: ErasedRegistryRetirementProofV1
    ) throws -> EraseRetirementPointerState {
        guard (original.cut == .swapped || original.cut == .complete),
              original.retired.data == replacementData,
              original.current.data == currentData,
              try eraseRetirementCheckedSnapshotIO.names(
                  in: installedGenerationsDescriptor)
                    == [Self.canonical(currentID)] else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let url = dataURL.appendingPathComponent("retired.json", isDirectory: false)
        func observe() throws -> EraseRetirementPointerState {
            try observeEraseRetirementPointerState(expected: expected,
                currentID: currentID, currentData: currentData,
                oldData: oldData, replacementData: replacementData,
                retirement: retirement)
        }
        guard try observe() == original else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        // A settled pointer needs no metadata write. A resource mismatch is
        // eligible only when the exact same leaf still has the temporary
        // disposition, including its backup exclusion and type.
        do {
            _ = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
                .generationPointer, at: url,
                retainUncertainDescriptor: { value in
                    self.eraseRetirementUncertainDescriptors.append(value)
                })
            guard eraseRetirementUncertainDescriptors.isEmpty,
                  try observe() == original else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return original
        } catch ProtectedFilePolicyError.resourceValueMismatch {
            guard eraseRetirementUncertainDescriptors.isEmpty,
                  try observe() == original else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        _ = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
            .generationPointerTemporary, at: url,
            retainUncertainDescriptor: { value in
                self.eraseRetirementUncertainDescriptors.append(value)
            })
        guard eraseRetirementUncertainDescriptors.isEmpty,
              try observe() == original else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let names = original.cut == .swapped
            ? [".retired.json.restore-next", "current.json", "generations", "retired.json"]
            : ["current.json", "generations", "retired.json"]
        func boundRead() throws -> EraseRetirementPointerRead {
            try retirement.requireRetiredPointerClear(expected: expected,
                currentID: currentID)
            try requireCheckedEraseRetirementWriterAuthority()
            var heldData = stat(), namedData = stat()
            guard Darwin.fstat(dataDescriptor, &heldData) == 0,
                  Darwin.fstatat(applicationSupportDescriptor, Self.dataName,
                      &namedData, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseRetirementFileFact(heldData) == original.dataDirectoryFact,
                  EraseRetirementFileFact(namedData) == original.dataDirectoryFact,
                  try eraseRetirementCheckedSnapshotIO.names(
                      in: installedGenerationsDescriptor)
                        == [Self.canonical(currentID)],
                  try eraseRetirementCheckedSnapshotIO.names(in: dataDescriptor) == names,
                  try checkedEraseRetirementRead("current.json") == original.current else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let retired = try checkedEraseRetirementRead("retired.json")
            guard retired.data == original.retired.data,
                  retired.identity == original.retired.identity,
                  retired.fact.mode == original.retired.fact.mode,
                  retired.fact.size == original.retired.fact.size,
                  retired.fact.modifiedSeconds == original.retired.fact.modifiedSeconds,
                  retired.fact.modifiedNanoseconds == original.retired.fact.modifiedNanoseconds else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if original.cut == .swapped {
                guard try checkedEraseRetirementRead(
                    ".retired.json.restore-next") == original.temporary else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard try eraseRetirementCheckedSnapshotIO.names(in: dataDescriptor) == names,
                  try eraseRetirementCheckedSnapshotIO.names(
                      in: installedGenerationsDescriptor)
                        == [Self.canonical(currentID)],
                  Darwin.fstat(dataDescriptor, &heldData) == 0,
                  Darwin.fstatat(applicationSupportDescriptor, Self.dataName,
                      &namedData, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseRetirementFileFact(heldData) == original.dataDirectoryFact,
                  EraseRetirementFileFact(namedData) == original.dataDirectoryFact else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return retired
        }
        guard try boundRead() == original.retired else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try ProtectedFilePolicyV1.applyAndVerifyEraseColdPrivateWithCheckedClose(
            .generationPointer, at: url,
            retainUncertainDescriptor: { value in
                self.eraseRetirementUncertainDescriptors.append(value)
            }, authorityCheck: {
                _ = try boundRead()
            }, beforeFirstEffect: {
                guard try observe() == original,
                      try boundRead() == original.retired else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            })
        guard eraseRetirementUncertainDescriptors.isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let settledRetired = try boundRead()
        eraseRetirementPointerProvenance["retired.json"] = .published(
            data: replacementData,
            fact: Self.eraseRetirementFactToken(settledRetired.fact))
        let settled = try observe()
        guard settled.current == original.current,
              settled.retired == settledRetired,
              settled.temporary == original.temporary,
              settled.cut == original.cut else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return settled
    }

    @MainActor
    fileprivate func retiredIDsForEraseRetirementWithReservedTemporary(
        expected: [UUID], currentID: UUID,
        retirement: ErasedRegistryRetirementProofV1
    ) throws -> [UUID] {
        let currentData = try retirement.readPointer(using: self, name: "current.json")
        let oldData = try Self.canonicalData(RetiredPointerV1(
            generationIDs: expected.map(Self.canonical),
            schemaVersion: StorePointerSchemaRegistry.retiredVersion))
        let replacementData = try Self.canonicalData(RetiredPointerV1(
            generationIDs: [], schemaVersion: StorePointerSchemaRegistry.retiredVersion))
        let original = try observeEraseRetirementPointerState(expected: expected,
            currentID: currentID, currentData: currentData,
            oldData: oldData, replacementData: replacementData,
            retirement: retirement)
        let settled: EraseRetirementPointerState
        if original.cut == .swapped || original.cut == .complete {
            settled = try settlePublishedEraseRetirementPointerPolicy(
                state: original, expected: expected, currentID: currentID,
                currentData: currentData, oldData: oldData,
                replacementData: replacementData, retirement: retirement)
        } else {
            settled = original
        }
        let names: [(String, OwnedFileKindV1)]
        switch settled.cut {
        case .before, .preparingTemporary:
            names = [("retired.json", .generationPointer)]
        case .swapped:
            names = [("retired.json", .generationPointer),
                     // RENAME_SWAP moves the old pointer inode under this
                     // reserved name. It retains pointer policy until its
                     // checked removal; ordinary Restore does the same.
                     (".retired.json.restore-next", .generationPointer)]
        case .complete:
            names = [("retired.json", .generationPointer)]
        }
        for (name, kind) in names {
            _ = try ProtectedFilePolicyV1
                .verifyEraseColdTemporalPolicyWithCheckedRequest(
                    kind, at: dataURL.appendingPathComponent(name),
                    retainUncertainDescriptor: { value in
                        self.eraseRetirementUncertainDescriptors.append(value)
                    }, unchangedWitness: {
                        let current = try self.observeEraseRetirementPointerState(
                            expected: expected, currentID: currentID,
                            currentData: currentData, oldData: oldData,
                            replacementData: replacementData,
                            retirement: retirement)
                        guard current == settled else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        return current
                    })
        }
        guard eraseRetirementUncertainDescriptors.isEmpty,
              try observeEraseRetirementPointerState(expected: expected,
                  currentID: currentID, currentData: currentData,
                  oldData: oldData, replacementData: replacementData,
                  retirement: retirement) == settled else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        switch settled.cut {
        case .before, .preparingTemporary: return expected
        case .swapped, .complete: return []
        }
    }

    @MainActor
    private func completeEraseRetirementTemporary(
        state original: EraseRetirementPointerState,
        expected: [UUID], currentID: UUID,
        currentData: Data, oldData: Data, replacementData: Data,
        retirement: ErasedRegistryRetirementProofV1
    ) throws -> EraseRetirementPointerState {
        guard original.cut == .before || original.cut == .preparingTemporary else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let temporaryName = ".retired.json.restore-next"
        func reproveSource() throws -> EraseRetirementPointerState {
            let value = try observeEraseRetirementPointerState(
                expected: expected, currentID: currentID,
                currentData: currentData, oldData: oldData,
                replacementData: replacementData, retirement: retirement)
            guard value.current == original.current,
                  value.retired == original.retired,
                  value.cut == .preparingTemporary,
                  let temporary = value.temporary,
                  replacementData.starts(with: temporary.data) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return value
        }
        if original.cut == .before {
            guard try observeEraseRetirementPointerState(
                expected: expected, currentID: currentID,
                currentData: currentData, oldData: oldData,
                replacementData: replacementData, retirement: retirement) == original else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            // Reserve an empty inode before a protection request or bytes.
            // A crash here leaves the exact empty-prefix cut for cold replay.
            try checkedEraseRetirementCreateEmpty(temporaryName)
        }
        let beforePolicy = try reproveSource()
        guard let beforeTemp = beforePolicy.temporary else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try ProtectedFilePolicyV1.applyAndVerifyEraseColdPrivateWithCheckedClose(
            .generationPointerTemporary,
            at: dataURL.appendingPathComponent(temporaryName),
            retainUncertainDescriptor: { value in
                self.eraseRetirementUncertainDescriptors.append(value)
            }, authorityCheck: {
                let now = try reproveSource()
                guard now.temporary?.identity == beforeTemp.identity,
                      now.temporary?.data == beforeTemp.data else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }, beforeFirstEffect: {
                guard try reproveSource() == beforePolicy else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            })
        guard eraseRetirementUncertainDescriptors.isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let protected = try reproveSource()
        guard protected.temporary?.identity == beforeTemp.identity,
              protected.temporary?.data == beforeTemp.data else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        if beforeTemp.data.count < replacementData.count {
            let suffix = Data(replacementData.dropFirst(beforeTemp.data.count))
            _ = try eraseRetirementCheckedSnapshotIO.withOpen(
                parent: dataDescriptor, name: temporaryName,
                flags: O_RDWR | O_NONBLOCK) { descriptor in
                var held = stat(), named = stat()
                guard Darwin.fstat(descriptor, &held) == 0,
                      Darwin.fstatat(dataDescriptor, temporaryName,
                          &named, AT_SYMLINK_NOFOLLOW) == 0,
                      EraseRetirementFileFact(held) == protected.temporary?.fact,
                      EraseRetirementFileFact(named) == protected.temporary?.fact,
                      try reproveSource() == protected else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try suffix.withUnsafeBytes { raw in
                    guard let base = raw.baseAddress else { return }
                    var written = 0
                    while written < raw.count {
                        let result = Darwin.pwrite(descriptor,
                            base.advanced(by: written), raw.count - written,
                            off_t(beforeTemp.data.count + written))
                        if result > 0 { written += result }
                        else if errno != EINTR {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                }
                guard Darwin.fsync(descriptor) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        let completed = try reproveSource()
        guard completed.temporary?.data == replacementData,
              completed.current == original.current,
              completed.retired == original.retired else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return completed
    }

    @MainActor
    private func publishEraseRetirementTemporary(
        state completed: EraseRetirementPointerState,
        expected: [UUID], currentID: UUID,
        currentData: Data, oldData: Data, replacementData: Data,
        retirement: ErasedRegistryRetirementProofV1
    ) throws -> EraseRetirementPointerState {
        guard completed.cut == .preparingTemporary,
              let sealed = completed.temporary,
              sealed.data == replacementData else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let temporaryName = ".retired.json.restore-next"
        func observe() throws -> EraseRetirementPointerState {
            try observeEraseRetirementPointerState(expected: expected,
                currentID: currentID, currentData: currentData,
                oldData: oldData, replacementData: replacementData,
                retirement: retirement)
        }
        _ = try ProtectedFilePolicyV1
            .verifyEraseColdTemporalPolicyWithCheckedRequest(
                .generationPointerTemporary,
                at: dataURL.appendingPathComponent(temporaryName),
                retainUncertainDescriptor: { value in
                    self.eraseRetirementUncertainDescriptors.append(value)
                }, unchangedWitness: {
                    let state = try observe()
                    guard state == completed else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    return state
                })
        guard eraseRetirementUncertainDescriptors.isEmpty,
              try observe() == completed else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let published = try eraseRetirementCheckedSnapshotIO.withOpen(
            parent: dataDescriptor, name: temporaryName,
            flags: O_RDONLY | O_NONBLOCK) { heldNew -> EraseRetirementPointerState in
            var held = stat(), named = stat()
            guard Darwin.fstat(heldNew, &held) == 0,
                  Darwin.fstatat(dataDescriptor, temporaryName,
                      &named, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseRetirementFileFact(held) == sealed.fact,
                  EraseRetirementFileFact(named) == sealed.fact,
                  try observe() == completed,
                  Darwin.fsync(heldNew) == 0,
                  Darwin.renameatx_np(dataDescriptor, temporaryName,
                      dataDescriptor, "retired.json", UInt32(RENAME_SWAP)) == 0,
                  Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let result = try observe()
            guard result.cut == .swapped,
                  result.current == completed.current,
                  result.retired.data == replacementData,
                  result.retired.identity == sealed.identity,
                  result.temporary?.data == oldData,
                  result.temporary?.identity == completed.retired.identity,
                  Darwin.fstat(heldNew, &held) == 0,
                  EraseRetirementFileFact(held) == result.retired.fact else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return result
        }
        try retirement.requireRetiredPointerClear(expected: expected, currentID: currentID)
        eraseRetirementPointerProvenance["retired.json"] = .published(
            data: replacementData,
            fact: Self.eraseRetirementFactToken(published.retired.fact))
        return try settlePublishedEraseRetirementPointerPolicy(
            state: published, expected: expected, currentID: currentID,
            currentData: currentData, oldData: oldData,
            replacementData: replacementData, retirement: retirement)
    }

    @MainActor
    private func removeEraseRetirementOldTemporary(
        state swapped: EraseRetirementPointerState,
        expected: [UUID], currentID: UUID,
        currentData: Data, oldData: Data, replacementData: Data,
        retirement: ErasedRegistryRetirementProofV1
    ) throws -> EraseRetirementPointerState {
        guard swapped.cut == .swapped,
              let displaced = swapped.temporary,
              displaced.data == oldData,
              swapped.retired.data == replacementData else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let temporaryName = ".retired.json.restore-next"
        func observe() throws -> EraseRetirementPointerState {
            try observeEraseRetirementPointerState(expected: expected,
                currentID: currentID, currentData: currentData,
                oldData: oldData, replacementData: replacementData,
                retirement: retirement)
        }
        let completed = try eraseRetirementCheckedSnapshotIO.withOpen(
            parent: dataDescriptor, name: temporaryName,
            flags: O_RDONLY | O_NONBLOCK) { heldOld -> EraseRetirementPointerState in
            var held = stat(), named = stat()
            guard Darwin.fstat(heldOld, &held) == 0,
                  Darwin.fstatat(dataDescriptor, temporaryName,
                      &named, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseRetirementFileFact(held) == displaced.fact,
                  EraseRetirementFileFact(named) == displaced.fact,
                  try observe() == swapped,
                  Darwin.unlinkat(dataDescriptor, temporaryName, 0) == 0,
                  Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            guard Darwin.fstat(heldOld, &held) == 0,
                  held.st_dev == displaced.identity.device,
                  held.st_ino == displaced.identity.inode,
                  held.st_nlink == 0,
                  Darwin.fstatat(dataDescriptor, temporaryName,
                      &named, AT_SYMLINK_NOFOLLOW) != 0,
                  errno == ENOENT else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let result = try observe()
            guard result.cut == .complete,
                  result.current == swapped.current,
                  result.retired == swapped.retired else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return result
        }
        try retirement.requireRetiredPointerClear(expected: expected, currentID: currentID)
        return completed
    }

    private func replacePointer<Value: Encodable>(
        name: String,
        value: Value,
        expectedData requiredExpectedData: Data? = nil
    ) throws {
        Self.pointerMutationLock.lock()
        defer { Self.pointerMutationLock.unlock() }
        try verify()
        try enforce(
            .generationPointer,
            at: dataURL.appendingPathComponent(name, isDirectory: false)
        )
        let expectedRead = try Self.readRegularFileWithIdentity(
            parent: dataDescriptor,
            name: name
        )
        let expectedIdentity = expectedRead.identity
        let expected = expectedRead.data
        if let requiredExpectedData,
           expected != requiredExpectedData {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let replacement = try Self.canonicalData(value)
        let temporary = ".\(name).restore-next"
        if try Self.itemExists(parent: dataDescriptor, name: temporary) {
            try enforce(
                .generationPointerTemporary,
                at: dataURL.appendingPathComponent(temporary, isDirectory: false)
            )
            let existingTemporary = try Self.readRegularFileWithIdentity(
                parent: dataDescriptor,
                name: temporary
            )
            let existingCurrent = try Self.readRegularFileWithIdentity(
                parent: dataDescriptor,
                name: name
            )
            guard existingTemporary.data == replacement,
                  existingTemporary.identity.linkCount == 1,
                  existingCurrent.data == expected,
                  existingCurrent.identity == expectedIdentity,
                  Darwin.unlinkat(dataDescriptor, temporary, 0) == 0,
                  Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try verify()
        }
        try Self.createRegularFile(
            parent: dataDescriptor,
            name: temporary,
            data: replacement
        )
        try enforce(
            .generationPointerTemporary,
            at: dataURL.appendingPathComponent(temporary, isDirectory: false)
        )
        let replacementIdentity = try Self.regularFileIdentity(
            parent: dataDescriptor,
            name: temporary
        )
        var published = false
        let publishedIdentity = replacementIdentity
        do {
            try verify()
            let currentBeforeSwap = try Self.readRegularFileWithIdentity(
                parent: dataDescriptor,
                name: name
            )
            guard currentBeforeSwap.identity == expectedIdentity,
                  currentBeforeSwap.data == expected,
                  Darwin.renameatx_np(
                      dataDescriptor,
                      temporary,
                      dataDescriptor,
                      name,
                      UInt32(RENAME_SWAP)
                  ) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            published = true
            guard Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try verify()
            try enforce(
                .generationPointer,
                at: dataURL.appendingPathComponent(name, isDirectory: false)
            )
            let currentAfterSwap = try Self.readRegularFileWithIdentity(
                parent: dataDescriptor,
                name: name
            )
            let oldTemporary = try Self.readRegularFileWithIdentity(
                parent: dataDescriptor,
                name: temporary
            )
            guard currentAfterSwap.data == replacement,
                  currentAfterSwap.identity == replacementIdentity,
                  oldTemporary.data == expected,
                  oldTemporary.identity == expectedIdentity,
                  Darwin.unlinkat(dataDescriptor, temporary, 0) == 0,
                  Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        } catch {
            if published,
               let current = try? Self.readRegularFileWithIdentity(
                   parent: dataDescriptor,
                   name: name
               ),
               current.data == replacement,
               current.identity == publishedIdentity {
                do {
                    let oldTemporary = try Self.readRegularFileWithIdentity(
                        parent: dataDescriptor,
                        name: temporary
                    )
                    guard oldTemporary.data == expected,
                          oldTemporary.identity == expectedIdentity,
                          Darwin.renameatx_np(
                              dataDescriptor,
                              name,
                              dataDescriptor,
                              temporary,
                              UInt32(RENAME_SWAP)
                          ) == 0,
                          Darwin.fsync(dataDescriptor) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    try verify()
                    try enforce(
                        .generationPointer,
                        at: dataURL.appendingPathComponent(name, isDirectory: false)
                    )
                    let restored = try Self.readRegularFileWithIdentity(
                        parent: dataDescriptor,
                        name: name
                    )
                    let replacementTemporary = try Self.readRegularFileWithIdentity(
                        parent: dataDescriptor,
                        name: temporary
                    )
                    guard restored.data == expected,
                          restored.identity == expectedIdentity,
                          replacementTemporary.data == replacement,
                          replacementTemporary.identity == replacementIdentity,
                          Darwin.unlinkat(dataDescriptor, temporary, 0) == 0,
                          Darwin.fsync(dataDescriptor) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                } catch {
                    if ProtectedFilePolicyV1.isProtectedDataUnavailable(error) {
                        throw error
                    }
                }
            }
            if let temporaryData = try? Self.readRegularFile(
                parent: dataDescriptor,
                name: temporary
            ), temporaryData == replacement {
                _ = Darwin.unlinkat(dataDescriptor, temporary, 0)
                _ = Darwin.fsync(dataDescriptor)
            }
            throw error
        }
    }

    private func restorePointer(
        name: String,
        data: Data,
        expectedCurrentIdentity: RegularFileIdentity? = nil
    ) throws {
        let rollback = ".\(name).restore-rollback"
        let replacedIdentity = try Self.regularFileIdentity(
            parent: dataDescriptor,
            name: name
        )
        if let expectedCurrentIdentity {
            guard replacedIdentity == expectedCurrentIdentity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        if try Self.itemExists(parent: dataDescriptor, name: rollback) {
            guard try Self.readRegularFile(parent: dataDescriptor, name: rollback)
                    == data else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            guard Darwin.unlinkat(dataDescriptor, rollback, 0) == 0,
                  Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        try Self.createRegularFile(
            parent: dataDescriptor,
            name: rollback,
            data: data
        )
        try enforce(
            .generationPointerTemporary,
            at: dataURL.appendingPathComponent(rollback, isDirectory: false)
        )
        let publishedIdentity = try Self.regularFileIdentity(
            parent: dataDescriptor,
            name: rollback
        )
        var swapped = false
        do {
            guard try Self.regularFileIdentity(
                      parent: dataDescriptor,
                      name: name
                  ) == replacedIdentity,
                  Darwin.renameatx_np(
                      dataDescriptor,
                      rollback,
                      dataDescriptor,
                      name,
                      UInt32(RENAME_SWAP)
                  ) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            swapped = true
            guard Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try enforce(
                .generationPointer,
                at: dataURL.appendingPathComponent(name, isDirectory: false)
            )
            let restored = try Self.readRegularFileWithIdentity(
                parent: dataDescriptor,
                name: name
            )
            let replaced = try Self.regularFileIdentity(
                parent: dataDescriptor,
                name: rollback
            )
            guard restored.data == data,
                  restored.identity == publishedIdentity,
                  replaced == replacedIdentity,
                  Darwin.unlinkat(dataDescriptor, rollback, 0) == 0,
                  Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            swapped = false
        } catch {
            if swapped,
               let currentIdentity = try? Self.regularFileIdentity(
                   parent: dataDescriptor,
                   name: name
               ),
               currentIdentity == publishedIdentity,
               let rollbackIdentity = try? Self.regularFileIdentity(
                   parent: dataDescriptor,
                   name: rollback
               ),
               rollbackIdentity == replacedIdentity {
                do {
                    guard Darwin.renameatx_np(
                              dataDescriptor,
                              name,
                              dataDescriptor,
                              rollback,
                              UInt32(RENAME_SWAP)
                          ) == 0,
                          Darwin.fsync(dataDescriptor) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                } catch {
                    if ProtectedFilePolicyV1.isProtectedDataUnavailable(error) {
                        throw error
                    }
                }
            }
            throw error
        }
    }

    private func tree(parent: Int32, id: UUID) throws -> Tree {
        try verify()
        let name = Self.canonical(id)
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        let inventory = try GenerationInventory(parent: descriptor, requireModel: false, partialCleanup: true)
        try inventory.revalidate()
        try verify()
        guard try Self.requiredDirectoryIdentity(parent: parent, name: name) == inventory.root.identity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return inventory.tree
    }

    private enum DirectoryCleanupOwnership { case generation, importStaging }

    private func removeDirectory(parent: Int32, name: String, ownership: DirectoryCleanupOwnership, expectedRoot: Identity? = nil) throws {
        try Self.requireSafeBasename(name)
        try verify()
        let descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        if descriptor < 0, errno == ENOENT { return }
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        let expected = try Self.identity(descriptor)
        guard expectedRoot == nil || expectedRoot == expected else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        switch ownership {
        case .generation:
            try Self.removeContents(of: descriptor, authorityCheck: {
                try self.verify()
                guard try Self.requiredDirectoryIdentity(parent: parent, name: name) == expected else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            })
        case .importStaging:
            // Import packages have their own record/member authority, not the
            // installed-generation filename grammar.
            try Self.removeImportContents(of: descriptor)
        }
        try verify()
        guard try Self.requiredDirectoryIdentity(parent: parent, name: name) == expected,
              Darwin.unlinkat(parent, name, AT_REMOVEDIR) == 0,
              Darwin.fsync(parent) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        guard try !Self.itemExists(parent: parent, name: name) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    fileprivate static func removeContents(of directory: Int32, authorityCheck: () throws -> Void = {}) throws {
        let inventory = try GenerationInventory(parent: directory, requireModel: false, partialCleanup: true)
        try inventory.removeAll(authorityCheck: authorityCheck)
    }

    private static func removeImportContents(of directory: Int32) throws {
        for name in try names(in: directory) {
            var info = stat()
            guard Darwin.fstatat(
                directory,
                name,
                &info,
                AT_SYMLINK_NOFOLLOW
            ) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            switch info.st_mode & S_IFMT {
            case S_IFDIR:
                let child = Darwin.openat(
                    directory,
                    name,
                    O_RDONLY | O_DIRECTORY | O_NOFOLLOW
                )
                guard child >= 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let expected: Identity
                do {
                    expected = try identity(child)
                    try removeImportContents(of: child)
                } catch {
                    _ = Darwin.close(child)
                    throw error
                }
                _ = Darwin.close(child)
                guard try requiredDirectoryIdentity(parent: directory, name: name)
                        == expected,
                      Darwin.unlinkat(directory, name, AT_REMOVEDIR) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            case S_IFREG:
                guard info.st_nlink == 1,
                      Darwin.unlinkat(directory, name, 0) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            default:
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        guard Darwin.fsync(directory) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }



    static func names(in descriptor: Int32) throws -> [String] {
        let independent = Darwin.openat(
            descriptor,
            ".",
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard independent >= 0, let directory = Darwin.fdopendir(independent) else {
            if independent >= 0 { _ = Darwin.close(independent) }
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.closedir(directory) }
        var result = [String]()
        errno = 0
        while let entry = Darwin.readdir(directory) {
            guard let name = OwnedStorageDirectoryEntryNameV1.decode(entry) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if name != "." && name != ".." { result.append(name) }
            errno = 0
        }
        guard errno == 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        return result.sorted()
    }

    fileprivate static func itemExists(parent: Int32, name: String) throws -> Bool {
        try requireSafeBasename(name)
        var info = stat()
        if Darwin.fstatat(parent, name, &info, AT_SYMLINK_NOFOLLOW) == 0 {
            return true
        }
        guard errno == ENOENT else { throw StoreGenerationFailure.dataPointerInvalid }
        return false
    }

    private static func directoryPresence(parent: Int32, name: String) throws -> Bool {
        var info = stat()
        if Darwin.fstatat(parent, name, &info, AT_SYMLINK_NOFOLLOW) != 0 {
            guard errno == ENOENT else { throw StoreGenerationFailure.dataPointerInvalid }
            return false
        }
        guard (info.st_mode & S_IFMT) == S_IFDIR else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return true
    }

    fileprivate static func requiredDirectoryIdentity(
        parent: Int32,
        name: String
    ) throws -> Identity {
        let descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        return try identity(descriptor)
    }

    private static func openDirectory(parent: Int32, name: String) throws -> Int32 {
        let descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        return descriptor
    }

    private static func openOrCreateDirectory(parent: Int32, name: String) throws -> Int32 {
        var descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        if descriptor < 0, errno == ENOENT {
            guard Darwin.mkdirat(parent, name, mode_t(0o700)) == 0 || errno == EEXIST,
                  Darwin.fsync(parent) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            descriptor = Darwin.openat(
                parent,
                name,
                O_RDONLY | O_DIRECTORY | O_NOFOLLOW
            )
        }
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        return descriptor
    }

    private static func regularFileSnapshot(
        descriptor: Int32,
        mismatchReason: StoreMigrationMaintenanceReasonV1
    ) throws -> RegularFileSnapshot {
        var information = stat()
        guard Darwin.fstat(descriptor, &information) == 0,
              (information.st_mode & S_IFMT) == S_IFREG,
              information.st_nlink == 1,
              information.st_size >= 0,
              information.st_size <= off_t(Int.max) else {
            throw StoreMigrationFailure.maintenanceRequired(mismatchReason)
        }
        return RegularFileSnapshot(
            device: information.st_dev,
            inode: information.st_ino,
            linkCount: information.st_nlink,
            type: information.st_mode & S_IFMT,
            byteCount: information.st_size,
            modificationSeconds: Int64(information.st_mtimespec.tv_sec),
            modificationNanoseconds: Int64(information.st_mtimespec.tv_nsec),
            statusChangeSeconds: Int64(information.st_ctimespec.tv_sec),
            statusChangeNanoseconds: Int64(information.st_ctimespec.tv_nsec)
        )
    }

    private static func namedRegularFileSnapshot(
        parent: Int32,
        name: String,
        mismatchReason: StoreMigrationMaintenanceReasonV1
    ) throws -> RegularFileSnapshot {
        try requireSafeBasename(name)
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_NONBLOCK | O_NOFOLLOW)
        guard descriptor >= 0 else {
            throw StoreMigrationFailure.maintenanceRequired(mismatchReason)
        }
        defer { _ = Darwin.close(descriptor) }
        return try regularFileSnapshot(
            descriptor: descriptor,
            mismatchReason: mismatchReason
        )
    }

    private static func streamedDigest(
        descriptor: Int32,
        expectedSnapshot: RegularFileSnapshot,
        mismatchReason: StoreMigrationMaintenanceReasonV1,
        cancellationCheck: () throws -> Void = {}
    ) throws -> StreamedFileDigest {
        try cancellationCheck()
        guard Darwin.lseek(descriptor, 0, SEEK_SET) == 0 else {
            throw StoreMigrationFailure.maintenanceRequired(mismatchReason)
        }
        var hasher = SHA256()
        var byteCount = 0
        var buffer = [UInt8](
            repeating: 0,
            count: migrationStreamBufferByteCount
        )
        while true {
            try cancellationCheck()
            let count = buffer.withUnsafeMutableBytes {
                Darwin.read(descriptor, $0.baseAddress, $0.count)
            }
            if count == 0 { break }
            guard count > 0 else {
                if errno == EINTR { continue }
                throw StoreMigrationFailure.maintenanceRequired(mismatchReason)
            }
            let (nextCount, overflow) = byteCount.addingReportingOverflow(count)
            guard !overflow, off_t(nextCount) <= expectedSnapshot.byteCount else {
                throw StoreMigrationFailure.maintenanceRequired(mismatchReason)
            }
            byteCount = nextCount
            hasher.update(data: Data(buffer.prefix(count)))
            try cancellationCheck()
        }
        guard byteCount == Int(expectedSnapshot.byteCount),
              try regularFileSnapshot(
                  descriptor: descriptor,
                  mismatchReason: mismatchReason
              ) == expectedSnapshot else {
            throw StoreMigrationFailure.maintenanceRequired(mismatchReason)
        }
        return StreamedFileDigest(
            byteCount: byteCount,
            sha256: hexDigest(hasher.finalize()),
            snapshot: expectedSnapshot
        )
    }

    private static func hexDigest(_ digest: SHA256.Digest) -> String {
        digest.map { String(format: "%02x", $0) }.joined()
    }

    fileprivate static func readRegularFileWithIdentity(
        parent: Int32,
        name: String
    ) throws -> RegularFileRead {
        try requireSafeBasename(name)
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        var before = stat()
        guard Darwin.fstat(descriptor, &before) == 0,
              (before.st_mode & S_IFMT) == S_IFREG,
              before.st_nlink == 1,
              before.st_size >= 0,
              before.st_size <= off_t(Self.maximumControlFileByteCount) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var data = Data()
        var buffer = [UInt8](repeating: 0, count: 16 * 1024)
        while true {
            let count = buffer.withUnsafeMutableBytes {
                Darwin.read(descriptor, $0.baseAddress, $0.count)
            }
            if count > 0 {
                data.append(contentsOf: buffer.prefix(count))
            } else if count == 0 {
                break
            } else if errno != EINTR {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        var after = stat()
        guard Darwin.fstat(descriptor, &after) == 0,
              (after.st_mode & S_IFMT) == S_IFREG,
              after.st_nlink == 1,
              before.st_dev == after.st_dev,
              before.st_ino == after.st_ino,
              before.st_size == after.st_size,
              data.count == Int(after.st_size) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return RegularFileRead(
            data: data,
            identity: RegularFileIdentity(
                device: after.st_dev,
                inode: after.st_ino,
                linkCount: after.st_nlink
            )
        )
    }

    fileprivate static func readRegularFile(
        parent: Int32,
        name: String
    ) throws -> Data {
        try readRegularFileWithIdentity(parent: parent, name: name).data
    }

    fileprivate static func createRegularFile(
        parent: Int32,
        name: String,
        data: Data
    ) throws {
        try requireSafeBasename(name)
        let descriptor = Darwin.openat(
            parent,
            name,
            O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW,
            mode_t(0o600)
        )
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        do {
            try data.withUnsafeBytes { raw in
                guard let base = raw.baseAddress else { return }
                var offset = 0
                while offset < raw.count {
                    let count = Darwin.write(
                        descriptor,
                        base.advanced(by: offset),
                        raw.count - offset
                    )
                    if count > 0 {
                        offset += count
                    } else if errno != EINTR {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
            }
            guard Darwin.fsync(descriptor) == 0,
                  Darwin.fsync(parent) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        } catch {
            _ = Darwin.unlinkat(parent, name, 0)
            _ = Darwin.fsync(parent)
            throw error
        }
    }

    private static func canonicalData<Value: Encodable>(_ value: Value) throws -> Data {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]
        return try encoder.encode(value)
    }

    private static func decodeCanonicalPointer<Value: Codable>(
        _ data: Data
    ) throws -> Value {
        do {
            let value = try JSONDecoder().decode(Value.self, from: data)
            guard try canonicalData(value) == data else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return value
        } catch let error as StoreGenerationFailure {
            throw error
        } catch {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    fileprivate static func decodeCanonicalPointer<Value: Codable>(
        parent: Int32,
        name: String
    ) throws -> Value {
        let captured = try readRegularFileWithIdentity(parent: parent, name: name)
        let value: Value = try decodeCanonicalPointer(captured.data)
        guard try regularFileIdentity(parent: parent, name: name) == captured.identity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return value
    }

    private static func identity(_ descriptor: Int32) throws -> Identity {
        var info = stat()
        guard Darwin.fstat(descriptor, &info) == 0,
              (info.st_mode & S_IFMT) == S_IFDIR else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return Identity(device: info.st_dev, inode: info.st_ino)
    }

    fileprivate static func regularFileIdentity(
        parent: Int32,
        name: String
    ) throws -> RegularFileIdentity {
        try requireSafeBasename(name)
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_NOFOLLOW)
        guard descriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.close(descriptor) }

        var before = stat()
        guard Darwin.fstat(descriptor, &before) == 0,
              (before.st_mode & S_IFMT) == S_IFREG,
              before.st_nlink == 1 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var after = stat()
        guard Darwin.fstat(descriptor, &after) == 0,
              (after.st_mode & S_IFMT) == S_IFREG,
              after.st_nlink == 1,
              before.st_dev == after.st_dev,
              before.st_ino == after.st_ino else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return RegularFileIdentity(
            device: after.st_dev,
            inode: after.st_ino,
            linkCount: after.st_nlink
        )
    }

    fileprivate static func regularFileIdentity(
        descriptor: Int32
    ) throws -> RegularFileIdentity {
        var before = stat()
        guard Darwin.fstat(descriptor, &before) == 0,
              (before.st_mode & S_IFMT) == S_IFREG,
              before.st_nlink == 1 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var after = stat()
        guard Darwin.fstat(descriptor, &after) == 0,
              (after.st_mode & S_IFMT) == S_IFREG,
              after.st_nlink == 1,
              before.st_dev == after.st_dev,
              before.st_ino == after.st_ino else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return RegularFileIdentity(
            device: after.st_dev,
            inode: after.st_ino,
            linkCount: after.st_nlink
        )
    }

    fileprivate static func regularFileIdentity(
        at url: URL
    ) throws -> RegularFileIdentity {
        let descriptor = Darwin.open(url.standardizedFileURL.path, O_RDONLY | O_NOFOLLOW)
        guard descriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.close(descriptor) }
        return try regularFileIdentity(descriptor: descriptor)
    }

    fileprivate static func directoryIdentity(
        at url: URL
    ) throws -> Identity {
        let descriptor = Darwin.open(
            url.standardizedFileURL.path,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.close(descriptor) }
        return try identity(descriptor)
    }

    fileprivate static func directoryIdentity(
        descriptor: Int32
    ) throws -> Identity {
        try identity(descriptor)
    }

    private static func require(_ descriptor: Int32, _ expected: Identity) throws {
        guard try identity(descriptor) == expected else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private static func currentURL(for descriptor: Int32) throws -> URL {
        var path = [CChar](repeating: 0, count: Int(MAXPATHLEN))
        let result = Darwin.fcntl(descriptor, F_GETPATH, &path)
        guard result >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let value = String(cString: path)
        guard !value.isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return URL(fileURLWithPath: value, isDirectory: true)
            .standardizedFileURL
    }

    private static func canonical(_ id: UUID) -> String {
        id.uuidString.lowercased()
    }

    private static func idOrder(_ lhs: UUID, _ rhs: UUID) -> Bool {
        canonical(lhs) < canonical(rhs)
    }
}

enum StoreGenerationPruneFaultBoundaryV1: String, CaseIterable, Equatable, Sendable {
    case prepared
    case bytesRemoved
    case retiredPointerPublished
    case receiptPublished
}

#if DEBUG
enum StoreGenerationPruneInjectedFailureV1: Error, Equatable {
    case injectedFault(StoreGenerationPruneFaultBoundaryV1)
}

final class StoreGenerationPruneFailureInjectionV1 {
    private var pending: StoreGenerationPruneFaultBoundaryV1?

    init(failOnceAt boundary: StoreGenerationPruneFaultBoundaryV1) {
        self.pending = boundary
    }

    func reach(_ boundary: StoreGenerationPruneFaultBoundaryV1) throws {
        guard pending == boundary else { return }
        pending = nil
        throw StoreGenerationPruneInjectedFailureV1.injectedFault(boundary)
    }
}
#endif

struct StoreGenerationFactory {
#if DEBUG
    enum OriginalErasePointerTestStageV1 {
        case semanticSessionProved
        case beforeFirstPointerEffect
    }

    @MainActor
    private final class OriginalErasePointerTestHookV1 {
        weak var operation: EraseRouterOperationV1?
        let support: URL
        let stage: OriginalErasePointerTestStageV1
        let callback: @MainActor (StoreGenerationSession?) throws -> Void

        init(operation: EraseRouterOperationV1, support: URL,
             stage: OriginalErasePointerTestStageV1,
             callback: @escaping @MainActor (StoreGenerationSession?) throws -> Void) {
            self.operation = operation
            self.support = support.standardizedFileURL
            self.stage = stage
            self.callback = callback
        }
    }

    @MainActor private static var originalErasePointerTestHook:
        OriginalErasePointerTestHookV1?

    @MainActor
    static func installOriginalErasePointerTestHook(
        operation: EraseRouterOperationV1, applicationSupportURL: URL,
        stage: OriginalErasePointerTestStageV1,
        callback: @escaping @MainActor (StoreGenerationSession?) throws -> Void
    ) throws {
        guard originalErasePointerTestHook == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        originalErasePointerTestHook = OriginalErasePointerTestHookV1(
            operation: operation, support: applicationSupportURL,
            stage: stage, callback: callback)
    }

    @MainActor
    static func clearOriginalErasePointerTestHook(
        operation: EraseRouterOperationV1
    ) {
        guard originalErasePointerTestHook?.operation === operation else { return }
        originalErasePointerTestHook = nil
    }

    @MainActor
    fileprivate static func fireOriginalErasePointerTestHook(
        operation: EraseRouterOperationV1, applicationSupportURL: URL,
        stage: OriginalErasePointerTestStageV1,
        session: StoreGenerationSession? = nil
    ) throws {
        guard let hook = originalErasePointerTestHook,
              hook.operation === operation,
              hook.support == applicationSupportURL.standardizedFileURL,
              hook.stage == stage else { return }
        originalErasePointerTestHook = nil
        try hook.callback(session)
    }
#endif

