        try authority.retiredIDsForEraseRetirementWithReservedTemporary(
            expected: expected, currentID: currentID, retirement: retirement)
    }

    /// Fixed noncreating current validation under the genuine retired-reader
    /// capability. No new registry or migration store is constructed here.
    @MainActor
    func currentGenerationIDForEraseRetirement(
        authority: StoreRestoreGenerationAuthority,
        retirement: ErasedRegistryRetirementProofV1,
        manifestScope: EraseCurrentManifestScopeV1
    ) throws -> UUID {
        try retirement.requireCurrentGenerationValidation()
        guard manifestScope.binding == retirement.binding,
              applicationSupportURL.standardizedFileURL
                == retirement.binding.subject.applicationSupportURL.standardizedFileURL else {
            throw EraseAllServiceError.invalidAuthority
        }
        let pointerData = try retirement.readPointer(using: authority, name: "current.json")
        let envelope = try CurrentPointerCodecV1.decode(pointerData)
        guard let current = UUID(uuidString: envelope.generationID),
              current == retirement.binding.subject.newGenerationID,
              envelope.data == manifestScope.pointerData,
              envelope.generationID == canonicalString(for: current) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        switch envelope {
        case .legacy:
            guard manifestScope.store == nil else { throw EraseAllServiceError.invalidAuthority }
        case .v2(let pointer, _):
            guard let store = manifestScope.store else { throw EraseAllServiceError.invalidAuthority }
            try pointer.validate()
            let manifest = try retirement.readCurrentManifest(using: store,
                generationID: current, expectedDigest: pointer.generationManifestSHA256)
            guard manifest.generationID == current, manifest.storeSchemaRelease == .v2 else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        case .v3(let pointer, _):
            guard let store = manifestScope.store else { throw EraseAllServiceError.invalidAuthority }
            try pointer.validate()
            let manifest = try retirement.readCurrentManifest(using: store,
                generationID: current, expectedDigest: pointer.generationManifestSHA256)
            guard let expectedRelease = PersistentSchemaReleaseRegistryV1.releases.first(where: {
                $0.versionIdentifier.major == pointer.storeSchemaVersion
            }) else {
                throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
            }
            guard manifest.generationID == current,
                  manifest.storeSchemaRelease == expectedRelease else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        }
        try retirement.requireCurrentGenerationValidation()
        return current
    }

    @MainActor
    func currentGenerationID() throws -> UUID {
        let authority = try makeRestoreGenerationAuthority()
        return try currentGenerationID(authority: authority)
    }

    @MainActor
    func currentGenerationID(
        authority: StoreRestoreGenerationAuthority
    ) throws -> UUID {
        let authorityValue = try authority.currentGenerationID()
        let envelope = try decodeCurrentPointer(
            at: dataRootURL.appendingPathComponent(Self.currentPointerName)
        )
        switch envelope {
        case .legacy(let pointer, _):
            guard canonicalUUID(from: pointer.generationID) == authorityValue else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        case .v2(let pointer, _):
            guard canonicalUUID(from: pointer.generationID) == authorityValue else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            _ = try requireCurrentManifest(pointer)
        case .v3(let pointer, _):
            guard canonicalUUID(from: pointer.generationID) == authorityValue else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            _ = try requireCurrentManifest(pointer)
        }
        return authorityValue
    }

    @MainActor
    func currentWorkspaceIdentity(
        expectedGenerationID: UUID,
        authority suppliedAuthority: StoreRestoreGenerationAuthority? = nil
    ) throws -> WorkspaceReplicaIdentityV1 {
        let pointer = try currentGenerationPointerV3(
            expectedGenerationID: expectedGenerationID,
            authority: suppliedAuthority
        )
        return try pointer.identity()
    }

    @MainActor
    func currentGenerationPointerV3(
        expectedGenerationID: UUID,
        authority suppliedAuthority: StoreRestoreGenerationAuthority? = nil
    ) throws -> CurrentGenerationPointerV3 {
        let authority: StoreRestoreGenerationAuthority
        if let suppliedAuthority {
            authority = suppliedAuthority
        } else {
            authority = try makeRestoreGenerationAuthority()
        }
        guard try authority.currentGenerationID() == expectedGenerationID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        guard case .v3(let pointer, _) = try decodeCurrentPointer(
                  at: dataRootURL.appendingPathComponent(Self.currentPointerName)
              ), canonicalUUID(from: pointer.generationID) == expectedGenerationID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try requireCurrentManifest(pointer)
        return pointer
    }

    @MainActor
    func currentGenerationDeletionLedgerProof(
        expectedPointer: RestorePointerIdentityV1,
        authority: StoreRestoreGenerationAuthority,
        observeManifest: ((StoreGenerationManifestV1) -> Void)? = nil,
        observeSourceTreeStage: (@MainActor (String) -> Void)? = nil
    ) throws -> DeletionLedgerProofV2 {
#if DEBUG
        observeSourceTreeStage?("before-pointer")
#endif
        let pointer = try requireCurrentPointer(expectedPointer, authority: authority)
#if DEBUG
        observeSourceTreeStage?("after-pointer")
#endif
        let session = try openValidatedV3Current(
            pointer: pointer,
            dataRootURL: dataRootURL,
            store: StoreMigrationJournalStoreV1(applicationSupportURL: applicationSupportURL),
            observeManifest: observeManifest,
            observeSourceTreeStage: observeSourceTreeStage
        )
#if DEBUG
        coldOpenDiagnostic("current-ledger.open-complete")
#endif
        let proof = try deletionLedgerProof(in: session.modelContext)
#if DEBUG
        observeSourceTreeStage?("after-ledger")
#endif
#if DEBUG
        coldOpenDiagnostic("current-ledger.proof-complete")
#endif
        return proof
    }

    /// Re-read the already admitted old writer's semantic ledger while the
    /// original Erase operation retains EX. Opening the current generation
    /// here would allocate a second reader through ordinary temporal
    /// registration, which cannot run under that exclusive owner.
    @MainActor
    func requireOriginalEraseRetainedSourceLedger(
        intent: EraseIntentV1,
        coordinator: StoreSessionCoordinator,
        authority: StoreRestoreGenerationAuthority
    ) throws {
        guard let oldPointer = intent.oldPointer,
              let expected = intent.sourceLedger,
              coordinator.generationID == intent.oldGenerationID,
              coordinator.generationRootURL.standardizedFileURL
                == installedGenerationURL(id: intent.oldGenerationID),
              !coordinator.modelContext.hasChanges else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try requireCurrentPointer(oldPointer, authority: authority)
        guard try deletionLedgerProof(in: coordinator.modelContext) == expected else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    /// The original target-reader publisher calls this through Router while
    /// its retained activity holds G. Compare exact canonical current bytes,
    /// not only the target epoch or generation ID.
    @MainActor
    func requireOriginalEraseCurrentPointerBytes(
        _ expectedData: Data,
        identity: RestorePointerIdentityV1,
        authority: StoreRestoreGenerationAuthority
    ) throws {
        let current = try requireCurrentPointer(identity,
            authority: authority)
        guard try current.canonicalData() == expectedData else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    @MainActor
    func prepareErasePreparationDiscard(
        expectedOldPointer: RestorePointerIdentityV1,
        targetGenerationID: UUID,
        targetIdentity: WorkspaceReplicaIdentityV1,
        expectedEmptyLedger: DeletionLedgerProofV2,
        authority: StoreRestoreGenerationAuthority,
        coldOperation: EraseColdPreparationOperationV1? = nil,
        diagnosticPhase: (@MainActor (String) -> Void)? = nil
    ) throws -> ErasePreparedGenerationDiscardV1 {
        diagnosticPhase?("discard.expected-ledger")
        try expectedEmptyLedger.validate()
        diagnosticPhase?("discard.current-pointer")
        let old = try requireCurrentPointer(expectedOldPointer, authority: authority)
        let oldIdentityValues = Set(
            [
                expectedOldPointer.workspaceID,
                expectedOldPointer.replicaID,
            ] + expectedOldPointer.knownReplicaIDs
        )
        let forbidden = Set(
            [
                expectedOldPointer.generationID,
                expectedOldPointer.workspaceID,
                expectedOldPointer.replicaID,
                targetGenerationID,
            ] + expectedOldPointer.knownReplicaIDs
        )
        let activeRelease = PersistentSchemaReleaseRegistryV1.activeRelease
        let activeSchemaVersion = PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major
        diagnosticPhase?("discard.identity")
        guard old.storeSchemaVersion == activeSchemaVersion,
              expectedEmptyLedger.entryCount == 0,
              targetGenerationID != expectedOldPointer.generationID,
              !oldIdentityValues.contains(targetGenerationID),
              targetIdentity.workspaceID.rawValue != targetIdentity.replicaID.rawValue,
              !forbidden.contains(targetIdentity.workspaceID.rawValue),
              !forbidden.contains(targetIdentity.replicaID.rawValue) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        diagnosticPhase?("discard.restore-journal")
        try authority.requireNoRestoreJournal()

        diagnosticPhase?("discard.inventory")
        let retired = try authority.retiredGenerationIDs()
        guard !retired.contains(targetGenerationID),
              try authority.restoreGenerationNames().isEmpty,
              try authority.importStagingNames().isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let expectedNames = Set(
            ([expectedOldPointer.generationID] + retired).map {
                canonicalString(for: $0)
            }
        )
        let actualNames = Set(try authority.installedGenerationNames())
        let targetName = canonicalString(for: targetGenerationID)
        guard actualNames == expectedNames
                || actualNames == expectedNames.union([targetName]) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let presence = try authority.presence(id: targetGenerationID)
        guard !presence.staging,
              presence.installed == actualNames.contains(targetName) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }

        let store = try StoreMigrationJournalStoreV1(
            applicationSupportURL: applicationSupportURL
        )
        guard presence.installed else {
            guard try store.loadManifestIfPresent(
                targetGenerationID: targetGenerationID
            ) == nil else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            _ = try requireCurrentPointer(expectedOldPointer, authority: authority)
            return ErasePreparedGenerationDiscardV1(expectedOldPointer: expectedOldPointer,
            targetGenerationID: targetGenerationID, targetIdentity: targetIdentity,
            expectedEmptyLedger: expectedEmptyLedger, authority: authority,
            expectedNames: expectedNames, store: store,
            targetRootIdentity: presence.installed
                ? try ReportPDFAnchoredFile.rootIdentity(at: installedGenerationURL(id: targetGenerationID)) : nil)
        }

        diagnosticPhase?("discard.open-target")
        let root = installedGenerationURL(id: targetGenerationID)
#if DEBUG
        if diagnosticPhase != nil {
            observeEraseFileSnapshot(
                generationID: targetGenerationID,
                at: root,
                stage: .beforeTargetOpen,
                manifestObservation: .notLoaded,
                expectedFiles: nil,
                diagnosticPhase: diagnosticPhase
            )
        }
#endif
        func requireSemanticEmptyTarget(_ session: StoreGenerationSession) throws {
            diagnosticPhase?("discard.marker")
            let marker = try session.modelContext.fetch(
                FetchDescriptor<PersistentSchemaReleaseMarker>()
            )
            guard marker.count == 1,
                  marker.first?.schemaVersion == activeSchemaVersion,
                  marker.first?.releaseID
                    == activeRelease.compatibilityID,
                   marker.first?.migrationID == targetGenerationID else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            diagnosticPhase?("discard.empty-content")
            guard BackupRestoreService.isEmptyCurrent(session.modelContext) else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            diagnosticPhase?("discard.empty-ledger")
            guard try deletionLedgerProof(in: session.modelContext) == expectedEmptyLedger else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        }

        // The cold route binds physical bytes around the exact semantic read
        // while the same Registry G excludes another app writer. It repeats
        // after the actual connection has left its autoreleasepool. A byte
        // change during validation or close is an unresolved target.
        let targetSnapshot: ErasePreparedTargetSnapshotV1?
        if let coldOperation {
            try coldOperation.requireServiceAccess()
            let registry = try makeGenerationLeaseRegistry()
            guard authority.mutationRegistry === registry else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            targetSnapshot = try registry.withNoMigrationReservation {
                try coldOperation.requireServiceAccess()
                // Bind the bytes before the semantic read, through the read,
                // and after the actual connection closes. Any drift fails
                // this attempt; a retry must not adopt a newly changed tree.
                let observed = try autoreleasepool { () throws
                    -> (before: ErasePreparedTargetSnapshotV1,
                        after: ErasePreparedTargetSnapshotV1) in
                    let session = try openGeneration(id: targetGenerationID,
                        at: root, identity: targetIdentity)
                    let before = try authority.snapshotErasePreparedTarget(id: targetGenerationID)
                    try requireSemanticEmptyTarget(session)
                    let after = try authority.snapshotErasePreparedTarget(id: targetGenerationID)
                    return (before, after)
                }
                let closed = try authority.snapshotErasePreparedTarget(id: targetGenerationID)
                guard observed.before == observed.after, observed.after == closed else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                return closed
            }
        } else {
            // Original-operation validation retains its existing scope.
            try autoreleasepool {
                let session = try openGeneration(id: targetGenerationID,
                    at: root, identity: targetIdentity)
                try requireSemanticEmptyTarget(session)
            }
            targetSnapshot = nil
        }

        return ErasePreparedGenerationDiscardV1(expectedOldPointer: expectedOldPointer,
            targetGenerationID: targetGenerationID, targetIdentity: targetIdentity,
            expectedEmptyLedger: expectedEmptyLedger, authority: authority,
            expectedNames: expectedNames, store: store,
            targetRootIdentity: presence.installed
                ? try ReportPDFAnchoredFile.rootIdentity(at: installedGenerationURL(id: targetGenerationID)) : nil,
            targetSnapshot: targetSnapshot)
    }

    @MainActor
    func completeColdErasePreparationDiscard(_ validation: ErasePreparedGenerationDiscardV1,
        sourceLedger: DeletionLedgerProofV2, operation: EraseColdPreparationOperationV1) throws {
        try operation.requireRollbackRemoval(validation, factory: self)
        let expectedOldPointer = validation.expectedOldPointer
        let targetGenerationID = validation.targetGenerationID
        let authority = validation.authority
        let expectedNames = validation.expectedNames
        let store = validation.store
        let activeRelease = PersistentSchemaReleaseRegistryV1.activeRelease
        let root = installedGenerationURL(id: targetGenerationID)
        let diagnosticPhase: (@MainActor (String) -> Void)? = nil
        let registry = try makeGenerationLeaseRegistry()
        guard authority.mutationRegistry === registry else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try registry.withNoMigrationReservation {
            try operation.requireRollbackRemoval(validation, factory: self)
            // The actual source reader is captured by this SAME provider and
            // cold operation while G excludes writer acquisition/mutation.
            // Do not reuse a ledger observed before the target cohort drained.
            guard try currentGenerationDeletionLedgerProof(expectedPointer: expectedOldPointer,
                authority: authority) == sourceLedger else { throw StoreGenerationFailure.dataPointerInvalid }
            guard try !registry.activeEpochs().contains(where: { $0.generationID == targetGenerationID }) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            _ = try requireCurrentPointer(expectedOldPointer, authority: authority)
            let names = Set(try authority.installedGenerationNames())
            let presence = try authority.presence(id: targetGenerationID)
            guard !presence.staging,
                  names == expectedNames || names == expectedNames.union([canonicalString(for: targetGenerationID)]),
                  presence.installed == names.contains(canonicalString(for: targetGenerationID)) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if presence.installed {
                guard let expectedRoot = validation.targetRootIdentity,
                      try ReportPDFAnchoredFile.rootIdentity(at: root) == expectedRoot else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            if !presence.installed {
                guard validation.targetRootIdentity == nil || validation.removalStarted else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                guard try store.loadManifestIfPresent(targetGenerationID: targetGenerationID) == nil,
                      names == expectedNames else { throw StoreGenerationFailure.dataPointerInvalid }
                return
            }
            guard let snapshot = validation.targetSnapshot else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let currentTarget = try authority.snapshotErasePreparedTarget(
                id: targetGenerationID, partialCleanup: validation.removalStarted)
            try snapshot.requireCurrent(currentTarget, removalStarted: validation.removalStarted)
            diagnosticPhase?("discard.manifest-load")
            if let prepared = try store.loadManifestIfPresent(
                targetGenerationID: targetGenerationID
            ) {
                diagnosticPhase?("discard.manifest-identity")
                guard prepared.manifest.generationID == targetGenerationID,
                      prepared.manifest.predecessorGenerationID
                        == expectedOldPointer.generationID,
                      prepared.manifest.storeSchemaRelease == activeRelease,
                      prepared.manifest.migrationID == targetGenerationID else {
                    throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                }
                diagnosticPhase?("discard.manifest-snapshot")
                try requireRestoreManifestSnapshot(
                    prepared.manifest,
                    expectedOldID: expectedOldPointer.generationID,
                    generationID: targetGenerationID,
                    at: root,
                    staging: false,
                    diagnosticPhase: diagnosticPhase
                )
                diagnosticPhase?("discard.remove-manifest")
                validation.removalStarted = true
                try removePreparedRestoreGenerationManifestBeforeDiscard(
                    expectedOldID: expectedOldPointer.generationID,
                    generationID: targetGenerationID,
                    expectedDigest: prepared.digest,
                    authority: authority
                )
            }
    
            diagnosticPhase?("discard.final-current-pointer")
            _ = try requireCurrentPointer(expectedOldPointer, authority: authority)
            diagnosticPhase?("discard.remove-target")
            validation.removalStarted = true
            try authority.removeInstalledGeneration(id: targetGenerationID)
            diagnosticPhase?("discard.final-presence")
            let finalPresence = try authority.presence(id: targetGenerationID)
            guard !finalPresence.staging,
                  !finalPresence.installed,
                  Set(try authority.installedGenerationNames()) == expectedNames,
                  try store.loadManifestIfPresent(
                    targetGenerationID: targetGenerationID
                  ) == nil else {
                throw StoreMigrationFailure.maintenanceRequired(.forwardFixRequired)
            }
            _ = try requireCurrentPointer(expectedOldPointer, authority: authority)
        }
    }

    @MainActor
    func createEmptyEraseGeneration(
        id: UUID,
        expectedOldPointer: RestorePointerIdentityV1,
        identity: WorkspaceReplicaIdentityV1,
        authority: StoreRestoreGenerationAuthority
    ) throws -> (pointer: RestorePointerIdentityV1, ledgerProof: DeletionLedgerProofV2) {
        _ = try requireCurrentPointer(expectedOldPointer, authority: authority)
        try createEmptyInstalledGeneration(id: id, authority: authority)
        // Finish the empty store's connection lifetime before sealing physical
        // database/WAL/SHM bytes. Closing a live connection can change those bytes.
        let proof: DeletionLedgerProofV2 = try autoreleasepool {
            let session = try openGeneration(
                id: id,
                at: installedGenerationURL(id: id),
                identity: identity
            )
            // Finalize journal state before sealing the physical database files.
            // Even a logically empty reset can write SQLite pages.
            try MutationJournalStoreV1(
                modelContext: session.modelContext,
                identity: identity,
                generationID: id
            ).clearForErase(
                expectedWorkspaceID: identity.workspaceID,
                expectedGenerationID: id
            )
            let proof = try deletionLedgerProof(in: session.modelContext)
            guard proof.entryCount == 0 else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            return proof
        }
        let prepared = try makeRestoreCurrentPointer(
            expectedOldID: expectedOldPointer.generationID,
            newID: id
        )
        let pointer = try CurrentGenerationPointerV3(
            generationID: id,
            generationManifestSHA256: prepared.generationManifestSHA256,
            workspaceID: identity.workspaceID,
            replicaID: identity.replicaID,
            knownReplicaIDs: [identity.replicaID],
            storeSchemaVersion: PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major
        )
        _ = try requireCurrentPointer(expectedOldPointer, authority: authority)
        return (try restorePointerIdentity(pointer), proof)
    }

    @MainActor
    func publishEmptyEraseGeneration(
        expectedOldPointer: RestorePointerIdentityV1,
        targetPointer: RestorePointerIdentityV1,
        expectedEmptyLedger: DeletionLedgerProofV2,
        authority: StoreRestoreGenerationAuthority
    ) throws {
        try expectedEmptyLedger.validate()
        guard expectedOldPointer.generationID != targetPointer.generationID,
              expectedEmptyLedger.entryCount == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let old = try requireCurrentPointer(expectedOldPointer, authority: authority)
        let target = try currentPointer(from: targetPointer)
        _ = try requireCurrentManifest(target)
        let session = try openGeneration(
            id: targetPointer.generationID,
            at: installedGenerationURL(id: targetPointer.generationID),
            identity: try target.identity()
        )
        guard try deletionLedgerProof(in: session.modelContext) == expectedEmptyLedger else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        let registry = try makeGenerationLeaseRegistry()
        try registry.withNoMigrationReservation {
            try authority.switchCurrentGeneration(
                expected: expectedOldPointer.generationID,
                to: targetPointer.generationID,
                pointer: target,
                expectedCurrentPointer: old
            )
        }
    }

    /// Same physical and semantic target preflight as the ordinary publisher,
    /// followed by the original operation's retained EX/G. The Router latches
    /// this exact current-pointer effect before the first mutable call.
    @MainActor
    func publishEmptyEraseGenerationForOriginalRetainedExclusion(
        expectedOldPointer: RestorePointerIdentityV1,
        targetPointer: RestorePointerIdentityV1,
        expectedEmptyLedger: DeletionLedgerProofV2,
        authority: StoreRestoreGenerationAuthority,
        intent: EraseIntentV1,
        store: EraseIntentStore,
        operation: EraseRouterOperationV1
    ) throws {
        try expectedEmptyLedger.validate()
        guard intent.oldPointer == expectedOldPointer,
              intent.targetPointer == targetPointer,
              intent.targetEmptyProof == EraseEmptyGenerationProofV2(
                contentRecordCount: 0, deletionLedgerEntryCount: 0),
              expectedOldPointer.generationID != targetPointer.generationID,
              expectedEmptyLedger.entryCount == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let old = try requireCurrentPointer(expectedOldPointer,
            authority: authority)
        let target = try currentPointer(from: targetPointer)
        _ = try requireCurrentManifest(target)
        let registry = try makeGenerationLeaseRegistry()
        guard authority.mutationRegistry === registry else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let activity = try operation.beginOriginalEraseRetainedPointerEffect(
            .current, intent: intent, store: store, registry: registry)
        do {
            // A ModelContainer may update its private target SQLite SHM on
            // release. Finish that owned semantic preflight before the first
            // Data sibling image is captured by the pointer publisher. The
            // Router's one-way pointer latch is already retained if an open,
            // ledger proof, or alias drain fails.
            let drain = try autoreleasepool {
                () throws -> OriginalEraseTargetPreflightDrainV1 in
                let session = try openGeneration(
                    id: targetPointer.generationID,
                    at: installedGenerationURL(id: targetPointer.generationID),
                    identity: try target.identity())
                let observation = try OriginalEraseTargetPreflightDrainV1(
                    session: session)
                guard try deletionLedgerProof(in: session.modelContext)
                        == expectedEmptyLedger else {
                    throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                }
                #if DEBUG
                try Self.fireOriginalErasePointerTestHook(
                    operation: operation,
                    applicationSupportURL: applicationSupportURL,
                    stage: .semanticSessionProved, session: session)
                #endif
                return observation
            }
            try drain.requireDrained()
            let priorRetired = intent.generationIDsToDelete
                .filter { $0 != intent.oldGenerationID }
            var issued: StoreRestoreGenerationAuthority
                .OriginalErasePointerReceiptV1?
            try registry.withOriginalEraseRetainedPointerEffect(
                stage: .current, intent: intent, activity: activity,
                operation: operation, store: store) {
                issued = try authority.publishOriginalEraseCurrentPointer(
                    expectedOldID: expectedOldPointer.generationID,
                    targetID: targetPointer.generationID,
                    expectedCurrent: old,
                    replacementCurrent: target,
                    priorRetiredIDs: priorRetired,
                    operation: operation)
            }
            guard let issued else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try issued.requireBound(authority: authority,
                operation: operation, stage: .current, predecessor: nil)
            guard issued.published.data == (try target.canonicalData()) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try operation.finishOriginalEraseRetainedPointerEffect(
                .current, receipt: issued, authority: authority)
        } catch {
            operation.failOriginalEraseRetainedPointerEffect()
            throw error
        }
    }

    @MainActor
    func requirePublishedEmptyEraseGeneration(
        oldPointer: RestorePointerIdentityV1,
        targetPointer: RestorePointerIdentityV1,
        expectedEmptyLedger: DeletionLedgerProofV2,
        authority: StoreRestoreGenerationAuthority,
        originalRetainedEraseOperation: EraseRouterOperationV1? = nil
    ) throws -> StoreGenerationSession {
        do {
        try expectedEmptyLedger.validate()
        guard oldPointer.generationID != targetPointer.generationID,
              expectedEmptyLedger.entryCount == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        #if DEBUG
        if originalRetainedEraseOperation != nil {
            FileHandle.standardError.write(Data("V23_ORIGINAL_READER_DIAG stage=published.pointer-enter\n".utf8))
        }
        #endif
        let pointer = try requireCurrentPointer(targetPointer, authority: authority)
        #if DEBUG
        if originalRetainedEraseOperation != nil {
            FileHandle.standardError.write(Data("V23_ORIGINAL_READER_DIAG stage=published.pointer-complete\n".utf8))
        }
        #endif
        #if DEBUG
        if originalRetainedEraseOperation != nil {
            FileHandle.standardError.write(Data("V23_ORIGINAL_READER_DIAG stage=published.open-enter\n".utf8))
        }
        #endif
        let session = try openValidatedV3Current(
            pointer: pointer,
            dataRootURL: dataRootURL,
            store: StoreMigrationJournalStoreV1(applicationSupportURL: applicationSupportURL),
            originalRetainedEraseOperation: originalRetainedEraseOperation,
            originalRetainedEraseAuthority: authority
        )
        #if DEBUG
        if originalRetainedEraseOperation != nil {
            FileHandle.standardError.write(Data("V23_ORIGINAL_READER_DIAG stage=published.open-complete\n".utf8))
        }
        #endif
        guard try deletionLedgerProof(in: session.modelContext) == expectedEmptyLedger else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        #if DEBUG
        if originalRetainedEraseOperation != nil {
            FileHandle.standardError.write(Data("V23_ORIGINAL_READER_DIAG stage=published.ledger-complete\n".utf8))
        }
        #endif
        return session
        } catch {
#if DEBUG
            if originalRetainedEraseOperation != nil {
                let family: String
                if error is GenerationLeaseRegistryFailureV1 { family = "registry" }
                else if error is StoreMigrationFailure { family = "migration" }
                else if error is StoreGenerationFailure { family = "generation" }
                else if error is ProtectedFilePolicyError { family = "policy" }
                else { family = "other" }
                FileHandle.standardError.write(Data(
                    ("V23_ORIGINAL_READER_DIAG stage=published.failure family="
                     + family + "\n").utf8))
            }
#endif
            throw error
        }
    }

    @MainActor
    func discardPreparedEmptyEraseGeneration(
        expectedOldPointer: RestorePointerIdentityV1,
        targetGenerationID: UUID,
        targetIdentity: WorkspaceReplicaIdentityV1,
        expectedEmptyLedger: DeletionLedgerProofV2,
        authority: StoreRestoreGenerationAuthority,
        diagnosticPhase: (@MainActor (String) -> Void)? = nil,
        reproveBeforeDestructiveEffect: (@MainActor () throws -> Void)? = nil
    ) throws {
        diagnosticPhase?("discard.expected-ledger")
        try expectedEmptyLedger.validate()
        diagnosticPhase?("discard.current-pointer")
        let old = try requireCurrentPointer(expectedOldPointer, authority: authority)
        let oldIdentityValues = Set(
            [
                expectedOldPointer.workspaceID,
                expectedOldPointer.replicaID,
            ] + expectedOldPointer.knownReplicaIDs
        )
        let forbidden = Set(
            [
                expectedOldPointer.generationID,
                expectedOldPointer.workspaceID,
                expectedOldPointer.replicaID,
                targetGenerationID,
            ] + expectedOldPointer.knownReplicaIDs
        )
        let activeRelease = PersistentSchemaReleaseRegistryV1.activeRelease
        let activeSchemaVersion = PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major
        diagnosticPhase?("discard.identity")
        guard old.storeSchemaVersion == activeSchemaVersion,
              expectedEmptyLedger.entryCount == 0,
              targetGenerationID != expectedOldPointer.generationID,
              !oldIdentityValues.contains(targetGenerationID),
              targetIdentity.workspaceID.rawValue != targetIdentity.replicaID.rawValue,
              !forbidden.contains(targetIdentity.workspaceID.rawValue),
              !forbidden.contains(targetIdentity.replicaID.rawValue) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        diagnosticPhase?("discard.restore-journal")
        try authority.requireNoRestoreJournal()

        diagnosticPhase?("discard.inventory")
        let retired = try authority.retiredGenerationIDs()
        guard !retired.contains(targetGenerationID),
              try authority.restoreGenerationNames().isEmpty,
              try authority.importStagingNames().isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let expectedNames = Set(
            ([expectedOldPointer.generationID] + retired).map {
                canonicalString(for: $0)
            }
        )
        let actualNames = Set(try authority.installedGenerationNames())
        let targetName = canonicalString(for: targetGenerationID)
        guard actualNames == expectedNames
                || actualNames == expectedNames.union([targetName]) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let presence = try authority.presence(id: targetGenerationID)
        guard !presence.staging,
              presence.installed == actualNames.contains(targetName) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }

        let store = try StoreMigrationJournalStoreV1(
            applicationSupportURL: applicationSupportURL
        )
        guard presence.installed else {
            guard try store.loadManifestIfPresent(
                targetGenerationID: targetGenerationID
            ) == nil else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            _ = try requireCurrentPointer(expectedOldPointer, authority: authority)
            return
        }

        diagnosticPhase?("discard.open-target")
        let root = installedGenerationURL(id: targetGenerationID)
#if DEBUG
        if diagnosticPhase != nil {
            observeEraseFileSnapshot(
                generationID: targetGenerationID,
                at: root,
                stage: .beforeTargetOpen,
                manifestObservation: .notLoaded,
                expectedFiles: nil,
                diagnosticPhase: diagnosticPhase
            )
        }
#endif
        // Do not keep this verification connection alive across the manifest's
        // physical file check or the eventual target removal.
        try autoreleasepool {
            let session = try openGeneration(
                id: targetGenerationID,
                at: root,
                identity: targetIdentity
            )
            diagnosticPhase?("discard.marker")
            let marker = try session.modelContext.fetch(
                FetchDescriptor<PersistentSchemaReleaseMarker>()
            )
            guard marker.count == 1,
                  marker.first?.schemaVersion == activeSchemaVersion,
                  marker.first?.releaseID
                    == activeRelease.compatibilityID,
                   marker.first?.migrationID == targetGenerationID else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            diagnosticPhase?("discard.empty-content")
            guard BackupRestoreService.isEmptyCurrent(session.modelContext) else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            diagnosticPhase?("discard.empty-ledger")
            guard try deletionLedgerProof(in: session.modelContext) == expectedEmptyLedger else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        }

        let registry = try makeGenerationLeaseRegistry()
        let sourceEpoch = try GenerationEpochV1(
            generationID: expectedOldPointer.generationID,
            generationManifestSHA256: expectedOldPointer.generationManifestSHA256
        )
        // One genuine registry exclusion spans both destructive steps. The
        // original source readers may remain live, but no target/unknown
        // allocation or weak target session may authorize manifest removal.
        try registry.withNoMigrationReservation {
            try reproveBeforeDestructiveEffect?()
            try eraseReaderRetirementInventory?.requireSourceOnlyPreparationForAbort(
                sourceEpoch: sourceEpoch, registry: registry)
            guard try !registry.activeEpochs().contains(where: {
                $0.generationID == targetGenerationID
            }) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            diagnosticPhase?("discard.manifest-load")
            if let prepared = try store.loadManifestIfPresent(
                targetGenerationID: targetGenerationID
            ) {
                diagnosticPhase?("discard.manifest-identity")
                guard prepared.manifest.generationID == targetGenerationID,
                      prepared.manifest.predecessorGenerationID
                        == expectedOldPointer.generationID,
                      prepared.manifest.storeSchemaRelease == activeRelease,
                      prepared.manifest.migrationID == targetGenerationID else {
                    throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                }
                diagnosticPhase?("discard.manifest-snapshot")
                try requireRestoreManifestSnapshot(
                    prepared.manifest,
                    expectedOldID: expectedOldPointer.generationID,
                    generationID: targetGenerationID,
                    at: root,
                    staging: false,
                    diagnosticPhase: diagnosticPhase
                )
                diagnosticPhase?("discard.remove-manifest")
                try reproveBeforeDestructiveEffect?()
                try removePreparedRestoreGenerationManifestBeforeDiscard(
                    expectedOldID: expectedOldPointer.generationID,
                    generationID: targetGenerationID,
                    expectedDigest: prepared.digest,
                    authority: authority
                )
            }

            diagnosticPhase?("discard.final-current-pointer")
            _ = try requireCurrentPointer(expectedOldPointer, authority: authority)
            diagnosticPhase?("discard.remove-target")
            try eraseReaderRetirementInventory?.requireSourceOnlyPreparationForAbort(
                sourceEpoch: sourceEpoch, registry: registry)
            guard try !registry.activeEpochs().contains(where: {
                $0.generationID == targetGenerationID
            }) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try reproveBeforeDestructiveEffect?()
            try authority.removeInstalledGeneration(id: targetGenerationID)
        }
        diagnosticPhase?("discard.final-presence")
        let finalPresence = try authority.presence(id: targetGenerationID)
        guard !finalPresence.staging,
              !finalPresence.installed,
              Set(try authority.installedGenerationNames()) == expectedNames,
              try store.loadManifestIfPresent(
                targetGenerationID: targetGenerationID
              ) == nil else {
            throw StoreMigrationFailure.maintenanceRequired(.forwardFixRequired)
        }
        _ = try requireCurrentPointer(expectedOldPointer, authority: authority)
    }

    @MainActor
    private func deletionLedgerProof(
        in context: ModelContext
    ) throws -> DeletionLedgerProofV2 {
        let ledger = try DeletionLedgerStore(context: context).snapshot()
        return try DeletionLedgerProofV2(
            entryCount: ledger.entries.count,
            canonicalSHA256: StoreMigrationCanonicalJSONV1.sha256(
                try ledger.canonicalData()
            )
        )
    }

    /// Original Erase recovery validates a private copy while its actual
    /// Registry G and Support EX remain held by the original ticket owner.
    /// The copy's context/container must drain before the checked scratch
    /// directory is released or the original source is re-proved.
    @MainActor
    func withOriginalEraseRecoveryPrivateSource<Value>(
        owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
        authority: StoreRestoreGenerationAuthority,
        generationID: UUID,
        treeDigest: String,
        migrationID: UUID,
        operationID: UUID,
        diagnosticPhase: (@MainActor (String) -> Void)? = nil,
        onCheckedScratchSettlement: (@MainActor (
            ScratchDataLeaseStoreV1.OriginalEraseExclusiveSourceReadReceiptV1
        ) -> Void)? = nil,
        _ validate: (ModelContext, URL) throws -> Value
    ) throws -> Value {
#if DEBUG
        diagnosticPhase?("recovery.original.old.factory.owner-enter")
#endif
        try owner.requireObservationUnchanged()
#if DEBUG
        diagnosticPhase?("recovery.original.old.factory.owner-complete")
        diagnosticPhase?("recovery.original.old.factory.files-enter")
#endif
        let files = try authority.originalRecoverySQLiteFiles(
            id: generationID, treeDigest: treeDigest)
#if DEBUG
        diagnosticPhase?("recovery.original.old.factory.files-complete")
        diagnosticPhase?("recovery.original.old.factory.request-enter")
#endif
        var requested: UInt64 = 0
        for file in files {
            let (sum, overflow) = requested.addingReportingOverflow(file.byteCount)
            guard !overflow else { throw ScratchDataLeaseStoreFailureV1.sizeLimitExceeded }
            requested = sum
        }
        if !files.contains(where: { $0.name == "model.sqlite-shm" }) {
            let wal = files.first(where: { $0.name == "model.sqlite-wal" })?.byteCount ?? 0
            let (sum, overflow) = requested.addingReportingOverflow(max(32_768, wal))
            guard !overflow else { throw ScratchDataLeaseStoreFailureV1.sizeLimitExceeded }
            requested = sum
        }
        guard requested > 0,
              requested <= ScratchDataPurposeV1.source.maximumByteCount else {
            throw ScratchDataLeaseStoreFailureV1.sizeLimitExceeded
        }
        let now = Date()
        let request = try ScratchDataLeaseRequestV1(
            leaseID: UUID(), purpose: .source, owner: .source,
            ownerOperationID: operationID, requestedByteCount: requested,
            createdAt: now, expiresAt: now.addingTimeInterval(
                ScratchDataPurposeV1.source.maximumLifetimeSeconds))
#if DEBUG
        diagnosticPhase?("recovery.original.old.factory.request-complete")
#endif
        weak var retainedContainer: ModelContainer?
        weak var retainedContext: ModelContext?
        var constructionAttempted = false
        var constructionSettled = false
#if DEBUG
        diagnosticPhase?("recovery.original.old.factory.scratch-enter")
#endif
        let value = try owner.withExclusiveSourceScratch { permit in
            let scratchImage = try onCheckedScratchSettlement.map { _ in
                try owner.requireOriginalScratchImageInsideOriginalRecoveryG()
            }
            let settled = try ScratchDataLeaseStoreV1.withExclusiveOriginalEraseSourceRead(
                applicationSupportURL: applicationSupportURL,
                request: request, permit: permit,
                requireProtectedIngressUnchanged: {
                    try owner.requireObservationUnchangedInsideOriginalRecoveryG()
                },
                readerIsDrained: {
                    (!constructionAttempted || constructionSettled)
                        && retainedContainer == nil && retainedContext == nil
                }, originalScratchImage: scratchImage,
                onCheckedSettlement: onCheckedScratchSettlement,
                diagnosticPhase: diagnosticPhase) { copy in
#if DEBUG
                diagnosticPhase?("recovery.original.old.factory.read-enter")
                diagnosticPhase?("recovery.original.old.factory.copy-enter")
#endif
                try authority.copyOriginalRecoverySQLiteFiles(
                    id: generationID, files: files,
                    treeDigest: treeDigest, into: copy)
#if DEBUG
                diagnosticPhase?("recovery.original.old.factory.copy-complete")
                diagnosticPhase?("recovery.original.old.factory.input-proofs-enter")
#endif
                var immutableInputs: [String: ScratchDataLeaseStoreV1.SourceReadDirectory.FileProof] = [:]
                for file in files where file.name != "model.sqlite-shm" {
                    let proof = try copy.sqliteFileProof(named: file.name)
                    guard proof.byteCount == file.byteCount,
                          proof.sha256 == file.sha256 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    immutableInputs[file.name] = proof
                }
#if DEBUG
                diagnosticPhase?("recovery.original.old.factory.input-proofs-complete")
                diagnosticPhase?("recovery.original.old.factory.shm-integrity-enter")
#endif
                try copy.requireExclusiveOwnedFilesBeforeContainer()
                try copy.prepareExclusiveOwnedSHMForContainer()
                try CompletedAbortSQLitePhysicalImageV1.requireFullIntegrity(
                    at: copy.modelURL)
                try copy.requireExclusiveContainerKeptOwnedFiles()
#if DEBUG
                diagnosticPhase?("recovery.original.old.factory.shm-integrity-complete")
                diagnosticPhase?("recovery.original.old.factory.container-enter")
#endif
                let result = Result { try autoreleasepool {
                    try permit.requireHeld()
                    constructionAttempted = true
                    let container = try openReadOnlyReleasedContainer(
                        at: copy.modelURL, release: .v53,
                        markerMigrationID: migrationID,
                        observe: { opened in
                            retainedContainer = opened
                            retainedContext = opened.mainContext
                        },
                        afterConstruct: { _ in
                            try copy.requireExclusiveContainerKeptOwnedFiles()
                        })
                    constructionSettled = true
#if DEBUG
                    diagnosticPhase?("recovery.original.old.factory.container-complete")
                    diagnosticPhase?("recovery.original.old.factory.callback-enter")
#endif
                    let validated = try validate(container.mainContext, copy.modelURL)
#if DEBUG
                    diagnosticPhase?("recovery.original.old.factory.callback-complete")
#endif
                    return validated
                } }
                guard retainedContainer == nil, retainedContext == nil else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let semantic = try result.get()
#if DEBUG
                diagnosticPhase?("recovery.original.old.factory.postinput-enter")
#endif
                try permit.requireHeld()
                guard try copy.sqliteFileNames().subtracting(["model.sqlite-shm"])
                        == Set(immutableInputs.keys) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                for (name, original) in immutableInputs {
                    guard try copy.sqliteFileProof(named: name) == original else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
                guard try authority.originalRecoverySQLiteFiles(
                    id: generationID, treeDigest: treeDigest) == files else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
#if DEBUG
                diagnosticPhase?("recovery.original.old.factory.postinput-complete")
#endif
                return semantic
            }
            if scratchImage != nil {
                _ = try owner.requireOriginalScratchImageInsideOriginalRecoveryG()
            }
            return settled
        }
#if DEBUG
        diagnosticPhase?("recovery.original.old.factory.scratch-complete")
        diagnosticPhase?("recovery.original.old.factory.final-owner-enter")
#endif
        try owner.requireObservationUnchanged()
#if DEBUG
        diagnosticPhase?("recovery.original.old.factory.final-owner-complete")
        diagnosticPhase?("recovery.original.old.factory.final-files-enter")
#endif
        guard try authority.originalRecoverySQLiteFiles(
            id: generationID, treeDigest: treeDigest) == files else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
#if DEBUG
        diagnosticPhase?("recovery.original.old.factory.final-files-complete")
#endif
        return value
    }

#if DEBUG
    @MainActor
    func completedAbortCanonicalSource(
        in context: ModelContext,
        generationRootURL: URL,
        generationID: UUID,
        migrationID: UUID,
        expectedIdentity: WorkspaceReplicaIdentityV1
    ) throws -> EraseCompletedAbortCanonicalSourceV1 {
        var diagnosticStage = "context-binding"
        do {
        let configurations = Array(context.container.configurations)
        guard configurations.count == 1,
              !configurations[0].isStoredInMemoryOnly,
              configurations[0].url.standardizedFileURL
                == generationRootURL.appendingPathComponent(Self.modelStoreName)
                    .standardizedFileURL,
              !context.hasChanges else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        diagnosticStage = "semantic-identity"
        let identity = try acceptedV53SemanticIdentity(
            in: context, generationID: generationID, migrationID: migrationID)
        guard identity == expectedIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        diagnosticStage = "canonical-rows"
        let canonicalRowsFramedSHA256 = try framedSemanticDigest(
            in: context, release: .v53)
        diagnosticStage = "journal-open"
        let journal = try MutationJournalStoreV1(modelContext: context,
            identity: identity, generationID: generationID,
            allowStateBootstrap: false)
        diagnosticStage = "journal-history"
        let history = try journal.exportSnapshot()
        diagnosticStage = "journal-validation"
        try journal.validateAll()
        diagnosticStage = "context-after"
        guard !context.hasChanges else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return EraseCompletedAbortCanonicalSourceV1(
            workspaceIdentity: identity,
            canonicalRowsFramedSHA256: canonicalRowsFramedSHA256,
            mutationHistory: history)
        } catch {
            FileHandle.standardError.write(Data((
                "ERASE_COMPLETED_ABORT_CANONICAL_V1 stage=" + diagnosticStage + "\n"
            ).utf8))
            throw error
        }
    }

    /// The original G/EX permit exists only for this synchronous call. The
    /// source uses retained no-follow FDs; only the bounded private copy is
    /// opened with SwiftData. The scratch owner closes and deletes its exact
    /// lease before the result can be compared with the pre-alias baseline.
    @MainActor
    func completedAbortCanonicalSourceFromExclusiveCopy(
        generationID: UUID,
        migrationID: UUID,
        expectedIdentity: WorkspaceReplicaIdentityV1,
        expectedTreeDigest: String,
        operationID: UUID,
        sourceAuthority: StoreRestoreGenerationAuthority,
        permit: CompletedAbortExclusiveScratchPermitV1,
        requireProtectedIngressUnchanged: @escaping @MainActor () throws -> Void,
        afterCopyBeforeReadForTesting: (@MainActor (URL) throws -> Void)? = nil,
        afterReadBeforeCleanupForTesting: (@MainActor (URL) throws -> Void)? = nil
    ) throws -> EraseCompletedAbortCanonicalSourceV1 {
        try permit.requireHeld()
        CompletedAbortRSSStageV1.record(.privateCopyStart)
        let files = try sourceAuthority.completedAbortSQLiteFiles(
            id: generationID, treeDigest: expectedTreeDigest)
        CompletedAbortRSSStageV1.record(.privateCopyFiles)
        var requested: UInt64 = 0
        for file in files {
            let (sum, overflow) = requested.addingReportingOverflow(file.byteCount)
            guard !overflow else { throw ScratchDataLeaseStoreFailureV1.sizeLimitExceeded }
            requested = sum
        }
        if !files.contains(where: { $0.name == "model.sqlite-shm" }) {
            let wal = files.first(where: { $0.name == "model.sqlite-wal" })?.byteCount ?? 0
            let (sum, overflow) = requested.addingReportingOverflow(max(32_768, wal))
            guard !overflow else { throw ScratchDataLeaseStoreFailureV1.sizeLimitExceeded }
            requested = sum
        }
        guard requested > 0,
              requested <= ScratchDataPurposeV1.source.maximumByteCount else {
            throw ScratchDataLeaseStoreFailureV1.sizeLimitExceeded
        }
        let now = Date()
        let request = try ScratchDataLeaseRequestV1(
            leaseID: UUID(), purpose: .source, owner: .source,
            ownerOperationID: operationID,
            requestedByteCount: requested, createdAt: now,
            expiresAt: now.addingTimeInterval(
                ScratchDataPurposeV1.source.maximumLifetimeSeconds))
        weak var retainedContainer: ModelContainer?
        weak var retainedContext: ModelContext?
        var constructionAttempted = false
        var constructionSettled = false
        let snapshot = try ScratchDataLeaseStoreV1.withExclusiveCompletedAbortSourceRead(
            applicationSupportURL: applicationSupportURL,
            request: request, permit: permit,
            requireProtectedIngressUnchanged: requireProtectedIngressUnchanged,
            readerIsDrained: {
                (!constructionAttempted || constructionSettled) &&
                    retainedContainer == nil && retainedContext == nil
            }) { copy in
            try sourceAuthority.copyCompletedAbortSQLiteFiles(
                id: generationID, files: files,
                treeDigest: expectedTreeDigest, into: copy)
            CompletedAbortRSSStageV1.record(.privateCopyCopied)
            var immutableInputs: [String: ScratchDataLeaseStoreV1.SourceReadDirectory.FileProof] = [:]
            for file in files where file.name != "model.sqlite-shm" {
                let proof = try copy.sqliteFileProof(named: file.name)
                guard proof.byteCount == file.byteCount,
                      proof.sha256 == file.sha256 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                immutableInputs[file.name] = proof
            }
            try afterCopyBeforeReadForTesting?(copy.modelURL)
            try copy.requireExclusiveOwnedFilesBeforeContainer()
            try copy.prepareExclusiveOwnedSHMForContainer()
            try CompletedAbortSQLitePhysicalImageV1.requireFullIntegrity(
                at: copy.modelURL)
            CompletedAbortRSSStageV1.record(.privateCopyIntegrity)
            try copy.requireExclusiveContainerKeptOwnedFiles()
            let result = Result { try autoreleasepool {
                try permit.requireHeld()
                constructionAttempted = true
                let container = try openReadOnlyReleasedContainer(
                    at: copy.modelURL, release: .v53,
                    markerMigrationID: migrationID,
                    observe: { opened in
                        retainedContainer = opened
                        retainedContext = opened.mainContext
                    },
                    afterConstruct: { _ in
                        try copy.requireExclusiveContainerKeptOwnedFiles()
                    })
                constructionSettled = true
                return try completedAbortCanonicalSource(
                    in: container.mainContext,
                    generationRootURL: copy.modelURL.deletingLastPathComponent(),
                    generationID: generationID, migrationID: migrationID,
                    expectedIdentity: expectedIdentity)
            } }
            guard retainedContainer == nil, retainedContext == nil else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let canonical = try result.get()
            CompletedAbortRSSStageV1.record(.privateCopyRead)
            try afterReadBeforeCleanupForTesting?(copy.modelURL)
            try permit.requireHeld()
            guard try copy.sqliteFileNames().subtracting(["model.sqlite-shm"])
                    == Set(immutableInputs.keys) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            for (name, original) in immutableInputs {
                guard try copy.sqliteFileProof(named: name) == original else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard try sourceAuthority.completedAbortSQLiteFiles(
                id: generationID, treeDigest: expectedTreeDigest) == files else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return canonical
        }
        try permit.requireHeld()
        CompletedAbortRSSStageV1.record(.privateCopyClosed)
        return snapshot
    }

    @MainActor
    func requireFreshCompletedAbortSourceLedger(
        coordinator: StoreSessionCoordinator,
        witness: EraseOriginalShutdownWitnessV1,
        registry: GenerationLeaseRegistryV1,
        sourceAuthority: StoreRestoreGenerationAuthority,
        sourceBytes: EraseCompletedAbortSourceBytesV1,
        manifestMigrationID: UUID,
        manifestRelease: PersistentSchemaReleaseV1,
        expected: DeletionLedgerProofV2,
        reproveOriginal: @escaping () throws -> Void
    ) throws {
        guard coordinator.generationRootURL.standardizedFileURL
                  == installedGenerationURL(id: coordinator.generationID),
              case .v3(let pointer, _) = try CurrentPointerCodecV1.decode(sourceBytes.current),
              try pointer.canonicalData() == sourceBytes.current,
              pointer.generationID == coordinator.generationID.uuidString.lowercased(),
              let release = PersistentSchemaReleaseV1(
                  rawValue: "V\(pointer.storeSchemaVersion)"),
              release == manifestRelease else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let observation = try witness.beginCompletedAbortContextConstruction(
            registry: registry)
        let modelURL = coordinator.generationRootURL
            .appendingPathComponent(Self.modelStoreName)
        func reprove() throws {
            try reproveOriginal()
            try sourceAuthority.requireCompletedAbortModelURL(
                id: coordinator.generationID,
                rootURL: coordinator.generationRootURL,
                modelURL: modelURL)
        }
        // Construct a distinct no-save container from the exact original
        // source URL. The constructor is weak-observed before invocation.
        // Its first marker fetch and the ledger fetch each have the original
        // Service-frame physical source witness checked on both sides.
        try reprove()
        let container = try openReadOnlyReleasedContainer(
            at: modelURL,
            release: release, markerMigrationID: manifestMigrationID,
            observe: { _ in },
            afterConstruct: { opened in
                try observation.completeCompletedAbortContextConstruction(opened)
                try reprove()
            })
        try reprove()
        let fresh = container.mainContext
        guard !fresh.hasChanges else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let freshLedger = try deletionLedgerProof(in: fresh)
        try reprove()
        guard freshLedger == expected, !fresh.hasChanges else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }
    @MainActor
    func requireFreshRetiredOriginalSourceLedgerForColdExit(
        sourceGenerationID: UUID,
        manifestMigrationID: UUID,
        manifestRelease: PersistentSchemaReleaseV1,
        expected: DeletionLedgerProofV2,
        sourceAuthority: StoreRestoreGenerationAuthority,
        retainObservation: (EraseOriginalColdExitContextObservationV1) throws -> Void,
        reproveOriginal: @escaping () throws -> Void
    ) throws {
        try expected.validate()
        let sourceRoot = installedGenerationURL(id: sourceGenerationID)
        let modelURL = sourceRoot.appendingPathComponent(Self.modelStoreName)
        let observation = EraseOriginalColdExitContextObservationV1()
        try retainObservation(observation)
        func reprove() throws {
            try reproveOriginal()
            try sourceAuthority.requireCompletedAbortModelURL(
                id: sourceGenerationID, rootURL: sourceRoot, modelURL: modelURL)
        }
        try reprove()
        let container = try openReadOnlyReleasedContainer(
            at: modelURL, release: manifestRelease,
            markerMigrationID: manifestMigrationID,
            observe: { _ in },
            afterConstruct: { opened in
                try observation.complete(opened)
                try reprove()
            })
        try reprove()
        let context = container.mainContext
        guard !context.hasChanges else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let actual = try deletionLedgerProof(in: context)
        try reprove()
        guard actual == expected, !context.hasChanges else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }
#endif

    private func currentPointer(
        from identity: RestorePointerIdentityV1
    ) throws -> CurrentGenerationPointerV3 {
        try CurrentGenerationPointerV3(
            generationID: identity.generationID,
            generationManifestSHA256: identity.generationManifestSHA256,
            workspaceID: WorkspaceID(rawValue: identity.workspaceID),
            replicaID: ReplicaID(rawValue: identity.replicaID),
            knownReplicaIDs: Set(identity.knownReplicaIDs.map { ReplicaID(rawValue: $0) }),
            storeSchemaVersion: PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major
        )
    }

    @MainActor
    private func requireCurrentPointer(
        _ identity: RestorePointerIdentityV1,
        authority: StoreRestoreGenerationAuthority
    ) throws -> CurrentGenerationPointerV3 {
        guard try authority.currentGenerationID() == identity.generationID,
              case .v3(let actual, let data) = try decodeCurrentPointer(
                at: dataRootURL.appendingPathComponent(Self.currentPointerName)
              ) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let expected = try currentPointer(from: identity)
        guard actual == expected,
              data == (try expected.canonicalData()) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try requireCurrentManifest(actual)
        return actual
    }

    private func restorePointerIdentity(
        _ pointer: CurrentGenerationPointerV3
    ) throws -> RestorePointerIdentityV1 {
        try pointer.validate()
        guard let generationID = canonicalUUID(from: pointer.generationID),
              let workspaceID = canonicalUUID(from: pointer.workspaceID),
              let replicaID = canonicalUUID(from: pointer.replicaID) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return RestorePointerIdentityV1(
            generationID: generationID,
            generationManifestSHA256: pointer.generationManifestSHA256,
            knownReplicaIDs: Set(try pointer.knownReplicaIdentitySet().map(\.rawValue)),
            workspaceID: workspaceID,
            replicaID: replicaID
        )
    }

    /// Creates only the sealed plan's destination reviews in an unpublished generation.
    /// No writer, journal or temporary capability leaves this synchronous scope.
    @MainActor
    func writeRestoreDestinationReviews(
        plan: RepetitiveCaptureRestoreReviewPlanV1,
        authority: StoreRestoreGenerationAuthority,
        clock: any ApplicationClock,
        idSource: any ApplicationIDSource,
        fileAuthority: any ApplicationFileAuthorityV1,
        diagnosticPhase: (@MainActor (String) -> Void)? = nil
    ) throws -> (history: MutationHistorySnapshotV1, checkpoints: [FieldDraftCheckpointV1]) {
        diagnosticPhase?("reviews.lock.begin")
        return try authority.mutationRegistry.withNoMigrationReservation {
            diagnosticPhase?("reviews.lock.acquired")
            diagnosticPhase?("reviews.plan")
            try plan.validate()
            let target = plan.identity.targetPointer
            let identity = try WorkspaceReplicaIdentityV1(
                workspaceID: WorkspaceID(rawValue: target.workspaceID),
                replicaID: ReplicaID(rawValue: target.replicaID))
            diagnosticPhase?("reviews.manifest-store")
            let manifestStore = try StoreMigrationJournalStoreV1(
                applicationSupportURL: applicationSupportURL)
            @MainActor func requireUnpublished() throws {
                diagnosticPhase?("reviews.unpublished.root")
                try authority.requireRestoreReviewRoot(applicationSupportURL)
                diagnosticPhase?("reviews.unpublished.no-journal")
                try authority.requireNoRestoreJournal()
                diagnosticPhase?("reviews.unpublished.current-pointer")
                _ = try requireCurrentPointer(plan.identity.oldPointer, authority: authority)
                diagnosticPhase?("reviews.unpublished.presence")
                let presence = try authority.presence(id: target.generationID)
                diagnosticPhase?("reviews.unpublished.guards")
                guard presence.staging, !presence.installed,
                      target.generationID != plan.identity.oldPointer.generationID,
                      try manifestStore.loadManifestIfPresent(targetGenerationID: target.generationID) == nil,
                      try !authority.mutationRegistry.activeEpochs().contains(where: {
                          $0.generationID == target.generationID
                      }) else { throw WorkspaceMutationFailureV1.wrongGeneration }
                diagnosticPhase?("reviews.unpublished.staging")
                try authority.requireStagingGeneration(id: target.generationID)
            }
            try requireUnpublished()
            diagnosticPhase?("reviews.open-staging")
            let session = try openRestoreStagingGeneration(id: target.generationID,
                identity: identity, authority: authority, diagnosticPhase: diagnosticPhase)
            diagnosticPhase?("reviews.open-staging.end")
            let context = session.modelContext
            guard !context.hasChanges, session.workspaceIdentity == identity,
                  session.generationID == target.generationID,
                  session.generationEpoch == nil else {
                throw WorkspaceMutationFailureV1.wrongGeneration
            }
            diagnosticPhase?("reviews.root-identity")
            let rootIdentity = try authority.restoreReviewRootIdentity(id: target.generationID)
            diagnosticPhase?("reviews.mutations")
            let mutations: [FieldDraftMutationV1] = try plan.checkpoints.map { checkpoint in
                try FieldDraftMutationV1(workspaceID: checkpoint.workspaceID,
                    expectedRevision: 0,
                    expectedBaseCanonicalRevision: checkpoint.baseCanonicalRevision,
                    mutationID: checkpoint.mutationID, postImage: .createCheckpoint(checkpoint))
            }
            diagnosticPhase?("reviews.capability")
            let capability = StoreRestoreReviewWriteAuthorityV1(
                context: context, identity: identity, generationID: target.generationID,
                commands: mutations.map { WorkspaceCommandV1.applyFieldDraft($0) },
                validateBinding: {
                    try requireUnpublished()
                    guard session.modelContext === context,
                          session.workspaceIdentity == identity,
                          session.generationID == target.generationID,
                          try authority.restoreReviewRootIdentity(id: target.generationID) == rootIdentity else {
                        throw WorkspaceMutationFailureV1.wrongGeneration
                    }
                })
            defer {
                diagnosticPhase?("reviews.cleanup.begin")
                capability.revoke(); context.rollback()
                diagnosticPhase?("reviews.cleanup.end")
            }
            diagnosticPhase?("reviews.journal-init")
            let journal = try MutationJournalStoreV1(modelContext: context, identity: identity,
                generationID: target.generationID, restoreReviewAuthority: capability)
            diagnosticPhase?("reviews.original-history")
            let originalHistory = try journal.exportSnapshot()
            diagnosticPhase?("reviews.original-checkpoints")
            let originalCheckpoints = try context.fetch(FetchDescriptor<FieldDraftCheckpointRow>()).map { try $0.value() }
            diagnosticPhase?("reviews.original-history.end")
            let originalDraftIDs = Set(originalCheckpoints.map(\.draftID))
            let originalDraftRevisionIDs = Set(originalHistory.entityRevisions.filter {
                $0.identity.kind == .fieldDraftCheckpoint
            }.map { $0.identity.id })
            let originalMutationIDs = try Set(originalHistory.receipts.map {
                try MutationEnvelopeV1.decodeCanonical(from: $0.envelopeData).mutationID
            })
            guard Set(plan.checkpoints.map(\.draftID)).count == plan.checkpoints.count,
                  Set(mutations.map(\.mutationID)).count == mutations.count,
                  plan.checkpoints.allSatisfy({
                      !originalDraftIDs.contains($0.draftID) && !originalDraftRevisionIDs.contains($0.draftID)
                  }),
                  mutations.allSatisfy({ !originalMutationIDs.contains($0.mutationID) }) else {
                throw WorkspaceMutationFailureV1.invalidCommand
            }
            let initial = try WorkspaceRevisionV1(workspaceID: identity.workspaceID,
                generationID: target.generationID, revision: 0, entityRevisions: [])
            diagnosticPhase?("reviews.writer-init")
            let writer = try WorkspaceWriterV1(identity: identity, generationID: target.generationID,
                initialRevision: initial, clock: clock, idSource: idSource,
                fileAuthority: fileAuthority,
                adapter: WorkspaceWriterAdapterV1(modelContext: context,
                    generationRootURL: session.generationRootURL, expectedRootIdentity: rootIdentity),
                journalStore: journal)
            defer { writer.invalidate() }
            diagnosticPhase?("reviews.writer-init.end")
            var createdRecords: [MutationHistoryReceiptRecordV1] = []
            for mutation in mutations {
                diagnosticPhase?("reviews.current-revision")
                let current = try writer.currentRevision()
                diagnosticPhase?("reviews.request")
                let entities: [WorkspaceEntityRevisionV1] = try mutation.concurrencyIdentities.map {
                    WorkspaceEntityRevisionV1(identity: $0, revision: 0)
                }
                let expected = try WorkspaceExpectedRevisionV1(workspaceID: current.workspaceID,
                    generationID: current.generationID, writerInstanceID: current.writerInstanceID,
                    workspaceRevision: current.revision, entityRevisions: entities)
                let request = WorkspaceMutationRequestV1(mutationID: mutation.mutationID,
                    expectedRevision: expected, command: .applyFieldDraft(mutation))
                let envelope = try MutationEnvelopeV1(request: request, identity: identity)
                diagnosticPhase?("reviews.bind")
                try capability.bind(envelope: envelope)
                diagnosticPhase?("reviews.execute")
                _ = try writer.execute(request)
                diagnosticPhase?("reviews.reproof")
                try session.reproofAfterSave()
                diagnosticPhase?("reviews.receipt")
                guard !context.hasChanges, let receipt = try journal.receipt(mutationID: mutation.mutationID),
                      receipt.envelopeSHA256 == (try envelope.canonicalSHA256()) else {
                    throw WorkspaceMutationFailureV1.receiptHistoryCorrupt
                }
                let record = MutationHistoryReceiptRecordV1(envelopeData: try envelope.canonicalData(),
                    receiptData: try receipt.canonicalData(), reversalBasisData: nil, semanticReversalData: nil)
                createdRecords.append(record)
                diagnosticPhase?("reviews.finish")
                try capability.finish(envelope: envelope)
            }
            try requireUnpublished()
            diagnosticPhase?("reviews.final-history")
            let history = try journal.exportSnapshot()
            diagnosticPhase?("reviews.final-history.end")
            let addedRevisions: [MutationHistoryEntityRevisionV1] = try plan.checkpoints.map {
                MutationHistoryEntityRevisionV1(
                    identity: try WorkspaceEntityIdentityV1(kind: .fieldDraftCheckpoint, id: $0.draftID),
                    revision: $0.draftRevision)
            }
            let createdIDs = Set(mutations.map(\.mutationID))
            var retainedRecords: [MutationHistoryReceiptRecordV1] = []
            var newRecords: [MutationHistoryReceiptRecordV1] = []
            for record in history.receipts {
                let envelope = try MutationEnvelopeV1.decodeCanonical(from: record.envelopeData)
                if createdIDs.contains(envelope.mutationID) { newRecords.append(record) }
                else { retainedRecords.append(record) }
            }
            let newRevisionIDs = Set(addedRevisions.map(\.identity))
            let retainedRevisions = history.entityRevisions.filter { !newRevisionIDs.contains($0.identity) }
            let newRevisions = history.entityRevisions.filter { newRevisionIDs.contains($0.identity) }
            let count = UInt64(createdRecords.count)
            let revision = originalHistory.workspaceRevision.addingReportingOverflow(count)
            let sequence = originalHistory.lastLocalSequence.addingReportingOverflow(count)
            diagnosticPhase?("reviews.final-checkpoints")
            let checkpoints = try context.fetch(FetchDescriptor<FieldDraftCheckpointRow>()).map { try $0.value() }
            diagnosticPhase?("reviews.final-comparison")
            guard !context.hasChanges, !revision.overflow, !sequence.overflow,
                  history.workspaceRevision == revision.partialValue,
                  history.lastLocalSequence == sequence.partialValue,
                  history.entityRevisions.count == originalHistory.entityRevisions.count + addedRevisions.count,
                  retainedRevisions == originalHistory.entityRevisions,
                  newRevisions == addedRevisions.sorted(by: { $0.identity.stableKey < $1.identity.stableKey }),
                  history.receipts.count == originalHistory.receipts.count + createdRecords.count,
                  retainedRecords == originalHistory.receipts, newRecords == createdRecords,
                  history.quarantines == originalHistory.quarantines,
                  checkpoints.count == originalCheckpoints.count + plan.checkpoints.count,
                  Set(checkpoints) == Set(originalCheckpoints + plan.checkpoints) else {
                throw WorkspaceMutationFailureV1.receiptHistoryCorrupt
            }
            let createdCheckpoints = checkpoints.filter { !originalDraftIDs.contains($0.draftID) }
                .sorted { $0.draftID.uuidString < $1.draftID.uuidString }
            diagnosticPhase?("reviews.return")
            return (history, createdCheckpoints)
        }
    }

    @MainActor
    func prepareRestoreStagingGenerationManifest(
        expectedOldID: UUID,
        newID: UUID,
        restoreProof: StoreRestoreGenerationManifestProofV1? = nil,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1? = nil,
        authority: StoreRestoreGenerationAuthority,
        diagnosticPhase: (@MainActor (String) -> Void)? = nil
    ) throws -> String {
        diagnosticPhase?("recovery.manifest.lock.begin")
        return try authority.mutationRegistry.withNoMigrationReservation {
            diagnosticPhase?("recovery.manifest.lock.acquired")
            try authority.requireRestoreReviewRoot(applicationSupportURL)
            return try prepareRestoreStagingGenerationManifestLocked(expectedOldID: expectedOldID,
                newID: newID, restoreProof: restoreProof, restoreFileSnapshot: restoreFileSnapshot,
                authority: authority, diagnosticPhase: diagnosticPhase)
        }
    }

    @MainActor
    private func prepareRestoreStagingGenerationManifestLocked(
        expectedOldID: UUID,
        newID: UUID,
        restoreProof: StoreRestoreGenerationManifestProofV1? = nil,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1? = nil,
        authority: StoreRestoreGenerationAuthority,
        diagnosticPhase: (@MainActor (String) -> Void)? = nil
    ) throws -> String {
        guard try authority.currentGenerationID() == expectedOldID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try authority.requireStagingGeneration(id: newID)
        if let restoreProof {
            try restoreProof.validate()
            guard restoreProof.predecessorGenerationID == expectedOldID,
                  restoreProof.generationID == newID else {
                throw StoreMigrationFailure.invalidContract
            }
            guard restoreFileSnapshot?.staging == true else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        } else {
            guard restoreFileSnapshot == nil else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            try authority.protectStagingGeneration(id: newID)
        }
        diagnosticPhase?("recovery.manifest.preflight.end")
        let root = restoreStagingGenerationURL(id: newID)
        _ = try requireRestoreFileSnapshot(
            restoreFileSnapshot,
            generationID: restoreProof?.generationID,
            at: root,
            restoreProof: restoreProof
        )
        diagnosticPhase?("recovery.manifest.file-snapshot.end")
        let modelStoreURL = root.appendingPathComponent(Self.modelStoreName)
        let markerMigrationID = try autoreleasepool { () throws -> UUID in
            diagnosticPhase?("recovery.manifest.container.begin")
            let container = try makeV53Container(at: modelStoreURL, migrate: false)
            diagnosticPhase?("recovery.manifest.container.end")
            diagnosticPhase?("recovery.manifest.marker.begin")
            let marker = try requireV53Marker(
                in: container.mainContext,
                expectedMigrationID: nil
            )
            diagnosticPhase?("recovery.manifest.marker.end")
            guard let value = marker.migrationID else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            return value
        }
        diagnosticPhase?("recovery.manifest.container-scope.end")
        let store = try StoreMigrationJournalStoreV1(
            applicationSupportURL: applicationSupportURL
        )
        let digest: String
        diagnosticPhase?("recovery.manifest.load.begin")
        if let existing = try store.loadManifestIfPresent(targetGenerationID: newID) {
            diagnosticPhase?("recovery.manifest.existing-verify.begin")
            try requireRestoreManifestSnapshot(
                existing.manifest,
                expectedOldID: expectedOldID,
                generationID: newID,
                at: root,
                staging: true,
                restoreProof: restoreProof,
                restoreFileSnapshot: restoreFileSnapshot
            )
            diagnosticPhase?("recovery.manifest.existing-verify.end")
            digest = existing.digest
        } else {
            diagnosticPhase?("recovery.manifest.semantic.begin")
            let semanticSHA256: String = try framedSemanticDigest(
                at: modelStoreURL,
                release: PersistentSchemaReleaseRegistryV1.activeRelease
            )
            diagnosticPhase?("recovery.manifest.semantic.end")
            diagnosticPhase?("recovery.manifest.identity.begin")
            let identityDigest: String = try frozenIdentityDigest(
                for: root,
                restoreProof: restoreProof,
                restoreFileSnapshot: restoreFileSnapshot
            )
            diagnosticPhase?("recovery.manifest.identity.end")
            diagnosticPhase?("recovery.manifest.files.begin")
            let fileDigests: [StoreGenerationFileDigestV1] = try generationFileDigests(
                at: root,
                durable: true,
                restoreProof: restoreProof,
                restoreFileSnapshot: restoreFileSnapshot
            )
            diagnosticPhase?("recovery.manifest.files.end")
            diagnosticPhase?("recovery.manifest.construct.begin")
            let manifest = try StoreGenerationManifestV1(
                schemaVersion: 2,
                generationID: newID,
                predecessorGenerationID: expectedOldID,
                migrationID: markerMigrationID,
                storeSchemaRelease: PersistentSchemaReleaseRegistryV1.activeRelease,
                semanticSHA256: semanticSHA256,
                semanticDigestAlgorithm: .framedLayersV1,
                frozenIdentityDigest: identityDigest,
                files: fileDigests,
                restoreProof: restoreProof
            )
            diagnosticPhase?("recovery.manifest.construct.end")
            diagnosticPhase?("recovery.manifest.write.begin")
            digest = try store.writeManifest(manifest)
            diagnosticPhase?("recovery.manifest.write.end")
            diagnosticPhase?("recovery.manifest.new-verify.begin")
            try requireRestoreManifestSnapshot(
                manifest,
                expectedOldID: expectedOldID,
                generationID: newID,
                at: root,
                staging: true,
                restoreProof: restoreProof,
                restoreFileSnapshot: restoreFileSnapshot
            )
        }
        guard try authority.currentGenerationID() == expectedOldID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try authority.requireStagingGeneration(id: newID)
        diagnosticPhase?("recovery.manifest.return")
        return digest
    }

    @MainActor
    func requireInstalledRestoreGenerationSnapshot(
        expectedOldID: UUID,
        generationID: UUID,
        expectedManifestDigest: String,
        restoreProof: StoreRestoreGenerationManifestProofV1? = nil,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1? = nil,
        authority: StoreRestoreGenerationAuthority
    ) throws {
        guard StoreMigrationCanonicalJSONV1.isLowercaseSHA256(
            expectedManifestDigest
        ) else {
            throw StoreMigrationFailure.invalidDigest
        }
        try authority.requireInstalledGeneration(id: generationID)
        if restoreProof == nil {
            guard restoreFileSnapshot == nil else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            try authority.protectInstalledGeneration(id: generationID)
        } else {
            guard restoreFileSnapshot?.staging == false else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        }
        let store = try StoreMigrationJournalStoreV1(
            applicationSupportURL: applicationSupportURL
        )
        let manifest = try store.loadManifest(
            targetGenerationID: generationID,
            expectedDigest: expectedManifestDigest
        )
        try requireRestoreManifestSnapshot(
            manifest,
            expectedOldID: expectedOldID,
            generationID: generationID,
            at: installedGenerationURL(id: generationID),
            staging: false,
            restoreProof: restoreProof,
            restoreFileSnapshot: restoreFileSnapshot
        )
        if restoreProof == nil {
            try authority.protectInstalledGeneration(id: generationID)
        } else {
            _ = try requireRestoreFileSnapshot(
                restoreFileSnapshot,
                generationID: generationID,
                at: installedGenerationURL(id: generationID),
                restoreProof: restoreProof
            )
        }
        try authority.requireInstalledGeneration(id: generationID)
    }

    @MainActor
    func removePreparedRestoreGenerationManifestBeforeDiscard(
        expectedOldID: UUID,
        generationID: UUID,
        expectedDigest: String,
        restoreProof: StoreRestoreGenerationManifestProofV1? = nil,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1? = nil,
        authority: StoreRestoreGenerationAuthority
    ) throws {
        guard generationID != expectedOldID,
              StoreMigrationCanonicalJSONV1.isLowercaseSHA256(expectedDigest),
              try currentGenerationID(authority: authority) == expectedOldID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let presence = try generationPresence(
            id: generationID,
            authority: authority
        )
        guard !(presence.staging && presence.installed) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        if let restoreProof {
            guard let restoreFileSnapshot,
                  restoreFileSnapshot.staging == presence.staging,
                  presence.staging || presence.installed else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            _ = try requireRestoreFileSnapshot(
                restoreFileSnapshot,
                generationID: generationID,
                at: presence.staging
                    ? restoreStagingGenerationURL(id: generationID)
                    : installedGenerationURL(id: generationID),
                restoreProof: restoreProof
            )
        } else if presence.staging {
            guard restoreFileSnapshot == nil else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            try authority.protectStagingGeneration(id: generationID)
            try authority.requireStagingGeneration(id: generationID)
        } else if presence.installed {
            guard restoreFileSnapshot == nil else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            try authority.protectInstalledGeneration(id: generationID)
            try authority.requireInstalledGeneration(id: generationID)
        }

        let store = try StoreMigrationJournalStoreV1(
            applicationSupportURL: applicationSupportURL
        )
        if let existing = try store.loadManifestIfPresent(
            targetGenerationID: generationID
        ) {
            guard existing.digest == expectedDigest,
                  existing.manifest.generationID == generationID,
                  presence.staging || presence.installed else {
                throw StoreMigrationFailure.digestMismatch
            }
            try requireRestoreManifestSnapshot(
                existing.manifest,
                expectedOldID: expectedOldID,
                generationID: generationID,
                at: presence.staging
                    ? restoreStagingGenerationURL(id: generationID)
                    : installedGenerationURL(id: generationID),
                staging: presence.staging,
                restoreProof: restoreProof,
                restoreFileSnapshot: restoreFileSnapshot
            )
            try store.removeManifest(
                targetGenerationID: generationID,
                expectedDigest: expectedDigest
            )
        }

        if let _ = try store.loadManifestIfPresent(
            targetGenerationID: generationID
        ) {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        guard try currentGenerationID(authority: authority) == expectedOldID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let after = try generationPresence(
            id: generationID,
            authority: authority
        )
        guard after.staging == presence.staging,
              after.installed == presence.installed,
              !(after.staging && after.installed) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        if let restoreProof {
            _ = try requireRestoreFileSnapshot(
                restoreFileSnapshot,
                generationID: generationID,
                at: after.staging
                    ? restoreStagingGenerationURL(id: generationID)
                    : installedGenerationURL(id: generationID),
                restoreProof: restoreProof
            )
        } else if after.staging {
            try authority.protectStagingGeneration(id: generationID)
            try authority.requireStagingGeneration(id: generationID)
        } else if after.installed {
            try authority.protectInstalledGeneration(id: generationID)
            try authority.requireInstalledGeneration(id: generationID)
        }
    }

    @MainActor
    func removePreparedRestoreStagingGenerationManifest(
        generationID: UUID,
        expectedDigest: String,
        restoreProof: StoreRestoreGenerationManifestProofV1? = nil,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1? = nil,
        authority: StoreRestoreGenerationAuthority
    ) throws {
        guard StoreMigrationCanonicalJSONV1.isLowercaseSHA256(expectedDigest),
              try authority.currentGenerationID() != generationID,
              !(try generationPresence(
                  id: generationID,
                  authority: authority
              ).installed) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        if let restoreProof {
            guard restoreFileSnapshot?.staging == true else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            _ = try requireRestoreFileSnapshot(
                restoreFileSnapshot,
                generationID: generationID,
                at: restoreStagingGenerationURL(id: generationID),
                restoreProof: restoreProof
            )
        } else if restoreFileSnapshot != nil {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        let store = try StoreMigrationJournalStoreV1(
            applicationSupportURL: applicationSupportURL
        )
        guard let existing = try store.loadManifestIfPresent(
            targetGenerationID: generationID
        ) else {
            return
        }
        guard existing.digest == expectedDigest,
              existing.manifest.generationID == generationID,
              existing.manifest.restoreProof == restoreProof else {
            throw StoreMigrationFailure.digestMismatch
        }
        try store.removeManifest(
            targetGenerationID: generationID,
            expectedDigest: expectedDigest
        )
        if let _ = try store.loadManifestIfPresent(
            targetGenerationID: generationID
        ) {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        if let restoreProof {
            _ = try requireRestoreFileSnapshot(
                restoreFileSnapshot,
                generationID: generationID,
                at: restoreStagingGenerationURL(id: generationID),
                restoreProof: restoreProof
            )
        }
    }

    func restoreStagingGenerationURL(id: UUID) -> URL {
        applicationSupportURL
            .appendingPathComponent("FieldEvidenceRestore", isDirectory: true)
            .appendingPathComponent("generations", isDirectory: true)
            .appendingPathComponent(canonicalString(for: id), isDirectory: true)
    }

    func installedGenerationURL(id: UUID) -> URL {
        generationsURL.appendingPathComponent(
            canonicalString(for: id),
            isDirectory: true
        )
    }

    func prepareRestoreGenerationFileSnapshot(
        generationID: UUID,
        staging: Bool,
        expectedRootIdentity: StreamingArchiveRootIdentityV1,
        restoreProof: StoreRestoreGenerationManifestProofV1
    ) async throws -> StoreRestoreGenerationFileSnapshotV1 {
        try Task.checkCancellation()
        try restoreProof.validate()
        guard restoreProof.generationID == generationID else {
            throw StoreMigrationFailure.invalidContract
        }
        let rootURL = (staging
            ? restoreStagingGenerationURL(id: generationID)
            : installedGenerationURL(id: generationID)).standardizedFileURL
        let task = Task.detached {
            try StoreRestoreGenerationAuthority.prepareRestoreGenerationFileSnapshot(
                generationID: generationID,
                staging: staging,
                rootURL: rootURL,
                expectedRootIdentity: expectedRootIdentity,
                restoreProof: restoreProof,
                cancellationCheck: { try Task.checkCancellation() }
            )
        }
        return try await withTaskCancellationHandler(
            operation: { try await task.value },
            onCancel: { task.cancel() }
        )
    }

