/// Privately created from actual current membership and kept by its Router
/// operation. Caller arrays can never supply or extend exhaustive coverage.
@MainActor
final class TemporalNormalizationRetainedSourceSetV1 {
    private let operation: TemporalNormalizationSourceOperationV1
    private let exclusion: TemporalNormalizationSourceExclusionV1
    let currentGenerationID: UUID
    let retiredGenerationIDs: [UUID]
    private let baselineLeases: [GenerationLeaseTokenV1]
    private struct Retained {
        let observation: TemporalNormalizationRetainedSourceObservationV1
        let pins: TemporalNormalizationCurrentPinsV1
        let digests: [String: String]
    }
    private var retained: [UUID: Retained] = [:]
    private var worker: Task<[String: String], any Error>?
    private var pendingObservedBytes: [String: String]?
    private var closed = false
    private var disposalStarted = false
    private var abandonmentRead: TemporalNormalizationAbandonmentReadV1?
    private var abandonmentWorker: Task<Void, any Error>?
    private var abandonmentJournal: TemporalOperationalJournalObservationV1?
    private var abandonmentPrepared: PreparedTemporalUncommittedOriginalV1?
    private var abandonmentClassificationWorker: Task<TemporalNormalizationUncommittedOriginalClassificationV1, any Error>?
    private var abandonmentClassification: TemporalNormalizationUncommittedOriginalClassificationV1?
    private var abandonmentEffectStarted = false
    private weak var activePublication: TemporalNormalizationPublicationProofV1?
    fileprivate init(operation: TemporalNormalizationSourceOperationV1,
        exclusion: TemporalNormalizationSourceExclusionV1, currentGenerationID: UUID,
        retiredGenerationIDs: [UUID], baselineLeases: [GenerationLeaseTokenV1]) {
        self.operation = operation; self.exclusion = exclusion; self.currentGenerationID = currentGenerationID
        self.retiredGenerationIDs = retiredGenerationIDs; self.baselineLeases = baselineLeases
    }
    func isBound(to expected: TemporalNormalizationSourceOperationV1) -> Bool { operation.matches(expected) }
    fileprivate func requireExpectedSource(operation expected: TemporalNormalizationSourceOperationV1,
        generationID: UUID) throws {
        guard operation.matches(expected), !closed, !disposalStarted, worker == nil,
              ([currentGenerationID] + retiredGenerationIDs).contains(generationID), retained[generationID] == nil else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try exclusion.revalidate()
    }
    fileprivate func acceptSource(operation expected: TemporalNormalizationSourceOperationV1,
        snapshot: TemporalNormalizationCanonicalSnapshotV1,
        reports: [TemporalNormalizationReportSnapshotObservationV1],
        profileRegistry: WorkspacePackageLifecycleProfileRegistryV1,
        pins: TemporalNormalizationCurrentPinsV1) throws {
        try requireExpectedSource(operation: expected, generationID: snapshot.generationID)
        try pins.revalidate()
        guard pins.manifest?.generationID == snapshot.generationID,
              Set(pins.observedFileDigests.keys) == Set(pins.files.map { $0.url.path }) else {
            throw StoreMigrationFailure.invalidIdentity
        }
        retained[snapshot.generationID] = Retained(observation: .init(snapshot: snapshot, reports: reports,
            profileRegistry: profileRegistry), pins: pins, digests: pins.observedFileDigests)
    }
    func requireCompletePhysicalSet(scope: TemporalNormalizationOriginalAccessScopeV1) throws {
        try scope.requireSourceSet(operation: operation, sourceSet: self)
        guard !closed, !disposalStarted, Set(retained.keys) == Set([currentGenerationID] + retiredGenerationIDs),
              let current = retained[currentGenerationID] else { throw StoreMigrationFailure.invalidIdentity }
        try exclusion.revalidate()
        let leases = try exclusion.observeSourceRegistry().leases
        guard leases.count == baselineLeases.count, Set(leases.map(\.leaseID)).count == leases.count,
              leases.allSatisfy({ baselineLeases.contains($0) }) else { throw StoreMigrationFailure.invalidIdentity }
        guard try current.pins.retainSourceMembership(currentGenerationID: currentGenerationID) == retiredGenerationIDs else {
            throw StoreMigrationFailure.invalidIdentity
        }
        for value in retained.values {
            try value.pins.revalidate()
            guard value.pins.observedFileDigests == value.digests else { throw StoreMigrationFailure.invalidIdentity }
        }
        try scope.requireSourceSet(operation: operation, sourceSet: self)
    }
    func startFreshByteObservation(scope: TemporalNormalizationOriginalAccessScopeV1,
        access: TemporalNormalizationSourceSetReadAccessV1) throws {
        try requireCompletePhysicalSet(scope: scope)
        guard worker == nil else { throw StoreMigrationFailure.invalidIdentity }
        // Paths shared between source pins must denote exactly identical
        // original facts/digests; no later source wins an overwrite.
        var files: [String: TemporalNormalizationCurrentPinsV1.File] = [:]
        var expected: [String: String] = [:]
        for value in retained.values {
            for file in value.pins.files {
                guard let digest = value.digests[file.url.path] else { throw StoreMigrationFailure.invalidIdentity }
                if let prior = files[file.url.path] {
                    guard prior.identity == file.identity, expected[file.url.path] == digest else { throw StoreMigrationFailure.invalidIdentity }
                } else { files[file.url.path] = file; expected[file.url.path] = digest }
            }
        }
        pendingObservedBytes = nil
        let reads = files.keys.sorted().map { TemporalNormalizationSourceSetFingerprintV1(sourceSet: self,
            file: files[$0]!, expectedSHA256: expected[$0]!) }
        worker = Task.detached(priority: .utility) {
            var result: [String: String] = [:]
            for read in reads {
                while try access.readNextChunk(read) {}
                let completed = try read.completed()
                result[completed.path] = completed.sha256
            }
            return result
        }
    }
    func joinFreshByteObservationIfRunning() async throws {
        if worker != nil { try await joinFreshByteObservation() }
    }
    func joinFreshByteObservation() async throws {
        guard let worker else { throw StoreMigrationFailure.invalidIdentity }
        let result = await worker.result
        self.worker = nil
        pendingObservedBytes = try result.get() // actual completed worker, not a success Boolean
    }
    func observations(scope: TemporalNormalizationOriginalAccessScopeV1) throws -> [TemporalNormalizationRetainedSourceObservationV1] {
        try requireCompletePhysicalSet(scope: scope)
        guard worker == nil, pendingObservedBytes != nil else { throw StoreMigrationFailure.invalidIdentity }
        pendingObservedBytes = nil // this actual byte pass is consumed once
        return ([currentGenerationID] + retiredGenerationIDs).map { retained[$0]!.observation }
    }
    func closeAfterFailure() throws {
        guard worker == nil, abandonmentWorker == nil, abandonmentClassificationWorker == nil, activePublication == nil else { throw StoreMigrationFailure.invalidIdentity }
        if closed { return }
        disposalStarted = true; pendingObservedBytes = nil
        try abandonmentRead?.closeAfterWorkerJoined()
        abandonmentRead = nil
        for id in retained.keys.sorted(by: { $0.uuidString < $1.uuidString }) {
            guard let value = retained[id] else { throw StoreMigrationFailure.invalidIdentity }
            try value.pins.closeRetainedSourceSetPins()
            retained.removeValue(forKey: id)
        }
        closed = true
    }
    func requireClosed() throws {
        guard closed, retained.isEmpty, worker == nil else { throw StoreMigrationFailure.invalidIdentity }
    }
}

/// Read-only chunk operation bound to the actual retained source set. No URL,
/// FD, expected digest or owner identity can be supplied outside this file.
final class TemporalNormalizationSourceSetFingerprintV1: @unchecked Sendable {
    let sourceSetIdentity: ObjectIdentifier
    private let file: TemporalNormalizationCurrentPinsV1.File
    private let expectedSHA256: String
    private let lock = NSLock()
    private var offset: Int64 = 0
    private var hash = SHA256()
    private var result: String?
    @MainActor
    fileprivate init(sourceSet: TemporalNormalizationRetainedSourceSetV1,
        file: TemporalNormalizationCurrentPinsV1.File, expectedSHA256: String) {
        sourceSetIdentity = ObjectIdentifier(sourceSet); self.file = file; self.expectedSHA256 = expectedSHA256
    }
    func readNextChunkUnderOriginalReference() throws -> Bool {
        try lock.withLock {
            try TemporalNormalizationCurrentPinsV1.revalidate(file)
            if result != nil { return false }
            let remaining = file.identity.size - offset
            guard remaining >= 0 else { throw StoreMigrationFailure.invalidIdentity }
            if remaining > 0 {
                var bytes = Data(count: Int(min(65_536, remaining)))
                let amount = bytes.withUnsafeMutableBytes { Darwin.pread(file.descriptor, $0.baseAddress!, $0.count, off_t(offset)) }
                if amount < 0, errno == EINTR { return true }
                guard amount >= 0 else { throw TemporalNormalizationReportReadFailureV1.readFailed(errorNumber: errno) }
                guard amount > 0 else { throw TemporalNormalizationReportReadFailureV1.unexpectedEOF(expected: file.identity.size, observed: offset) }
                bytes.count = amount; hash.update(data: bytes); offset += Int64(amount)
            }
            try TemporalNormalizationCurrentPinsV1.revalidate(file)
            if offset == file.identity.size {
                let digest = hash.finalize().map { String(format: "%02x", $0) }.joined()
                guard digest == expectedSHA256 else { throw StoreMigrationFailure.digestMismatch }
                result = digest; return false
            }
            return true
        }
    }
    fileprivate func completed() throws -> (path: String, sha256: String) {
        try lock.withLock {
            guard let result, offset == file.identity.size else { throw StoreMigrationFailure.invalidIdentity }
            try TemporalNormalizationCurrentPinsV1.revalidate(file)
            return (file.url.path, result)
        }
    }
}


extension StoreGenerationFactory {
    @MainActor
    func makeTemporalNormalizationColdRetiredSource(operation: TemporalNormalizationColdOperationAuthorityV1,
        exclusion: TemporalNormalizationColdExclusionV1, generationID: UUID,
        profileRegistry: WorkspacePackageLifecycleProfileRegistryV1,
        scope: TemporalNormalizationOriginalAccessScopeV1) throws -> TemporalNormalizationSourceOwnerV1 {
        try scope.requireColdPreparation(operation: operation, exclusion: exclusion)
        return try TemporalNormalizationSourceOwnerV1(factory: self, applicationSupportURL: applicationSupportURL,
            retiredGenerationID: generationID, operation: operation, exclusion: exclusion,
            profileRegistry: profileRegistry, scope: scope)
    }
}

/// The only original-removal publication authority. Construction is confined to
/// the actual source-set executor after fixed M17 classification under real G.
@MainActor
final class TemporalNormalizationPublicationProofV1 {
    fileprivate let owner: TemporalNormalizationRetainedSourceSetV1
    fileprivate let read: TemporalNormalizationAbandonmentReadV1
    fileprivate let reservation: TemporalEvidencePromotionReservationV1
    fileprivate let originalAccess: TemporalNormalizationOriginalAccessScopeV1
    fileprivate let mutationScope: TemporalNormalizationMutationScopeV1
    private var active = true
    fileprivate init(owner: TemporalNormalizationRetainedSourceSetV1,
        read: TemporalNormalizationAbandonmentReadV1, reservation: TemporalEvidencePromotionReservationV1,
        originalAccess: TemporalNormalizationOriginalAccessScopeV1,
        mutationScope: TemporalNormalizationMutationScopeV1) {
        self.owner = owner; self.read = read; self.reservation = reservation
        self.originalAccess = originalAccess; self.mutationScope = mutationScope
    }
    fileprivate func revoke() { active = false }
    func originalOnlyCensus() throws -> Bool {
        try requireUncommittedOriginalRemoval(reservation: reservation, generationRootURL: read.generationRootURL)
        return try read.originalOnlyCensus()
    }
    func publishRetainedOriginal(_ prepared: PreparedTemporalUncommittedOriginalV1,
        service: OrphanFileCleanupService) throws -> OrphanFileCleanupSummary {
        try requireUncommittedOriginalRemoval(reservation: prepared.reservation, generationRootURL: prepared.generationRootURL)
        return try read.publishRetainedOriginal(prepared, service: service, publication: self)
    }
    func requireUncommittedOriginalRemoval(reservation expected: TemporalEvidencePromotionReservationV1,
        generationRootURL: URL) throws {
        guard active, reservation == expected, generationRootURL == read.generationRootURL else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try Task.checkCancellation()
        try owner.requireOriginalPublication(self)
    }
}

extension TemporalNormalizationRetainedSourceSetV1 {
    func prepareAbandonmentRead(scope: TemporalNormalizationOriginalAccessScopeV1) throws -> TemporalNormalizationAbandonmentReadV1 {
        try requireCompletePhysicalSet(scope: scope)
        guard abandonmentRead == nil, abandonmentWorker == nil, !abandonmentEffectStarted,
              let current = retained[currentGenerationID] else { throw StoreMigrationFailure.invalidIdentity }
        let root = current.pins.applicationSupportURL.appendingPathComponent("FieldEvidenceData/generations")
            .appendingPathComponent(currentGenerationID.uuidString.lowercased(), isDirectory: true)
        let read = TemporalNormalizationAbandonmentReadV1(sourceSet: self, generationRootURL: root)
        abandonmentRead = read // retained before the first open or throwing observation
        try read.prepareJournalDescriptors()
        return read
    }
    func startAbandonmentRead(scope: TemporalNormalizationOriginalAccessScopeV1,
        access: TemporalNormalizationAbandonmentReadAccessV1) throws {
        try requireCompletePhysicalSet(scope: scope)
        guard let read = abandonmentRead, abandonmentWorker == nil, !abandonmentEffectStarted else {
            throw StoreMigrationFailure.invalidIdentity
        }
        abandonmentWorker = Task.detached(priority: .utility) {
            while try access.readNextChunk(read) {}
        }
    }
    func joinAbandonmentRead() async throws {
        guard let worker = abandonmentWorker else { throw StoreMigrationFailure.invalidIdentity }
        let result = await worker.result
        abandonmentWorker = nil
        try result.get()
    }
    func joinAbandonmentReadIfRunning() async throws {
        if abandonmentWorker != nil { try await joinAbandonmentRead() }
    }
    func prepareAbandonmentOriginal(mutationID: MutationIDV1,
        scope: TemporalNormalizationOriginalAccessScopeV1) throws {
        try requireCompletePhysicalSet(scope: scope)
        guard let read = abandonmentRead, abandonmentWorker == nil,
              abandonmentJournal == nil, !abandonmentEffectStarted else { throw StoreMigrationFailure.invalidIdentity }
        let journal = try read.completedJournal()
        let candidates = journal.published.flatMap(\.promotions).filter { $0.mutationID == mutationID }
        guard candidates.count == 1 else { throw StoreMigrationFailure.invalidIdentity }
        abandonmentJournal = journal
        try read.prepareOriginalDescriptors(candidates[0])
    }
    func finishAbandonmentOriginal(scope: TemporalNormalizationOriginalAccessScopeV1) throws {
        try requireCompletePhysicalSet(scope: scope)
        guard let read = abandonmentRead, abandonmentWorker == nil, abandonmentJournal != nil,
              abandonmentPrepared == nil, !abandonmentEffectStarted else { throw StoreMigrationFailure.invalidIdentity }
        abandonmentPrepared = try read.completedOriginal()
    }
    func startAbandonmentClassification(scope: TemporalNormalizationOriginalAccessScopeV1) throws {
        try requireCompletePhysicalSet(scope: scope)
        guard abandonmentWorker == nil, abandonmentClassificationWorker == nil,
              abandonmentClassification == nil, !abandonmentEffectStarted,
              let read = abandonmentRead, let journal = abandonmentJournal,
              let prepared = abandonmentPrepared else { throw StoreMigrationFailure.invalidIdentity }
        try read.requireJournalUnchanged()
        let ownedSources = try observations(scope: scope) // actual fresh pass, consumed once
        abandonmentClassificationWorker = Task.detached(priority: .utility) {
            let sources = try ownedSources.map { item in
                try TemporalNormalizationReferencePreflightV1.observe(snapshot: item.snapshot,
                    history: TemporalNormalizationHistoryObservationV1(history: item.snapshot.history),
                    reports: item.reports, profileRegistry: item.profileRegistry)
            }
            return try TemporalNormalizationUncommittedOriginalClassificationV1(
                reservation: prepared.reservation, operational: journal, sources: sources)
        }
    }
    func joinAbandonmentClassification() async throws {
        guard let worker = abandonmentClassificationWorker else { throw StoreMigrationFailure.invalidIdentity }
        let result = await worker.result
        abandonmentClassificationWorker = nil
        abandonmentClassification = try result.get()
    }
    func joinAbandonmentClassificationIfRunning() async throws {
        if abandonmentClassificationWorker != nil { try await joinAbandonmentClassification() }
    }
    func executeOriginalAbandonment(scope: TemporalNormalizationOriginalAccessScopeV1) throws -> OrphanFileCleanupSummary {
        try requireCompletePhysicalSet(scope: scope)
        switch exclusion {
        case .coordinated(let value): return try value.executeOriginalAbandonment(sourceSet: self, originalAccess: scope)
        case .cold(let value): return try value.executeOriginalAbandonment(sourceSet: self, originalAccess: scope)
        }
    }
    private func requireMutationScope(_ scope: TemporalNormalizationMutationScopeV1) throws {
        switch exclusion {
        case .coordinated(let value): try value.requireOriginalAbandonmentScope(scope)
        case .cold(let value): try value.requireOriginalAbandonmentScope(scope)
        }
    }
    func publishOriginalAbandonment(mutationScope: TemporalNormalizationMutationScopeV1,
        originalAccess: TemporalNormalizationOriginalAccessScopeV1) throws -> OrphanFileCleanupSummary {
        try requireMutationScope(mutationScope)
        try requireCompletePhysicalSet(scope: originalAccess)
        guard abandonmentWorker == nil, !abandonmentEffectStarted, activePublication == nil,
              let read = abandonmentRead, let journal = abandonmentJournal,
              let prepared = abandonmentPrepared else { throw StoreMigrationFailure.invalidIdentity }
        try read.requireJournalUnchanged()
        for value in retained.values { try value.pins.requireStrictPolicyForEffect() }
        // The pure worker is joined before G. Its data result is usable only
        // with this same retained input set and these fresh physical checks.
        guard abandonmentClassificationWorker == nil, let classification = abandonmentClassification,
              classification.reservation == prepared.reservation, classification.blockers.isEmpty,
              case .noReferencedContentInSuppliedObservations = classification.decision else {
            throw StoreMigrationFailure.invalidIdentity
        }
        let proof = TemporalNormalizationPublicationProofV1(owner: self, read: read,
            reservation: prepared.reservation, originalAccess: originalAccess, mutationScope: mutationScope)
        activePublication = proof
        defer { proof.revoke(); activePublication = nil }
        try requireOriginalPublication(proof)
        let service = try read.fixedRemovalService()
        abandonmentEffectStarted = true // failure after an effect is never reminted as initial absence
        let result = try service.publishTemporalUncommittedOriginalRemoval(prepared, publication: proof)
        try requireOriginalPublication(proof) // unchanged raw source/journal and census at exit
        try read.closeAfterWorkerJoined() // checked terminal close; uncertainty remains owned
        return result
    }
    fileprivate func requireOriginalPublication(_ proof: TemporalNormalizationPublicationProofV1) throws {
        guard activePublication === proof, proof.owner === self, abandonmentRead === proof.read,
              abandonmentPrepared?.reservation == proof.reservation, abandonmentWorker == nil,
              abandonmentClassificationWorker == nil, worker == nil else { throw StoreMigrationFailure.invalidIdentity }
        try requireMutationScope(proof.mutationScope)
        try requireCompletePhysicalSet(scope: proof.originalAccess)
        try proof.read.requireJournalUnchanged()
        for value in retained.values { try value.pins.requireStrictPolicyForEffect() }
    }
}


extension StoreRestoreGenerationAuthority {
    // The worker is deliberately outside the MainActor attempt type. It owns
    // only pinned filesystem authority and immutable IDs, never SwiftData or
    // callbacks. The caller retains actual EX and joins this one Task before
    // any validation, disposal or lease close.
    fileprivate enum EraseValidationCopyOutcome: Sendable { case complete, failed }
    fileprivate final class EraseValidationCopyWork: @unchecked Sendable {
        let authority: StoreRestoreGenerationAuthority
        let sourceID: UUID
        let targetID: UUID
        let targetIdentity: Identity
        init(authority: StoreRestoreGenerationAuthority, sourceID: UUID,
             targetID: UUID, targetIdentity: Identity) {
            self.authority = authority; self.sourceID = sourceID
            self.targetID = targetID; self.targetIdentity = targetIdentity
        }
        func run() -> EraseValidationCopyOutcome {
            do {
                guard try StoreRestoreGenerationAuthority.requiredDirectoryIdentity(
                    parent: authority.stagingGenerationsDescriptor,
                    name: StoreRestoreGenerationAuthority.canonical(targetID)) == targetIdentity else {
                    return .failed
                }
                _ = try authority.cloneInstalledGenerationLocked(sourceID: sourceID,
                    toStagingGeneration: targetID)
                guard try StoreRestoreGenerationAuthority.requiredDirectoryIdentity(
                    parent: authority.stagingGenerationsDescriptor,
                    name: StoreRestoreGenerationAuthority.canonical(targetID)) == targetIdentity else {
                    return .failed
                }
                return .complete
            } catch { return .failed }
        }
    }


    /// One registered private-copy validation attempt. It owns the exact
    /// created namespace before fsync/protection/copy can throw, retains a real
    /// copy Task until join, and never stores an arbitrary model-bearing Error.
    @MainActor
    final class EraseTargetValidationAttemptV1 {
        private enum Phase { case registered, allocating, copying, copied, reading,
            validated, disposing, ready, failed, constructorUnresolved, closeUncertain }
        private let authority: StoreRestoreGenerationAuthority
        fileprivate let binding: EraseRetirementBindingV1
        private weak var exclusion: EraseRetirementExclusionV1?
        private weak var witness: EraseSessionDrainWitnessV1?
        private let reader: GenerationLeaseHandleV1
        fileprivate let intent: EraseIntentV1
        fileprivate let manifest: StoreGenerationManifestV1
        private let manifestScope: EraseCurrentManifestScopeV1
        private var manifestRetirement: EraseManifestRetirementAttemptV1?
        private let copyID = UUID()
        private var phase: Phase = .registered
        private var original: MigrationCloneResult?
        private var copyDescriptor: Int32?
        private var copyIdentity: Identity?
        private var copyTask: Task<EraseValidationCopyOutcome, Never>?
        private weak var privateContainer: ModelContainer?
        private weak var privateContext: ModelContext?
        private var returnedContainerObserved = false
        private var closeAdmissionClosed = false
        private var terminalSourceReceipt: EraseGenerationAuthorityTerminalCloseReceiptV1?
        private weak var terminalSourceRetirement: ErasedRegistryRetirementProofV1?

        fileprivate init(authority: StoreRestoreGenerationAuthority,
            binding: EraseRetirementBindingV1, exclusion: EraseRetirementExclusionV1,
            witness: EraseSessionDrainWitnessV1, reader: GenerationLeaseHandleV1,
            intent: EraseIntentV1, manifest: StoreGenerationManifestV1,
            manifestScope: EraseCurrentManifestScopeV1) {
            self.authority = authority; self.binding = binding; self.exclusion = exclusion
            self.witness = witness; self.reader = reader; self.intent = intent; self.manifest = manifest
            self.manifestScope = manifestScope
        }

        fileprivate func isBound(to value: EraseSessionDrainWitnessV1) -> Bool { witness === value }

        fileprivate func registerTerminalSourceOwner(
            _ completed: EraseGenerationAuthorityTerminalCloseReceiptV1,
            retirement: ErasedRegistryRetirementProofV1,
            authority expectedAuthority: StoreRestoreGenerationAuthority,
            witness expectedWitness: EraseSessionDrainWitnessV1) throws {
            guard authority === expectedAuthority, witness === expectedWitness,
                  terminalSourceReceipt == nil, terminalSourceRetirement == nil,
                  phase == .ready, closeAdmissionClosed, original != nil,
                  copyTask == nil, copyDescriptor == nil,
                  privateContainer == nil, privateContext == nil,
                  let manifestRetirement, let exclusion,
                  manifestRetirement.matches(binding: binding, exclusion: exclusion,
                    retirement: retirement),
                  completed.matchesSourceOwner(proof: retirement, authority: authority,
                    binding: binding) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            // Retain the authentic completed close before any later source
            // observation can fail. A refused transfer is never reset/reopened.
            terminalSourceReceipt = completed
            terminalSourceRetirement = retirement
        }
        fileprivate var modelURL: URL {
            authority.stagingGenerationsURL.appendingPathComponent(
                StoreRestoreGenerationAuthority.canonical(copyID), isDirectory: true)
                .appendingPathComponent("model.sqlite")
        }

        private func requireBeforeClose() throws -> EraseRetirementExclusionV1 {
            guard let exclusion, let witness, !closeAdmissionClosed else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try exclusion.requirePostDrainValidation(reader: reader, proof: witness)
            return exclusion
        }

        private func requireSourceUnchanged() throws {
            guard let exclusion, let original, manifestScope.binding == binding,
                  let store = manifestScope.store else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let observedManifest: StoreGenerationManifestV1
            let current: StoreRestoreGenerationAuthority.MigrationCloneResult
            if let completed = terminalSourceReceipt {
                guard let retirement = terminalSourceRetirement, let manifestRetirement else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                observedManifest = try manifestRetirement.requirePostCloseSourceControls(
                    binding: binding, exclusion: exclusion, retirement: retirement,
                    receipt: completed, authority: authority,
                    expectedPointerData: manifestScope.pointerData)
                guard observedManifest == manifest else {
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
                current = try authority.snapshotTargetForPostCloseEraseValidation(
                    binding: binding, exclusion: exclusion, manifest: manifestRetirement,
                    receipt: completed, retirement: retirement,
                    pointerData: manifestScope.pointerData)
            } else {
                guard terminalSourceRetirement == nil,
                      try authority.readPointerForEraseRetirement(name: "current.json",
                        expectedData: manifestScope.pointerData,
                        binding: binding, exclusion: exclusion) == manifestScope.pointerData else {
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
                if let manifestRetirement {
                    observedManifest = try manifestRetirement.requireCurrentManifest(
                        binding: binding, exclusion: exclusion)
                } else {
                    observedManifest = try store.readManifestForEraseRetirement(
                        targetGenerationID: binding.subject.newGenerationID,
                        expectedDigest: binding.generationEpoch.generationManifestSHA256,
                        binding: binding, exclusion: exclusion)
                }
                guard observedManifest == manifest else {
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
                current = try authority.snapshotTargetForEraseValidation(binding: binding, exclusion: exclusion)
            }
            guard current.files == original.files,
                  current.sourceTreeDigest == original.sourceTreeDigest,
                  current.frozenIdentityDigest == original.frozenIdentityDigest else {
                throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
            }
        }

        private func requireCopyIdentity() throws {
            guard let descriptor = copyDescriptor, let identity = copyIdentity else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try authority.verify()
            try StoreRestoreGenerationAuthority.require(descriptor, identity)
            guard try StoreRestoreGenerationAuthority.requiredDirectoryIdentity(
                parent: authority.stagingGenerationsDescriptor,
                name: StoreRestoreGenerationAuthority.canonical(copyID)) == identity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }

        fileprivate func copyAfterOriginalDrain() async throws {
            guard phase == .registered, copyTask == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let exclusion = try requireBeforeClose()
            original = try authority.snapshotTargetForEraseValidation(binding: binding, exclusion: exclusion)
            try authority.verify()
            let name = StoreRestoreGenerationAuthority.canonical(copyID)
            guard try !StoreRestoreGenerationAuthority.itemExists(
                parent: authority.stagingGenerationsDescriptor, name: name),
                  try !StoreRestoreGenerationAuthority.itemExists(
                    parent: authority.installedGenerationsDescriptor, name: name) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            phase = .allocating
            do {
                guard Darwin.mkdirat(authority.stagingGenerationsDescriptor, name, mode_t(0o700)) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let descriptor = Darwin.openat(authority.stagingGenerationsDescriptor, name,
                    O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
                guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
                copyDescriptor = descriptor // retain before any throwing identity/policy/fsync
                copyIdentity = try StoreRestoreGenerationAuthority.identity(descriptor)
                try requireCopyIdentity()
                guard Darwin.fsync(authority.stagingGenerationsDescriptor) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try authority.enforce(.restoreStaging,
                    at: authority.stagingGenerationsURL.appendingPathComponent(name, isDirectory: true),
                    authorityCheck: { try self.requireCopyIdentity() })
                guard let identity = copyIdentity else { throw StoreGenerationFailure.dataPointerInvalid }
                let work = EraseValidationCopyWork(authority: authority, sourceID: binding.subject.newGenerationID,
                    targetID: copyID, targetIdentity: identity)
                phase = .copying
                let task = Task.detached { work.run() }
                copyTask = task
                let result = await task.value // real join, including cancellation/failure
                copyTask = nil
                guard case .complete = result else { throw StoreGenerationFailure.dataPointerInvalid }
                _ = try requireBeforeClose()
                try requireCopyIdentity()
                try requireSourceUnchanged()
                phase = .copied
            } catch {
                phase = .failed
                throw EraseAllServiceError.recoveryRequired
            }
        }

        fileprivate func beginRead() throws {
            guard phase == .copied, copyTask == nil,
                  privateContainer == nil, privateContext == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            _ = try requireBeforeClose(); try requireCopyIdentity(); try requireSourceUnchanged()
            phase = .reading
        }
        fileprivate func observe(_ container: ModelContainer) {
            returnedContainerObserved = true
            privateContainer = container; privateContext = container.mainContext
        }
        fileprivate func endRead(valid: Bool) throws {
            guard phase == .reading else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            guard returnedContainerObserved else {
                phase = .constructorUnresolved
                throw EraseAllServiceError.recoveryRequired
            }
            guard valid else { phase = .failed; throw EraseAllServiceError.recoveryRequired }
            phase = .validated
            // A surviving private alias remains a real pending attempt; it is
            // not cleared or converted to success because the scope returned.
        }

        fileprivate func disposeValidatedCopy() throws -> Bool {
            guard phase == .validated || phase == .disposing, copyTask == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            guard privateContainer == nil, privateContext == nil else { return false }
            _ = try requireBeforeClose(); try requireSourceUnchanged()
            guard let identity = copyIdentity else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if phase == .validated {
                try requireCopyIdentity()
                phase = .disposing
            }
            if let descriptor = copyDescriptor {
                // Never retry an uncertain close using an integer that could
                // have been reused. The retained failed attempt denies success.
                guard Darwin.close(descriptor) == 0 else {
                    phase = .closeUncertain
                    throw EraseAllServiceError.recoveryRequired
                }
                copyDescriptor = nil
            }
            try authority.removeDirectory(parent: authority.stagingGenerationsDescriptor,
                name: StoreRestoreGenerationAuthority.canonical(copyID), ownership: .generation,
                expectedRoot: identity)
            guard try !StoreRestoreGenerationAuthority.itemExists(
                parent: authority.stagingGenerationsDescriptor,
                name: StoreRestoreGenerationAuthority.canonical(copyID)) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try requireSourceUnchanged()
            phase = .ready
            return true
        }

        fileprivate func registerManifestRetirement(_ attempt: EraseManifestRetirementAttemptV1,
            retirement: ErasedRegistryRetirementProofV1,
            exclusion expectedExclusion: EraseRetirementExclusionV1,
            store: StoreMigrationJournalStoreV1) throws {
            guard phase == .ready, closeAdmissionClosed, manifestRetirement == nil,
                  exclusion === expectedExclusion, manifestScope.store === store,
                  let witness, copyTask == nil, copyDescriptor == nil,
                  privateContainer == nil, privateContext == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try retirement.requireManifestRegistration(witness: witness, attempt: attempt,
                store: store, exclusion: expectedExclusion)
            try requireSourceUnchanged()
            try attempt.requireOriginalPointerBytes(manifestScope.pointerData)
            guard try attempt.requireCurrentManifest(binding: binding,
                exclusion: expectedExclusion) == manifest else {
                throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
            }
            manifestRetirement = attempt // last, nonthrowing: original proof stays intact on failure
        }

        fileprivate func observesManifestRetirement(_ attempt: EraseManifestRetirementAttemptV1) -> Bool {
            manifestRetirement === attempt
        }

        /// Resume disposal of this exact already-validated private reader.
        /// This cannot start another constructor/copy or treat failed-nil as drain.
        func resumeValidatedDisposal(binding expected: EraseRetirementBindingV1,
            witness expectedWitness: EraseSessionDrainWitnessV1,
            exclusion expectedExclusion: EraseRetirementExclusionV1) throws -> Bool {
            guard binding == expected, witness === expectedWitness,
                  exclusion === expectedExclusion else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            if phase == .ready {
                guard copyTask == nil, copyDescriptor == nil,
                      privateContainer == nil, privateContext == nil else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                try requireSourceUnchanged()
                return true
            }
            return try disposeValidatedCopy()
        }

        fileprivate func requireValidatedAndDrained(binding expected: EraseRetirementBindingV1,
            witness expectedWitness: EraseSessionDrainWitnessV1) throws {
            guard binding == expected, witness === expectedWitness, phase == .ready,
                  copyTask == nil, copyDescriptor == nil,
                  privateContainer == nil, privateContext == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            // This one-way edge prevents another private reader after any
            // close gate is reached, including a subsequently failed close.
            closeAdmissionClosed = true
            try requireSourceUnchanged()
        }
    }
}

extension StoreGenerationFactory {
    /// Returns only the retained attempt. Its fixed private reader cannot
    /// escape, acquire a new lease, repair policy or create a writer/session.
    @MainActor
    func validateOrResumeEraseTargetAfterOriginalDrain(binding: EraseRetirementBindingV1,
        reader: GenerationLeaseHandleV1, drain: EraseSessionDrainWitnessV1,
        exclusion: EraseRetirementExclusionV1, authority: StoreRestoreGenerationAuthority,
        intent: EraseIntentV1, manifestScope: EraseCurrentManifestScopeV1) async throws -> Bool {
        if let attempt = drain.postDrainValidation {
            return try attempt.resumeValidatedDisposal(binding: binding,
                witness: drain, exclusion: exclusion)
        }
        let attempt = try await validateEraseTargetAfterOriginalDrain(binding: binding,
            reader: reader, drain: drain, exclusion: exclusion, authority: authority,
            intent: intent, manifestScope: manifestScope)
        return try attempt.resumeValidatedDisposal(binding: binding,
            witness: drain, exclusion: exclusion)
    }

    @MainActor
    func validateEraseTargetAfterOriginalDrain(binding: EraseRetirementBindingV1,
        reader: GenerationLeaseHandleV1, drain: EraseSessionDrainWitnessV1,
        exclusion: EraseRetirementExclusionV1, authority: StoreRestoreGenerationAuthority,
        intent: EraseIntentV1, manifestScope: EraseCurrentManifestScopeV1) async throws
        -> StoreRestoreGenerationAuthority.EraseTargetValidationAttemptV1 {
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-exclusion-enter")
#endif
        try exclusion.requirePostDrainValidation(reader: reader, proof: drain)
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-exclusion-complete")
#endif
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-pointer-enter")
#endif
        guard drain.postDrainValidation == nil, manifestScope.binding == binding,
              manifestScope.pointerData == (try authority.readPointerForEraseRetirement(
                name: "current.json", expectedData: manifestScope.pointerData,
                binding: binding, exclusion: exclusion)),
              let store = manifestScope.store,
              intent.eraseID == binding.subject.eraseID,
              intent.newGenerationID == binding.subject.newGenerationID,
              intent.phase == .sessionActivated || intent.phase == .cleanupComplete,
              EraseIntentCodecV1.valid(intent) else {
            throw EraseAllServiceError.invalidAuthority
        }
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-pointer-complete")
#endif
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-manifest-enter")
#endif
        let manifest = try store.readManifestForEraseRetirement(
            targetGenerationID: binding.subject.newGenerationID,
            expectedDigest: binding.generationEpoch.generationManifestSHA256,
            binding: binding, exclusion: exclusion)
        // Incumbent current Erase targets use the complete v53 empty-graph
        // validator. This does not invent older released schema validation.
        guard manifest.storeSchemaRelease == .v53 else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-manifest-complete")
#endif
        let attempt = StoreRestoreGenerationAuthority.EraseTargetValidationAttemptV1(
            authority: authority, binding: binding, exclusion: exclusion,
            witness: drain, reader: reader, intent: intent, manifest: manifest,
            manifestScope: manifestScope)
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-attempt-register-enter")
#endif
        try drain.registerPostDrainValidation(attempt) // before mkdir/copy/model construction
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-copy-enter")
#endif
        try await attempt.copyAfterOriginalDrain()
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-copy-complete")
#endif
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-read-enter")
#endif
        try attempt.beginRead()
        let valid: Bool = autoreleasepool {
            do {
                let container = try openReadOnlyReleasedContainer(at: attempt.modelURL,
                    release: manifest.storeSchemaRelease, markerMigrationID: manifest.migrationID,
                    observe: { attempt.observe($0) })
                let identity = try acceptedV53SemanticIdentity(in: container.mainContext,
                    generationID: binding.subject.newGenerationID, migrationID: manifest.migrationID)
                guard identity == binding.workspaceIdentity else { return false }
                try EraseAllService.requireEmptyErasePublishedGraph(context: container.mainContext,
                    generationID: binding.subject.newGenerationID, identity: identity,
                    activated: intent.advancing(to: .sessionActivated))
                return true
            } catch { return false } // map inside pool; no arbitrary Error escapes
        }
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-read-complete")
#endif
        try attempt.endRead(valid: valid)
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-dispose-enter")
#endif
        _ = try attempt.disposeValidatedCopy()
#if DEBUG
        print("C46_ERASE_ADVANCE_V1 stage=target-dispose-complete")
#endif
        return attempt
    }
}


@MainActor
final class EraseColdPreparationFailureDrainWitnessV1 {
    private weak var operation: EraseColdPreparationOperationV1?
    private let registry: GenerationLeaseRegistryV1
    private let observations: [EraseSessionWeakObservationV1]
    private let readers: [GenerationLeaseAllocationAttemptV1]
    private var disposed = false

    fileprivate init(operation: EraseColdPreparationOperationV1, registry: GenerationLeaseRegistryV1,
        observations: [EraseSessionWeakObservationV1], readers: [GenerationLeaseAllocationAttemptV1]) {
        self.operation = operation; self.registry = registry
        self.observations = observations; self.readers = readers
    }

    private func requireDrained(registry expected: GenerationLeaseRegistryV1) throws {
        guard let operation, expected === registry,
              observations.allSatisfy({ $0.isDrained }),
              readers.allSatisfy({ $0.sealedForRetirement && $0.matches(registry: registry) }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try operation.requireFailureDisposal(witness: self, registry: registry)
    }

    func requireDrained(registry: GenerationLeaseRegistryV1,
        readerAllocation: GenerationLeaseAllocationAttemptV1) throws {
        guard readers.contains(where: { $0 === readerAllocation }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try requireDrained(registry: registry)
    }

    func disposeOwnedAllocations() throws {
        try requireDrained(registry: registry)
        for reader in readers { try reader.closeAfterColdErasePreparationFailure(proof: self) }
        disposed = true
    }

    func requireDisposed() throws {
        guard disposed else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireDrained(registry: registry)
    }
}

/// A successful cold C05 drain proves the source model aliases disappeared
/// while retaining every exact reader allocation for checked Registry exit.
/// It has no failure-disposal authority and no strong SwiftData reference.
@MainActor
final class EraseC05ColdSourceDrainWitnessV1 {
    private weak var operation: EraseColdPreparationOperationV1?
    private weak var inventory: EraseReaderRetirementInventoryV1?
    private let registry: GenerationLeaseRegistryV1
    private let observations: [EraseSessionWeakObservationV1]
    private let readers: [GenerationLeaseAllocationAttemptV1]

    fileprivate init(
        operation: EraseColdPreparationOperationV1,
        registry: GenerationLeaseRegistryV1,
        inventory: EraseReaderRetirementInventoryV1,
        observations: [EraseSessionWeakObservationV1],
        readers: [GenerationLeaseAllocationAttemptV1]
    ) {
        self.operation = operation
        self.registry = registry
        self.inventory = inventory
        self.observations = observations
        self.readers = readers
    }

    func requireDrained(registry expected: GenerationLeaseRegistryV1) throws {
        guard let operation, inventory != nil, expected === registry,
              observations.allSatisfy({ $0.isDrained }),
              readers.allSatisfy({ $0.sealedForRetirement
                  && $0.matches(registry: registry) }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try operation.requireC05ColdSourceDrainWitness(self, registry: registry)
    }

    func readerAllocations(registry expected: GenerationLeaseRegistryV1)
        throws -> [GenerationLeaseAllocationAttemptV1] {
        try requireDrained(registry: expected)
        return readers
    }
}

/// Value-only observation from the exact Erase-cold manifest owner. It has no
/// independent writer, lease, generation-construction or deletion authority.
struct EraseSchema2ColdGenerationSnapshotV1 {
    let pointer: CurrentGenerationPointerV3
    let manifest: StoreGenerationManifestV1
    let retiredGenerationIDs: [UUID]
    let installedGenerationIDs: Set<UUID>
}

extension StoreGenerationFactory {
    /// No ordinary Restore authority, migration-store constructor, pointer
    /// reconciliation, bootstrap or protection setter is reached here. The
    /// operation already retains the descriptor owner before this call.
    @MainActor
    func observeSchema2ColdCurrent(
        expectedPointer: RestorePointerIdentityV1,
        manifestOwner: EraseSchema2ColdManifestOwnerV1,
        operation: EraseColdPreparationOperationV1
    ) throws -> EraseSchema2ColdGenerationSnapshotV1 {
        try operation.requireSchema2ColdManifestOwner(manifestOwner)
        let current = try manifestOwner.readCurrentManifest(
            expectedPointer: expectedPointer, operation: operation)
        guard case .v3(let pointer, _) = current.pointer else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let physical = try manifestOwner.readGenerationInventory(
            operation: operation)
        let retired: RetiredPointerV1
        do {
            retired = try JSONDecoder().decode(RetiredPointerV1.self,
                from: physical.retiredPointerBytes)
            guard try StoreMigrationCanonicalJSONV1.encode(retired)
                    == physical.retiredPointerBytes else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try StorePointerSchemaRegistry.requireRetired(retired.schemaVersion)
        } catch {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let strings = retired.generationIDs
        guard strings == strings.sorted(), Set(strings).count == strings.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let retiredIDs = strings.compactMap(UUID.init(uuidString:))
        let installedIDs = physical.installedNames.compactMap(UUID.init(uuidString:))
        guard retiredIDs.count == strings.count,
              installedIDs.count == physical.installedNames.count,
              Set(installedIDs).count == installedIDs.count,
              zip(retiredIDs, strings).allSatisfy({
                  $0.0.uuidString.lowercased() == $0.1
              }),
              zip(installedIDs, physical.installedNames).allSatisfy({
                  $0.0.uuidString.lowercased() == $0.1
              }),
              current.manifest.generationID == expectedPointer.generationID,
              current.manifest.storeSchemaRelease.versionIdentifier.major
                == pointer.storeSchemaVersion else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return EraseSchema2ColdGenerationSnapshotV1(
            pointer: pointer, manifest: current.manifest,
            retiredGenerationIDs: retiredIDs,
            installedGenerationIDs: Set(installedIDs))
    }
}

// The schema-2 late Erase path has no durable Registry token after its
// recursive cut. This worker borrows only the operation's already captured
// target FD and a private, operation-retained staging FD. It cannot publish a
// generation, open an ordinary Store authority, or create a lease.
private enum EraseSchema2ColdTempAncestryV1 {
    static func requireDisjoint(parent: Int32, canonicalURL: URL,
        configuredURL: URL, heldSupport: (dev_t, ino_t),
        io: EraseAbortCheckedSnapshotIOV1) throws {
        func identity(_ descriptor: Int32) throws -> (dev_t, ino_t) {
            var value = stat()
            guard Darwin.fstat(descriptor, &value) == 0,
                  value.st_mode & S_IFMT == S_IFDIR,
                  value.st_nlink > 0 else {
                throw EraseAllServiceError.invalidAuthority
            }
            return (value.st_dev, value.st_ino)
        }
        guard canonicalURL.isFileURL,
              configuredURL.resolvingSymlinksInPath().standardizedFileURL
                == canonicalURL else {
            throw EraseAllServiceError.invalidAuthority
        }
        let expected = try identity(parent)
        var named = stat()
        guard Darwin.lstat(canonicalURL.path, &named) == 0,
              named.st_mode & S_IFMT == S_IFDIR,
              named.st_dev == expected.0,
              named.st_ino == expected.1 else {
            throw EraseAllServiceError.invalidAuthority
        }
        func walk(_ descriptor: Int32, depth: Int) throws {
            guard depth < 128 else { throw EraseAllServiceError.invalidAuthority }
            let current = try identity(descriptor)
            guard current != heldSupport else {
                throw EraseAllServiceError.invalidAuthority
            }
            try io.withOpen(parent: descriptor, name: "..",
                flags: O_RDONLY | O_DIRECTORY) { ancestor in
                let prior = try identity(ancestor)
                if prior != current { try walk(ancestor, depth: depth + 1) }
            }
        }
        try walk(parent, depth: 0)
        try io.requireSettled()
        guard try identity(parent) == expected,
              configuredURL.resolvingSymlinksInPath().standardizedFileURL
                == canonicalURL else {
            throw EraseAllServiceError.invalidAuthority
        }
    }
}

private final class EraseSchema2ColdPrivateCopyWorkerV1: @unchecked Sendable {
    private let source: Int32
    private let parent: Int32
    private let staging: Int32
    private let stagingURL: URL
    private let stagingIdentity: (dev_t, ino_t)
    private let configuredTemporaryDirectoryURL: URL
    private let heldSupportIdentity: (dev_t, ino_t)
    let io = EraseAbortCheckedSnapshotIOV1()
    private(set) var sourceDigest: String?
    private(set) var files: [String: (dev_t, ino_t)] = [:]
    private(set) var directories: [String: (dev_t, ino_t)] = [:]
    private(set) var copiedModel = false
    private var uncertainCreatedFiles: [Int32] = []

    init(source: Int32, parent: Int32, staging: Int32,
        stagingURL: URL, stagingIdentity: (dev_t, ino_t),
        configuredTemporaryDirectoryURL: URL,
        heldSupportIdentity: (dev_t, ino_t)) {
        self.source = source; self.parent = parent
        self.staging = staging; self.stagingURL = stagingURL
        self.stagingIdentity = stagingIdentity
        self.configuredTemporaryDirectoryURL = configuredTemporaryDirectoryURL
        self.heldSupportIdentity = heldSupportIdentity
    }

    private func requireStagingRoot() throws {
        try EraseSchema2ColdTempAncestryV1.requireDisjoint(
            parent: parent, canonicalURL: stagingURL.deletingLastPathComponent(),
            configuredURL: configuredTemporaryDirectoryURL,
            heldSupport: heldSupportIdentity, io: io)
        let held = try identity(staging, directory: true)
        var named = stat(), path = stat(), parentHeld = stat(), parentNamed = stat()
        guard held.st_dev == stagingIdentity.0,
              held.st_ino == stagingIdentity.1,
              Darwin.fstatat(parent, stagingURL.lastPathComponent,
                &named, AT_SYMLINK_NOFOLLOW) == 0,
              Darwin.lstat(stagingURL.path, &path) == 0,
              named.st_mode & S_IFMT == S_IFDIR,
              named.st_dev == held.st_dev, named.st_ino == held.st_ino,
              path.st_dev == held.st_dev, path.st_ino == held.st_ino,
              Darwin.fstat(parent, &parentHeld) == 0,
              Darwin.lstat(stagingURL.deletingLastPathComponent().path,
                &parentNamed) == 0,
              parentHeld.st_mode & S_IFMT == S_IFDIR,
              parentHeld.st_dev == parentNamed.st_dev,
              parentHeld.st_ino == parentNamed.st_ino else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private func identity(_ descriptor: Int32, directory: Bool) throws -> stat {
        var value = stat()
        guard Darwin.fstat(descriptor, &value) == 0,
              value.st_mode & S_IFMT == (directory ? S_IFDIR : S_IFREG),
              value.st_nlink > 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return value
    }

    private func requireSame(_ first: stat, _ second: stat) throws {
        guard first.st_dev == second.st_dev, first.st_ino == second.st_ino,
              first.st_mode == second.st_mode, first.st_nlink == second.st_nlink,
              first.st_size == second.st_size,
              first.st_mtimespec.tv_sec == second.st_mtimespec.tv_sec,
              first.st_mtimespec.tv_nsec == second.st_mtimespec.tv_nsec,
              first.st_ctimespec.tv_sec == second.st_ctimespec.tv_sec,
              first.st_ctimespec.tv_nsec == second.st_ctimespec.tv_nsec else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private func digest(_ descriptor: Int32) throws -> String {
        guard Darwin.lseek(descriptor, 0, SEEK_SET) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var hash = SHA256()
        var buffer = [UInt8](repeating: 0, count: 64 * 1024)
        while true {
            let count = buffer.withUnsafeMutableBytes {
                Darwin.read(descriptor, $0.baseAddress, $0.count)
            }
            if count > 0 { hash.update(data: Data(buffer.prefix(count))) }
            else if count == 0 { break }
            else if errno != EINTR { throw StoreGenerationFailure.dataPointerInvalid }
        }
        return hash.finalize().map { String(format: "%02x", $0) }.joined()
    }

    private func copyFile(sourceParent: Int32, targetParent: Int32,
        name: String, path: String) throws {
        try requireStagingRoot()
        _ = try GenerationOwnedPathV1.classify(path, nodeType: .regularFile)
        try io.withOpen(parent: sourceParent, name: name,
            flags: O_RDONLY | O_NONBLOCK) { input in
            let before = try identity(input, directory: false)
            guard before.st_nlink == 1, before.st_size >= 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var named = stat()
            guard Darwin.fstatat(sourceParent, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try requireSame(before, named)
            let output = Darwin.openat(targetParent, name,
                O_RDWR | O_CREAT | O_EXCL | O_NOFOLLOW | O_CLOEXEC,
                mode_t(0o600))
            guard output >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
            var closeAttempted = false
            var outputFact = stat()
            var expectedDigest = ""
            do {
            var buffer = [UInt8](repeating: 0, count: 64 * 1024)
            var copied: off_t = 0
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(input, $0.baseAddress, $0.count)
                }
                if count == 0 { break }
                if count < 0 {
                    if errno == EINTR { continue }
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                guard copied <= before.st_size - off_t(count) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                copied += off_t(count)
                guard copied <= before.st_size else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                var offset = 0
                while offset < count {
                    let written = buffer.withUnsafeBytes {
                        Darwin.write(output, $0.baseAddress!.advanced(by: offset),
                            count - offset)
                    }
                    if written < 0 && errno == EINTR { continue }
                    guard written > 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    offset += written
                }
            }
            guard copied == before.st_size, Darwin.fsync(output) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let after = try identity(input, directory: false)
            guard Darwin.fstatat(sourceParent, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try requireSame(before, after)
            try requireSame(before, named)
            outputFact = try identity(output, directory: false)
            guard outputFact.st_nlink == 1,
                  outputFact.st_size == before.st_size else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            expectedDigest = try digest(input)
            guard try digest(output) == expectedDigest else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            closeAttempted = true
            guard Darwin.close(output) == 0 else {
                uncertainCreatedFiles.append(output)
                throw StoreGenerationFailure.dataPointerInvalid
            }
            } catch {
                if !closeAttempted, Darwin.close(output) != 0 {
                    uncertainCreatedFiles.append(output)
                }
                throw error
            }
            let url = stagingURL.appendingPathComponent(path)
            try ProtectedFilePolicyV1.applyAndVerifyEraseColdPrivateWithCheckedClose(
                .stagingFile, at: url,
                retainUncertainDescriptor: { self.uncertainCreatedFiles.append($0) },
                authorityCheck: {
                    try self.requireStagingRoot()
                    var namedFile = stat()
                    guard Darwin.fstatat(targetParent, name, &namedFile,
                            AT_SYMLINK_NOFOLLOW) == 0,
                          namedFile.st_mode & S_IFMT == S_IFREG,
                          namedFile.st_dev == outputFact.st_dev,
                          namedFile.st_ino == outputFact.st_ino else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                })
            var final = stat()
            guard Darwin.fstatat(targetParent, name, &final,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  final.st_mode & S_IFMT == S_IFREG,
                  final.st_nlink == 1,
                  final.st_dev == outputFact.st_dev,
                  final.st_ino == outputFact.st_ino else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try io.withOpen(parent: targetParent, name: name,
                flags: O_RDONLY | O_NONBLOCK) { readback in
                guard try digest(readback) == expectedDigest else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            files[path] = (final.st_dev, final.st_ino)
            if path == "model.sqlite" { copiedModel = true }
        }
    }

    private func copyDirectory(sourceRoot: Int32, targetRoot: Int32,
        prefix: String, depth: Int) throws {
        guard depth <= 64, files.count + directories.count < 100_000 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let names = try io.names(in: sourceRoot)
        for name in names {
            guard !name.isEmpty, name != ".", name != "..",
                  !name.contains("/"), !name.contains("\u{0}") else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let path = prefix.isEmpty ? name : "\(prefix)/\(name)"
            var named = stat()
            guard Darwin.fstatat(sourceRoot, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            switch named.st_mode & S_IFMT {
            case S_IFDIR:
                try requireStagingRoot()
                _ = try GenerationOwnedPathV1.classify(path, nodeType: .directory)
                guard Darwin.mkdirat(targetRoot, name, mode_t(0o700)) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try io.withOpen(parent: sourceRoot, name: name,
                    flags: O_RDONLY | O_DIRECTORY) { childSource in
                    try io.withOpen(parent: targetRoot, name: name,
                        flags: O_RDONLY | O_DIRECTORY) { childTarget in
                        try copyDirectory(sourceRoot: childSource,
                            targetRoot: childTarget, prefix: path, depth: depth + 1)
                        guard Darwin.fsync(childTarget) == 0 else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                }
                let url = stagingURL.appendingPathComponent(path, isDirectory: true)
                try ProtectedFilePolicyV1.applyAndVerifyEraseColdPrivateWithCheckedClose(
                    .stagingDirectory, at: url,
                    retainUncertainDescriptor: { self.uncertainCreatedFiles.append($0) },
                    authorityCheck: {
                        try self.requireStagingRoot()
                        var childNamed = stat()
                        guard Darwin.fstatat(targetRoot, name, &childNamed,
                                AT_SYMLINK_NOFOLLOW) == 0,
                              childNamed.st_mode & S_IFMT == S_IFDIR else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    })
                var final = stat()
                guard Darwin.fstatat(targetRoot, name, &final,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      final.st_mode & S_IFMT == S_IFDIR else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                directories[path] = (final.st_dev, final.st_ino)
            case S_IFREG:
                try requireStagingRoot()
                try copyFile(sourceParent: sourceRoot, targetParent: targetRoot,
                    name: name, path: path)
            default:
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        guard try io.names(in: sourceRoot) == names,
              Darwin.fsync(targetRoot) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    func copy() -> Bool {
        do {
            try requireStagingRoot()
            guard try io.names(in: staging).isEmpty else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let before = try io.postRetiredTree(parent: source, name: ".")
            try copyDirectory(sourceRoot: source, targetRoot: staging,
                prefix: "", depth: 0)
            guard copiedModel,
                  try io.postRetiredTree(parent: source, name: ".") == before else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try io.requireSettled()
            try requireStagingRoot()
            guard uncertainCreatedFiles.isEmpty else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            sourceDigest = before
            return true
        } catch { return false }
    }

    func requireOriginalUnchanged(sourceRoot: Int32) throws {
        guard let sourceDigest,
              try io.postRetiredTree(parent: sourceRoot, name: ".") == sourceDigest else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try io.requireSettled()
        guard uncertainCreatedFiles.isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private func withDirectory<T>(_ path: String,
        _ body: (Int32) throws -> T) throws -> T {
        let parts = path.split(separator: "/").map(String.init)
        func walk(_ descriptor: Int32, _ index: Int) throws -> T {
            if index == parts.count { return try body(descriptor) }
            return try io.withOpen(parent: descriptor, name: parts[index],
                flags: O_RDONLY | O_DIRECTORY) { child in
                let key = parts.prefix(index + 1).joined(separator: "/")
                guard let expected = directories[key] else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let observed = try identity(child, directory: true)
                guard observed.st_dev == expected.0,
                      observed.st_ino == expected.1 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                return try walk(child, index + 1)
            }
        }
        return try walk(staging, 0)
    }

    private func requireExpectedTree(
        directory: Int32, prefix: String,
        expectedFiles: [String: (dev_t, ino_t)]
    ) throws {
        let expected = Set(expectedFiles.keys.compactMap { path -> String? in
            let parent = path.split(separator: "/").dropLast().joined(separator: "/")
            return parent == prefix ? String(path.split(separator: "/").last!) : nil
        }).union(directories.keys.compactMap { path -> String? in
            let parent = path.split(separator: "/").dropLast().joined(separator: "/")
            return parent == prefix ? String(path.split(separator: "/").last!) : nil
        })
        guard Set(try io.names(in: directory)) == expected else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        for name in expected.sorted() {
            let path = prefix.isEmpty ? name : "\(prefix)/\(name)"
            var named = stat()
            guard Darwin.fstatat(directory, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if let file = expectedFiles[path] {
                guard named.st_mode & S_IFMT == S_IFREG,
                      named.st_nlink == 1,
                      named.st_dev == file.0, named.st_ino == file.1 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            } else if let ownedDirectory = directories[path] {
                guard named.st_mode & S_IFMT == S_IFDIR,
                      named.st_dev == ownedDirectory.0,
                      named.st_ino == ownedDirectory.1 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try io.withOpen(parent: directory, name: name,
                    flags: O_RDONLY | O_DIRECTORY) { child in
                    try requireExpectedTree(directory: child, prefix: path,
                        expectedFiles: expectedFiles)
                }
            } else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
    }

    /// SwiftData's read-only SQLite open may need writable WAL/SHM siblings
    /// in its disposable copy. Own their names and inodes *before* entering
    /// the constructor; never adopt a newly found post-read sidecar.
    func preparePrivateReadSidecars() throws {
        guard sourceDigest != nil, copiedModel else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireStagingRoot()
        try io.requireSettled()
        for sidecar in ["model.sqlite-wal", "model.sqlite-shm"] where files[sidecar] == nil {
            var absent = stat()
            guard Darwin.fstatat(staging, sidecar, &absent,
                    AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let descriptor = Darwin.openat(staging, sidecar,
                O_RDWR | O_CREAT | O_EXCL | O_NOFOLLOW | O_CLOEXEC,
                mode_t(0o600))
            guard descriptor >= 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var closeAttempted = false
            let captured: stat
            do {
                captured = try identity(descriptor, directory: false)
                guard captured.st_nlink == 1, captured.st_size == 0,
                      Darwin.fsync(descriptor) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                var named = stat()
                guard Darwin.fstatat(staging, sidecar, &named,
                        AT_SYMLINK_NOFOLLOW) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try requireSame(captured, named)
                closeAttempted = true
                guard Darwin.close(descriptor) == 0 else {
                    uncertainCreatedFiles.append(descriptor)
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            } catch {
                if !closeAttempted, Darwin.close(descriptor) != 0 {
                    uncertainCreatedFiles.append(descriptor)
                }
                throw error
            }
            files[sidecar] = (captured.st_dev, captured.st_ino)
            try ProtectedFilePolicyV1.applyAndVerifyEraseColdPrivateWithCheckedClose(
                .stagingFile,
                at: stagingURL.appendingPathComponent(sidecar),
                retainUncertainDescriptor: { self.uncertainCreatedFiles.append($0) },
                authorityCheck: {
                    try self.requireStagingRoot()
                    var named = stat()
                    guard Darwin.fstatat(self.staging, sidecar, &named,
                            AT_SYMLINK_NOFOLLOW) == 0,
                          named.st_mode & S_IFMT == S_IFREG,
                          named.st_nlink == 1,
                          named.st_dev == captured.st_dev,
                          named.st_ino == captured.st_ino else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                })
        }
        guard Darwin.fsync(staging) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try io.requireSettled()
        guard uncertainCreatedFiles.isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    func removeValidatedCopy() throws {
        try requireStagingRoot()
        guard sourceDigest != nil else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireExpectedTree(directory: staging, prefix: "",
            expectedFiles: files)
        for path in files.keys.sorted(by: >) {
            try requireStagingRoot()
            let parts = path.split(separator: "/").map(String.init)
            let parent = parts.dropLast().joined(separator: "/")
            try withDirectory(parent) { directory in
                var named = stat()
                guard let expected = files[path],
                      Darwin.fstatat(directory, parts.last!, &named,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      named.st_mode & S_IFMT == S_IFREG,
                      named.st_nlink == 1,
                      named.st_dev == expected.0,
                      named.st_ino == expected.1,
                      Darwin.unlinkat(directory, parts.last!, 0) == 0,
                      Darwin.fsync(directory) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        let byDepth = directories.keys.sorted {
            let lhs = $0.split(separator: "/").count
            let rhs = $1.split(separator: "/").count
            return lhs == rhs ? $0 > $1 : lhs > rhs
        }
        for path in byDepth {
            try requireStagingRoot()
            let parts = path.split(separator: "/").map(String.init)
            let parent = parts.dropLast().joined(separator: "/")
            try withDirectory(parent) { directory in
                var named = stat()
                guard let expected = directories[path],
                      Darwin.fstatat(directory, parts.last!, &named,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      named.st_mode & S_IFMT == S_IFDIR,
                      named.st_dev == expected.0,
                      named.st_ino == expected.1,
                      try io.names(in: directory).contains(parts.last!) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try io.withOpen(parent: directory, name: parts.last!,
                    flags: O_RDONLY | O_DIRECTORY) { child in
                    guard try io.names(in: child).isEmpty else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
                guard Darwin.unlinkat(directory, parts.last!, AT_REMOVEDIR) == 0,
                      Darwin.fsync(directory) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        guard try io.names(in: staging).isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try io.requireSettled()
    }
}

/// The target's manifest is authenticated independently of the current
/// pointer. A pointer-switched crash may still leave the old pointer current.
struct EraseSchema2ColdTargetSnapshotV1 {
    let currentPointer: CurrentGenerationPointerV3
    let pointer: CurrentGenerationPointerV3
    let manifest: StoreGenerationManifestV1
    let retiredGenerationIDs: [UUID]
    let installedGenerationIDs: Set<UUID>
}

enum EraseSchema2ColdTargetValidationStageV1: Equatable {
    case preparedTargetCurrent
    case preactivation
    case activated
}

/// A live target constructor may checkpoint SQLite or rewrite its shared
/// memory file. This witness is captured around only that constructor, under
/// the retained cold G and Support EX, using one operation-owned checked IO.
/// It never admits a new non-SQLite tree baseline.
struct EraseSchema2ColdTargetLiveOpenPhysicalV1 {
    struct Before {
        fileprivate let nodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode]
        fileprivate let sqlite: CompletedAbortSQLitePhysicalImageV1
        fileprivate let validationAttempt: EraseSchema2ColdTargetValidationAttemptV1
        fileprivate let snapshot: EraseSchema2ColdTargetSnapshotV1
        fileprivate let stage: EraseSchema2ColdTargetValidationStageV1
    }

    private let before: Before
    private let after: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode]

    var beforeNodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode] {
        before.nodes
    }
    var afterNodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode] {
        after
    }

    @MainActor
    static func captureBefore(root: Int32,
        validationAttempt: EraseSchema2ColdTargetValidationAttemptV1,
        snapshot: EraseSchema2ColdTargetSnapshotV1,
        stage: EraseSchema2ColdTargetValidationStageV1,
        io: EraseAbortCheckedSnapshotIOV1) throws -> Before {
        switch stage {
        case .preparedTargetCurrent:
            throw StoreGenerationFailure.dataPointerInvalid
        case .preactivation:
            try validationAttempt.requireRecordedPreactivation(
                snapshot: snapshot)
            try validationAttempt.requireExactPreactivationTree(root: root)
        case .activated:
            try validationAttempt.requireRecordedActivated(
                snapshot: snapshot)
            try validationAttempt.requireExactActivatedTree(root: root)
        }
        let nodes = try io.treeWithNodes(parent: root, name: ".").nodes
        switch stage {
        case .preparedTargetCurrent:
            throw StoreGenerationFailure.dataPointerInvalid
        case .preactivation:
            try validationAttempt.requireExactPreactivationTree(root: root)
        case .activated:
            try validationAttempt.requireExactActivatedTree(root: root)
        }
        let sqlite = try captureSQLite(root: root, nodes: nodes, io: io)
        try io.requireSettled()
        return Before(nodes: nodes, sqlite: sqlite,
            validationAttempt: validationAttempt, snapshot: snapshot,
            stage: stage)
    }

    init(before: Before, root: Int32,
        io: EraseAbortCheckedSnapshotIOV1) throws {
        let after = try io.treeWithNodes(parent: root, name: ".").nodes
        guard before.nodes.count == after.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        for (old, new) in zip(before.nodes, after) {
            guard old.path == new.path else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            switch old.path {
            case "":
                // SQLite may create and remove a transient journal under the
                // exclusively held root. Final membership is exactly the
                // same; the root inode, policy-relevant mode and link count
                // remain fixed. Size and timestamps may reflect that owned
                // constructor interval; exact final membership is checked.
                guard old.fact.st_dev == new.fact.st_dev,
                      old.fact.st_ino == new.fact.st_ino,
                      old.fact.st_mode == new.fact.st_mode,
                      old.fact.st_nlink == new.fact.st_nlink else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            case "model.sqlite", "model.sqlite-wal":
                try Self.requireSameLeafIdentity(old, new)
            case "model.sqlite-shm":
                try Self.requireSameLeafIdentity(old, new)
                guard old.fact.st_size == new.fact.st_size else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            default:
                guard Self.sameFullFact(old.fact, new.fact),
                      old.sha256 == new.sha256 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        let postSQLite = try Self.captureSQLite(root: root, nodes: after, io: io)
        try before.sqlite.requireOwnedCloseTransition(to: postSQLite)
        try io.requireSettled()
        self.before = before
        self.after = after
    }

    func requireExactProof() throws {
        guard before.nodes.count == after.count,
              before.nodes.contains(where: { $0.path == "model.sqlite" }) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    @MainActor
    private func requireBoundToValidation(
        attempt: EraseSchema2ColdTargetValidationAttemptV1,
        snapshot: EraseSchema2ColdTargetSnapshotV1,
        stage: EraseSchema2ColdTargetValidationStageV1
    ) throws {
        guard before.validationAttempt === attempt,
              before.stage == stage,
              before.snapshot.currentPointer == snapshot.currentPointer,
              before.snapshot.pointer == snapshot.pointer,
              before.snapshot.manifest == snapshot.manifest,
              before.snapshot.installedGenerationIDs
                == snapshot.installedGenerationIDs,
              before.snapshot.retiredGenerationIDs
                == snapshot.retiredGenerationIDs else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        switch stage {
        case .preparedTargetCurrent:
            throw StoreGenerationFailure.dataPointerInvalid
        case .preactivation:
            try attempt.requireRecordedPreactivation(snapshot: snapshot)
        case .activated:
            try attempt.requireRecordedActivated(snapshot: snapshot)
        }
        try requireExactProof()
    }

    @MainActor
    func requireBoundToPreactivation(
        attempt: EraseSchema2ColdTargetValidationAttemptV1,
        snapshot: EraseSchema2ColdTargetSnapshotV1
    ) throws {
        try requireBoundToValidation(attempt: attempt,
            snapshot: snapshot, stage: .preactivation)
    }

    @MainActor
    func requireBoundToActivated(
        attempt: EraseSchema2ColdTargetValidationAttemptV1,
        snapshot: EraseSchema2ColdTargetSnapshotV1
    ) throws {
        try requireBoundToValidation(attempt: attempt,
            snapshot: snapshot, stage: .activated)
    }

    func requireCurrentPostimage(root: Int32,
        io: EraseAbortCheckedSnapshotIOV1) throws {
        let current = try io.treeWithNodes(parent: root, name: ".").nodes
        guard current.count == after.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        for (expected, observed) in zip(after, current) {
            guard expected.path == observed.path,
                  Self.sameFullFact(expected.fact, observed.fact),
                  expected.sha256 == observed.sha256 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        try io.requireSettled()
    }

    private static func captureSQLite(root: Int32,
        nodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode],
        io: EraseAbortCheckedSnapshotIOV1)
        throws -> CompletedAbortSQLitePhysicalImageV1 {
        guard let modelNode = nodes.first(where: {
            $0.path == "model.sqlite"
        }) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return try io.withOpen(parent: root, name: "model.sqlite",
            flags: O_RDONLY | O_NONBLOCK) { model in
            try requireExactOpenedLeaf(model, parent: root,
                name: "model.sqlite", node: modelNode)
            let image: CompletedAbortSQLitePhysicalImageV1
            if let walNode = nodes.first(where: {
                $0.path == "model.sqlite-wal"
            }) {
                image = try io.withOpen(parent: root,
                    name: "model.sqlite-wal",
                    flags: O_RDONLY | O_NONBLOCK) { wal in
                    try requireExactOpenedLeaf(wal, parent: root,
                        name: "model.sqlite-wal", node: walNode)
                    let captured = try CompletedAbortSQLitePhysicalImageV1
                        .capture(model: model, wal: wal)
                    try requireExactOpenedLeaf(wal, parent: root,
                        name: "model.sqlite-wal", node: walNode)
                    return captured
                }
            } else {
                image = try CompletedAbortSQLitePhysicalImageV1.capture(
                    model: model, wal: nil)
            }
            try requireExactOpenedLeaf(model, parent: root,
                name: "model.sqlite", node: modelNode)
            return image
        }
    }

    private static func requireExactOpenedLeaf(_ descriptor: Int32,
        parent: Int32, name: String,
        node: EraseAbortCheckedSnapshotIOV1.CheckedTreeNode) throws {
        var held = stat(), named = stat()
        guard Darwin.fstat(descriptor, &held) == 0,
              Darwin.fstatat(parent, name, &named,
                AT_SYMLINK_NOFOLLOW) == 0,
              sameFullFact(held, node.fact),
              sameFullFact(named, node.fact) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private static func requireSameLeafIdentity(
        _ old: EraseAbortCheckedSnapshotIOV1.CheckedTreeNode,
        _ new: EraseAbortCheckedSnapshotIOV1.CheckedTreeNode
    ) throws {
        guard old.fact.st_dev == new.fact.st_dev,
              old.fact.st_ino == new.fact.st_ino,
              old.fact.st_mode == new.fact.st_mode,
              old.fact.st_nlink == new.fact.st_nlink,
              old.fact.st_nlink == 1 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private static func sameFullFact(_ a: stat, _ b: stat) -> Bool {
        a.st_dev == b.st_dev && a.st_ino == b.st_ino &&
        a.st_mode == b.st_mode && a.st_nlink == b.st_nlink &&
        a.st_size == b.st_size &&
        a.st_mtimespec.tv_sec == b.st_mtimespec.tv_sec &&
        a.st_mtimespec.tv_nsec == b.st_mtimespec.tv_nsec &&
        a.st_ctimespec.tv_sec == b.st_ctimespec.tv_sec &&
        a.st_ctimespec.tv_nsec == b.st_ctimespec.tv_nsec
    }
}

@MainActor
final class EraseSchema2ColdTargetValidationAttemptV1 {
    private enum Phase { case registered, copying, copied, reading,
        validated, disposing, ready, uncertain }
    private weak var operation: EraseColdPreparationOperationV1?
    private let source: EraseSchema2ColdTargetSourceV1
    private let snapshot: EraseSchema2ColdTargetSnapshotV1
    private let intent: EraseIntentV1
    private let validationStage: EraseSchema2ColdTargetValidationStageV1
    private let configuredTemporaryDirectoryURL: URL
    private let temporaryDirectoryURL: URL
    private let copyID = UUID()
    private var phase: Phase = .registered
    private var tempParent: Int32 = -1
    private var tempChild: Int32 = -1
    private var copiedSource: Int32 = -1
    private var uncertainFDs: [Int32] = []
    private var parentIdentity: (dev_t, ino_t)?
    private var childIdentity: (dev_t, ino_t)?
    private var worker: EraseSchema2ColdPrivateCopyWorkerV1?
    private var copyTask: Task<Bool, Never>?
    private weak var privateContainer: ModelContainer?
    private weak var privateContext: ModelContext?
    private var containerObserved = false
    private let ancestryIO = EraseAbortCheckedSnapshotIOV1()

    var isCheckedClosed: Bool {
        guard phase == .ready, tempParent < 0, tempChild < 0,
              copiedSource < 0, copyTask == nil,
              privateContainer == nil, privateContext == nil,
              uncertainFDs.isEmpty else { return false }
        return (try? ancestryIO.requireSettled()) != nil
    }

    var validatedStage: EraseSchema2ColdTargetValidationStageV1 {
        validationStage
    }

    private func requireRecordedValidation(
        snapshot expectedSnapshot: EraseSchema2ColdTargetSnapshotV1,
        stage expectedStage: EraseSchema2ColdTargetValidationStageV1
    ) throws {
        guard validationStage == expectedStage, isCheckedClosed,
              snapshot.currentPointer == expectedSnapshot.currentPointer,
              snapshot.pointer == expectedSnapshot.pointer,
              snapshot.manifest == expectedSnapshot.manifest,
              snapshot.installedGenerationIDs
                == expectedSnapshot.installedGenerationIDs,
              snapshot.retiredGenerationIDs
                == expectedSnapshot.retiredGenerationIDs else {
            throw EraseAllServiceError.invalidAuthority
        }
    }

    private func requireExactValidatedTree(
        root: Int32,
        stage: EraseSchema2ColdTargetValidationStageV1
    ) throws {
        try requireRecordedValidation(snapshot: snapshot, stage: stage)
        guard let worker else { throw EraseAllServiceError.invalidAuthority }
        try worker.requireOriginalUnchanged(sourceRoot: root)
    }

    private func requireCompletedValidation(
        source expectedSource: EraseSchema2ColdTargetSourceV1,
        snapshot expectedSnapshot: EraseSchema2ColdTargetSnapshotV1,
        intent expectedIntent: EraseIntentV1,
        stage expectedStage: EraseSchema2ColdTargetValidationStageV1
    ) throws {
        try requireRecordedValidation(snapshot: expectedSnapshot,
            stage: expectedStage)
        guard source === expectedSource,
              intent == expectedIntent else {
            throw EraseAllServiceError.invalidAuthority
        }
        _ = try requireBound()
        try source.withHeldTargetRoot { descriptor in
            try requireExactValidatedTree(root: descriptor,
                stage: expectedStage)
        }
    }

    func requireRecordedPreactivation(
        snapshot expectedSnapshot: EraseSchema2ColdTargetSnapshotV1
    ) throws {
        try requireRecordedValidation(snapshot: expectedSnapshot,
            stage: .preactivation)
    }

    func requireExactPreactivationTree(root: Int32) throws {
        try requireExactValidatedTree(root: root, stage: .preactivation)
    }

    /// P target-current is a private semantic observation only. It is not
    /// interchangeable with the Q preactivation witness used for effects.
    func requireCompletedPreparedTarget(
        source expectedSource: EraseSchema2ColdTargetSourceV1,
        snapshot expectedSnapshot: EraseSchema2ColdTargetSnapshotV1,
        intent expectedIntent: EraseIntentV1
    ) throws {
        try requireCompletedValidation(source: expectedSource,
            snapshot: expectedSnapshot, intent: expectedIntent,
            stage: .preparedTargetCurrent)
    }

    func requireRecordedActivated(
        snapshot expectedSnapshot: EraseSchema2ColdTargetSnapshotV1
    ) throws {
        try requireRecordedValidation(snapshot: expectedSnapshot,
            stage: .activated)
    }

    func requireExactActivatedTree(root: Int32) throws {
        try requireExactValidatedTree(root: root, stage: .activated)
    }

    /// The Router may bind only the completed preactivation proof before a
    /// current-pointer effect. A late activated-copy proof is a different
    /// phase and cannot be substituted for it.
    func requireCompletedPreactivation(
        source expectedSource: EraseSchema2ColdTargetSourceV1,
        snapshot expectedSnapshot: EraseSchema2ColdTargetSnapshotV1,
        intent expectedIntent: EraseIntentV1
    ) throws {
        try requireCompletedValidation(source: expectedSource,
            snapshot: expectedSnapshot, intent: expectedIntent,
            stage: .preactivation)
    }

    /// A fresh authenticated R cut has already published the target pointer.
    /// Its full private activated read is distinct from the P preactivation
    /// witness and cannot authorize a second P→R phase write.
    func requireCompletedActivated(
        source expectedSource: EraseSchema2ColdTargetSourceV1,
        snapshot expectedSnapshot: EraseSchema2ColdTargetSnapshotV1,
        intent expectedIntent: EraseIntentV1
    ) throws {
        try requireCompletedValidation(source: expectedSource,
            snapshot: expectedSnapshot, intent: expectedIntent,
            stage: .activated)
    }

    init(source: EraseSchema2ColdTargetSourceV1,
        snapshot: EraseSchema2ColdTargetSnapshotV1,
        intent: EraseIntentV1, temporaryDirectoryURL: URL,
        operation: EraseColdPreparationOperationV1,
        validationStage: EraseSchema2ColdTargetValidationStageV1) {
        self.source = source; self.snapshot = snapshot; self.intent = intent
        self.validationStage = validationStage
        self.configuredTemporaryDirectoryURL = temporaryDirectoryURL.standardizedFileURL
        self.temporaryDirectoryURL = temporaryDirectoryURL.standardizedFileURL
            .resolvingSymlinksInPath().standardizedFileURL
        self.operation = operation
    }

    private var name: String {
        ".assetrounds-erase-validation-\(copyID.uuidString.lowercased())"
    }
    var modelURL: URL {
        temporaryDirectoryURL.appendingPathComponent(name, isDirectory: true)
            .appendingPathComponent("model.sqlite")
    }

    private func requireBound() throws -> EraseColdPreparationOperationV1 {
        guard let operation, uncertainFDs.isEmpty,
              ((validationStage == .preparedTargetCurrent
                && operation.schema2ColdPreparedTargetValidationAttempt === self)
               || (validationStage != .preparedTargetCurrent
                && operation.schema2ColdTargetValidationAttempt === self)),
              source.generationID == intent.newGenerationID,
              snapshot.pointer.generationID
                == intent.newGenerationID.uuidString.lowercased(),
              snapshot.manifest.generationID == intent.newGenerationID,
              snapshot.manifest.storeSchemaRelease == .v53,
              intent.schemaVersion == 2,
              ((validationStage == .preparedTargetCurrent &&
                    intent.phase == .emptyGenerationPrepared &&
                    snapshot.currentPointer == snapshot.pointer) ||
               (validationStage == .preactivation &&
                    intent.phase == .pointerSwitched) ||
                (validationStage == .activated &&
                    (intent.phase == .sessionActivated ||
                     intent.phase == .cleanupComplete))),
              let target = intent.targetPointer,
              target.generationID == intent.newGenerationID,
              target.generationManifestSHA256
                == snapshot.pointer.generationManifestSHA256,
              target.workspaceID.uuidString.lowercased()
                == snapshot.pointer.workspaceID,
              target.replicaID.uuidString.lowercased()
                == snapshot.pointer.replicaID,
              target.knownReplicaIDs.map({ $0.uuidString.lowercased() })
                == snapshot.pointer.knownReplicaIDs else {
            throw EraseAllServiceError.invalidAuthority
        }
        if validationStage == .preparedTargetCurrent {
            try operation.requireSchema2ColdPreparedTargetValidationAttempt(self)
        } else {
            try operation.requireSchema2ColdTargetValidationAttempt(self)
        }
        try ancestryIO.requireSettled()
        try source.withHeldTargetRoot { _ in () }
        return operation
    }

    private func identity(_ descriptor: Int32) throws -> (dev_t, ino_t) {
        var value = stat()
        guard descriptor >= 0, Darwin.fstat(descriptor, &value) == 0,
              value.st_mode & S_IFMT == S_IFDIR, value.st_nlink > 0 else {
            throw EraseAllServiceError.invalidAuthority
        }
        return (value.st_dev, value.st_ino)
    }

    /// The configured temp parent must remain the exact canonical held root
    /// and must not be Support or any descendant of the original held Support.
    /// Every opened ancestor is checked-closed by the retained attempt owner.
    private func requireDisjointTemporaryParent(
        expected: (dev_t, ino_t)
    ) throws {
        let heldSupport = try source.requireHeldApplicationSupportIdentity()
        try EraseSchema2ColdTempAncestryV1.requireDisjoint(
            parent: tempParent, canonicalURL: temporaryDirectoryURL,
            configuredURL: configuredTemporaryDirectoryURL,
            heldSupport: heldSupport, io: ancestryIO)
        guard try identity(tempParent) == expected else {
            throw EraseAllServiceError.invalidAuthority
        }
    }

    private func requirePrivateRoot() throws {
        guard phase != .uncertain, tempParent >= 0, tempChild >= 0,
              let parentIdentity, let childIdentity else {
            throw EraseAllServiceError.invalidAuthority
        }
        let parent = try identity(tempParent)
        let child = try identity(tempChild)
        try requireDisjointTemporaryParent(expected: parentIdentity)
        var named = stat(), rootNamed = stat()
        guard parent == parentIdentity, child == childIdentity,
              Darwin.lstat(temporaryDirectoryURL.path, &rootNamed) == 0,
              rootNamed.st_mode & S_IFMT == S_IFDIR,
              rootNamed.st_dev == parent.0,
              rootNamed.st_ino == parent.1,
              Darwin.fstatat(tempParent, name, &named,
                AT_SYMLINK_NOFOLLOW) == 0,
              named.st_mode & S_IFMT == S_IFDIR,
              named.st_dev == child.0,
              named.st_ino == child.1 else {
            throw EraseAllServiceError.invalidAuthority
        }
    }

    func requireSource() throws {
        _ = try requireBound()
        if phase == .copied || phase == .reading ||
           phase == .validated || phase == .disposing || phase == .ready {
            guard let worker else { throw EraseAllServiceError.invalidAuthority }
            try source.withHeldTargetRoot { descriptor in
                try worker.requireOriginalUnchanged(sourceRoot: descriptor)
            }
        }
        try requirePrivateRoot()
    }

    func startCopy() async throws {
        guard phase == .registered, copyTask == nil,
              tempParent < 0, tempChild < 0 else {
            throw EraseAllServiceError.invalidAuthority
        }
        _ = try requireBound()
        do {
            let temporary = temporaryDirectoryURL
            guard temporary.isFileURL else {
                throw EraseAllServiceError.invalidAuthority
            }
            // The copy must not modify a parent pinned by the source owner.
            tempParent = Darwin.open(temporary.path,
                O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
            guard tempParent >= 0 else { throw EraseAllServiceError.invalidAuthority }
            let capturedParent = try identity(tempParent)
            parentIdentity = capturedParent
            try requireDisjointTemporaryParent(expected: capturedParent)
            var named = stat()
            guard Darwin.lstat(temporary.path, &named) == 0,
                  named.st_mode & S_IFMT == S_IFDIR,
                  named.st_dev == capturedParent.0,
                  named.st_ino == capturedParent.1,
                  Darwin.mkdirat(tempParent, name, mode_t(0o700)) == 0 else {
                throw EraseAllServiceError.invalidAuthority
            }
            tempChild = Darwin.openat(tempParent, name,
                O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
            guard tempChild >= 0 else { throw EraseAllServiceError.invalidAuthority }
            childIdentity = try identity(tempChild)
            try requirePrivateRoot()
            try ProtectedFilePolicyV1.applyAndVerifyEraseColdPrivateWithCheckedClose(
                .stagingDirectory,
                at: temporary.appendingPathComponent(name, isDirectory: true),
                retainUncertainDescriptor: { self.uncertainFDs.append($0) },
                authorityCheck: { try self.requirePrivateRoot() })
            try source.withHeldTargetRoot { descriptor in
                let captured = Darwin.openat(descriptor, ".",
                    O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
                guard captured >= 0 else { throw EraseAllServiceError.invalidAuthority }
                // Retain before the scoped owner's post-callback reproof can
                // throw; the operation then keeps an ambiguous descriptor.
                copiedSource = captured
                var original = stat(), duplicate = stat()
                guard Darwin.fstat(descriptor, &original) == 0,
                      Darwin.fstat(captured, &duplicate) == 0,
                      original.st_dev == duplicate.st_dev,
                      original.st_ino == duplicate.st_ino,
                      original.st_mode == duplicate.st_mode else {
                    throw EraseAllServiceError.invalidAuthority
                }
            }
            guard let childIdentity else { throw EraseAllServiceError.invalidAuthority }
            let copied = EraseSchema2ColdPrivateCopyWorkerV1(
                source: copiedSource, parent: tempParent, staging: tempChild,
                stagingURL: temporary.appendingPathComponent(name, isDirectory: true),
                stagingIdentity: childIdentity,
                configuredTemporaryDirectoryURL: configuredTemporaryDirectoryURL,
                heldSupportIdentity: try source.requireHeldApplicationSupportIdentity())
            worker = copied // retained before detached task creation
            phase = .copying
            let task = Task.detached(priority: .utility) { copied.copy() }
            copyTask = task
            let completed = await task.value // genuine join, including cancellation
            copyTask = nil
            guard completed else { throw EraseAllServiceError.recoveryRequired }
            _ = try requireBound()
            try requirePrivateRoot()
            try source.withHeldTargetRoot { descriptor in
                try copied.requireOriginalUnchanged(sourceRoot: descriptor)
            }
            let duplicate = copiedSource
            copiedSource = -1 // never retry an ambiguous numeric descriptor
            guard Darwin.close(duplicate) == 0 else {
                uncertainFDs.append(duplicate)
                throw EraseAllServiceError.recoveryRequired
            }
            try copied.preparePrivateReadSidecars()
            try source.withHeldTargetRoot { descriptor in
                try copied.requireOriginalUnchanged(sourceRoot: descriptor)
            }
            phase = .copied
        } catch {
            phase = .uncertain
            throw error
        }
    }

    func beginRead() throws {
        guard phase == .copied, copyTask == nil,
              privateContainer == nil, privateContext == nil else {
            throw EraseAllServiceError.invalidAuthority
        }
        try requireSource()
        phase = .reading
    }

    func observe(_ container: ModelContainer) {
        containerObserved = true
        privateContainer = container
        privateContext = container.mainContext
    }

    func endRead(valid: Bool) throws {
        guard phase == .reading, containerObserved, valid else {
            phase = .uncertain
            throw EraseAllServiceError.recoveryRequired
        }
        try requireSource()
        phase = .validated
    }

    func disposeAfterAliasDrain(source expectedSource: EraseSchema2ColdTargetSourceV1,
        snapshot expectedSnapshot: EraseSchema2ColdTargetSnapshotV1,
        intent expectedIntent: EraseIntentV1,
        validationStage expectedStage: EraseSchema2ColdTargetValidationStageV1) throws -> Bool {
        guard source === expectedSource, intent == expectedIntent,
              validationStage == expectedStage,
              snapshot.currentPointer == expectedSnapshot.currentPointer,
              snapshot.pointer == expectedSnapshot.pointer,
              snapshot.manifest == expectedSnapshot.manifest,
              snapshot.installedGenerationIDs
                == expectedSnapshot.installedGenerationIDs,
              snapshot.retiredGenerationIDs
                == expectedSnapshot.retiredGenerationIDs,
              copyTask == nil, copiedSource < 0 else {
            throw EraseAllServiceError.invalidAuthority
        }
        if phase == .ready {
            _ = try requireBound()
            guard let worker else { throw EraseAllServiceError.invalidAuthority }
            try source.withHeldTargetRoot { descriptor in
                try worker.requireOriginalUnchanged(sourceRoot: descriptor)
            }
            return true
        }
        guard phase == .validated else {
            throw EraseAllServiceError.invalidAuthority
        }
        if privateContainer != nil || privateContext != nil { return false }
        do {
            try requireSource()
            phase = .disposing
            guard let worker else { throw EraseAllServiceError.invalidAuthority }
            try worker.removeValidatedCopy()
            try requirePrivateRoot()
            let child = tempChild
            tempChild = -1
            guard Darwin.close(child) == 0 else {
                uncertainFDs.append(child)
                throw EraseAllServiceError.recoveryRequired
            }
            guard let parentIdentity, let childIdentity,
                  try identity(tempParent) == parentIdentity else {
                throw EraseAllServiceError.invalidAuthority
            }
            try requireDisjointTemporaryParent(expected: parentIdentity)
            var named = stat()
            guard Darwin.fstatat(tempParent, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  named.st_mode & S_IFMT == S_IFDIR,
                  named.st_dev == childIdentity.0,
                  named.st_ino == childIdentity.1,
                  Darwin.unlinkat(tempParent, name, AT_REMOVEDIR) == 0,
                  Darwin.fsync(tempParent) == 0 else {
                throw EraseAllServiceError.invalidAuthority
            }
            let parent = tempParent
            tempParent = -1
            guard Darwin.close(parent) == 0 else {
                uncertainFDs.append(parent)
                throw EraseAllServiceError.recoveryRequired
            }
            try source.withHeldTargetRoot { descriptor in
                try worker.requireOriginalUnchanged(sourceRoot: descriptor)
            }
            phase = .ready
            return true
        } catch {
            phase = .uncertain
            throw error
        }
    }
}

extension StoreGenerationFactory {
    /// The prepared intent is still P. This validates an exact retained
    /// target-current source by private copy without publishing Q or a reader.
    @MainActor
    func validateOrResumeSchema2ColdPreparedTargetCurrent(
        source: EraseSchema2ColdTargetSourceV1,
        snapshot: EraseSchema2ColdTargetSnapshotV1,
        intent: EraseIntentV1,
        temporaryDirectoryURL: URL,
        operation: EraseColdPreparationOperationV1
    ) async throws -> Bool {
        guard intent.phase == .emptyGenerationPrepared,
              snapshot.currentPointer == snapshot.pointer else {
            throw EraseAllServiceError.invalidAuthority
        }
        return try await validateOrResumeSchema2ColdTargetCopy(
            source: source, snapshot: snapshot, intent: intent,
            temporaryDirectoryURL: temporaryDirectoryURL,
            operation: operation, stage: .preparedTargetCurrent)
    }

    /// A pointer-switched target is still a preactivation generation. Its
    /// complete private semantic read grants no live session or phase CAS.
    @MainActor
    func validateOrResumeSchema2ColdPreactivationTarget(
        source: EraseSchema2ColdTargetSourceV1,
        snapshot: EraseSchema2ColdTargetSnapshotV1,
        intent: EraseIntentV1,
        temporaryDirectoryURL: URL,
        operation: EraseColdPreparationOperationV1
    ) async throws -> Bool {
        guard intent.phase == .pointerSwitched else {
            throw EraseAllServiceError.invalidAuthority
        }
        return try await validateOrResumeSchema2ColdTargetCopy(
            source: source, snapshot: snapshot, intent: intent,
            temporaryDirectoryURL: temporaryDirectoryURL,
            operation: operation, stage: .preactivation)
    }

    /// Late schema-2 Erase validates only a private copy of the exact already
    /// held target. The current pointer is the target at these late phases.
    @MainActor
    func validateOrResumeSchema2ColdTarget(
        source: EraseSchema2ColdTargetSourceV1,
        snapshot: EraseSchema2ColdGenerationSnapshotV1,
        intent: EraseIntentV1,
        temporaryDirectoryURL: URL,
        operation: EraseColdPreparationOperationV1
    ) async throws -> Bool {
        guard intent.phase == .sessionActivated ||
                intent.phase == .cleanupComplete,
              snapshot.pointer.generationID
                == intent.newGenerationID.uuidString.lowercased() else {
            throw EraseAllServiceError.invalidAuthority
        }
        let target = EraseSchema2ColdTargetSnapshotV1(
            currentPointer: snapshot.pointer, pointer: snapshot.pointer,
            manifest: snapshot.manifest,
            retiredGenerationIDs: snapshot.retiredGenerationIDs,
            installedGenerationIDs: snapshot.installedGenerationIDs)
        return try await validateOrResumeSchema2ColdTarget(
            source: source, snapshot: target, intent: intent,
            temporaryDirectoryURL: temporaryDirectoryURL,
            operation: operation)
    }

    @MainActor
    func validateOrResumeSchema2ColdTarget(
        source: EraseSchema2ColdTargetSourceV1,
        snapshot: EraseSchema2ColdTargetSnapshotV1,
        intent: EraseIntentV1,
        temporaryDirectoryURL: URL,
        operation: EraseColdPreparationOperationV1
    ) async throws -> Bool {
        guard intent.phase == .sessionActivated ||
                intent.phase == .cleanupComplete,
              snapshot.currentPointer == snapshot.pointer else {
            throw EraseAllServiceError.invalidAuthority
        }
        return try await validateOrResumeSchema2ColdTargetCopy(
            source: source, snapshot: snapshot, intent: intent,
            temporaryDirectoryURL: temporaryDirectoryURL,
            operation: operation, stage: .activated)
    }

    @MainActor
    private func validateOrResumeSchema2ColdTargetCopy(
        source: EraseSchema2ColdTargetSourceV1,
        snapshot: EraseSchema2ColdTargetSnapshotV1,
        intent: EraseIntentV1,
        temporaryDirectoryURL: URL,
        operation: EraseColdPreparationOperationV1,
        stage: EraseSchema2ColdTargetValidationStageV1
    ) async throws -> Bool {
        let retained = stage == .preparedTargetCurrent
            ? operation.schema2ColdPreparedTargetValidationAttempt
            : operation.schema2ColdTargetValidationAttempt
        if let attempt = retained {
            return try attempt.disposeAfterAliasDrain(source: source,
                snapshot: snapshot, intent: intent, validationStage: stage)
        }
        guard intent.schemaVersion == 2,
              ((stage == .preparedTargetCurrent
                  && intent.phase == .emptyGenerationPrepared
                  && snapshot.currentPointer == snapshot.pointer)
                || (stage == .preactivation
                  && intent.phase == .pointerSwitched)
                || (stage == .activated
                  && (intent.phase == .sessionActivated ||
                      intent.phase == .cleanupComplete))),
              intent.newGenerationID == source.generationID,
              snapshot.manifest.storeSchemaRelease == .v53,
              snapshot.manifest.generationID == source.generationID,
              snapshot.installedGenerationIDs.contains(source.generationID),
              let target = intent.targetPointer,
              snapshot.pointer.generationID
                == target.generationID.uuidString.lowercased(),
              target.generationID == source.generationID,
              target.generationManifestSHA256
                == snapshot.pointer.generationManifestSHA256,
              target.workspaceID.uuidString.lowercased()
                == snapshot.pointer.workspaceID,
              target.replicaID.uuidString.lowercased()
                == snapshot.pointer.replicaID,
              target.knownReplicaIDs.map({ $0.uuidString.lowercased() })
                == snapshot.pointer.knownReplicaIDs else {
            throw EraseAllServiceError.invalidAuthority
        }
        let attempt = EraseSchema2ColdTargetValidationAttemptV1(
            source: source, snapshot: snapshot, intent: intent,
            temporaryDirectoryURL: temporaryDirectoryURL,
            operation: operation, validationStage: stage)
        if stage == .preparedTargetCurrent {
            try operation.retainSchema2ColdPreparedTargetValidationAttempt(
                attempt, snapshot: snapshot, intent: intent)
        } else {
            try operation.retainSchema2ColdTargetValidationAttempt(attempt)
        }
        try await attempt.startCopy()
        try attempt.beginRead()
        let valid: Bool = autoreleasepool {
            do {
                let container = try openReadOnlyReleasedContainer(
                    at: attempt.modelURL, release: .v53,
                    markerMigrationID: snapshot.manifest.migrationID,
                    observe: { attempt.observe($0) },
                    afterConstruct: { _ in try attempt.requireSource() })
                let identity = try acceptedV53SemanticIdentity(
                    in: container.mainContext,
                    generationID: source.generationID,
                    migrationID: snapshot.manifest.migrationID)
                let expected = try WorkspaceReplicaIdentityV1(
                    workspaceID: WorkspaceID(rawValue: target.workspaceID),
                    replicaID: ReplicaID(rawValue: target.replicaID))
                guard identity == expected else { return false }
                if stage == .preactivation ||
                    stage == .preparedTargetCurrent {
                    try EraseAllService.requireSchema2ColdPreactivationGraph(
                        context: container.mainContext,
                        generationID: source.generationID,
                        identity: identity,
                        switched: stage == .preparedTargetCurrent
                            ? intent.advancing(to: .pointerSwitched) : intent)
                } else {
                    try EraseAllService.requireEmptyErasePublishedGraph(
                        context: container.mainContext,
                        generationID: source.generationID,
                        identity: identity,
                        activated: intent.advancing(to: .sessionActivated))
                }
                return true
            } catch { return false }
        }
        try attempt.endRead(valid: valid)
        return try attempt.disposeAfterAliasDrain(source: source,
            snapshot: snapshot, intent: intent, validationStage: stage)
    }
}

/// The actual target reader and SwiftData aliases are retained by the same
/// cold operation before any constructor or publication can suspend. A failed
/// constructor leaves the allocation and every returned alias pinned; it
/// cannot be mistaken for a fresh preactivation attempt on retry.
/// A genuine cold target semantic witness. It retains no model alias and
/// cannot become the Original private-copy validation/manifest authority.
@MainActor
final class ColdEraseSchema2TargetSemanticProofV1 {
    private enum State { case validating, validated, detached, readOnlyOpening,
        readOnlyValidated, ready, uncertain }
    let binding: EraseRetirementBindingV1
    private weak var operation: EraseColdPreparationOperationV1?
    private let attempt: EraseSchema2ColdActivatedTargetAttemptV1
    private let source: EraseSchema2ColdTargetSourceV1
    private let physical: EraseSchema2ColdTargetLiveOpenPhysicalV1
    private let activated: EraseIntentV1
    private let aliases: EraseSessionWeakObservationV1
    private weak var drain: EraseSessionDrainWitnessV1?
    private var state: State = .validating
    // This constructor has its own retained checked IO and weak alias census.
    // No return observation, uncertain close, or failed constructor can be
    // retried as a new read or substituted by the earlier live-open proof.
    private let readOnlyIO = EraseAbortCheckedSnapshotIOV1()
    private let readOnlyAliases = EraseSessionWeakObservationV1()
    private var readOnlyBefore: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode]?
    private var readOnlyURL: URL?
    private var terminalPhysicalWitness: ColdEraseSchema2TerminalTargetPhysicalWitnessV1?
    private var terminalTargetObservation: ColdEraseSchema2TerminalTargetObservationV1?
    private weak var terminalTargetOwner: ColdEraseSchema2TerminalOwnerV1?

    fileprivate init(binding: EraseRetirementBindingV1,
        attempt: EraseSchema2ColdActivatedTargetAttemptV1,
        source: EraseSchema2ColdTargetSourceV1,
        physical: EraseSchema2ColdTargetLiveOpenPhysicalV1,
        activated: EraseIntentV1, session: StoreGenerationSession,
        operation: EraseColdPreparationOperationV1) {
        self.binding = binding; self.attempt = attempt; self.source = source
        self.physical = physical; self.activated = activated
        self.operation = operation; aliases = EraseSessionWeakObservationV1(session)
    }

    fileprivate func validate(session: StoreGenerationSession) throws {
        guard state == .validating, let operation,
              aliases.session === session, aliases.context === session.modelContext,
              aliases.container === session.modelContext.container,
              activated.schemaVersion == 2, activated.phase == .sessionActivated,
              activated.eraseID == binding.subject.eraseID,
              activated.newGenerationID == binding.subject.newGenerationID,
              session.generationID == activated.newGenerationID,
              session.generationEpoch == binding.generationEpoch,
              session.workspaceIdentity == binding.workspaceIdentity,
              session.readerLeaseToken == attempt.reader?.token else {
            state = .uncertain
            throw EraseAllServiceError.invalidAuthority
        }
        do {
            try operation.requireColdTargetSemanticProof(self, binding: binding, attempt: attempt)
            try EraseAllService.requireEmptyErasePublishedGraph(context: session.modelContext,
                generationID: session.generationID, identity: session.workspaceIdentity,
                activated: activated)
            guard !session.modelContext.hasChanges,
                  try session.modelContext.fetchCount(FetchDescriptor<MutationReceiptRow>()) == 0 else {
                throw EraseAllServiceError.invalidAuthority
            }
            try source.withColdPostGenerationTargetRoot(operation: operation) { root in
                try physical.requireCurrentPostimage(root: root, io: attempt.physicalIO)
            }
            try attempt.physicalIO.requireSettled()
            try operation.requireColdTargetSemanticProof(self, binding: binding, attempt: attempt)
            state = .validated
        } catch { state = .uncertain; operation.poisonColdScratchOwner(); throw error }
    }

    fileprivate func registerDrain(_ witness: EraseSessionDrainWitnessV1,
        operation expected: EraseColdPreparationOperationV1) throws {
        guard state == .validated, operation === expected, drain == nil,
              witness.binding == binding, let session = aliases.session,
              witness.observes(session: session),
              let reader = attempt.reader, let allocation = attempt.allocation,
              witness.capturedReaders.contains(where: { $0 === reader }),
              witness.capturedAllocations.contains(where: { $0 === allocation }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expected.requireColdTargetSemanticProof(self, binding: binding, attempt: attempt)
        drain = witness
    }

    fileprivate func requireAliasDetachment(attempt expected: EraseSchema2ColdActivatedTargetAttemptV1,
        operation expectedOperation: EraseColdPreparationOperationV1) throws {
        guard state == .validated, attempt === expected, operation === expectedOperation,
              drain != nil, aliases.session === expected.session,
              aliases.container === expected.container else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expectedOperation.requireColdTargetSemanticProof(self, binding: binding, attempt: attempt)
        state = .detached // permanent constructor/model-access fence before nil
    }

    fileprivate func requireValidatedAndDrained(binding expected: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws {
        guard state == .ready, readOnlyAliases.isDrained, binding == expected, drain === witness,
              aliases.isDrained, witness.isActuallyDrained, let operation,
              attempt.session == nil, attempt.container == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        do {
            try operation.requireColdTargetDrain(witness, proof: self, binding: binding)
            if let terminalTargetObservation {
                guard let terminalTargetOwner else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                try terminalTargetObservation.requireSemanticProof(self, binding: binding, witness: witness)
                try terminalTargetObservation.requireCheckedSourceClosed(owner: terminalTargetOwner)
                try terminalTargetObservation.requireCurrent(owner: terminalTargetOwner,
                    witness: witness, binding: binding)
                try readOnlyIO.requireSettled()
            } else {
                try source.withColdPostGenerationTargetRoot(operation: operation) { root in
                    try physical.requireCurrentPostimage(root: root, io: attempt.physicalIO)
                }
                try requireReadOnlyZeroPostimage(operation: operation)
            }
            try attempt.physicalIO.requireSettled()
            guard aliases.isDrained, readOnlyAliases.isDrained, witness.isActuallyDrained else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        } catch { state = .uncertain; operation.poisonColdScratchOwner(); throw error }
    }

    /// Current weak lifetime DATA for polling only. False starts no IO or
    /// constructor; downstream close still requires the complete typed proof.
    fileprivate func requireReadOnlyAliasDrain(binding expected: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws -> Bool {
        guard binding == expected, drain === witness, let operation,
              state == .detached || state == .readOnlyValidated || state == .ready,
              attempt.session == nil, attempt.container == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try operation.requireColdTargetDrain(witness, proof: self, binding: binding)
        return aliases.isDrained && witness.isActuallyDrained
    }

    /// Admit one actual-target read only after the original live aliases are
    /// gone. A nil URL means the same retained read is awaiting disposal or
    /// already complete; it never permits another constructor or baseline.
    fileprivate func beginReadOnlyAfterDrain(binding expected: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws -> URL? {
        guard binding == expected, drain === witness, let operation,
              aliases.isDrained, witness.isActuallyDrained,
              attempt.session == nil, attempt.container == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try operation.requireColdTargetDrain(witness, proof: self, binding: binding)
        switch state {
        case .readOnlyValidated, .ready:
            try requireReadOnlyZeroPostimage(operation: operation)
            return nil
        case .detached: break
        default: throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        do {
            let snapshot = attempt.snapshot
            guard readOnlyBefore == nil, readOnlyURL == nil,
                  snapshot.manifest.storeSchemaRelease == .v53,
                  snapshot.manifest.generationID == binding.subject.newGenerationID,
                  source.generationID == binding.subject.newGenerationID,
                  snapshot.pointer.generationManifestSHA256
                    == binding.generationEpoch.generationManifestSHA256,
                  let target = activated.targetPointer,
                  target.generationID == source.generationID,
                  target.generationManifestSHA256
                    == snapshot.pointer.generationManifestSHA256,
                  target.workspaceID == binding.workspaceIdentity.workspaceID.rawValue,
                  target.replicaID == binding.workspaceIdentity.replicaID.rawValue,
                  target.workspaceID.uuidString.lowercased() == snapshot.pointer.workspaceID,
                  target.replicaID.uuidString.lowercased() == snapshot.pointer.replicaID,
                  target.knownReplicaIDs.map({ $0.uuidString.lowercased() })
                    == snapshot.pointer.knownReplicaIDs else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let url = try source.requireColdPostGenerationModelURL(operation: operation)
            let before = try source.withColdPostGenerationTargetRoot(operation: operation) { root in
                // Live-close changes are not adopted as a fresh target baseline.
                try physical.requireCurrentPostimage(root: root, io: attempt.physicalIO)
                return try readOnlyIO.treeWithNodes(parent: root, name: ".").nodes
            }
            try readOnlyIO.requireSettled()
            try Self.requireExactReadOnlyNodes(physical.afterNodes, before)
            readOnlyBefore = before
            readOnlyURL = url
            try requireReadOnlyZeroPostimage(operation: operation)
            readOnlyAliases.constructionInProgress = true
            readOnlyAliases.constructorStarted = true
            state = .readOnlyOpening // permanent latch before ModelContainer
            return url
        } catch { state = .uncertain; operation.poisonColdScratchOwner(); throw error }
    }

    fileprivate var readOnlyManifest: StoreGenerationManifestV1 { attempt.snapshot.manifest }
    fileprivate var readOnlyActivatedIntent: EraseIntentV1 { activated }

    fileprivate func observeReadOnlyContainer(_ container: ModelContainer) {
        // The sole Factory helper calls this immediately after a real return,
        // before marker, semantic or source reproof can throw.
        readOnlyAliases.container = container
        readOnlyAliases.context = container.mainContext
    }

    fileprivate func requireReadOnlyCurrent() throws {
        guard state == .readOnlyOpening, let operation, let witness = drain,
              aliases.isDrained, witness.isActuallyDrained,
              attempt.session == nil, attempt.container == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try operation.requireColdTargetDrain(witness, proof: self, binding: binding)
        try requireReadOnlyZeroPostimage(operation: operation)
    }

    fileprivate func endReadOnly(valid: Bool) throws {
        readOnlyAliases.constructionInProgress = false
        guard state == .readOnlyOpening, valid, let operation else {
            state = .uncertain
            operation?.poisonColdScratchOwner()
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        do {
            try requireReadOnlyCurrent()
            state = .readOnlyValidated
        } catch { state = .uncertain; operation.poisonColdScratchOwner(); throw error }
    }

    fileprivate func finishReadOnlyAfterDrain(binding expected: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws -> Bool {
        guard binding == expected, drain === witness, let operation,
              state == .readOnlyValidated || state == .ready,
              aliases.isDrained, witness.isActuallyDrained else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        do {
            try operation.requireColdTargetDrain(witness, proof: self, binding: binding)
            try requireReadOnlyZeroPostimage(operation: operation)
            // Waiting retains the same attempt and its original physical image.
            // Failed-nil constructors never reach this edge.
            guard readOnlyAliases.isDrained else { return false }
            try requireReadOnlyZeroPostimage(operation: operation)
            state = .ready
            try requireValidatedAndDrained(binding: expected, witness: witness)
            return true
        } catch { state = .uncertain; operation.poisonColdScratchOwner(); throw error }
    }

    private func requireReadOnlyZeroPostimage(operation: EraseColdPreparationOperationV1) throws {
        guard let before = readOnlyBefore, let readOnlyURL,
              try source.requireColdPostGenerationModelURL(operation: operation) == readOnlyURL else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try source.withColdPostGenerationTargetRoot(operation: operation) { root in
            try physical.requireCurrentPostimage(root: root, io: attempt.physicalIO)
            let after = try readOnlyIO.treeWithNodes(parent: root, name: ".").nodes
            try Self.requireExactReadOnlyNodes(before, after)
        }
        try readOnlyIO.requireSettled()
        try attempt.physicalIO.requireSettled()
    }
    /// The immutable target witness is issued only after this actual read,
    /// full physical ZERO and both real model alias cohorts have drained.
    /// Its consumer still needs a genuine Manifest/terminal-owner scope.
    func makeColdTerminalTargetPhysicalWitness(binding expected: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws -> ColdEraseSchema2TerminalTargetPhysicalWitnessV1 {
        try requireValidatedAndDrained(binding: expected, witness: witness)
        if let terminalPhysicalWitness {
            try terminalPhysicalWitness.requireBound(proof: self, binding: expected, witness: witness)
            return terminalPhysicalWitness
        }
        guard let nodes = readOnlyBefore else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let issued = ColdEraseSchema2TerminalTargetPhysicalWitnessV1(proof: self,
            binding: expected, witness: witness, nodes: nodes)
        terminalPhysicalWitness = issued
        try issued.requireBound(proof: self, binding: expected, witness: witness)
        return issued
    }

    /// Source authority is replaced only by the actual same-Manifest target
    /// observation after its private checked-close receipt and fresh ZERO.
    func registerColdTerminalTargetObservation(
        observation: ColdEraseSchema2TerminalTargetObservationV1,
        owner: ColdEraseSchema2TerminalOwnerV1) throws {
        guard state == .ready, let witness = drain, let operation,
              aliases.isDrained, readOnlyAliases.isDrained, witness.isActuallyDrained,
              attempt.session == nil, attempt.container == nil,
              terminalPhysicalWitness != nil,
              terminalTargetObservation == nil || terminalTargetObservation === observation,
              terminalTargetOwner == nil || terminalTargetOwner === owner else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        do {
            try operation.requireColdTargetDrain(witness, proof: self, binding: binding)
            try observation.requireSemanticProof(self, binding: binding, witness: witness)
            try observation.requireCheckedSourceClosed(owner: owner)
            try observation.requireCurrent(owner: owner, witness: witness, binding: binding)
            try attempt.physicalIO.requireSettled()
            try readOnlyIO.requireSettled()
            terminalTargetObservation = observation
            terminalTargetOwner = owner
        } catch { state = .uncertain; operation.poisonColdScratchOwner(); throw error }
    }

    /// Memory/resource association only: no Source or Store dependency and no
    /// observer, G or constructor recursion after a genuine terminal transfer.
    fileprivate func requireColdTerminalWitness(_ expected: ColdEraseSchema2TerminalTargetPhysicalWitnessV1,
        binding expectedBinding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws {
        guard terminalPhysicalWitness === expected, binding == expectedBinding,
              drain === witness, state == .ready, operation != nil,
              aliases.isDrained, readOnlyAliases.isDrained, witness.isActuallyDrained,
              attempt.session == nil, attempt.container == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try readOnlyIO.requireSettled()
        try attempt.physicalIO.requireSettled()
    }

    fileprivate static func requireExactReadOnlyNodes(
        _ before: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode],
        _ after: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode]) throws {
        guard before.count == after.count else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        for (old, current) in zip(before, after) {
            let a = old.fact, b = current.fact
            guard old.path == current.path, old.sha256 == current.sha256,
                  a.st_dev == b.st_dev, a.st_ino == b.st_ino,
                  a.st_mode == b.st_mode, a.st_nlink == b.st_nlink,
                  a.st_uid == b.st_uid, a.st_gid == b.st_gid,
                  a.st_size == b.st_size,
                  a.st_mtimespec.tv_sec == b.st_mtimespec.tv_sec,
                  a.st_mtimespec.tv_nsec == b.st_mtimespec.tv_nsec,
                  a.st_ctimespec.tv_sec == b.st_ctimespec.tv_sec,
                  a.st_ctimespec.tv_nsec == b.st_ctimespec.tv_nsec else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

}


/// Distinct cold Factory output, not an Original publication/manifest proof.
/// Numeric root descriptors are consumed only inside a separately genuine
/// held Manifest scope; the closed snapshot alone authorizes no effect.
@MainActor
final class ColdEraseSchema2TerminalTargetPhysicalWitnessV1 {
    private weak var proof: ColdEraseSchema2TargetSemanticProofV1?
    private weak var witness: EraseSessionDrainWitnessV1?
    let binding: EraseRetirementBindingV1
    private let nodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode]

    fileprivate init(proof: ColdEraseSchema2TargetSemanticProofV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1,
        nodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode]) {
        self.proof = proof; self.binding = binding; self.witness = witness
        self.nodes = nodes
    }

    func requireBound(proof expectedProof: ColdEraseSchema2TargetSemanticProofV1,
        binding expectedBinding: EraseRetirementBindingV1,
        witness expectedWitness: EraseSessionDrainWitnessV1) throws {
        guard proof === expectedProof, witness === expectedWitness, binding == expectedBinding else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expectedProof.requireColdTerminalWitness(self, binding: expectedBinding, witness: expectedWitness)
    }

    func requireCurrent(root: Int32, io: EraseAbortCheckedSnapshotIOV1) throws {
        guard let proof, let witness else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireBound(proof: proof, binding: binding, witness: witness)
        let observed = try io.treeWithNodes(parent: root, name: ".").nodes
        try ColdEraseSchema2TargetSemanticProofV1.requireExactReadOnlyNodes(nodes, observed)
        try io.requireSettled()
        try requireBound(proof: proof, binding: binding, witness: witness)
    }
}

extension StoreGenerationFactory {
    /// Exactly one allowsSave:false / nil-migration-plan actual-target read.
    /// The privately retained proof owns constructor admission, weak aliases
    /// and the exact before/after physical ZERO witness across drain polling.
    @MainActor
    func validateOrResumeSchema2ColdTargetReadOnlyAfterDrain(
        proof: ColdEraseSchema2TargetSemanticProofV1,
        binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws -> Bool {
        guard try proof.requireReadOnlyAliasDrain(binding: binding, witness: witness) else { return false }
        if let modelURL = try proof.beginReadOnlyAfterDrain(binding: binding, witness: witness) {
            let valid: Bool = autoreleasepool {
                do {
                    let manifest = proof.readOnlyManifest
                    let container = try openReadOnlyReleasedContainer(at: modelURL,
                        release: .v53, markerMigrationID: manifest.migrationID,
                        observe: { proof.observeReadOnlyContainer($0) },
                        afterConstruct: { _ in try proof.requireReadOnlyCurrent() })
                    let identity = try acceptedV53SemanticIdentity(in: container.mainContext,
                        generationID: binding.subject.newGenerationID,
                        migrationID: manifest.migrationID)
                    guard identity == binding.workspaceIdentity else { return false }
                    try EraseAllService.requireEmptyErasePublishedGraph(context: container.mainContext,
                        generationID: binding.subject.newGenerationID, identity: identity,
                        activated: proof.readOnlyActivatedIntent)
                    guard !container.mainContext.hasChanges,
                          try container.mainContext.fetchCount(FetchDescriptor<MutationReceiptRow>()) == 0 else {
                        return false
                    }
                    try proof.requireReadOnlyCurrent()
                    return true
                } catch {
                    #if DEBUG
                    print("COLD_SCHEMA2_TARGET_READONLY_V1 stage=constructor-or-semantic-refused family=\(type(of: error))")
                    #endif
                    return false // no arbitrary SwiftData Error escapes the pool
                }
            }
            try proof.endReadOnly(valid: valid)
        }
        return try proof.finishReadOnlyAfterDrain(binding: binding, witness: witness)
    }
}

@MainActor
final class EraseSchema2ColdActivatedTargetAttemptV1 {
    private enum Phase { case registered, readerAllocated, opening,
        physicallySettled, ready, draining, uncertain }
    private weak var operation: EraseColdPreparationOperationV1?
    let source: EraseSchema2ColdTargetSourceV1
    let snapshot: EraseSchema2ColdTargetSnapshotV1
    let intent: EraseIntentV1
    let registry: GenerationLeaseRegistryV1
    let activity: GenerationTemporalActivityHandleV1
    let preactivation: EraseSchema2ColdTargetValidationAttemptV1
    let validationStage: EraseSchema2ColdTargetValidationStageV1
    private var phase: Phase = .registered
    private(set) var allocation: GenerationLeaseAllocationAttemptV1?
    private(set) var reader: GenerationLeaseHandleV1?
    private(set) var container: ModelContainer?
    private(set) var session: StoreGenerationSession?
    private(set) var physical: EraseSchema2ColdTargetLiveOpenPhysicalV1?
    let physicalIO = EraseAbortCheckedSnapshotIOV1()

    init(source: EraseSchema2ColdTargetSourceV1,
        snapshot: EraseSchema2ColdTargetSnapshotV1,
        intent: EraseIntentV1,
        registry: GenerationLeaseRegistryV1,
        activity: GenerationTemporalActivityHandleV1,
        preactivation: EraseSchema2ColdTargetValidationAttemptV1,
        operation: EraseColdPreparationOperationV1) {
        self.source = source; self.snapshot = snapshot
        self.intent = intent; self.registry = registry
        self.activity = activity; self.preactivation = preactivation
        self.validationStage = preactivation.validatedStage
        self.operation = operation
    }

    func requireBound() throws -> EraseColdPreparationOperationV1 {
        guard let operation, phase != .uncertain,
              operation.schema2ColdActivatedTargetAttempt === self,
              operation.schema2ColdTargetValidationAttempt === preactivation,
              snapshot.pointer.generationID
                == intent.newGenerationID.uuidString.lowercased(),
              snapshot.manifest.generationID == intent.newGenerationID,
              ((validationStage == .preactivation
                    && intent.phase == .pointerSwitched)
                || (validationStage == .activated
                    && intent.phase == .sessionActivated)),
              intent.schemaVersion == 2 else {
            throw EraseAllServiceError.invalidAuthority
        }
        try operation.requireSchema2ColdActivatedTargetAttempt(self)
        try operation.requireConstructedSchema2ColdRegistry(registry)
        try physicalIO.requireSettled()
        return operation
    }

    func retainAllocation(_ value: GenerationLeaseAllocationAttemptV1) throws {
        _ = try requireBound()
        guard phase == .registered, allocation == nil else {
            throw EraseAllServiceError.invalidAuthority
        }
        allocation = value
        phase = .readerAllocated
    }

    func retainReader(_ value: GenerationLeaseHandleV1) throws {
        _ = try requireBound()
        guard phase == .readerAllocated, reader == nil,
              allocation?.allocatedHandle === value else {
            throw EraseAllServiceError.invalidAuthority
        }
        reader = value
    }

    func beginLiveOpen() throws ->
        EraseSchema2ColdTargetLiveOpenPhysicalV1.Before {
        let operation = try requireBound()
        guard phase == .readerAllocated,
              reader != nil, container == nil, session == nil,
              preactivation.isCheckedClosed else {
            throw EraseAllServiceError.invalidAuthority
        }
        switch validationStage {
        case .preparedTargetCurrent:
            throw EraseAllServiceError.invalidAuthority
        case .preactivation:
            try preactivation.requireCompletedPreactivation(
                source: source, snapshot: snapshot, intent: intent)
        case .activated:
            try preactivation.requireCompletedActivated(
                source: source, snapshot: snapshot, intent: intent)
        }
        let captured = try source.withHeldTargetRoot { descriptor in
            try EraseSchema2ColdTargetLiveOpenPhysicalV1.captureBefore(
                root: descriptor, validationAttempt: preactivation,
                snapshot: snapshot, stage: validationStage,
                io: physicalIO)
        }
        switch validationStage {
        case .preparedTargetCurrent:
            throw EraseAllServiceError.invalidAuthority
        case .preactivation:
            try operation.beginSchema2ColdTargetLiveOpen(
                source: source, snapshot: snapshot, attempt: self)
        case .activated:
            try operation.beginSchema2ColdActivatedEntryLiveOpen(
                source: source, snapshot: snapshot, attempt: self)
        }
        phase = .opening
        return captured
    }

    func retainContainer(_ value: ModelContainer) throws {
        guard phase == .opening, container == nil else {
            throw EraseAllServiceError.invalidAuthority
        }
        container = value
    }

    func retainSession(_ value: StoreGenerationSession) throws {
        guard phase == .opening, session == nil,
              value.modelContext === container?.mainContext,
              value.generationID == intent.newGenerationID,
              value.readerLeaseToken == reader?.token else {
            throw EraseAllServiceError.invalidAuthority
        }
        session = value
    }

    func settleLiveOpen(
        before: EraseSchema2ColdTargetLiveOpenPhysicalV1.Before
    ) throws -> StoreGenerationSession {
        let operation = try requireBound()
        guard phase == .opening, let session,
              let reader else {
            throw EraseAllServiceError.invalidAuthority
        }
        try reader.requireExactRegistry(registry)
        let proof = try source.withHeldTargetRootAfterOwnedLiveOpen(
            attempt: self) { descriptor in
            try EraseSchema2ColdTargetLiveOpenPhysicalV1(
                before: before, root: descriptor, io: physicalIO)
        }
        switch validationStage {
        case .preparedTargetCurrent:
            throw EraseAllServiceError.invalidAuthority
        case .preactivation:
            try proof.requireBoundToPreactivation(
                attempt: preactivation, snapshot: snapshot)
        case .activated:
            try proof.requireBoundToActivated(
                attempt: preactivation, snapshot: snapshot)
        }
        physical = proof
        phase = .physicallySettled
        switch validationStage {
        case .preparedTargetCurrent:
            throw EraseAllServiceError.invalidAuthority
        case .preactivation:
            try operation.finishSchema2ColdTargetLiveOpen(
                source: source, snapshot: snapshot, attempt: self,
                session: session, physical: proof)
        case .activated:
            try operation.finishSchema2ColdActivatedEntryLiveOpen(
                source: source, snapshot: snapshot, attempt: self,
                session: session, physical: proof)
        }
        phase = .ready
        return session
    }

    func requireCompletedLiveOpen(
        source expectedSource: EraseSchema2ColdTargetSourceV1,
        snapshot expectedSnapshot: EraseSchema2ColdTargetSnapshotV1,
        operation expectedOperation: EraseColdPreparationOperationV1
    ) throws -> StoreGenerationSession {
        let operation = try requireBound()
        guard operation === expectedOperation,
              source === expectedSource,
              snapshot.currentPointer == expectedSnapshot.currentPointer,
              snapshot.pointer == expectedSnapshot.pointer,
              snapshot.manifest == expectedSnapshot.manifest,
              snapshot.installedGenerationIDs
                == expectedSnapshot.installedGenerationIDs,
              snapshot.retiredGenerationIDs
                == expectedSnapshot.retiredGenerationIDs,
              phase == .ready,
              let session, let physical,
              session.readerLeaseToken == reader?.token else {
            throw EraseAllServiceError.invalidAuthority
        }
        switch validationStage {
        case .preparedTargetCurrent:
            throw EraseAllServiceError.invalidAuthority
        case .preactivation:
            try physical.requireBoundToPreactivation(
                attempt: preactivation, snapshot: snapshot)
        case .activated:
            try physical.requireBoundToActivated(
                attempt: preactivation, snapshot: snapshot)
        }
        if let reader { try reader.requireExactRegistry(registry) }
        try source.withHeldTargetRoot { descriptor in
            try physical.requireCurrentPostimage(root: descriptor,
                io: physicalIO)
        }
        return session
    }

    func markUncertain() { phase = .uncertain }

    func makeColdRetirementSemanticProof(binding: EraseRetirementBindingV1,
        activated: EraseIntentV1, operation expected: EraseColdPreparationOperationV1)
        throws -> ColdEraseSchema2TargetSemanticProofV1 {
        guard operation === expected, phase == .ready, let session, let physical,
              source.generationID == activated.newGenerationID,
              activated.eraseID == intent.eraseID,
              allocation != nil, reader != nil else {
            throw EraseAllServiceError.invalidAuthority
        }
        let proof = ColdEraseSchema2TargetSemanticProofV1(binding: binding,
            attempt: self, source: source, physical: physical,
            activated: activated, session: session, operation: expected)
        try expected.retainColdTargetSemanticProof(proof, binding: binding, attempt: self)
        try proof.validate(session: session)
        return proof
    }

    func detachColdRetirementAliases(proof: ColdEraseSchema2TargetSemanticProofV1,
        operation expected: EraseColdPreparationOperationV1) throws {
        guard operation === expected, phase == .ready else {
            throw EraseAllServiceError.invalidAuthority
        }
        try proof.requireAliasDetachment(attempt: self, operation: expected)
        phase = .draining
        session = nil
        container = nil
    }
}

extension StoreGenerationFactory {
    /// Construct the real target session only after the separate private
    /// preactivation proof and actual target-current pointer publication.
    /// Every reader publication and returned SwiftData alias is retained by
    /// the same cold operation; ordinary creating open paths are not used.
    @MainActor
    func openSchema2ColdActivatedTargetSession(
        source: EraseSchema2ColdTargetSourceV1,
        snapshot: EraseSchema2ColdTargetSnapshotV1,
        intent: EraseIntentV1,
        registry: GenerationLeaseRegistryV1,
        activity: GenerationTemporalActivityHandleV1,
        operation: EraseColdPreparationOperationV1
    ) throws -> StoreGenerationSession {
        enum DiagnosticStage: String {
            case entry, retained, stageProof, registryBinding,
                attemptRetention, allocationMake, attemptAllocation,
                operationAllocation, readerAcquire, readerRetention,
                physicalOpen, containerOpen, sessionBinding
        }
        var diagnosticStage: DiagnosticStage = .entry
        do {
        if let retained = operation.schema2ColdActivatedTargetAttempt {
            diagnosticStage = .retained
            return try retained.requireCompletedLiveOpen(
                source: source, snapshot: snapshot, operation: operation)
        }
        diagnosticStage = .stageProof
        guard intent.schemaVersion == 2,
              intent.phase == .pointerSwitched
                || intent.phase == .sessionActivated,
              source.generationID == intent.newGenerationID,
              snapshot.pointer.generationID
                == intent.newGenerationID.uuidString.lowercased(),
              snapshot.manifest.generationID == intent.newGenerationID,
              snapshot.manifest.storeSchemaRelease == .v53,
              let expectedTarget = intent.targetPointer,
              expectedTarget.generationManifestSHA256
                == snapshot.pointer.generationManifestSHA256,
              let validated = operation.schema2ColdTargetValidationAttempt else {
            throw EraseAllServiceError.invalidAuthority
        }
        switch validated.validatedStage {
        case .preparedTargetCurrent:
            throw EraseAllServiceError.invalidAuthority
        case .preactivation:
            guard intent.phase == .pointerSwitched else {
                throw EraseAllServiceError.invalidAuthority
            }
            try validated.requireCompletedPreactivation(
                source: source, snapshot: snapshot, intent: intent)
        case .activated:
            guard intent.phase == .sessionActivated else {
                throw EraseAllServiceError.invalidAuthority
            }
            try validated.requireCompletedActivated(
                source: source, snapshot: snapshot, intent: intent)
        }
        diagnosticStage = .registryBinding
        let boundFactory = try bindingExistingSchema2ColdRegistry(
            registry, operation: operation)
        let epoch = try GenerationEpochV1(
            generationID: intent.newGenerationID,
            generationManifestSHA256:
                snapshot.pointer.generationManifestSHA256)
        let attempt = EraseSchema2ColdActivatedTargetAttemptV1(
            source: source, snapshot: snapshot, intent: intent,
            registry: registry, activity: activity,
            preactivation: validated, operation: operation)
        diagnosticStage = .attemptRetention
        try operation.retainSchema2ColdActivatedTargetAttempt(attempt)
        do {
            diagnosticStage = .allocationMake
            let allocation = try registry
                .makeEraseSchema2ColdTargetReaderAllocation(
                    epoch: epoch, operation: operation,
                    activity: activity)
            diagnosticStage = .attemptAllocation
            try attempt.retainAllocation(allocation)
            diagnosticStage = .operationAllocation
            try operation.retainSchema2ColdTargetReaderAllocation(
                allocation, registry: registry)
            diagnosticStage = .readerAcquire
            let reader = try allocation
                .acquireReaderForEraseSchema2ColdTarget(
                    operation: operation, activity: activity)
            diagnosticStage = .readerRetention
            try operation.retainSchema2ColdTargetReaderHandle(
                reader, allocation: allocation, registry: registry)
            try attempt.retainReader(reader)
            diagnosticStage = .physicalOpen
            let before = try attempt.beginLiveOpen()
            let modelURL = installedGenerationURL(
                id: intent.newGenerationID)
                .appendingPathComponent(Self.modelStoreName,
                    isDirectory: false)
            diagnosticStage = .containerOpen
            let container = try makeV53Container(at: modelURL,
                migrate: false)
            try attempt.retainContainer(container)
            let observedIdentity = try acceptedV53SemanticIdentity(
                in: container.mainContext,
                generationID: intent.newGenerationID,
                migrationID: snapshot.manifest.migrationID)
            let expectedIdentity = try WorkspaceReplicaIdentityV1(
                workspaceID: WorkspaceID(
                    rawValue: expectedTarget.workspaceID),
                replicaID: ReplicaID(
                    rawValue: expectedTarget.replicaID))
            guard observedIdentity == expectedIdentity else {
                throw EraseAllServiceError.invalidAuthority
            }
            switch validated.validatedStage {
            case .preparedTargetCurrent:
                throw EraseAllServiceError.invalidAuthority
            case .preactivation:
                try EraseAllService.requireSchema2ColdPreactivationGraph(
                    context: container.mainContext,
                    generationID: intent.newGenerationID,
                    identity: observedIdentity, switched: intent)
            case .activated:
                try EraseAllService.requireEmptyErasePublishedGraph(
                    context: container.mainContext,
                    generationID: intent.newGenerationID,
                    identity: observedIdentity, activated: intent)
            }
            let session = StoreGenerationSession(
                generationID: intent.newGenerationID,
                generationRootURL: installedGenerationURL(
                    id: intent.newGenerationID),
                workspaceIdentity: observedIdentity,
                modelContainer: container,
                storeSchemaRelease: .v53,
                generationEpoch: epoch,
                readerLeaseHandle: reader,
                openingFactoryForWriter: boundFactory,
                afterSaveReproof: { [weak attempt, weak operation] in
                    guard let attempt, let operation else {
                        throw EraseAllServiceError.invalidAuthority
                    }
                    try operation.requireSchema2ColdActivatedTargetAttempt(
                        attempt)
                })
            diagnosticStage = .sessionBinding
            try attempt.retainSession(session)
            try operation.retainSchema2ColdActivatedTargetSession(
                session, attempt: attempt)
            return try attempt.settleLiveOpen(before: before)
        } catch {
            attempt.markUncertain()
            throw error
        }
        } catch {
            #if DEBUG
            enum DiagnosticFamily: String {
                case registry, migration, policy, other
            }
            let family: DiagnosticFamily
            if error is GenerationLeaseRegistryFailureV1 {
                family = .registry
            } else if error is StoreMigrationFailure {
                family = .migration
            } else if error is ProtectedFilePolicyError {
                family = .policy
            } else {
                family = .other
            }
            print("V23_C05_READER_PREPUBLISH_DIAG_V1 stage=\(diagnosticStage.rawValue) family=\(family.rawValue)")
            #endif
            throw error
        }
    }
}

@MainActor
protocol EraseSchema2ColdPrivateReadableSourceV1: AnyObject {
    var generationID: UUID { get }
    var generationRootURL: URL { get }
    var manifest: StoreGenerationManifestV1 { get }
    var manifestDigest: String { get }
    func withHeldOriginalRoot<T>(_ body: (Int32) throws -> T) throws -> T
    func withHeldApplicationSupport<T>(_ body: (Int32) throws -> T) throws -> T
    func checkedOriginalTree() throws -> (digest: String,
        nodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode])
    func requireOriginalUnchanged() throws
    func requireHeldApplicationSupportIdentity() throws
        -> (device: dev_t, inode: ino_t)
    func requireTargetRootIdentity(targetID: UUID) throws
        -> ReportPDFAnchoredFile.RootIdentity
    func requireCurrentTargetPointer(intent: EraseIntentV1) throws
        -> CurrentGenerationPointerV3
    func checkedOriginalC05TransientWitness() throws
        -> StoreRestoreGenerationAuthority.C05GenerationTransientWitnessV1?
}

extension EraseSchema2ColdRetainedSourceV1:
    EraseSchema2ColdPrivateReadableSourceV1 {}

extension EraseSchema2ColdRetiredSourceV1:
    EraseSchema2ColdPrivateReadableSourceV1 {}

@MainActor
final class EraseSchema2ColdPrivateSourceAttemptV1 {
    private enum Phase { case registered, copying, copied, reading,
        validated, disposing, ready, uncertain }
    private weak var operation: EraseColdPreparationOperationV1?
    private let source: any EraseSchema2ColdPrivateReadableSourceV1
    private let intent: EraseIntentV1
    private let configuredTemporaryDirectoryURL: URL
    private let temporaryDirectoryURL: URL
    private let copyID = UUID()
    private var phase: Phase = .registered
    private var tempParent: Int32 = -1
    private var tempChild: Int32 = -1
    private var copiedSource: Int32 = -1
    private var uncertainFDs: [Int32] = []
    private var parentIdentity: (dev_t, ino_t)?
    private var childIdentity: (dev_t, ino_t)?
    private var worker: EraseSchema2ColdPrivateCopyWorkerV1?
    private var copyTask: Task<Bool, Never>?
    private weak var privateContainer: ModelContainer?
    private weak var privateContext: ModelContext?
    private var containerObserved = false
    private let ancestryIO = EraseAbortCheckedSnapshotIOV1()
    private let contentIO = EraseAbortCheckedSnapshotIOV1()

    /// This becomes true only after the private context aliases have gone,
    /// the complete staged tree/root has been checked-removed, and every
    /// retained descriptor has completed its checked close.
    var isCheckedClosed: Bool {
        guard phase == .ready, tempParent < 0, tempChild < 0,
              copiedSource < 0, copyTask == nil,
              privateContainer == nil, privateContext == nil,
              uncertainFDs.isEmpty else { return false }
        return (try? ancestryIO.requireSettled()) != nil
            && (try? contentIO.requireSettled()) != nil
    }

    init(source: any EraseSchema2ColdPrivateReadableSourceV1,
        intent: EraseIntentV1, temporaryDirectoryURL: URL,
        operation: EraseColdPreparationOperationV1) {
        self.source = source; self.intent = intent
        self.configuredTemporaryDirectoryURL = temporaryDirectoryURL.standardizedFileURL
        self.temporaryDirectoryURL = temporaryDirectoryURL.standardizedFileURL
            .resolvingSymlinksInPath().standardizedFileURL
        self.operation = operation
    }

    private var name: String {
        ".assetrounds-erase-retained-validation-\(copyID.uuidString.lowercased())"
    }
    var modelURL: URL {
        temporaryDirectoryURL.appendingPathComponent(name, isDirectory: true)
            .appendingPathComponent("model.sqlite")
    }

    func checkedOriginalRootIdentity() throws
        -> ReportPDFAnchoredFile.RootIdentity {
        _ = try requireBound()
        return try source.withHeldOriginalRoot { descriptor in
            var info = stat()
            guard Darwin.fstat(descriptor, &info) == 0,
                  info.st_mode & S_IFMT == S_IFDIR,
                  info.st_nlink > 0 else {
                throw EraseAllServiceError.invalidAuthority
            }
            return ReportPDFAnchoredFile.RootIdentity(
                device: info.st_dev, inode: info.st_ino)
        }
    }

    func resolveOriginalContentReference(_ reference: ContentReferenceV1)
        throws -> ContentReferenceV1? {
        _ = try requireBound()
        let result = try source.withHeldOriginalRoot { descriptor in
            try EraseSchema2ColdContentReadbackV1(
                rootURL: source.generationRootURL, io: contentIO,
                retainUncertainDescriptor: { self.uncertainFDs.append($0) })
                .resolveContentReference(reference, root: descriptor)
        }
        try source.requireOriginalUnchanged()
        try contentIO.requireSettled()
        return result
    }

    func readOriginalAssetLabelArtifacts(jobID: LocalJobIDV1)
        throws -> AssetLabelPublishedContentReadbackV1? {
        _ = try requireBound()
        let tree = try source.checkedOriginalTree()
        let result = try source.withHeldOriginalRoot { descriptor in
            try EraseSchema2ColdContentReadbackV1(
                rootURL: source.generationRootURL, io: contentIO,
                retainUncertainDescriptor: { self.uncertainFDs.append($0) })
                .readAssetLabelArtifacts(jobID: jobID, root: descriptor,
                    treePaths: tree.nodes.map(\.path))
        }
        try source.requireOriginalUnchanged()
        try contentIO.requireSettled()
        return result
    }

    func readOriginalRegular(_ relativePath: String,
        kind: OwnedFileKindV1, maximumBytes: Int64) throws -> Data {
        _ = try requireBound()
        let result = try source.withHeldOriginalRoot { descriptor in
            try EraseSchema2ColdContentReadbackV1(
                rootURL: source.generationRootURL, io: contentIO,
                retainUncertainDescriptor: { self.uncertainFDs.append($0) })
                .readRegular(root: descriptor, relativePath: relativePath,
                    kind: kind, maximumBytes: maximumBytes)
        }
        try source.requireOriginalUnchanged()
        try contentIO.requireSettled()
        guard let result else { throw EraseAllServiceError.invalidAuthority }
        return result
    }

    func originalLeafIsAbsent(_ relativePath: String) throws -> Bool {
        _ = try requireBound()
        let result = try source.withHeldOriginalRoot { descriptor in
            try EraseSchema2ColdContentReadbackV1(
                rootURL: source.generationRootURL, io: contentIO,
                retainUncertainDescriptor: { self.uncertainFDs.append($0) })
                .leafIsAbsent(root: descriptor, relativePath: relativePath)
        }
        try source.requireOriginalUnchanged()
        try contentIO.requireSettled()
        return result
    }

    func readApplicationSupportRegular(_ url: URL,
        kind: OwnedFileKindV1, maximumBytes: Int64) throws -> Data? {
        _ = try requireBound()
        let supportURL = source.generationRootURL.deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
            .standardizedFileURL
        let requested = url.standardizedFileURL
        let prefix = supportURL.path + "/"
        guard requested.isFileURL, requested.path.hasPrefix(prefix) else {
            throw EraseAllServiceError.invalidAuthority
        }
        let relative = String(requested.path.dropFirst(prefix.count))
        let result = try source.withHeldApplicationSupport { descriptor in
            try EraseSchema2ColdContentReadbackV1(
                rootURL: supportURL, io: contentIO,
                retainUncertainDescriptor: { self.uncertainFDs.append($0) })
                .readRegular(root: descriptor, relativePath: relative,
                    kind: kind, maximumBytes: maximumBytes)
        }
        try source.requireOriginalUnchanged()
        try contentIO.requireSettled()
        return result
    }

    private func requireBound() throws -> EraseColdPreparationOperationV1 {
        guard let operation, uncertainFDs.isEmpty,
              intent.generationIDsToDelete.contains(source.generationID),
              source.manifest.generationID == source.generationID,
              source.manifest.storeSchemaRelease == .v53,
              intent.schemaVersion == 2,
              intent.phase == .emptyGenerationPrepared ||
                intent.phase == .pointerSwitched ||
                intent.phase == .sessionActivated else {
            throw EraseAllServiceError.invalidAuthority
        }
        if let original = source as? EraseSchema2ColdRetainedSourceV1 {
            guard operation.schema2ColdPrivateSourceAttempt === self,
                  source.generationID == intent.oldGenerationID,
                  let old = intent.oldPointer,
                  old.generationID == intent.oldGenerationID,
                  old.generationManifestSHA256
                    == source.manifestDigest else {
                throw EraseAllServiceError.invalidAuthority
            }
            try operation.requireSchema2ColdRetainedSource(original)
            try operation.requireSchema2ColdPrivateSourceAttempt(self)
        } else if let retired = source as? EraseSchema2ColdRetiredSourceV1 {
            guard retired.generationID != intent.oldGenerationID,
                  retired.intent == intent else {
                throw EraseAllServiceError.invalidAuthority
            }
            try operation.requireSchema2ColdRetiredPrivateAttempt(
                self, source: retired)
        } else {
            throw EraseAllServiceError.invalidAuthority
        }
        try source.requireOriginalUnchanged()
        _ = try source.requireCurrentTargetPointer(intent: intent)
        _ = try source.requireTargetRootIdentity(targetID: intent.newGenerationID)
        try ancestryIO.requireSettled()
        try contentIO.requireSettled()
        try source.withHeldOriginalRoot { _ in () }
        return operation
    }

    private func identity(_ descriptor: Int32) throws -> (dev_t, ino_t) {
        var value = stat()
        guard descriptor >= 0, Darwin.fstat(descriptor, &value) == 0,
              value.st_mode & S_IFMT == S_IFDIR, value.st_nlink > 0 else {
            throw EraseAllServiceError.invalidAuthority
        }
        return (value.st_dev, value.st_ino)
    }

    /// The configured temp parent must remain the exact canonical held root
    /// and must not be Support or any descendant of the original held Support.
    /// Every opened ancestor is checked-closed by the retained attempt owner.
    private func requireDisjointTemporaryParent(
        expected: (dev_t, ino_t)
    ) throws {
        let heldSupport = try source.requireHeldApplicationSupportIdentity()
        try EraseSchema2ColdTempAncestryV1.requireDisjoint(
            parent: tempParent, canonicalURL: temporaryDirectoryURL,
            configuredURL: configuredTemporaryDirectoryURL,
            heldSupport: heldSupport, io: ancestryIO)
        guard try identity(tempParent) == expected else {
            throw EraseAllServiceError.invalidAuthority
        }
    }

    private func requirePrivateRoot() throws {
        guard phase != .uncertain, tempParent >= 0, tempChild >= 0,
              let parentIdentity, let childIdentity else {
            throw EraseAllServiceError.invalidAuthority
        }
        let parent = try identity(tempParent)
        let child = try identity(tempChild)
        try requireDisjointTemporaryParent(expected: parentIdentity)
        var named = stat(), rootNamed = stat()
        guard parent == parentIdentity, child == childIdentity,
              Darwin.lstat(temporaryDirectoryURL.path, &rootNamed) == 0,
              rootNamed.st_mode & S_IFMT == S_IFDIR,
              rootNamed.st_dev == parent.0,
              rootNamed.st_ino == parent.1,
              Darwin.fstatat(tempParent, name, &named,
                AT_SYMLINK_NOFOLLOW) == 0,
              named.st_mode & S_IFMT == S_IFDIR,
              named.st_dev == child.0,
              named.st_ino == child.1 else {
            throw EraseAllServiceError.invalidAuthority
        }
    }

    func requireSource() throws {
        _ = try requireBound()
        if phase == .copied || phase == .reading ||
           phase == .validated || phase == .disposing || phase == .ready {
            guard let worker else { throw EraseAllServiceError.invalidAuthority }
            try source.withHeldOriginalRoot { descriptor in
                try worker.requireOriginalUnchanged(sourceRoot: descriptor)
            }
        }
        try requirePrivateRoot()
    }

    func startCopy() async throws {
        guard phase == .registered, copyTask == nil,
              tempParent < 0, tempChild < 0 else {
            throw EraseAllServiceError.invalidAuthority
        }
        _ = try requireBound()
        do {
            let temporary = temporaryDirectoryURL
            guard temporary.isFileURL else {
                throw EraseAllServiceError.invalidAuthority
            }
            // The copy must not modify a parent pinned by the source owner.
            tempParent = Darwin.open(temporary.path,
                O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
            guard tempParent >= 0 else { throw EraseAllServiceError.invalidAuthority }
            let capturedParent = try identity(tempParent)
            parentIdentity = capturedParent
            try requireDisjointTemporaryParent(expected: capturedParent)
            var named = stat()
            guard Darwin.lstat(temporary.path, &named) == 0,
                  named.st_mode & S_IFMT == S_IFDIR,
                  named.st_dev == capturedParent.0,
                  named.st_ino == capturedParent.1,
                  Darwin.mkdirat(tempParent, name, mode_t(0o700)) == 0 else {
                throw EraseAllServiceError.invalidAuthority
            }
            tempChild = Darwin.openat(tempParent, name,
                O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
            guard tempChild >= 0 else { throw EraseAllServiceError.invalidAuthority }
            childIdentity = try identity(tempChild)
            try requirePrivateRoot()
            try ProtectedFilePolicyV1.applyAndVerifyEraseColdPrivateWithCheckedClose(
                .stagingDirectory,
                at: temporary.appendingPathComponent(name, isDirectory: true),
                retainUncertainDescriptor: { self.uncertainFDs.append($0) },
                authorityCheck: { try self.requirePrivateRoot() })
            try source.withHeldOriginalRoot { descriptor in
                let captured = Darwin.openat(descriptor, ".",
                    O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
                guard captured >= 0 else { throw EraseAllServiceError.invalidAuthority }
                // Retain before the scoped owner's post-callback reproof can
                // throw; the operation then keeps an ambiguous descriptor.
                copiedSource = captured
                var original = stat(), duplicate = stat()
                guard Darwin.fstat(descriptor, &original) == 0,
                      Darwin.fstat(captured, &duplicate) == 0,
                      original.st_dev == duplicate.st_dev,
                      original.st_ino == duplicate.st_ino,
                      original.st_mode == duplicate.st_mode else {
                    throw EraseAllServiceError.invalidAuthority
                }
            }
            guard let childIdentity else { throw EraseAllServiceError.invalidAuthority }
            let copied = EraseSchema2ColdPrivateCopyWorkerV1(
                source: copiedSource, parent: tempParent, staging: tempChild,
                stagingURL: temporary.appendingPathComponent(name, isDirectory: true),
                stagingIdentity: childIdentity,
                configuredTemporaryDirectoryURL: configuredTemporaryDirectoryURL,
                heldSupportIdentity: try source.requireHeldApplicationSupportIdentity())
            worker = copied // retained before detached task creation
            phase = .copying
            let task = Task.detached(priority: .utility) { copied.copy() }
            copyTask = task
            let completed = await task.value // genuine join, including cancellation
            copyTask = nil
            guard completed else { throw EraseAllServiceError.recoveryRequired }
            _ = try requireBound()
            try requirePrivateRoot()
            try source.withHeldOriginalRoot { descriptor in
                try copied.requireOriginalUnchanged(sourceRoot: descriptor)
            }
            let duplicate = copiedSource
            copiedSource = -1 // never retry an ambiguous numeric descriptor
            guard Darwin.close(duplicate) == 0 else {
                uncertainFDs.append(duplicate)
                throw EraseAllServiceError.recoveryRequired
            }
            try copied.preparePrivateReadSidecars()
            try source.withHeldOriginalRoot { descriptor in
                try copied.requireOriginalUnchanged(sourceRoot: descriptor)
            }
            phase = .copied
        } catch {
            phase = .uncertain
            throw error
        }
    }

    func beginRead() throws {
        guard phase == .copied, copyTask == nil,
              privateContainer == nil, privateContext == nil else {
            throw EraseAllServiceError.invalidAuthority
        }
        try requireSource()
        phase = .reading
    }

    func observe(_ container: ModelContainer) {
        containerObserved = true
        privateContainer = container
        privateContext = container.mainContext
    }

    func endRead(valid: Bool) throws {
        guard phase == .reading, containerObserved, valid else {
            phase = .uncertain
            throw EraseAllServiceError.recoveryRequired
        }
        try requireSource()
        phase = .validated
    }

    func disposeAfterAliasDrain(source expectedSource:
        any EraseSchema2ColdPrivateReadableSourceV1,
        intent expectedIntent: EraseIntentV1) throws -> Bool {
        guard source === expectedSource, intent == expectedIntent,
              copyTask == nil, copiedSource < 0 else {
            throw EraseAllServiceError.invalidAuthority
        }
        if phase == .ready {
            _ = try requireBound()
            guard let worker else { throw EraseAllServiceError.invalidAuthority }
            try source.withHeldOriginalRoot { descriptor in
                try worker.requireOriginalUnchanged(sourceRoot: descriptor)
            }
            return true
        }
        guard phase == .validated else {
            throw EraseAllServiceError.invalidAuthority
        }
        if privateContainer != nil || privateContext != nil { return false }
        do {
            try requireSource()
            phase = .disposing
            guard let worker else { throw EraseAllServiceError.invalidAuthority }
            try worker.removeValidatedCopy()
            try requirePrivateRoot()
            let child = tempChild
            tempChild = -1
            guard Darwin.close(child) == 0 else {
                uncertainFDs.append(child)
                throw EraseAllServiceError.recoveryRequired
            }
            guard let parentIdentity, let childIdentity,
                  try identity(tempParent) == parentIdentity else {
                throw EraseAllServiceError.invalidAuthority
            }
            try requireDisjointTemporaryParent(expected: parentIdentity)
            var named = stat()
            guard Darwin.fstatat(tempParent, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  named.st_mode & S_IFMT == S_IFDIR,
                  named.st_dev == childIdentity.0,
                  named.st_ino == childIdentity.1,
                  Darwin.unlinkat(tempParent, name, AT_REMOVEDIR) == 0,
                  Darwin.fsync(tempParent) == 0 else {
                throw EraseAllServiceError.invalidAuthority
            }
            let parent = tempParent
            tempParent = -1
            guard Darwin.close(parent) == 0 else {
                uncertainFDs.append(parent)
                throw EraseAllServiceError.recoveryRequired
            }
            try source.withHeldOriginalRoot { descriptor in
                try worker.requireOriginalUnchanged(sourceRoot: descriptor)
            }
            phase = .ready
            return true
        } catch {
            phase = .uncertain
            throw error
        }
    }
}

extension StoreGenerationFactory {
    /// Read the exact held old generation from a disposable private copy. The
    /// operation owns the attempt before any temporary or source descriptor is
    /// opened; a retry resumes only that same attempt and its alias drain.
    @MainActor
    func validateOrResumeSchema2ColdRetainedSource(
        source: EraseSchema2ColdRetainedSourceV1,
        intent: EraseIntentV1,
        temporaryDirectoryURL: URL,
        operation: EraseColdPreparationOperationV1,
        validate: @MainActor (ModelContext,
            EraseSchema2ColdPrivateSourceAttemptV1) throws -> Void
    ) async throws -> Bool {
        guard intent.schemaVersion == 2,
              intent.phase == .emptyGenerationPrepared
                || intent.phase == .pointerSwitched
                || intent.phase == .sessionActivated,
              source.generationID == intent.oldGenerationID,
              source.manifest.generationID == intent.oldGenerationID,
              source.manifest.storeSchemaRelease == .v53,
              let old = intent.oldPointer,
              old.generationManifestSHA256 == source.manifestDigest else {
            throw EraseAllServiceError.invalidAuthority
        }
        guard try source.checkedOriginalC05TransientWitness() == nil else {
            throw EraseAllServiceError.invalidAuthority
        }
        return try await validateOrResumeSchema2ColdPrivateSource(
            source: source, intent: intent,
            temporaryDirectoryURL: temporaryDirectoryURL,
            operation: operation, validate: validate)
    }

    /// The other frozen retired roots use the same checked copy, content and
    /// alias lifecycle. Their per-ID semantic witness is distinct from the
    /// old pointer's source-ledger witness and is supplied by the caller.
    @MainActor
    func validateOrResumeSchema2ColdRetiredSource(
        source: EraseSchema2ColdRetiredSourceV1,
        intent: EraseIntentV1,
        temporaryDirectoryURL: URL,
        operation: EraseColdPreparationOperationV1,
        validate: @MainActor (ModelContext,
            EraseSchema2ColdPrivateSourceAttemptV1) throws -> Void
    ) async throws -> Bool {
        guard intent.schemaVersion == 2,
              intent.phase == .pointerSwitched ||
                intent.phase == .sessionActivated,
              intent.generationIDsToDelete.contains(source.generationID),
              source.generationID != intent.oldGenerationID,
              source.intent == intent,
              source.manifest.generationID == source.generationID,
              source.manifest.storeSchemaRelease == .v53,
              try source.checkedOriginalC05TransientWitness() == nil else {
            throw EraseAllServiceError.invalidAuthority
        }
        try operation.requireSchema2ColdRetiredSource(source)
        return try await validateOrResumeSchema2ColdPrivateSource(
            source: source, intent: intent,
            temporaryDirectoryURL: temporaryDirectoryURL,
            operation: operation, validate: validate)
    }

    @MainActor
    private func validateOrResumeSchema2ColdPrivateSource(
        source: any EraseSchema2ColdPrivateReadableSourceV1,
        intent: EraseIntentV1,
        temporaryDirectoryURL: URL,
        operation: EraseColdPreparationOperationV1,
        validate: @MainActor (ModelContext,
            EraseSchema2ColdPrivateSourceAttemptV1) throws -> Void
    ) async throws -> Bool {
        if let old = source as? EraseSchema2ColdRetainedSourceV1,
           let attempt = operation.schema2ColdPrivateSourceAttempt {
            return try attempt.disposeAfterAliasDrain(
                source: old, intent: intent)
        }
        if let retired = source as? EraseSchema2ColdRetiredSourceV1,
           let attempt = operation.schema2ColdRetiredPrivateAttempt(
                id: retired.generationID) {
            return try attempt.disposeAfterAliasDrain(
                source: retired, intent: intent)
        }
        let attempt = EraseSchema2ColdPrivateSourceAttemptV1(
            source: source, intent: intent,
            temporaryDirectoryURL: temporaryDirectoryURL, operation: operation)
        if let old = source as? EraseSchema2ColdRetainedSourceV1 {
            try operation.requireSchema2ColdRetainedSource(old)
            try operation.retainSchema2ColdPrivateSourceAttempt(attempt)
        } else if let retired = source as? EraseSchema2ColdRetiredSourceV1 {
            try operation.retainSchema2ColdRetiredPrivateAttempt(
                attempt, source: retired)
        } else {
            throw EraseAllServiceError.invalidAuthority
        }
        try await attempt.startCopy()
        try attempt.beginRead()
        let valid: Bool = autoreleasepool {
            do {
                let container = try openReadOnlyReleasedContainer(
                    at: attempt.modelURL, release: .v53,
                    markerMigrationID: source.manifest.migrationID,
                    observe: { attempt.observe($0) },
                    afterConstruct: { _ in try attempt.requireSource() })
                try validate(container.mainContext, attempt)
                return true
            } catch { return false }
        }
        try attempt.endRead(valid: valid)
        return try attempt.disposeAfterAliasDrain(source: source, intent: intent)
    }
}
// Authentic weak provider provenance is memory DATA, never an effect issuer.
// Only this Factory file can construct it from its real private provider.
final class ColdEraseSchema2CompletedRegistryFactoryProvenanceV1 {
    fileprivate struct Storage {
        weak var provider: StoreGenerationLeaseRegistryProvider?
        let rootURL: URL
    }
    private let storage: Storage
    fileprivate init(provider: StoreGenerationLeaseRegistryProvider, rootURL: URL) {
        storage = Storage(provider: provider, rootURL: rootURL)
    }
    func requireMatches(factory: StoreGenerationFactory) throws {
        try factory.requireCompletedSchema2ConstructorFactoryProvenance(self)
    }
    fileprivate func requireActualProvider(_ provider: StoreGenerationLeaseRegistryProvider,
        rootURL: URL) throws {
        guard storage.provider === provider, storage.rootURL == rootURL,
              rootURL == rootURL.standardizedFileURL else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    func requireSameProvenance(_ other: ColdEraseSchema2CompletedRegistryFactoryProvenanceV1) throws {
        guard let provider = storage.provider else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try other.requireActualProvider(provider, rootURL: storage.rootURL)
    }
    static func declaredBackingBytes() -> UInt64 { UInt64(MemoryLayout<Storage>.stride) }
}

extension StoreGenerationFactory {
    func completedSchema2ConstructorFactoryProvenance() throws
        -> ColdEraseSchema2CompletedRegistryFactoryProvenanceV1 {
        guard applicationSupportURL.isFileURL,
              applicationSupportURL == applicationSupportURL.standardizedFileURL else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return ColdEraseSchema2CompletedRegistryFactoryProvenanceV1(
            provider: generationLeaseRegistryProvider, rootURL: applicationSupportURL)
    }
    fileprivate func requireCompletedSchema2ConstructorFactoryProvenance(
        _ provenance: ColdEraseSchema2CompletedRegistryFactoryProvenanceV1) throws {
        try provenance.requireActualProvider(generationLeaseRegistryProvider, rootURL: applicationSupportURL)
    }
    @MainActor func releaseSchema2ColdCompletedConstructorFactoryRetentionAfterPublicationReceiver(
        _ receiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1,
        registry: GenerationLeaseRegistryV1, owner: ColdEraseSchema2CompletedStartupOwnerV1,
        inventory: EraseReaderRetirementInventoryV1) throws {
        let attempt = try generationLeaseRegistryProvider.requireActualCompletedConstructor(registry: registry)
        try attempt.releaseCompletedFactoryRetentionAfterPublicationReceiver(receiver,
            registry: registry, owner: owner, factory: self, inventory: inventory)
    }
}

fileprivate extension StoreGenerationLeaseRegistryProvider {
    func requireActualCompletedConstructor(registry: GenerationLeaseRegistryV1) throws
        -> ColdEraseSchema2CompletedRegistryConstructorAttemptV1 {
        try lock.withLock {
            guard retainedRegistry === registry, let completedSchema2Constructor else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.requireCompletedSchema2ConstructorResourceTransfer(completedSchema2Constructor)
            return completedSchema2Constructor
        }
    }
}

extension StoreGenerationFactory {
    /// A genuine bounded Source constructor. Its Source, journal store and
    /// current byte receipt are retained by the actual Bootstrap before IO
    /// or any returned-resource postcondition. Session/container construction
    /// must consume a separate completed origin; this method grants none.
    @MainActor func prepareSchema2ColdCompletedBootstrapSource(
        registry: GenerationLeaseRegistryV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1,
        inventory: EraseReaderRetirementInventoryV1) throws
        -> ColdEraseSchema2CompletedJournalSourceV1 {
        try prepareSchema2ColdCompletedBootstrapSourceAndJournal(registry: registry,
            owner: owner, inventory: inventory).source
    }

    /// Keep the actual Source and its already transferred Store together for
    /// the initial Session receipt. No ordinary Store constructor is entered.
    @MainActor private func prepareSchema2ColdCompletedBootstrapSourceAndJournal(
        registry: GenerationLeaseRegistryV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1,
        inventory: EraseReaderRetirementInventoryV1) throws
        -> (source: ColdEraseSchema2CompletedJournalSourceV1, journal: StoreMigrationJournalStoreV1) {
        try owner.requireReaderConstructionFrame(factory: self)
        guard matchesSchema2ColdCompletedInventory(inventory), owner.readerInventory === inventory else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let attempt = try generationLeaseRegistryProvider.requireActualCompletedConstructor(registry: registry)
        try attempt.requireRetainedTransferredRegistry(registry: registry, owner: owner,
            factory: self, inventory: inventory)
        let bootstrap = try registry.prepareSchema2ColdCompletedBootstrap(owner: owner,
            factory: self, inventory: inventory)
        let returned = try bootstrap.withCurrentBootstrap(registry: registry, owner: owner,
            factory: self, inventory: inventory) {
            let source = try ColdEraseSchema2CompletedJournalSourceV1.constructForSchema2ColdCompletedStartup(
                bootstrap: bootstrap, owner: owner, factory: self, inventory: inventory)
            let journal = try source.requireReturnedJournalStore(bootstrap: bootstrap)
            let receipt = try source.captureCurrentSourceBytes(bootstrap: bootstrap,
                owner: owner, factory: self)
            // Producer already retains its actual receipt before returning.
            // Bootstrap retains the same receipt before canonical epoch joins.
            _ = try requireCompletedSchema2CurrentEpoch(source: receipt, owner: owner)
            return (source: source, journal: journal)
        }
        try bootstrap.requirePositivePermanentSettlement(registry: registry, owner: owner,
            factory: self, inventory: inventory)
        guard try returned.source.requireReturnedJournalStore(bootstrap: bootstrap) === returned.journal else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return returned
    }
}

// ORIGINAL_POINTER_RETAINED_PUBLICATION_SETTLEMENT_V1_BEGIN
/// Immutable returned publication DATA. Every fact/byte/name below comes
/// from the actual finite checked publisher reads, never a caller tuple.
struct OriginalEraseRetainedPointerPublicationDataV1 {
    struct Sibling {
        let path: String
        let fact: stat
        let names: [String]?
        let sha256: String?
        fileprivate init(path: String, fact: stat, names: [String]?, sha256: String?) {
            self.path = path; self.fact = fact; self.names = names; self.sha256 = sha256
        }
    }
    let stage: OriginalEraseRetainedPointerStageV1
    let dataRoot: stat
    let names: [String]
    let currentBytes: Data
    let currentFact: stat
    let retiredBytes: Data
    let retiredFact: stat
    let siblings: [Sibling]
    fileprivate init(stage: OriginalEraseRetainedPointerStageV1, dataRoot: stat, names: [String],
        currentBytes: Data, currentFact: stat, retiredBytes: Data, retiredFact: stat, siblings: [Sibling]) {
        self.stage = stage; self.dataRoot = dataRoot; self.names = names
        self.currentBytes = currentBytes; self.currentFact = currentFact
        self.retiredBytes = retiredBytes; self.retiredFact = retiredFact; self.siblings = siblings
    }
}

/// Pure completed publication data, not permission to observe the old FDs or
/// mutate a current namespace. The actual OP stays weak; the returned raw
/// publication/child-resource graph stays strong through receipt lifetime.
@MainActor final class OriginalEraseRetainedPointerPublicationSettlementV1 {
    fileprivate struct Storage {
        weak var authority: StoreRestoreGenerationAuthority?
        weak var operation: EraseRouterOperationV1?
        weak var receipt: StoreRestoreGenerationAuthority.OriginalErasePointerReceiptV1?
        let publication: OriginalErasePointerPublicationIOV1
        let stage: OriginalEraseRetainedPointerStageV1
        weak var predecessor: OriginalEraseRetainedPointerPublicationSettlementV1?
        let data: OriginalEraseRetainedPointerPublicationDataV1
        var successorPublication: OriginalErasePointerPublicationIOV1?
        var successor: OriginalEraseRetainedPointerPublicationSettlementV1?
        var originalIntervalReturned = false
        var failure: Error?
    }
    fileprivate var storage: Storage
    fileprivate static var declaredBackingBytes: UInt64 {
        UInt64(MemoryLayout<Storage>.stride
            + MemoryLayout<OriginalEraseRetainedPointerPublicationDataV1>.stride
            + 2 * MemoryLayout<stat>.stride + 2 * MemoryLayout<Bool>.stride)
    }
    fileprivate init(authority: StoreRestoreGenerationAuthority,
        operation: EraseRouterOperationV1,
        receipt: StoreRestoreGenerationAuthority.OriginalErasePointerReceiptV1,
        publication: OriginalErasePointerPublicationIOV1,
        predecessor: OriginalEraseRetainedPointerPublicationSettlementV1?,
        data: OriginalEraseRetainedPointerPublicationDataV1) {
        storage = Storage(authority: authority, operation: operation, receipt: receipt,
            publication: publication, stage: receipt.stage,
            predecessor: predecessor, data: data)
    }
    fileprivate func requireOwnPermanentData(authority: StoreRestoreGenerationAuthority,
        operation: EraseRouterOperationV1,
        receipt: StoreRestoreGenerationAuthority.OriginalErasePointerReceiptV1) throws {
        guard storage.authority === authority, storage.operation === operation,
              storage.receipt === receipt, receipt.authority === authority,
              receipt.publicationSettlement === self,
              receipt.stage == storage.stage, storage.originalIntervalReturned,
              storage.failure == nil,
              storage.publication.storage.settlement === self,
              storage.data.stage == storage.stage else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try storage.publication.requirePermanentReturnedGraph(authority: authority,
            operation: operation, receipt: receipt, settlement: self)
        if let predecessor = storage.predecessor {
            guard storage.stage == .retired,
                  receipt.predecessor === predecessor.storage.receipt,
                  predecessor.storage.stage == .current,
                  predecessor.storage.successor === self else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        } else {
            guard storage.stage == .current, receipt.predecessor == nil else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
    }
    func requirePermanentOriginalErasePointerData(authority: StoreRestoreGenerationAuthority,
        operation: EraseRouterOperationV1,
        receipt: StoreRestoreGenerationAuthority.OriginalErasePointerReceiptV1) throws {
        try requireOwnPermanentData(authority: authority, operation: operation, receipt: receipt)
        if let successor = storage.successor {
            guard let actualReceipt = successor.storage.receipt,
                  receipt.successor === actualReceipt,
                  storage.successorPublication === successor.storage.publication,
                  successor.storage.predecessor === self else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try successor.requireOwnPermanentData(authority: authority,
                operation: operation, receipt: actualReceipt)
        } else {
            guard receipt.successor == nil, storage.successorPublication == nil else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
    }
    func withPermanentOriginalErasePointerData(authority: StoreRestoreGenerationAuthority,
        operation: EraseRouterOperationV1,
        receipt: StoreRestoreGenerationAuthority.OriginalErasePointerReceiptV1,
        _ body: (OriginalEraseRetainedPointerPublicationDataV1) throws -> Void) throws {
        try requirePermanentOriginalErasePointerData(authority: authority,
            operation: operation, receipt: receipt)
        // Only the privately retained, genuinely returned retired successor
        // can advance this causal DATA projection. No fresh filesystem IO.
        if let selected = storage.successor {
            try body(selected.storage.data)
        } else {
            guard storage.successorPublication == nil, receipt.successor == nil else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try body(storage.data)
        }
        try requirePermanentOriginalErasePointerData(authority: authority,
            operation: operation, receipt: receipt)
    }
}
// ORIGINAL_POINTER_RETAINED_PUBLICATION_SETTLEMENT_V1_END

// ORIGINAL_POINTER_PUBLICATION_RAW_OWNER_V1_BEGIN
/// Mutated only inside the original publisher's actual pointer mutex/actor
/// interval. The nonisolated SnapshotIO wrappers can record its actual child
/// returns without adding actor assumptions to their incumbent call sites.
fileprivate final class OriginalErasePointerPublicationIOV1 {
    fileprivate enum Phase: Equatable { case retained, observing, publishing, completing, completed, uncertain }
    fileprivate enum Kind: Equatable { case capacity, open, held, named, read, eof, write,
        synchronize, swap, unlink, fdopendir, readdir, closedir, close }
    fileprivate struct CapacityReturn {
        let chargedBeforeBirth: UInt64
        let returned: Int32
        let savedErrno: Int32
        // Captured directly from the same returned statfs; only these
        // operands participate in the actual byte-capacity inequality.
        let blockSize: UInt64
        let availableBlocks: UInt64
    }
    /// One actual capacity syscall attempt. Its typed charge and graph slot
    /// are paid before birth; its raw return is retained before any predicate.
    /// This bookkeeping owns no FD and grants no later/current authority.
    fileprivate final class CapacityAttempt {
        enum Phase: Equatable { case retained, entered, returned, checked, uncertain }
        struct Storage {
            weak var graph: OriginalErasePointerPublicationIOV1?
            let ordinal: UInt64
            let descriptor: Int32
            let requestedBytes: UInt64
            let previousCharge: UInt64
            let bookkeepingBytes: UInt64
            let chargedBeforeBirth: UInt64
            var phase = Phase.retained
            var capacity: CapacityReturn?
            var failure: Error?
        }
        var storage: Storage
        static var declaredBackingBytes: UInt64 {
            UInt64(MemoryLayout<Storage>.stride + MemoryLayout<Storage>.alignment - 1
                + 2 * MemoryLayout<CapacityAttempt?>.stride
                + MemoryLayout<CapacityReturn>.stride)
        }
        init(graph: OriginalErasePointerPublicationIOV1, ordinal: UInt64,
            descriptor: Int32, requestedBytes: UInt64, previousCharge: UInt64,
            bookkeepingBytes: UInt64, chargedBeforeBirth: UInt64) {
            storage = .init(graph: graph, ordinal: ordinal, descriptor: descriptor,
                requestedBytes: requestedBytes, previousCharge: previousCharge,
                bookkeepingBytes: bookkeepingBytes, chargedBeforeBirth: chargedBeforeBirth)
        }
    }
    fileprivate final class Raw {
        struct Storage {
            let ordinal: UInt64
            let kind: Kind
            let descriptor: Int32
            let name: String?
            let requested: Int
            let flags: Int32?
            let capacity: CapacityAttempt
            var result: Int64?
            var savedErrno: Int32?
            var fact: stat?
            var directory: UnsafeMutablePointer<DIR>?
            var directoryEntry: UnsafeMutablePointer<dirent>?
            var pointerReturned = false
            var decodedName: String?
            var consumed = false
            var failure: Error?
        }
        var storage: Storage
        init(ordinal: UInt64, kind: Kind, descriptor: Int32, name: String?,
            requested: Int, flags: Int32?, capacity: CapacityAttempt) {
            storage = .init(ordinal: ordinal, kind: kind, descriptor: descriptor,
                name: name, requested: requested, flags: flags, capacity: capacity)
        }
        func returned(_ result: Int64, errno: Int32, fact: stat? = nil,
            directory: UnsafeMutablePointer<DIR>? = nil,
            entry: UnsafeMutablePointer<dirent>? = nil) {
            // Called immediately after the actual syscall, before any guard.
            storage.result = result; storage.savedErrno = errno
            storage.fact = fact; storage.directory = directory; storage.directoryEntry = entry
        }
        func returnedDirectory(_ value: UnsafeMutablePointer<DIR>?, errno: Int32) {
            storage.directory = value; storage.savedErrno = errno; storage.pointerReturned = true
        }
        func returnedEntry(_ value: UnsafeMutablePointer<dirent>?, errno: Int32) {
            storage.directoryEntry = value; storage.savedErrno = errno; storage.pointerReturned = true
        }
    }
    fileprivate final class Child {
        struct Storage {
            let open: Raw
            let role: String
            var descriptor: Int32
            var directory: UnsafeMutablePointer<DIR>?
            var adoption: Raw?
            var close: Raw?
            var bodyReturned = false
            var closeEntered = false
            var closeReturned = false
            var failure: Error?
        }
        var storage: Storage
        init(open: Raw, role: String, descriptor: Int32) {
            storage = .init(open: open, role: role, descriptor: descriptor)
        }
    }
    fileprivate final class Policy {
        enum Return { case returned(ProtectedFileVerificationDispositionV1), threw(Error) }
        struct Storage {
            let kind: OwnedFileKindV1
            let url: URL
            var result: Return?
            var authorityEntries: UInt64 = 0
            var firstEffectEntries: UInt64 = 0
            var uncertainDescriptors: [Int32] = []
            var failure: Error?
        }
        var storage: Storage
        init(kind: OwnedFileKindV1, url: URL) { storage = .init(kind: kind, url: url) }
    }
    fileprivate struct ReadProjection {
        let name: String
        let data: Data
        let held: stat
        let named: stat
        let child: Child
        let eof: Raw
    }
    fileprivate struct Storage {
        weak var authority: StoreRestoreGenerationAuthority?
        weak var operation: EraseRouterOperationV1?
        weak var receipt: StoreRestoreGenerationAuthority.OriginalErasePointerReceiptV1?
        weak var settlement: OriginalEraseRetainedPointerPublicationSettlementV1?
        let stage: OriginalEraseRetainedPointerStageV1
        weak var predecessor: StoreRestoreGenerationAuthority.OriginalErasePointerReceiptV1?
        let snapshotIO: EraseAbortCheckedSnapshotIOV1
        let supportDescriptor: Int32
        let dataDescriptor: Int32
        let dataName: String
        let dataURL: URL
        let maximumControlBytes: Int
        let birthCapacity: CapacityReturn
        var phase = Phase.retained
        var chargedBytes: UInt64
        var capacityAttempts: [CapacityAttempt] = []
        var raw: [Raw] = []
        var children: [Child] = []
        var policies: [Policy] = []
        var readProjections: [ReadProjection] = []
        var siblingProjections: [OriginalEraseRetainedPointerPublicationDataV1.Sibling] = []
        var firstSiblingProjections: [OriginalEraseRetainedPointerPublicationDataV1.Sibling]?
        var latestRoot: stat?
        var firstRoot: stat?
        var swap: Raw?
        var unlink: Raw?
        var writerSynchronize: Raw?
        var swapParentSynchronize: Raw?
        var unlinkParentSynchronize: Raw?
        var effectEntered = false
        var originalPostproofReturned = false
        var failure: Error?
        var capacityFailure: CapacityReturn?
    }
    fileprivate var storage: Storage
    @MainActor fileprivate static var declaredBirthBackingBytes: UInt64 {
        let rawCells: Int = MemoryLayout<Storage>.stride
            + 8 * MemoryLayout<stat>.stride + MemoryLayout<CapacityReturn>.stride
        let publicationCells: Int = MemoryLayout<StoreRestoreGenerationAuthority.OriginalErasePointerReceiptV1.PublicationStoredCellProfile>.stride
            + 2 * MemoryLayout<OriginalEraseRetainedPointerPublicationDataV1>.stride
            + 4 * MemoryLayout<Data>.stride + 4 * MemoryLayout<String>.stride
        let digestAndIOCells: Int = MemoryLayout<SHA256>.stride
            + MemoryLayout<SHA256.Digest>.stride
            + 2 * MemoryLayout<OriginalErasePointerPublicationIOV1?>.stride
            + MemoryLayout<[OriginalErasePointerPublicationIOV1]>.stride
        let declaredCells: UInt64 = UInt64(rawCells)
            + OriginalEraseRetainedPointerPublicationSettlementV1.declaredBackingBytes
            + UInt64(publicationCells) + UInt64(digestAndIOCells)
        return declaredCells + 65536 + 16384
    }
    fileprivate init(authority: StoreRestoreGenerationAuthority, operation: EraseRouterOperationV1,
        stage: OriginalEraseRetainedPointerStageV1,
        predecessor: StoreRestoreGenerationAuthority.OriginalErasePointerReceiptV1?,
        snapshotIO: EraseAbortCheckedSnapshotIOV1, supportDescriptor: Int32,
        dataDescriptor: Int32, dataName: String, dataURL: URL,
        maximumControlBytes: Int, birthCapacity: CapacityReturn) {
        storage = .init(authority: authority, operation: operation, stage: stage,
            predecessor: predecessor, snapshotIO: snapshotIO,
            supportDescriptor: supportDescriptor, dataDescriptor: dataDescriptor,
            dataName: dataName, dataURL: dataURL, maximumControlBytes: maximumControlBytes,
            birthCapacity: birthCapacity, chargedBytes: birthCapacity.chargedBeforeBirth)
    }
    fileprivate func requireLive() throws {
        guard storage.phase != .uncertain, storage.phase != .completed,
              storage.failure == nil, let authority = storage.authority,
              let operation = storage.operation else { throw StoreGenerationFailure.dataPointerInvalid }
        try authority.requireOriginalPointerPublicationLive(self, operation: operation)
    }
    fileprivate func fail(_ error: Error) {
        if storage.failure == nil { storage.failure = error }
        storage.phase = .uncertain
    }
    fileprivate func reserve(_ bytes: UInt64) throws -> CapacityAttempt {
        try requireLive()
        let bookkeeping = CapacityAttempt.declaredBackingBytes
        guard bytes > 0, bytes <= UInt64.max - bookkeeping else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let charge = bytes + bookkeeping
        guard storage.chargedBytes <= UInt64.max - charge else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let previous = storage.chargedBytes
        storage.chargedBytes += charge // all typed cells paid before attempt birth
        let attempt = CapacityAttempt(graph: self, ordinal: UInt64(storage.capacityAttempts.count),
            descriptor: storage.dataDescriptor, requestedBytes: bytes, previousCharge: previous,
            bookkeepingBytes: bookkeeping, chargedBeforeBirth: storage.chargedBytes)
        storage.capacityAttempts.append(attempt) // SAME owner before actual IO
        attempt.storage.phase = .entered
        var information = statfs()
        let result = Darwin.fstatfs(storage.dataDescriptor, &information); let saved = errno
        let capacity = CapacityReturn(chargedBeforeBirth: storage.chargedBytes,
            returned: result, savedErrno: saved,
            blockSize: UInt64(information.f_bsize), availableBlocks: UInt64(information.f_bavail))
        attempt.storage.capacity = capacity // raw return/errno/operands FIRST
        attempt.storage.phase = .returned
        do {
            guard result == 0, information.f_bsize > 0,
                  UInt64(information.f_bavail) <= UInt64.max / UInt64(information.f_bsize),
                  UInt64(information.f_bavail) * UInt64(information.f_bsize) >= storage.chargedBytes else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try requireLive()
            attempt.storage.phase = .checked // actual live postproof returned
            return attempt
        } catch {
            attempt.storage.failure = error; attempt.storage.phase = .uncertain
            storage.capacityFailure = capacity
            fail(error) // permanent uncertainty; no second capacity attempt
            throw error
        }
    }
    private func begin(_ kind: Kind, descriptor: Int32,
        name: String? = nil, requested: Int = 0, flags: Int32? = nil) throws -> Raw {
        let nameBytes = name.map { UInt64($0.utf8.count) } ?? 0
        let charge = UInt64(MemoryLayout<Raw.Storage>.stride
            + 2 * MemoryLayout<Raw?>.stride + MemoryLayout<CapacityReturn>.stride) + nameBytes
        let capacity = try reserve(charge)
        let entry = Raw(ordinal: UInt64(storage.raw.count), kind: kind,
            descriptor: descriptor, name: name, requested: requested, flags: flags, capacity: capacity)
        storage.raw.append(entry) // retained before actual syscall
        try requireLive()
        return entry
    }
