        let decoding: Int = 4 * MemoryLayout<String>.stride + 3 * MemoryLayout<Bool>.stride
        let scans: Int = MemoryLayout<IndexingIterator<[OriginalErasePointerPublicationIOV1.Raw]>>.stride
